window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MIC"]={"book":"MIC","editions":{"hbo-source":[[1,1,"דְּבַר־יְהוָ֣ה ׀ אֲשֶׁ֣ר הָיָ֗ה אֶל־מִיכָה֙ הַ⁠מֹּ֣רַשְׁתִּ֔י בִּ⁠ימֵ֥י יוֹתָ֛ם אָחָ֥ז יְחִזְקִיָּ֖ה מַלְכֵ֣י יְהוּדָ֑ה אֲשֶׁר־חָזָ֥ה עַל־שֹׁמְר֖וֹן וִ⁠ירֽוּשָׁלִָֽם׃","dĕ̇bar-yĕhwá֣h ׀ ʼàşě֣r háyá֗h ʼel-miykáh֙ ha⁠mò֣̇raşĕ̌ţi̇֔y bi̇⁠ymé֥y ywòţá֛m ʼáẖá֥z yĕẖizĕqiyá֖̇h malĕké֣y yĕhẇdá֑h ʼàşěr-ẖázá֥h ʻal-şò̌mĕr֖wòn wi⁠yrֽẇşá̌liáֽm׃"],[1,2,"שִׁמְעוּ֙ עַמִּ֣ים כֻּלָּ֔⁠ם הַקְשִׁ֖יבִי אֶ֣רֶץ וּ⁠מְלֹאָ֑⁠הּ וִ⁠יהִי֩ אֲדֹנָ֨⁠י יְהוִ֤ה בָּ⁠כֶם֙ לְ⁠עֵ֔ד אֲדֹנָ֖⁠י מֵ⁠הֵיכַ֥ל קָדְשֽׁ⁠וֹ׃","şǐmĕʻẇ֙ ʻami֣̇ym ku̇lá̇֔⁠m haqĕşǐ֖ybiy ʼe֣reẕ ẇ⁠mĕlòʼá֑⁠ḣ wi⁠yhiy֩ ʼàdòná֨⁠y yĕhwi֤h bá̇⁠kem֙ lĕ⁠ʻé֔d ʼàdòná֖⁠y mé⁠héyka֥l qádĕşֽ̌⁠wò׃"],[1,3,"כִּֽי־הִנֵּ֥ה יְהוָ֖ה יֹצֵ֣א מִ⁠מְּקוֹמ֑⁠וֹ וְ⁠יָרַ֥ד וְ⁠דָרַ֖ךְ עַל־במותי אָֽרֶץ׃","kiֽ̇y-hiné֥̇h yĕhwá֖h yòẕé֣ʼ mi⁠mĕ̇qwòm֑⁠wò wĕ⁠yára֥d wĕ⁠dára֖kĕ ʻal-bmwţy ʼáֽreẕ׃"],[1,4,"וְ⁠נָמַ֤סּוּ הֶֽ⁠הָרִים֙ תַּחְתָּ֔י⁠ו וְ⁠הָ⁠עֲמָקִ֖ים יִתְבַּקָּ֑עוּ כַּ⁠דּוֹנַג֙ מִ⁠פְּנֵ֣י הָ⁠אֵ֔שׁ כְּ⁠מַ֖יִם מֻגָּרִ֥ים בְּ⁠מוֹרָֽד׃","wĕ⁠náma֤ṡẇ heֽ⁠háriym֙ ţȧẖĕţá̇֔y⁠w wĕ⁠há⁠ʻàmáqi֖ym yiţĕbȧqá֑̇ʻẇ kȧ⁠ḋwònag֙ mi⁠pĕ̇né֣y há⁠ʼé֔ş̌ kĕ̇⁠ma֖yim mugá̇ri֥ym bĕ̇⁠mwòráֽd׃"],[1,5,"בְּ⁠פֶ֤שַׁע יַֽעֲקֹב֙ כָּל־זֹ֔את וּ⁠בְ⁠חַטֹּ֖אות בֵּ֣ית יִשְׂרָאֵ֑ל מִֽי־פֶ֣שַׁע יַעֲקֹ֗ב הֲ⁠לוֹא֙ שֹֽׁמְר֔וֹן וּ⁠מִי֙ בָּמ֣וֹת יְהוּדָ֔ה הֲ⁠ל֖וֹא יְרוּשָׁלִָֽם׃","bĕ̇⁠pe֤şǎʻ yaֽʻàqòb֙ ká̇l-zò֔ʼţ ẇ⁠bĕ⁠ẖatò֖̇ʼwţ bé֣̇yţ yişĕ̂ráʼé֑l miֽy-pe֣şǎʻ yaʻàqò֗b hà⁠lwòʼ֙ şòֽ̌mĕr֔wòn ẇ⁠miy֙ bá̇m֣wòţ yĕhẇdá֔h hà⁠l֖wòʼ yĕrẇşá̌liáֽm׃"],[1,6,"וְ⁠שַׂמְתִּ֥י שֹׁמְר֛וֹן לְ⁠עִ֥י הַ⁠שָּׂדֶ֖ה לְ⁠מַטָּ֣עֵי כָ֑רֶם וְ⁠הִגַּרְתִּ֤י לַ⁠גַּי֙ אֲבָנֶ֔י⁠הָ וִ⁠יסֹדֶ֖י⁠הָ אֲגַלֶּֽה׃","wĕ⁠şâmĕţi֥̇y şò̌mĕr֛wòn lĕ⁠ʻi֥y ha⁠şá̇̂de֖h lĕ⁠matá֣̇ʻéy ká֑rem wĕ⁠higȧrĕţi֤̇y la⁠gȧy֙ ʼàbáne֔y⁠há wi⁠ysòde֖y⁠há ʼàgalėֽh׃"],[1,7,"וְ⁠כָל־פְּסִילֶ֣י⁠הָ יֻכַּ֗תּוּ וְ⁠כָל־אֶתְנַנֶּ֨י⁠הָ֙ יִשָּׂרְפ֣וּ בָ⁠אֵ֔שׁ וְ⁠כָל־עֲצַבֶּ֖י⁠הָ אָשִׂ֣ים שְׁמָמָ֑ה כִּ֠י מֵ⁠אֶתְנַ֤ן זוֹנָה֙ קִבָּ֔צָה וְ⁠עַד־אֶתְנַ֥ן זוֹנָ֖ה יָשֽׁוּבוּ׃","wĕ⁠kál-pĕ̇siyle֣y⁠há yukȧ֗ţ̇ẇ wĕ⁠kál-ʼeţĕnanė֨y⁠há֙ yişá̇̂rĕp֣ẇ bá⁠ʼé֔ş̌ wĕ⁠kál-ʻàẕabė֖y⁠há ʼáşî֣ym şĕ̌mámá֑h ki̇֠y mé⁠ʼeţĕna֤n zwònáh֙ qibá̇֔ẕáh wĕ⁠ʻad-ʼeţĕna֥n zwòná֖h yáşֽ̌ẇbẇ׃"],[1,8,"עַל־זֹאת֙ אֶסְפְּדָ֣ה וְ⁠אֵילִ֔ילָה אֵילְכָ֥ה שילל וְ⁠עָר֑וֹם אֶעֱשֶׂ֤ה מִסְפֵּד֙ כַּ⁠תַּנִּ֔ים וְ⁠אֵ֖בֶל כִּ⁠בְנ֥וֹת יַעֲנָֽה׃","ʻal-zòʼţ֙ ʼesĕpĕ̇dá֣h wĕ⁠ʼéyli֔yláh ʼéylĕká֥h şyll wĕ⁠ʻár֑wòm ʼeʻèşê֤h misĕpé̇d֙ kȧ⁠ţȧni̇֔ym wĕ⁠ʼé֖bel ki̇⁠bĕn֥wòţ yaʻànáֽh׃"],[1,9,"כִּ֥י אֲנוּשָׁ֖ה מַכּוֹתֶ֑י⁠הָ כִּי־בָ֨אָה֙ עַד־יְהוּדָ֔ה נָגַ֛ע עַד־שַׁ֥עַר עַמִּ֖⁠י עַד־יְרוּשָׁלִָֽם׃","ki֥̇y ʼànẇşá֖̌h mak̇wòţe֑y⁠há ki̇y-bá֨ʼáh֙ ʻad-yĕhẇdá֔h nága֛ʻ ʻad-şǎ֥ʻar ʻami֖̇⁠y ʻad-yĕrẇşá̌liáֽm׃"],[1,10,"בְּ⁠גַת֙ אַל־תַּגִּ֔ידוּ בָּכ֖וֹ אַל־תִּבְכּ֑וּ בְּ⁠בֵ֣ית לְעַפְרָ֔ה עָפָ֖ר התפלשתי׃","bĕ̇⁠gaţ֙ ʼal-ţȧgi̇֔ydẇ bá̇k֖wò ʼal-ţi̇bĕk֑̇ẇ bĕ̇⁠bé֣yţ lĕʻapĕrá֔h ʻápá֖r hţplşţy׃"],[1,11,"עִבְרִ֥י לָ⁠כֶ֛ם יוֹשֶׁ֥בֶת שָׁפִ֖יר עֶרְיָה־בֹ֑שֶׁת לֹ֤א יָֽצְאָה֙ יוֹשֶׁ֣בֶת צַֽאֲנָ֔ן מִסְפַּד֙ בֵּ֣ית הָאֵ֔צֶל יִקַּ֥ח מִ⁠כֶּ֖ם עֶמְדָּתֽ⁠וֹ׃","ʻibĕri֥y lá⁠ke֛m ywòşě֥beţ şá̌pi֖yr ʻerĕyáh-bò֑şěţ lò֤ʼ yáֽẕĕʼáh֙ ywòşě֣beţ ẕaֽʼàná֔n misĕpȧd֙ bé֣̇yţ háʼé֔ẕel yiqȧ֥ẖ mi⁠kė֖m ʻemĕdá̇ţֽ⁠wò׃"],[1,12,"כִּֽי־חָ֥לָֽה לְ⁠ט֖וֹב יוֹשֶׁ֣בֶת מָר֑וֹת כִּֽי־יָ֤רַד רָע֙ מֵ⁠אֵ֣ת יְהוָ֔ה לְ⁠שַׁ֖עַר יְרוּשָׁלִָֽם׃","kiֽ̇y-ẖá֥láֽh lĕ⁠t֖wòb ywòşě֣beţ már֑wòţ kiֽ̇y-yá֤rad ráʻ֙ mé⁠ʼé֣ţ yĕhwá֔h lĕ⁠şǎ֖ʻar yĕrẇşá̌liáֽm׃"],[1,13,"רְתֹ֧ם הַ⁠מֶּרְכָּבָ֛ה לָ⁠רֶ֖כֶשׁ יוֹשֶׁ֣בֶת לָכִ֑ישׁ רֵאשִׁ֨ית חַטָּ֥את הִיא֙ לְ⁠בַת־צִיּ֔וֹן כִּי־בָ֥⁠ךְ נִמְצְא֖וּ פִּשְׁעֵ֥י יִשְׂרָאֵֽל׃","rĕţò֧m ha⁠mėrĕká̇bá֛h lá⁠re֖keş̌ ywòşě֣beţ láki֑yş̌ réʼşǐ֨yţ ẖatá֥̇ʼţ hiyʼ֙ lĕ⁠baţ-ẕiẏ֔wòn ki̇y-bá֥⁠kĕ nimĕẕĕʼ֖ẇ pi̇şĕ̌ʻé֥y yişĕ̂ráʼéֽl׃"],[1,14,"לָ⁠כֵן֙ תִּתְּנִ֣י שִׁלּוּחִ֔ים עַ֖ל מוֹרֶ֣שֶׁת גַּ֑ת בָּתֵּ֤י אַכְזִיב֙ לְ⁠אַכְזָ֔ב לְ⁠מַלְכֵ֖י יִשְׂרָאֵֽל׃","lá⁠kén֙ ţi̇ţĕ̇ni֣y şǐl̇ẇẖi֔ym ʻa֖l mwòre֣şěţ gȧ֑ţ bá̇ţé֤̇y ʼakĕziyb֙ lĕ⁠ʼakĕzá֔b lĕ⁠malĕké֖y yişĕ̂ráʼéֽl׃"],[1,15,"עֹ֗ד הַ⁠יֹּרֵשׁ֙ אָ֣בִי לָ֔⁠ךְ יוֹשֶׁ֖בֶת מָֽרֵשָׁ֑ה עַד־עֲדֻּלָּ֥ם יָב֖וֹא כְּב֥וֹד יִשְׂרָאֵֽל׃","ʻò֗d ha⁠yò̇réş̌֙ ʼá֣biy lá֔⁠kĕ ywòşě֖beţ máֽréşá֑̌h ʻad-ʻàdu̇lá֥̇m yáb֖wòʼ kĕ̇b֥wòd yişĕ̂ráʼéֽl׃"],[1,16,"קָרְחִ֣י וָ⁠גֹ֔זִּי עַל־בְּנֵ֖י תַּעֲנוּגָ֑יִ⁠ךְ הַרְחִ֤בִי קָרְחָתֵ⁠ךְ֙ כַּ⁠נֶּ֔שֶׁר כִּ֥י גָל֖וּ מִמֵּֽ⁠ךְ׃ס","qárĕẖi֣y wá⁠gò֔zi̇y ʻal-bĕ̇né֖y ţȧʻànẇgá֑yi⁠kĕ harĕẖi֤biy qárĕẖáţé⁠kĕ֙ kȧ⁠nė֔şěr ki֥̇y gál֖ẇ miméֽ̇⁠kĕ׃s"],[2,1,"ה֧וֹי חֹֽשְׁבֵי־אָ֛וֶן וּ⁠פֹ֥עֲלֵי רָ֖ע עַל־מִשְׁכְּבוֹתָ֑⁠ם בְּ⁠א֤וֹר הַ⁠בֹּ֨קֶר֙ יַעֲשׂ֔וּ⁠הָ כִּ֥י יֶשׁ־לְ⁠אֵ֖ל יָדָֽ⁠ם׃","h֧wòy ẖòֽşĕ̌béy-ʼá֛wen ẇ⁠pò֥ʻàléy rá֖ʻ ʻal-mişĕ̌kĕ̇bwòţá֑⁠m bĕ̇⁠ʼ֤wòr ha⁠bò̇֨qer֙ yaʻàş̂֔ẇ⁠há ki֥̇y yeş̌-lĕ⁠ʼé֖l yádáֽ⁠m׃"],[2,2,"וְ⁠חָמְד֤וּ שָׂדוֹת֙ וְ⁠גָזָ֔לוּ וּ⁠בָתִּ֖ים וְ⁠נָשָׂ֑אוּ וְ⁠עָֽשְׁקוּ֙ גֶּ֣בֶר וּ⁠בֵית֔⁠וֹ וְ⁠אִ֖ישׁ וְ⁠נַחֲלָתֽ⁠וֹ׃פ","wĕ⁠ẖámĕd֤ẇ şá̂dwòţ֙ wĕ⁠gázá֔lẇ ẇ⁠báţi֖̇ym wĕ⁠náşá֑̂ʼẇ wĕ⁠ʻáֽşĕ̌qẇ֙ gė֣ber ẇ⁠béyţ֔⁠wò wĕ⁠ʼi֖yş̌ wĕ⁠naẖàláţֽ⁠wò׃p"],[2,3,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֥י חֹשֵׁ֛ב עַל־הַ⁠מִּשְׁפָּחָ֥ה הַ⁠זֹּ֖את רָעָ֑ה אֲ֠שֶׁר לֹֽא־תָמִ֨ישׁוּ מִ⁠שָּׁ֜ם צַוְּארֹֽתֵי⁠כֶ֗ם וְ⁠לֹ֤א תֵֽלְכוּ֙ רוֹמָ֔ה כִּ֛י עֵ֥ת רָעָ֖ה הִֽיא׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֥y ẖòşé֛̌b ʻal-ha⁠mi̇şĕ̌pá̇ẖá֥h ha⁠zò֖̇ʼţ ráʻá֑h ʼà֠şěr lòֽʼ-ţámi֨yş̌ẇ mi⁠şá̇̌֜m ẕawĕ̇ʼròֽţéy⁠ke֗m wĕ⁠lò֤ʼ ţéֽlĕkẇ֙ rwòmá֔h ki֛̇y ʻé֥ţ ráʻá֖h hiֽyʼ׃"],[2,4,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא יִשָּׂ֧א עֲלֵי⁠כֶ֣ם מָשָׁ֗ל וְ⁠נָהָ֨ה נְהִ֤י נִֽהְיָה֙ אָמַר֙ שָׁד֣וֹד נְשַׁדֻּ֔נוּ חֵ֥לֶק עַמִּ֖⁠י יָמִ֑יר אֵ֚יךְ יָמִ֣ישׁ לִ֔⁠י לְ⁠שׁוֹבֵ֥ב שָׂדֵ֖י⁠נוּ יְחַלֵּֽק׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ yişá֧̇̂ʼ ʻàléy⁠ke֣m máşá̌֗l wĕ⁠náhá֨h nĕhi֤y niֽhĕyáh֙ ʼámar֙ şá̌d֣wòd nĕşǎdu̇֔nẇ ẖé֥leq ʻami֖̇⁠y yámi֑yr ʼé֚ykĕ yámi֣yş̌ li֔⁠y lĕ⁠ş̌wòbé֥b şá̂dé֖y⁠nẇ yĕẖaléֽ̇q׃"],[2,5,"לָ⁠כֵן֙ לֹֽא־יִֽהְיֶ֣ה לְ⁠ךָ֔ מַשְׁלִ֥יךְ חֶ֖בֶל בְּ⁠גוֹרָ֑ל בִּ⁠קְהַ֖ל יְהוָֽה׃","lá⁠kén֙ lòֽʼ-yiֽhĕye֣h lĕ⁠ká֔ maşĕ̌li֥ykĕ ẖe֖bel bĕ̇⁠gwòrá֑l bi̇⁠qĕha֖l yĕhwáֽh׃"],[2,6,"אַל־תַּטִּ֖פוּ יַטִּיפ֑וּ⁠ן לֹֽא־יַטִּ֣פוּ לָ⁠אֵ֔לֶּה לֹ֥א יִסַּ֖ג כְּלִמּֽוֹת׃","ʼal-ţȧti֖̇pẇ yati̇yp֑ẇ⁠n lòֽʼ-yati֣̇pẇ lá⁠ʼé֔lėh lò֥ʼ yisȧ֖g kĕ̇liṁֽwòţ׃"],[2,7,"הֶ⁠אָמ֣וּר בֵּֽית־יַעֲקֹ֗ב הֲ⁠קָצַר֙ ר֣וּחַ יְהוָ֔ה אִם־אֵ֖לֶּה מַעֲלָלָ֑י⁠ו הֲ⁠ל֤וֹא דְבָרַ֨⁠י יֵיטִ֔יבוּ עִ֖ם הַ⁠יָּשָׁ֥ר הוֹלֵֽךְ׃","he⁠ʼám֣ẇr béֽ̇yţ-yaʻàqò֗b hà⁠qáẕar֙ r֣ẇẖa yĕhwá֔h ʼim-ʼé֖lėh maʻàlálá֑y⁠w hà⁠l֤wòʼ dĕbára֨⁠y yéyti֔ybẇ ʻi֖m ha⁠yá̇şá֥̌r hwòléֽkĕ׃"],[2,8,"וְ⁠אֶתְמ֗וּל עַמִּ⁠י֙ לְ⁠אוֹיֵ֣ב יְקוֹמֵ֔ם מִ⁠מּ֣וּל שַׂלְמָ֔ה אֶ֖דֶר תַּפְשִׁט֑וּ⁠ן מֵ⁠עֹבְרִ֣ים בֶּ֔טַח שׁוּבֵ֖י מִלְחָמָֽה׃","wĕ⁠ʼeţĕm֗ẇl ʻami̇⁠y֙ lĕ⁠ʼwòyé֣b yĕqwòmé֔m mi⁠ṁ֣ẇl şâlĕmá֔h ʼe֖der ţȧpĕşǐt֑ẇ⁠n mé⁠ʻòbĕri֣ym bė֔taẖ ş̌ẇbé֖y milĕẖámáֽh׃"],[2,9,"נְשֵׁ֤י עַמִּ⁠י֙ תְּגָ֣רְשׁ֔וּ⁠ן מִ⁠בֵּ֖ית תַּֽעֲנֻגֶ֑י⁠הָ מֵ⁠עַל֙ עֹֽלָלֶ֔י⁠הָ תִּקְח֥וּ הֲדָרִ֖⁠י לְ⁠עוֹלָֽם׃","nĕşé֤̌y ʻami̇⁠y֙ ţĕ̇gá֣rĕş̌֔ẇ⁠n mi⁠bé֖̇yţ ţȧֽʻànuge֑y⁠há mé⁠ʻal֙ ʻòֽlále֔y⁠há ţi̇qĕẖ֥ẇ hàdári֖⁠y lĕ⁠ʻwòláֽm׃"],[2,10,"ק֣וּמוּ וּ⁠לְכ֔וּ כִּ֥י לֹא־זֹ֖את הַ⁠מְּנוּחָ֑ה בַּ⁠עֲב֥וּר טָמְאָ֛ה תְּחַבֵּ֖ל וְ⁠חֶ֥בֶל נִמְרָֽץ׃","q֣ẇmẇ ẇ⁠lĕk֔ẇ ki֥̇y lòʼ-zò֖ʼţ ha⁠mĕ̇nẇẖá֑h bȧ⁠ʻàb֥ẇr támĕʼá֛h ţĕ̇ẖabé֖̇l wĕ⁠ẖe֥bel nimĕráֽẕ׃"],[2,11,"לוּ־אִ֞ישׁ הֹלֵ֥ךְ ר֨וּחַ֙ וָ⁠שֶׁ֣קֶר כִּזֵּ֔ב אַטִּ֣ף לְ⁠ךָ֔ לַ⁠יַּ֖יִן וְ⁠לַ⁠שֵּׁכָ֑ר וְ⁠הָיָ֥ה מַטִּ֖יף הָ⁠עָ֥ם הַ⁠זֶּֽה׃","lẇ-ʼi֞yş̌ hòlé֥kĕ r֨ẇẖa֙ wá⁠şě֣qer ki̇zé̇֔b ʼati֣̇p lĕ⁠ká֔ la⁠yȧ֖yin wĕ⁠la⁠şé̇̌ká֑r wĕ⁠háyá֥h mati֖̇yp há⁠ʻá֥m ha⁠zėֽh׃"],[2,12,"אָסֹ֨ף אֶאֱסֹ֜ף יַעֲקֹ֣ב כֻּלָּ֗⁠ךְ קַבֵּ֤ץ אֲקַבֵּץ֙ שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל יַ֥חַד אֲשִׂימֶ֖⁠נּוּ כְּ⁠צֹ֣אן בָּצְרָ֑ה כְּ⁠עֵ֨דֶר֙ בְּ⁠ת֣וֹךְ הַ⁠דָּֽבְר֔⁠וֹ תְּהִימֶ֖נָה מֵ⁠אָדָֽם׃","ʼásò֨p ʼeʼèsò֜p yaʻàqò֣b ku̇lá̇֗⁠kĕ qabé֤̇ẕ ʼàqabé̇ẕ֙ şĕ̌ʼéri֣yţ yişĕ̂ráʼé֔l ya֥ẖad ʼàşîyme֖⁠ṅẇ kĕ̇⁠ẕò֣ʼn bá̇ẕĕrá֑h kĕ̇⁠ʻé֨der֙ bĕ̇⁠ţ֣wòkĕ ha⁠dáֽ̇bĕr֔⁠wò ţĕ̇hiyme֖náh mé⁠ʼádáֽm׃"],[2,13,"עָלָ֤ה הַ⁠פֹּרֵץ֙ לִ⁠פְנֵי⁠הֶ֔ם פָּֽרְצוּ֙ וַֽ⁠יַּעֲבֹ֔רוּ שַׁ֖עַר וַ⁠יֵּ֣צְאוּ ב֑⁠וֹ וַ⁠יַּעֲבֹ֤ר מַלְכָּ⁠ם֙ לִ⁠פְנֵי⁠הֶ֔ם וַ⁠יהוָ֖ה בְּ⁠רֹאשָֽׁ⁠ם׃פ","ʻálá֤h ha⁠pò̇réẕ֙ li⁠pĕnéy⁠he֔m páֽ̇rĕẕẇ֙ waֽ⁠yȧʻàbò֔rẇ şǎ֖ʻar wa⁠yé֣̇ẕĕʼẇ b֑⁠wò wa⁠yȧʻàbò֤r malĕká̇⁠m֙ li⁠pĕnéy⁠he֔m wa⁠yhwá֖h bĕ̇⁠ròʼşáֽ̌⁠m׃p"],[3,1,"וָ⁠אֹמַ֗ר שִׁמְעוּ־נָא֙ רָאשֵׁ֣י יַעֲקֹ֔ב וּ⁠קְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הֲ⁠ל֣וֹא לָ⁠כֶ֔ם לָ⁠דַ֖עַת אֶת־הַ⁠מִּשְׁפָּֽט׃","wá⁠ʼòma֗r şǐmĕʻẇ-náʼ֙ ráʼşé֣̌y yaʻàqò֔b ẇ⁠qĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l hà⁠l֣wòʼ lá⁠ke֔m lá⁠da֖ʻaţ ʼeţ-ha⁠mi̇şĕ̌páֽ̇t׃"],[3,2,"שֹׂ֥נְאֵי ט֖וֹב וְ⁠אֹ֣הֲבֵי רעה גֹּזְלֵ֤י עוֹרָ⁠ם֙ מֵֽ⁠עֲלֵי⁠הֶ֔ם וּ⁠שְׁאֵרָ֖⁠ם מֵ⁠עַ֥ל עַצְמוֹתָֽ⁠ם׃","şò֥̂nĕʼéy t֖wòb wĕ⁠ʼò֣hàbéy rʻh gò̇zĕlé֤y ʻwòrá⁠m֙ méֽ⁠ʻàléy⁠he֔m ẇ⁠şĕ̌ʼérá֖⁠m mé⁠ʻa֥l ʻaẕĕmwòţáֽ⁠m׃"],[3,3,"וַ⁠אֲשֶׁ֣ר אָכְלוּ֮ שְׁאֵ֣ר עַמִּ⁠י֒ וְ⁠עוֹרָ⁠ם֙ מֵ⁠עֲלֵי⁠הֶ֣ם הִפְשִׁ֔יטוּ וְ⁠אֶת־עַצְמֹֽתֵי⁠הֶ֖ם פִּצֵּ֑חוּ וּ⁠פָרְשׂוּ֙ כַּ⁠אֲשֶׁ֣ר בַּ⁠סִּ֔יר וּ⁠כְ⁠בָשָׂ֖ר בְּ⁠ת֥וֹךְ קַלָּֽחַת׃","wa⁠ʼàşě֣r ʼákĕlẇ֮ şĕ̌ʼé֣r ʻami̇⁠y֒ wĕ⁠ʻwòrá⁠m֙ mé⁠ʻàléy⁠he֣m hipĕşǐ֔ytẇ wĕ⁠ʼeţ-ʻaẕĕmòֽţéy⁠he֖m pi̇ẕé֑̇ẖẇ ẇ⁠párĕş̂ẇ֙ kȧ⁠ʼàşě֣r bȧ⁠si̇֔yr ẇ⁠kĕ⁠báşá֖̂r bĕ̇⁠ţ֥wòkĕ qaláֽ̇ẖaţ׃"],[3,4,"אָ֚ז יִזְעֲק֣וּ אֶל־יְהוָ֔ה וְ⁠לֹ֥א יַעֲנֶ֖ה אוֹתָ֑⁠ם וְ⁠יַסְתֵּ֨ר פָּנָ֤י⁠ו מֵ⁠הֶם֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא כַּ⁠אֲשֶׁ֥ר הֵרֵ֖עוּ מַעַלְלֵי⁠הֶֽם׃פ","ʼá֚z yizĕʻàq֣ẇ ʼel-yĕhwá֔h wĕ⁠lò֥ʼ yaʻàne֖h ʼwòţá֑⁠m wĕ⁠yasĕţé̇֨r pá̇ná֤y⁠w mé⁠hem֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ kȧ⁠ʼàşě֥r héré֖ʻẇ maʻalĕléy⁠heֽm׃p"],[3,5,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־הַ⁠נְּבִיאִ֖ים הַ⁠מַּתְעִ֣ים אֶת־עַמִּ֑⁠י הַ⁠נֹּשְׁכִ֤ים בְּ⁠שִׁנֵּי⁠הֶם֙ וְ⁠קָרְא֣וּ שָׁל֔וֹם וַ⁠אֲשֶׁר֙ לֹא־יִתֵּ֣ן עַל־פִּי⁠הֶ֔ם וְ⁠קִדְּשׁ֥וּ עָלָ֖י⁠ו מִלְחָמָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-ha⁠nĕ̇biyʼi֖ym ha⁠mȧţĕʻi֣ym ʼeţ-ʻami֑̇⁠y ha⁠nò̇şĕ̌ki֤ym bĕ̇⁠şǐné̇y⁠hem֙ wĕ⁠qárĕʼ֣ẇ şá̌l֔wòm wa⁠ʼàşěr֙ lòʼ-yiţé֣̇n ʻal-pi̇y⁠he֔m wĕ⁠qidĕ̇ş֥̌ẇ ʻálá֖y⁠w milĕẖámáֽh׃"],[3,6,"לָ⁠כֵ֞ן לַ֤יְלָה לָ⁠כֶם֙ מֵֽ⁠חָז֔וֹן וְ⁠חָשְׁכָ֥ה לָ⁠כֶ֖ם מִ⁠קְּסֹ֑ם וּ⁠בָ֤אָה הַ⁠שֶּׁ֨מֶשׁ֙ עַל־הַ⁠נְּבִיאִ֔ים וְ⁠קָדַ֥ר עֲלֵי⁠הֶ֖ם הַ⁠יּֽוֹם׃","lá⁠ké֞n la֤yĕláh lá⁠kem֙ méֽ⁠ẖáz֔wòn wĕ⁠ẖáşĕ̌ká֥h lá⁠ke֖m mi⁠qĕ̇sò֑m ẇ⁠bá֤ʼáh ha⁠şė̌֨meş̌֙ ʻal-ha⁠nĕ̇biyʼi֔ym wĕ⁠qáda֥r ʻàléy⁠he֖m ha⁠ẏֽwòm׃"],[3,7,"וּ⁠בֹ֣שׁוּ הַ⁠חֹזִ֗ים וְ⁠חָֽפְרוּ֙ הַ⁠קֹּ֣סְמִ֔ים וְ⁠עָט֥וּ עַל־שָׂפָ֖ם כֻּלָּ֑⁠ם כִּ֛י אֵ֥ין מַעֲנֵ֖ה אֱלֹהִֽים׃","ẇ⁠bò֣ş̌ẇ ha⁠ẖòzi֗ym wĕ⁠ẖáֽpĕrẇ֙ ha⁠qò֣̇sĕmi֔ym wĕ⁠ʻát֥ẇ ʻal-şá̂pá֖m ku̇lá֑̇⁠m ki֛̇y ʼé֥yn maʻàné֖h ʼèlòhiֽym׃"],[3,8,"וְ⁠אוּלָ֗ם אָנֹכִ֞י מָלֵ֤אתִי כֹ֨חַ֙ אֶת־ר֣וּחַ יְהוָ֔ה וּ⁠מִשְׁפָּ֖ט וּ⁠גְבוּרָ֑ה לְ⁠הַגִּ֤יד לְ⁠יַֽעֲקֹב֙ פִּשְׁע֔⁠וֹ וּ⁠לְ⁠יִשְׂרָאֵ֖ל חַטָּאתֽ⁠וֹ׃ס","wĕ⁠ʼẇlá֗m ʼánòki֞y málé֤ʼţiy kò֨ẖa֙ ʼeţ-r֣ẇẖa yĕhwá֔h ẇ⁠mişĕ̌pá֖̇t ẇ⁠gĕbẇrá֑h lĕ⁠hagi֤̇yd lĕ⁠yaֽʻàqòb֙ pi̇şĕ̌ʻ֔⁠wò ẇ⁠lĕ⁠yişĕ̂ráʼé֖l ẖatá̇ʼţֽ⁠wò׃s"],[3,9,"שִׁמְעוּ־נָ֣א זֹ֗את רָאשֵׁי֙ בֵּ֣ית יַעֲקֹ֔ב וּ⁠קְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הַֽ⁠מֲתַעֲבִ֣ים מִשְׁפָּ֔ט וְ⁠אֵ֥ת כָּל־הַ⁠יְשָׁרָ֖ה יְעַקֵּֽשׁוּ׃","şǐmĕʻẇ-ná֣ʼ zò֗ʼţ ráʼşé̌y֙ bé֣̇yţ yaʻàqò֔b ẇ⁠qĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l haֽ⁠màţaʻàbi֣ym mişĕ̌pá̇֔t wĕ⁠ʼé֥ţ ká̇l-ha⁠yĕşá̌rá֖h yĕʻaqéֽ̇ş̌ẇ׃"],[3,10,"בֹּנֶ֥ה צִיּ֖וֹן בְּ⁠דָמִ֑ים וִ⁠ירוּשָׁלִַ֖ם בְּ⁠עַוְלָֽה׃","bò̇ne֥h ẕiẏ֖wòn bĕ̇⁠dámi֑ym wi⁠yrẇşá̌lia֖m bĕ̇⁠ʻawĕláֽh׃"],[3,11,"רָאשֶׁ֣י⁠הָ ׀ בְּ⁠שֹׁ֣חַד יִשְׁפֹּ֗טוּ וְ⁠כֹהֲנֶ֨י⁠הָ֙ בִּ⁠מְחִ֣יר יוֹר֔וּ וּ⁠נְבִיאֶ֖י⁠הָ בְּ⁠כֶ֣סֶף יִקְסֹ֑מוּ וְ⁠עַל־יְהוָה֙ יִשָּׁעֵ֣נוּ לֵ⁠אמֹ֔ר הֲ⁠ל֤וֹא יְהוָה֙ בְּ⁠קִרְבֵּ֔⁠נוּ לֹֽא־תָב֥וֹא עָלֵ֖י⁠נוּ רָעָֽה׃","ráʼşě֣y⁠há ׀ bĕ̇⁠şò֣̌ẖad yişĕ̌pò̇֗tẇ wĕ⁠kòhàne֨y⁠há֙ bi̇⁠mĕẖi֣yr ywòr֔ẇ ẇ⁠nĕbiyʼe֖y⁠há bĕ̇⁠ke֣sep yiqĕsò֑mẇ wĕ⁠ʻal-yĕhwáh֙ yişá̇̌ʻé֣nẇ lé⁠ʼmò֔r hà⁠l֤wòʼ yĕhwáh֙ bĕ̇⁠qirĕbé̇֔⁠nẇ lòֽʼ-ţáb֥wòʼ ʻálé֖y⁠nẇ ráʻáֽh׃"],[3,12,"לָ⁠כֵן֙ בִּ⁠גְלַלְ⁠כֶ֔ם צִיּ֖וֹן שָׂדֶ֣ה תֵֽחָרֵ֑שׁ וִ⁠ירוּשָׁלִַ֨ם֙ עִיִּ֣ין תִּֽהְיֶ֔ה וְ⁠הַ֥ר הַ⁠בַּ֖יִת לְ⁠בָמ֥וֹת יָֽעַר׃פ","lá⁠kén֙ bi̇⁠gĕlalĕ⁠ke֔m ẕiẏ֖wòn şá̂de֣h ţéֽẖáré֑ş̌ wi⁠yrẇşá̌lia֨m֙ ʻiyi֣̇yn ţiֽ̇hĕye֔h wĕ⁠ha֥r ha⁠bȧ֖yiţ lĕ⁠bám֥wòţ yáֽʻar׃p"],[4,1,"וְ⁠הָיָ֣ה ׀ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֗ים יִ֠הְיֶה הַ֣ר בֵּית־יְהוָ֤ה נָכוֹן֙ בְּ⁠רֹ֣אשׁ הֶ⁠הָרִ֔ים וְ⁠נִשָּׂ֥א ה֖וּא מִ⁠גְּבָע֑וֹת וְ⁠נָהֲר֥וּ עָלָ֖י⁠ו עַמִּֽים׃","wĕ⁠háyá֣h ׀ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֗ym yi֠hĕyeh ha֣r bé̇yţ-yĕhwá֤h nákwòn֙ bĕ̇⁠rò֣ʼş̌ he⁠hári֔ym wĕ⁠nişá֥̇̂ʼ h֖ẇʼ mi⁠gĕ̇báʻ֑wòţ wĕ⁠náhàr֥ẇ ʻálá֖y⁠w ʻamiֽ̇ym׃"],[4,2,"וְֽ⁠הָלְכ֞וּ גּוֹיִ֣ם רַבִּ֗ים וְ⁠אָֽמְרוּ֙ לְכ֣וּ ׀ וְ⁠נַעֲלֶ֣ה אֶל־הַר־יְהוָ֗ה וְ⁠אֶל־בֵּית֙ אֱלֹהֵ֣י יַעֲקֹ֔ב וְ⁠יוֹרֵ֨⁠נוּ֙ מִ⁠דְּרָכָ֔י⁠ו וְ⁠נֵלְכָ֖ה בְּ⁠אֹֽרְחֹתָ֑י⁠ו כִּ֤י מִ⁠צִּיּוֹן֙ תֵּצֵ֣א תוֹרָ֔ה וּ⁠דְבַר־יְהוָ֖ה מִ⁠ירוּשָׁלִָֽם׃","wĕֽ⁠hálĕk֞ẇ ġwòyi֣m rabi̇֗ym wĕ⁠ʼáֽmĕrẇ֙ lĕk֣ẇ ׀ wĕ⁠naʻàle֣h ʼel-har-yĕhwá֗h wĕ⁠ʼel-bé̇yţ֙ ʼèlòhé֣y yaʻàqò֔b wĕ⁠ywòré֨⁠nẇ֙ mi⁠dĕ̇ráká֔y⁠w wĕ⁠nélĕká֖h bĕ̇⁠ʼòֽrĕẖòţá֑y⁠w ki֤̇y mi⁠ẕi̇ẏwòn֙ ţé̇ẕé֣ʼ ţwòrá֔h ẇ⁠dĕbar-yĕhwá֖h mi⁠yrẇşá̌liáֽm׃"],[4,3,"וְ⁠שָׁפַ֗ט בֵּ֚ין עַמִּ֣ים רַבִּ֔ים וְ⁠הוֹכִ֛יחַ לְ⁠גוֹיִ֥ם עֲצֻמִ֖ים עַד־רָח֑וֹק וְ⁠כִתְּת֨וּ חַרְבֹתֵי⁠הֶ֜ם לְ⁠אִתִּ֗ים וַ⁠חֲנִיתֹֽתֵי⁠הֶם֙ לְ⁠מַזְמֵר֔וֹת לֹֽא־יִשְׂא֞וּ גּ֤וֹי אֶל־גּוֹי֙ חֶ֔רֶב וְ⁠לֹא־יִלְמְד֥וּ⁠ן ע֖וֹד מִלְחָמָֽה׃","wĕ⁠şá̌pa֗t bé֚̇yn ʻami֣̇ym rabi̇֔ym wĕ⁠hwòki֛yẖa lĕ⁠gwòyi֥m ʻàẕumi֖ym ʻad-ráẖ֑wòq wĕ⁠kiţĕ̇ţ֨ẇ ẖarĕbòţéy⁠he֜m lĕ⁠ʼiţi̇֗ym wa⁠ẖàniyţòֽţéy⁠hem֙ lĕ⁠mazĕmér֔wòţ lòֽʼ-yişĕ̂ʼ֞ẇ ġ֤wòy ʼel-ġwòy֙ ẖe֔reb wĕ⁠lòʼ-yilĕmĕd֥ẇ⁠n ʻ֖wòd milĕẖámáֽh׃"],[4,4,"וְ⁠יָשְׁב֗וּ אִ֣ישׁ תַּ֧חַת גַּפְנ֛⁠וֹ וְ⁠תַ֥חַת תְּאֵנָת֖⁠וֹ וְ⁠אֵ֣ין מַחֲרִ֑יד כִּי־פִ֛י יְהוָ֥ה צְבָא֖וֹת דִּבֵּֽר׃","wĕ⁠yáşĕ̌b֗ẇ ʼi֣yş̌ ţȧ֧ẖaţ gȧpĕn֛⁠wò wĕ⁠ţa֥ẖaţ ţĕ̇ʼénáţ֖⁠wò wĕ⁠ʼé֣yn maẖàri֑yd ki̇y-pi֛y yĕhwá֥h ẕĕbáʼ֖wòţ di̇béֽ̇r׃"],[4,5,"כִּ֚י כָּל־הָ֣⁠עַמִּ֔ים יֵלְכ֕וּ אִ֖ישׁ בְּ⁠שֵׁ֣ם אֱלֹהָ֑י⁠ו וַ⁠אֲנַ֗חְנוּ נֵלֵ֛ךְ בְּ⁠שֵׁם־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃פ","ki֚̇y ká̇l-há֣⁠ʻami̇֔ym yélĕk֕ẇ ʼi֖yş̌ bĕ̇⁠şé֣̌m ʼèlòhá֑y⁠w wa⁠ʼàna֗ẖĕnẇ nélé֛kĕ bĕ̇⁠şé̌m-yĕhwá֥h ʼèlòhé֖y⁠nẇ lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃p"],[4,6,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻם־יְהוָ֗ה אֹֽסְפָה֙ הַ⁠צֹּ֣לֵעָ֔ה וְ⁠הַ⁠נִּדָּחָ֖ה אֲקַבֵּ֑צָה וַ⁠אֲשֶׁ֖ר הֲרֵעֹֽתִי׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼum-yĕhwá֗h ʼòֽsĕpáh֙ ha⁠ẕò֣̇léʻá֔h wĕ⁠ha⁠ni̇dá̇ẖá֖h ʼàqabé֑̇ẕáh wa⁠ʼàşě֖r hàréʻòֽţiy׃"],[4,7,"וְ⁠שַׂמְתִּ֤י אֶת־הַ⁠צֹּֽלֵעָה֙ לִ⁠שְׁאֵרִ֔ית וְ⁠הַ⁠נַּהֲלָאָ֖ה לְ⁠ג֣וֹי עָצ֑וּם וּ⁠מָלַ֨ךְ יְהוָ֤ה עֲלֵי⁠הֶם֙ בְּ⁠הַ֣ר צִיּ֔וֹן מֵ⁠עַתָּ֖ה וְ⁠עַד־עוֹלָֽם׃פ","wĕ⁠şâmĕţi֤̇y ʼeţ-ha⁠ẕòֽ̇léʻáh֙ li⁠şĕ̌ʼéri֔yţ wĕ⁠ha⁠nȧhàláʼá֖h lĕ⁠g֣wòy ʻáẕ֑ẇm ẇ⁠mála֨kĕ yĕhwá֤h ʻàléy⁠hem֙ bĕ̇⁠ha֣r ẕiẏ֔wòn mé⁠ʻaţá֖̇h wĕ⁠ʻad-ʻwòláֽm׃p"],[4,8,"וְ⁠אַתָּ֣ה מִגְדַּל־עֵ֗דֶר עֹ֛פֶל בַּת־צִיּ֖וֹן עָדֶ֣י⁠ךָ תֵּאתֶ֑ה וּ⁠בָאָ֗ה הַ⁠מֶּמְשָׁלָה֙ הָ⁠רִ֣אשֹׁנָ֔ה מַמְלֶ֖כֶת לְ⁠בַ֥ת־יְרוּשָׁלִָֽם׃","wĕ⁠ʼaţá֣̇h migĕdȧl-ʻé֗der ʻò֛pel bȧţ-ẕiẏ֖wòn ʻáde֣y⁠ká ţé̇ʼţe֑h ẇ⁠báʼá֗h ha⁠mėmĕşá̌láh֙ há⁠ri֣ʼşò̌ná֔h mamĕle֖keţ lĕ⁠ba֥ţ-yĕrẇşá̌liáֽm׃"],[4,9,"עַתָּ֕ה לָ֥⁠מָּה תָרִ֖יעִי רֵ֑עַ הֲ⁠מֶ֣לֶךְ אֵֽין־בָּ֗⁠ךְ אִֽם־יוֹעֲצֵ⁠ךְ֙ אָבָ֔ד כִּֽי־הֶחֱזִיקֵ֥⁠ךְ חִ֖יל כַּ⁠יּוֹלֵדָֽה׃","ʻaţá̇֕h lá֥⁠má̇h ţári֖yʻiy ré֑ʻa hà⁠me֣lekĕ ʼéֽyn-bá̇֗⁠kĕ ʼiֽm-ywòʻàẕé⁠kĕ֙ ʼábá֔d kiֽ̇y-heẖèziyqé֥⁠kĕ ẖi֖yl kȧ⁠ẏwòlédáֽh׃"],[4,10,"ח֧וּלִי וָ⁠גֹ֛חִי בַּת־צִיּ֖וֹן כַּ⁠יּֽוֹלֵדָ֑ה כִּֽי־עַתָּה֩ תֵצְאִ֨י מִ⁠קִּרְיָ֜ה וְ⁠שָׁכַ֣נְתְּ בַּ⁠שָּׂדֶ֗ה וּ⁠בָ֤את עַד־בָּבֶל֙ שָׁ֣ם תִּנָּצֵ֔לִי שָׁ֚ם יִגְאָלֵ֣⁠ךְ יְהוָ֔ה מִ⁠כַּ֖ף אֹיְבָֽיִ⁠ךְ׃","ẖ֧ẇliy wá⁠gò֛ẖiy bȧţ-ẕiẏ֖wòn kȧ⁠ẏֽwòlédá֑h kiֽ̇y-ʻaţá̇h֩ ţéẕĕʼi֨y mi⁠qi̇rĕyá֜h wĕ⁠şá̌ka֣nĕţĕ̇ bȧ⁠şá̇̂de֗h ẇ⁠bá֤ʼţ ʻad-bá̇bel֙ şá֣̌m ţi̇ná̇ẕé֔liy şá֚̌m yigĕʼálé֣⁠kĕ yĕhwá֔h mi⁠kȧ֖p ʼòyĕbáֽyi⁠kĕ׃"],[4,11,"וְ⁠עַתָּ֛ה נֶאֶסְפ֥וּ עָלַ֖יִ⁠ךְ גּוֹיִ֣ם רַבִּ֑ים הָ⁠אֹמְרִ֣ים תֶּחֱנָ֔ף וְ⁠תַ֥חַז בְּ⁠צִיּ֖וֹן עֵינֵֽי⁠נוּ׃","wĕ⁠ʻaţá֛̇h neʼesĕp֥ẇ ʻála֖yi⁠kĕ ġwòyi֣m rabi֑̇ym há⁠ʼòmĕri֣ym ţėẖèná֔p wĕ⁠ţa֥ẖaz bĕ̇⁠ẕiẏ֖wòn ʻéynéֽy⁠nẇ׃"],[4,12,"וְ⁠הֵ֗מָּה לֹ֤א יָֽדְעוּ֙ מַחְשְׁב֣וֹת יְהוָ֔ה וְ⁠לֹ֥א הֵבִ֖ינוּ עֲצָת֑⁠וֹ כִּ֥י קִבְּצָ֖⁠ם כֶּ⁠עָמִ֥יר גֹּֽרְנָ⁠ה׃","wĕ⁠hé֗má̇h lò֤ʼ yáֽdĕʻẇ֙ maẖĕşĕ̌b֣wòţ yĕhwá֔h wĕ⁠lò֥ʼ hébi֖ynẇ ʻàẕáţ֑⁠wò ki֥̇y qibĕ̇ẕá֖⁠m kė⁠ʻámi֥yr gòֽ̇rĕná⁠h׃"],[4,13,"ק֧וּמִי וָ⁠ד֣וֹשִׁי בַת־צִיּ֗וֹן כִּֽי־קַרְנֵ֞⁠ךְ אָשִׂ֤ים בַּרְזֶל֙ וּ⁠פַרְסֹתַ֨יִ⁠ךְ֙ אָשִׂ֣ים נְחוּשָׁ֔ה וַ⁠הֲדִקּ֖וֹת עַמִּ֣ים רַבִּ֑ים וְ⁠הַחֲרַמְתִּ֤י לַֽ⁠יהוָה֙ בִּצְעָ֔⁠ם וְ⁠חֵילָ֖⁠ם לַ⁠אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","q֧ẇmiy wá⁠d֣wòşǐy baţ-ẕiẏ֗wòn kiֽ̇y-qarĕné֞⁠kĕ ʼáşî֤ym bȧrĕzel֙ ẇ⁠parĕsòţa֨yi⁠kĕ֙ ʼáşî֣ym nĕẖẇşá̌֔h wa⁠hàdiq֖̇wòţ ʻami֣̇ym rabi֑̇ym wĕ⁠haẖàramĕţi֤̇y laֽ⁠yhwáh֙ bi̇ẕĕʻá֔⁠m wĕ⁠ẖéylá֖⁠m la⁠ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[5,1,"עַתָּה֙ תִּתְגֹּדְדִ֣י בַת־גְּד֔וּד מָצ֖וֹר שָׂ֣ם עָלֵ֑י⁠נוּ בַּ⁠שֵּׁ֨בֶט֙ יַכּ֣וּ עַֽל־הַ⁠לְּחִ֔י אֵ֖ת שֹׁפֵ֥ט יִשְׂרָאֵֽל׃ס","ʻaţá̇h֙ ţi̇ţĕgò̇dĕdi֣y baţ-gĕ̇d֔ẇd máẕ֖wòr şá֣̂m ʻálé֑y⁠nẇ bȧ⁠şé̇̌֨bet֙ yak֣̇ẇ ʻaֽl-ha⁠lĕ̇ẖi֔y ʼé֖ţ şò̌pé֥t yişĕ̂ráʼéֽl׃s"],[5,2,"וְ⁠אַתָּ֞ה בֵּֽית־לֶ֣חֶם אֶפְרָ֗תָה צָעִיר֙ לִֽ⁠הְיוֹת֙ בְּ⁠אַלְפֵ֣י יְהוּדָ֔ה מִמְּ⁠ךָ֙ לִ֣⁠י יֵצֵ֔א לִֽ⁠הְי֥וֹת מוֹשֵׁ֖ל בְּ⁠יִשְׂרָאֵ֑ל וּ⁠מוֹצָאֹתָ֥י⁠ו מִ⁠קֶּ֖דֶם מִ⁠ימֵ֥י עוֹלָֽם׃","wĕ⁠ʼaţá̇֞h béֽ̇yţ-le֣ẖem ʼepĕrá֗ţáh ẕáʻiyr֙ liֽ⁠hĕywòţ֙ bĕ̇⁠ʼalĕpé֣y yĕhẇdá֔h mimĕ̇⁠ká֙ li֣⁠y yéẕé֔ʼ liֽ⁠hĕy֥wòţ mwòşé֖̌l bĕ̇⁠yişĕ̂ráʼé֑l ẇ⁠mwòẕáʼòţá֥y⁠w mi⁠qė֖dem mi⁠ymé֥y ʻwòláֽm׃"],[5,3,"לָ⁠כֵ֣ן יִתְּנֵ֔⁠ם עַד־עֵ֥ת יוֹלֵדָ֖ה יָלָ֑דָה וְ⁠יֶ֣תֶר אֶחָ֔י⁠ו יְשׁוּב֖וּ⁠ן עַל־בְּנֵ֥י יִשְׂרָאֵֽל׃","lá⁠ké֣n yiţĕ̇né֔⁠m ʻad-ʻé֥ţ ywòlédá֖h yálá֑dáh wĕ⁠ye֣ţer ʼeẖá֔y⁠w yĕş̌ẇb֖ẇ⁠n ʻal-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[5,4,"וְ⁠עָמַ֗ד וְ⁠רָעָה֙ בְּ⁠עֹ֣ז יְהוָ֔ה בִּ⁠גְא֕וֹן שֵׁ֖ם יְהוָ֣ה אֱלֹהָ֑י⁠ו וְ⁠יָשָׁ֕בוּ כִּֽי־עַתָּ֥ה יִגְדַּ֖ל עַד־אַפְסֵי־אָֽרֶץ׃","wĕ⁠ʻáma֗d wĕ⁠ráʻáh֙ bĕ̇⁠ʻò֣z yĕhwá֔h bi̇⁠gĕʼ֕wòn şé֖̌m yĕhwá֣h ʼèlòhá֑y⁠w wĕ⁠yáşá̌֕bẇ kiֽ̇y-ʻaţá֥̇h yigĕdȧ֖l ʻad-ʼapĕséy-ʼáֽreẕ׃"],[5,5,"וְ⁠הָיָ֥ה זֶ֖ה שָׁל֑וֹם אַשּׁ֣וּר ׀ כִּֽי־יָב֣וֹא בְ⁠אַרְצֵ֗⁠נוּ וְ⁠כִ֤י יִדְרֹךְ֙ בְּ⁠אַרְמְנֹתֵ֔י⁠נוּ וַ⁠הֲקֵמֹ֤נוּ עָלָי⁠ו֙ שִׁבְעָ֣ה רֹעִ֔ים וּ⁠שְׁמֹנָ֖ה נְסִיכֵ֥י אָדָֽם׃","wĕ⁠háyá֥h ze֖h şá̌l֑wòm ʼaş֣̇̌ẇr ׀ kiֽ̇y-yáb֣wòʼ bĕ⁠ʼarĕẕé֗⁠nẇ wĕ⁠ki֤y yidĕròkĕ֙ bĕ̇⁠ʼarĕmĕnòţé֔y⁠nẇ wa⁠hàqémò֤nẇ ʻáláy⁠w֙ şǐbĕʻá֣h ròʻi֔ym ẇ⁠şĕ̌mòná֖h nĕsiyké֥y ʼádáֽm׃"],[5,6,"וְ⁠רָע֞וּ אֶת־אֶ֤רֶץ אַשּׁוּר֙ בַּ⁠חֶ֔רֶב וְ⁠אֶת־אֶ֥רֶץ נִמְרֹ֖ד בִּ⁠פְתָחֶ֑י⁠הָ וְ⁠הִצִּיל֙ מֵֽ⁠אַשּׁ֔וּר כִּֽי־יָב֣וֹא בְ⁠אַרְצֵ֔⁠נוּ וְ⁠כִ֥י יִדְרֹ֖ךְ בִּ⁠גְבוּלֵֽ⁠נוּ׃ס","wĕ⁠ráʻ֞ẇ ʼeţ-ʼe֤reẕ ʼaş̇̌ẇr֙ bȧ⁠ẖe֔reb wĕ⁠ʼeţ-ʼe֥reẕ nimĕrò֖d bi̇⁠pĕţáẖe֑y⁠há wĕ⁠hiẕi̇yl֙ méֽ⁠ʼaş̇̌֔ẇr kiֽ̇y-yáb֣wòʼ bĕ⁠ʼarĕẕé֔⁠nẇ wĕ⁠ki֥y yidĕrò֖kĕ bi̇⁠gĕbẇléֽ⁠nẇ׃s"],[5,7,"וְ⁠הָיָ֣ה ׀ שְׁאֵרִ֣ית יַעֲקֹ֗ב בְּ⁠קֶ֨רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּ⁠טַל֙ מֵ⁠אֵ֣ת יְהוָ֔ה כִּ⁠רְבִיבִ֖ים עֲלֵי־עֵ֑שֶׂב אֲשֶׁ֤ר לֹֽא־יְקַוֶּה֙ לְ⁠אִ֔ישׁ וְ⁠לֹ֥א יְיַחֵ֖ל לִ⁠בְנֵ֥י אָדָֽם׃","wĕ⁠háyá֣h ׀ şĕ̌ʼéri֣yţ yaʻàqò֗b bĕ̇⁠qe֨reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇⁠tal֙ mé⁠ʼé֣ţ yĕhwá֔h ki̇⁠rĕbiybi֖ym ʻàléy-ʻé֑şêb ʼàşě֤r lòֽʼ-yĕqawėh֙ lĕ⁠ʼi֔yş̌ wĕ⁠lò֥ʼ yĕyaẖé֖l li⁠bĕné֥y ʼádáֽm׃"],[5,8,"וְ⁠הָיָה֩ שְׁאֵרִ֨ית יַעֲקֹ֜ב בַּ⁠גּוֹיִ֗ם בְּ⁠קֶ֨רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּ⁠אַרְיֵה֙ בְּ⁠בַהֲמ֣וֹת יַ֔עַר כִּ⁠כְפִ֖יר בְּ⁠עֶדְרֵי צֹ֑אן אֲשֶׁ֧ר אִם עָבַ֛ר וְ⁠רָמַ֥ס וְ⁠טָרַ֖ף וְ⁠אֵ֥ין מַצִּֽיל׃","wĕ⁠háyáh֩ şĕ̌ʼéri֨yţ yaʻàqò֜b bȧ⁠ġwòyi֗m bĕ̇⁠qe֨reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇⁠ʼarĕyéh֙ bĕ̇⁠bahàm֣wòţ ya֔ʻar ki̇⁠kĕpi֖yr bĕ̇⁠ʻedĕréy ẕò֑ʼn ʼàşě֧r ʼim ʻába֛r wĕ⁠ráma֥s wĕ⁠tára֖p wĕ⁠ʼé֥yn maẕiֽ̇yl׃"],[5,9,"תָּרֹ֥ם יָדְ⁠ךָ֖ עַל־צָרֶ֑י⁠ךָ וְ⁠כָל־אֹיְבֶ֖י⁠ךָ יִכָּרֵֽתוּ׃פ","ţá̇rò֥m yádĕ⁠ká֖ ʻal-ẕáre֑y⁠ká wĕ⁠kál-ʼòyĕbe֖y⁠ká yiká̇réֽţẇ׃p"],[5,10,"וְ⁠הָיָ֤ה בַ⁠יּוֹם־הַ⁠הוּא֙ נְאֻם־יְהוָ֔ה וְ⁠הִכְרַתִּ֥י סוּסֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠הַאֲבַדְתִּ֖י מַרְכְּבֹתֶֽי⁠ךָ׃","wĕ⁠háyá֤h ba⁠ẏwòm-ha⁠hẇʼ֙ nĕʼum-yĕhwá֔h wĕ⁠hikĕraţi֥̇y sẇse֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠haʼàbadĕţi֖̇y marĕkĕ̇bòţeֽy⁠ká׃"],[5,11,"וְ⁠הִכְרַתִּ֖י עָרֵ֣י אַרְצֶ֑⁠ךָ וְ⁠הָרַסְתִּ֖י כָּל־מִבְצָרֶֽי⁠ךָ׃","wĕ⁠hikĕraţi֖̇y ʻáré֣y ʼarĕẕe֑⁠ká wĕ⁠hárasĕţi֖̇y ká̇l-mibĕẕáreֽy⁠ká׃"],[5,12,"וְ⁠הִכְרַתִּ֥י כְשָׁפִ֖ים מִ⁠יָּדֶ֑⁠ךָ וּֽ⁠מְעוֹנְנִ֖ים לֹ֥א יִֽהְיוּ־לָֽ⁠ךְ׃","wĕ⁠hikĕraţi֥̇y kĕşá̌pi֖ym mi⁠yá̇de֑⁠ká ẇֽ⁠mĕʻwònĕni֖ym lò֥ʼ yiֽhĕyẇ-láֽ⁠kĕ׃"],[5,13,"וְ⁠הִכְרַתִּ֧י פְסִילֶ֛י⁠ךָ וּ⁠מַצֵּבוֹתֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠לֹֽא־תִשְׁתַּחֲוֶ֥ה ע֖וֹד לְ⁠מַעֲשֵׂ֥ה יָדֶֽי⁠ךָ׃","wĕ⁠hikĕraţi֧̇y pĕsiyle֛y⁠ká ẇ⁠maẕé̇bwòţe֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠lòֽʼ-ţişĕ̌ţȧẖàwe֥h ʻ֖wòd lĕ⁠maʻàşé֥̂h yádeֽy⁠ká׃"],[5,14,"וְ⁠נָתַשְׁתִּ֥י אֲשֵׁירֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠הִשְׁמַדְתִּ֖י עָרֶֽי⁠ךָ׃","wĕ⁠náţaşĕ̌ţi֥̇y ʼàşé̌yre֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠hişĕ̌madĕţi֖̇y ʻáreֽy⁠ká׃"],[5,15,"וְ⁠עָשִׂ֜יתִי בְּ⁠אַ֧ף וּ⁠בְ⁠חֵמָ֛ה נָקָ֖ם אֶת־הַ⁠גּוֹיִ֑ם אֲשֶׁ֖ר לֹ֥א שָׁמֵֽעוּ׃ס","wĕ⁠ʻáşî֜yţiy bĕ̇⁠ʼa֧p ẇ⁠bĕ⁠ẖémá֛h náqá֖m ʼeţ-ha⁠ġwòyi֑m ʼàşě֖r lò֥ʼ şá̌méֽʻẇ׃s"],[6,1,"שִׁמְעוּ־נָ֕א אֵ֥ת אֲשֶׁר־יְהוָ֖ה אֹמֵ֑ר ק֚וּם רִ֣יב אֶת־הֶ⁠הָרִ֔ים וְ⁠תִשְׁמַ֥עְנָה הַ⁠גְּבָע֖וֹת קוֹלֶֽ⁠ךָ׃","şǐmĕʻẇ-ná֕ʼ ʼé֥ţ ʼàşěr-yĕhwá֖h ʼòmé֑r q֚ẇm ri֣yb ʼeţ-he⁠hári֔ym wĕ⁠ţişĕ̌ma֥ʻĕnáh ha⁠gĕ̇báʻ֖wòţ qwòleֽ⁠ká׃"],[6,2,"שִׁמְע֤וּ הָרִים֙ אֶת־רִ֣יב יְהוָ֔ה וְ⁠הָ⁠אֵתָנִ֖ים מֹ֣סְדֵי אָ֑רֶץ כִּ֣י רִ֤יב לַֽ⁠יהוָה֙ עִם־עַמּ֔⁠וֹ וְ⁠עִם־יִשְׂרָאֵ֖ל יִתְוַכָּֽח׃","şǐmĕʻ֤ẇ háriym֙ ʼeţ-ri֣yb yĕhwá֔h wĕ⁠há⁠ʼéţáni֖ym mò֣sĕdéy ʼá֑reẕ ki֣̇y ri֤yb laֽ⁠yhwáh֙ ʻim-ʻaṁ֔⁠wò wĕ⁠ʻim-yişĕ̂ráʼé֖l yiţĕwakáֽ̇ẖ׃"],[6,3,"עַמִּ֛⁠י מֶה־עָשִׂ֥יתִי לְ⁠ךָ֖ וּ⁠מָ֣ה הֶלְאֵתִ֑י⁠ךָ עֲנֵ֥ה בִּֽ⁠י׃","ʻami֛̇⁠y meh-ʻáşî֥yţiy lĕ⁠ká֖ ẇ⁠má֣h helĕʼéţi֑y⁠ká ʻàné֥h biֽ̇⁠y׃"],[6,4,"כִּ֤י הֶעֱלִתִ֨י⁠ךָ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם וּ⁠מִ⁠בֵּ֥ית עֲבָדִ֖ים פְּדִיתִ֑י⁠ךָ וָ⁠אֶשְׁלַ֣ח לְ⁠פָנֶ֔י⁠ךָ אֶת־מֹשֶׁ֖ה אַהֲרֹ֥ן וּ⁠מִרְיָֽם׃","ki֤̇y heʻèliţi֨y⁠ká֙ mé⁠ʼe֣reẕ miẕĕra֔yim ẇ⁠mi⁠bé֥̇yţ ʻàbádi֖ym pĕ̇diyţi֑y⁠ká wá⁠ʼeşĕ̌la֣ẖ lĕ⁠páne֔y⁠ká ʼeţ-mòşě֖h ʼahàrò֥n ẇ⁠mirĕyáֽm׃"],[6,5,"עַמִּ֗⁠י זְכָר־נָא֙ מַה־יָּעַ֗ץ בָּלָק֙ מֶ֣לֶךְ מוֹאָ֔ב וּ⁠מֶה־עָנָ֥ה אֹת֖⁠וֹ בִּלְעָ֣ם בֶּן־בְּע֑וֹר מִן־הַ⁠שִּׁטִּים֙ עַד־הַ⁠גִּלְגָּ֔ל לְמַ֕עַן דַּ֖עַת צִדְק֥וֹת יְהוָֽה׃","ʻami̇֗⁠y zĕkár-náʼ֙ mah-yá̇ʻa֗ẕ bá̇láq֙ me֣lekĕ mwòʼá֔b ẇ⁠meh-ʻáná֥h ʼòţ֖⁠wò bi̇lĕʻá֣m bėn-bĕ̇ʻ֑wòr min-ha⁠şi̇̌ti̇ym֙ ʻad-ha⁠gi̇lĕgá̇֔l lĕma֕ʻan dȧ֖ʻaţ ẕidĕq֥wòţ yĕhwáֽh׃"],[6,6,"בַּ⁠מָּה֙ אֲקַדֵּ֣ם יְהוָ֔ה אִכַּ֖ף לֵ⁠אלֹהֵ֣י מָר֑וֹם הַ⁠אֲקַדְּמֶ֣⁠נּוּ בְ⁠עוֹל֔וֹת בַּ⁠עֲגָלִ֖ים בְּנֵ֥י שָׁנָֽה׃","bȧ⁠má̇h֙ ʼàqadé֣̇m yĕhwá֔h ʼikȧ֖p lé⁠ʼlòhé֣y már֑wòm ha⁠ʼàqadĕ̇me֣⁠ṅẇ bĕ⁠ʻwòl֔wòţ bȧ⁠ʻàgáli֖ym bĕ̇né֥y şá̌náֽh׃"],[6,7,"הֲ⁠יִרְצֶ֤ה יְהוָה֙ בְּ⁠אַלְפֵ֣י אֵילִ֔ים בְּ⁠רִֽבְב֖וֹת נַֽחֲלֵי־שָׁ֑מֶן הַ⁠אֶתֵּ֤ן בְּכוֹרִ⁠י֙ פִּשְׁעִ֔⁠י פְּרִ֥י בִטְנִ֖⁠י חַטַּ֥את נַפְשִֽׁ⁠י׃","hà⁠yirĕẕe֤h yĕhwáh֙ bĕ̇⁠ʼalĕpé֣y ʼéyli֔ym bĕ̇⁠riֽbĕb֖wòţ naֽẖàléy-şá֑̌men ha⁠ʼeţé֤̇n bĕ̇kwòri⁠y֙ pi̇şĕ̌ʻi֔⁠y pĕ̇ri֥y bitĕni֖⁠y ẖatȧ֥ʼţ napĕşǐֽ⁠y׃"],[6,8,"הִגִּ֥יד לְ⁠ךָ֛ אָדָ֖ם מַה־טּ֑וֹב וּ⁠מָֽה־יְהוָ֞ה דּוֹרֵ֣שׁ מִמְּ⁠ךָ֗ כִּ֣י אִם־עֲשׂ֤וֹת מִשְׁפָּט֙ וְ⁠אַ֣הֲבַת חֶ֔סֶד וְ⁠הַצְנֵ֥עַ לֶ֖כֶת עִם־אֱלֹהֶֽי⁠ךָ׃פ","higi֥̇yd lĕ⁠ká֛ ʼádá֖m mah-ṫ֑wòb ẇ⁠máֽh-yĕhwá֞h ḋwòré֣ş̌ mimĕ̇⁠ká֗ ki֣̇y ʼim-ʻàş֤̂wòţ mişĕ̌pá̇t֙ wĕ⁠ʼa֣hàbaţ ẖe֔sed wĕ⁠haẕĕné֥ʻa le֖keţ ʻim-ʼèlòheֽy⁠ká׃p"],[6,9,"ק֤וֹל יְהוָה֙ לָ⁠עִ֣יר יִקְרָ֔א וְ⁠תוּשִׁיָּ֖ה יִרְאֶ֣ה שְׁמֶ֑⁠ךָ שִׁמְע֥וּ מַטֶּ֖ה וּ⁠מִ֥י יְעָדָֽ⁠הּ׃","q֤wòl yĕhwáh֙ lá⁠ʻi֣yr yiqĕrá֔ʼ wĕ⁠ţẇşǐyá֖̇h yirĕʼe֣h şĕ̌me֑⁠ká şǐmĕʻ֥ẇ matė֖h ẇ⁠mi֥y yĕʻádáֽ⁠ḣ׃"],[6,10,"ע֗וֹד הַ⁠אִשׁ֙ בֵּ֣ית רָשָׁ֔ע אֹצְר֖וֹת רֶ֑שַׁע וְ⁠אֵיפַ֥ת רָז֖וֹן זְעוּמָֽה׃","ʻ֗wòd ha⁠ʼiş̌֙ bé֣̇yţ ráşá̌֔ʻ ʼòẕĕr֖wòţ re֑şǎʻ wĕ⁠ʼéypa֥ţ ráz֖wòn zĕʻẇmáֽh׃"],[6,11,"הַ⁠אֶזְכֶּ֖ה בְּ⁠מֹ֣אזְנֵי רֶ֑שַׁע וּ⁠בְ⁠כִ֖יס אַבְנֵ֥י מִרְמָֽה׃","ha⁠ʼezĕkė֖h bĕ̇⁠mò֣ʼzĕnéy re֑şǎʻ ẇ⁠bĕ⁠ki֖ys ʼabĕné֥y mirĕmáֽh׃"],[6,12,"אֲשֶׁ֤ר עֲשִׁירֶ֨י⁠הָ֙ מָלְא֣וּ חָמָ֔ס וְ⁠יֹשְׁבֶ֖י⁠הָ דִּבְּרוּ־שָׁ֑קֶר וּ⁠לְשׁוֹנָ֖⁠ם רְמִיָּ֥ה בְּ⁠פִי⁠הֶֽם׃","ʼàşě֤r ʻàşǐyre֨y⁠há֙ málĕʼ֣ẇ ẖámá֔s wĕ⁠yòşĕ̌be֖y⁠há di̇bĕ̇rẇ-şá֑̌qer ẇ⁠lĕş̌wòná֖⁠m rĕmiyá֥̇h bĕ̇⁠piy⁠heֽm׃"],[6,13,"וְ⁠גַם־אֲנִ֖י הֶחֱלֵ֣יתִי הַכּוֹתֶ֑⁠ךָ הַשְׁמֵ֖ם עַל־חַטֹּאתֶֽ⁠ךָ׃","wĕ⁠gam-ʼàni֖y heẖèlé֣yţiy hak̇wòţe֑⁠ká haşĕ̌mé֖m ʻal-ẖatò̇ʼţeֽ⁠ká׃"],[6,14,"אַתָּ֤ה תֹאכַל֙ וְ⁠לֹ֣א תִשְׂבָּ֔ע וְ⁠יֶשְׁחֲ⁠ךָ֖ בְּ⁠קִרְבֶּ֑⁠ךָ וְ⁠תַסֵּג֙ וְ⁠לֹ֣א תַפְלִ֔יט וַ⁠אֲשֶׁ֥ר תְּפַלֵּ֖ט לַ⁠חֶ֥רֶב אֶתֵּֽן׃","ʼaţá֤̇h ţòʼkal֙ wĕ⁠lò֣ʼ ţişĕ̂bá̇֔ʻ wĕ⁠yeşĕ̌ẖà⁠ká֖ bĕ̇⁠qirĕbė֑⁠ká wĕ⁠ţasé̇g֙ wĕ⁠lò֣ʼ ţapĕli֔yt wa⁠ʼàşě֥r ţĕ̇palé֖̇t la⁠ẖe֥reb ʼeţéֽ̇n׃"],[6,15,"אַתָּ֥ה תִזְרַ֖ע וְ⁠לֹ֣א תִקְצ֑וֹר אַתָּ֤ה תִדְרֹֽךְ־זַ֨יִת֙ וְ⁠לֹא־תָס֣וּךְ שֶׁ֔מֶן וְ⁠תִיר֖וֹשׁ וְ⁠לֹ֥א תִשְׁתֶּה־יָּֽיִן׃","ʼaţá֥̇h ţizĕra֖ʻ wĕ⁠lò֣ʼ ţiqĕẕ֑wòr ʼaţá֤̇h ţidĕròֽkĕ-za֨yiţ֙ wĕ⁠lòʼ-ţás֣ẇkĕ şě֔men wĕ⁠ţiyr֖wòş̌ wĕ⁠lò֥ʼ ţişĕ̌ţėh-yáֽ̇yin׃"],[6,16,"וְ⁠יִשְׁתַּמֵּ֞ר חֻקּ֣וֹת עָמְרִ֗י וְ⁠כֹל֙ מַעֲשֵׂ֣ה בֵית־אַחְאָ֔ב וַ⁠תֵּלְכ֖וּ בְּ⁠מֹֽעֲצוֹתָ֑⁠ם לְמַעַן֩ תִּתִּ֨⁠י אֹתְ⁠ךָ֜ לְ⁠שַׁמָּ֗ה וְ⁠יֹשְׁבֶ֨י⁠הָ֙ לִ⁠שְׁרֵקָ֔ה וְ⁠חֶרְפַּ֥ת עַמִּ֖⁠י תִּשָּֽׂאוּ׃פ","wĕ⁠yişĕ̌ţȧmé̇֞r ẖuq֣̇wòţ ʻámĕri֗y wĕ⁠kòl֙ maʻàşé֣̂h béyţ-ʼaẖĕʼá֔b wa⁠ţé̇lĕk֖ẇ bĕ̇⁠mòֽʻàẕwòţá֑⁠m lĕmaʻan֩ ţi̇ţi̇֨⁠y ʼòţĕ⁠ká֜ lĕ⁠şǎmá̇֗h wĕ⁠yòşĕ̌be֨y⁠há֙ li⁠şĕ̌réqá֔h wĕ⁠ẖerĕpȧ֥ţ ʻami֖̇⁠y ţi̇şáֽ̇̂ʼẇ׃p"],[7,1,"אַ֣לְלַי לִ֗⁠י כִּ֤י הָיִ֨יתִי֙ כְּ⁠אָסְפֵּי־קַ֔יִץ כְּ⁠עֹלְלֹ֖ת בָּצִ֑יר אֵין־אֶשְׁכּ֣וֹל לֶ⁠אֱכ֔וֹל בִּכּוּרָ֖ה אִוְּתָ֥ה נַפְשִֽׁ⁠י׃","ʼa֣lĕlay li֗⁠y ki֤̇y háyi֨yţiy֙ kĕ̇⁠ʼásĕpé̇y-qa֔yiẕ kĕ̇⁠ʻòlĕlò֖ţ bá̇ẕi֑yr ʼéyn-ʼeşĕ̌k֣̇wòl le⁠ʼèk֔wòl bi̇k̇ẇrá֖h ʼiwĕ̇ţá֥h napĕşǐֽ⁠y׃"],[7,2,"אָבַ֤ד חָסִיד֙ מִן־הָ⁠אָ֔רֶץ וְ⁠יָשָׁ֥ר בָּ⁠אָדָ֖ם אָ֑יִן כֻּלָּ⁠ם֙ לְ⁠דָמִ֣ים יֶאֱרֹ֔בוּ אִ֥ישׁ אֶת־אָחִ֖י⁠הוּ יָצ֥וּדוּ חֵֽרֶם׃","ʼába֤d ẖásiyd֙ min-há⁠ʼá֔reẕ wĕ⁠yáşá֥̌r bá̇⁠ʼádá֖m ʼá֑yin ku̇lá̇⁠m֙ lĕ⁠dámi֣ym yeʼèrò֔bẇ ʼi֥yş̌ ʼeţ-ʼáẖi֖y⁠hẇ yáẕ֥ẇdẇ ẖéֽrem׃"],[7,3,"עַל־הָ⁠רַ֤ע כַּפַּ֨יִם֙ לְ⁠הֵיטִ֔יב הַ⁠שַּׂ֣ר שֹׁאֵ֔ל וְ⁠הַ⁠שֹּׁפֵ֖ט בַּ⁠שִׁלּ֑וּם וְ⁠הַ⁠גָּד֗וֹל דֹּבֵ֨ר הַוַּ֥ת נַפְשׁ֛⁠וֹ ה֖וּא וַֽ⁠יְעַבְּתֽוּ⁠הָ׃","ʻal-há⁠ra֤ʻ kȧpȧ֨yim֙ lĕ⁠héyti֔yb ha⁠şȧ֣̂r şò̌ʼé֔l wĕ⁠ha⁠şò̇̌pé֖t bȧ⁠şǐl֑̇ẇm wĕ⁠ha⁠gá̇d֗wòl dò̇bé֨r hawȧ֥ţ napĕş֛̌⁠wò h֖ẇʼ waֽ⁠yĕʻabĕ̇ţֽẇ⁠há׃"],[7,4,"טוֹבָ֣⁠ם כְּ⁠חֵ֔דֶק יָשָׁ֖ר מִ⁠מְּסוּכָ֑ה י֤וֹם מְצַפֶּ֨י⁠ךָ֙ פְּקֻדָּתְ⁠ךָ֣ בָ֔אָה עַתָּ֥ה תִהְיֶ֖ה מְבוּכָתָֽ⁠ם׃","twòbá֣⁠m kĕ̇⁠ẖé֔deq yáşá֖̌r mi⁠mĕ̇sẇká֑h y֤wòm mĕẕapė֨y⁠ká֙ pĕ̇qudá̇ţĕ⁠ká֣ bá֔ʼáh ʻaţá֥̇h ţihĕye֖h mĕbẇkáţáֽ⁠m׃"],[7,5,"אַל־תַּאֲמִ֣ינוּ בְ⁠רֵ֔עַ אַֽל־תִּבְטְח֖וּ בְּ⁠אַלּ֑וּף מִ⁠שֹּׁכֶ֣בֶת חֵיקֶ֔⁠ךָ שְׁמֹ֖ר פִּתְחֵי־פִֽי⁠ךָ׃","ʼal-ţȧʼàmi֣ynẇ bĕ⁠ré֔ʻa ʼaֽl-ţi̇bĕtĕẖ֖ẇ bĕ̇⁠ʼal֑̇ẇp mi⁠şò̇̌ke֣beţ ẖéyqe֔⁠ká şĕ̌mò֖r pi̇ţĕẖéy-piֽy⁠ká׃"],[7,6,"כִּֽי־בֵן֙ מְנַבֵּ֣ל אָ֔ב בַּ֚ת קָמָ֣ה בְ⁠אִמָּ֔⁠הּ כַּלָּ֖ה בַּ⁠חֲמֹתָ֑⁠הּ אֹיְבֵ֥י אִ֖ישׁ אַנְשֵׁ֥י בֵיתֽ⁠וֹ׃","kiֽ̇y-bén֙ mĕnabé֣̇l ʼá֔b bȧ֚ţ qámá֣h bĕ⁠ʼimá̇֔⁠ḣ kȧlá֖̇h bȧ⁠ẖàmòţá֑⁠ḣ ʼòyĕbé֥y ʼi֖yş̌ ʼanĕşé֥̌y béyţֽ⁠wò׃"],[7,7,"וַ⁠אֲנִי֙ בַּ⁠יהוָ֣ה אֲצַפֶּ֔ה אוֹחִ֖ילָה לֵ⁠אלֹהֵ֣י יִשְׁעִ֑⁠י יִשְׁמָעֵ֖⁠נִי אֱלֹהָֽ⁠י׃","wa⁠ʼàniy֙ bȧ⁠yhwá֣h ʼàẕapė֔h ʼwòẖi֖yláh lé⁠ʼlòhé֣y yişĕ̌ʻi֑⁠y yişĕ̌máʻé֖⁠niy ʼèlòháֽ⁠y׃"],[7,8,"אַֽל־תִּשְׂמְחִ֤י אֹיַ֨בְתִּ⁠י֙ לִ֔⁠י כִּ֥י נָפַ֖לְתִּי קָ֑מְתִּי כִּֽי־אֵשֵׁ֣ב בַּ⁠חֹ֔שֶׁךְ יְהוָ֖ה א֥וֹר לִֽ⁠י׃ס","ʼaֽl-ţi̇şĕ̂mĕẖi֤y ʼòya֨bĕţi̇⁠y֙ li֔⁠y ki֥̇y nápa֖lĕţi̇y qá֑mĕţi̇y kiֽ̇y-ʼéşé֣̌b bȧ⁠ẖò֔şěkĕ yĕhwá֖h ʼ֥wòr liֽ⁠y׃s"],[7,9,"זַ֤עַף יְהוָה֙ אֶשָּׂ֔א כִּ֥י חָטָ֖אתִי ל֑⁠וֹ עַד֩ אֲשֶׁ֨ר יָרִ֤יב רִיבִ⁠י֙ וְ⁠עָשָׂ֣ה מִשְׁפָּטִ֔⁠י יוֹצִיאֵ֣⁠נִי לָ⁠א֔וֹר אֶרְאֶ֖ה בְּ⁠צִדְקָתֽ⁠וֹ׃","za֤ʻap yĕhwáh֙ ʼeşá̇̂֔ʼ ki֥̇y ẖátá֖ʼţiy l֑⁠wò ʻad֩ ʼàşě֨r yári֤yb riybi⁠y֙ wĕ⁠ʻáşá֣̂h mişĕ̌pá̇ti֔⁠y ywòẕiyʼé֣⁠niy lá⁠ʼ֔wòr ʼerĕʼe֖h bĕ̇⁠ẕidĕqáţֽ⁠wò׃"],[7,10,"וְ⁠תֵרֶ֤א אֹיַ֨בְתִּ⁠י֙ וּ⁠תְכַסֶּ֣⁠הָ בוּשָׁ֔ה הָ⁠אֹמְרָ֣ה אֵלַ֔⁠י אַיּ֖⁠וֹ יְהוָ֣ה אֱלֹהָ֑יִ⁠ךְ עֵינַ⁠י֙ תִּרְאֶ֣ינָּה בָּ֔⁠הּ עַתָּ֛ה תִּֽהְיֶ֥ה לְ⁠מִרְמָ֖ס כְּ⁠טִ֥יט חוּצֽוֹת׃","wĕ⁠ţére֤ʼ ʼòya֨bĕţi̇⁠y֙ ẇ⁠ţĕkasė֣⁠há bẇşá̌֔h há⁠ʼòmĕrá֣h ʼéla֔⁠y ʼaẏ֖⁠wò yĕhwá֣h ʼèlòhá֑yi⁠kĕ ʻéyna⁠y֙ ţi̇rĕʼe֣yná̇h bá̇֔⁠ḣ ʻaţá֛̇h ţiֽ̇hĕye֥h lĕ⁠mirĕmá֖s kĕ̇⁠ti֥yt ẖẇẕֽwòţ׃"],[7,11,"י֖וֹם לִ⁠בְנ֣וֹת גְּדֵרָ֑יִ⁠ךְ י֥וֹם הַ⁠ה֖וּא יִרְחַק־חֹֽק׃","y֖wòm li⁠bĕn֣wòţ gĕ̇dérá֑yi⁠kĕ y֥wòm ha⁠h֖ẇʼ yirĕẖaq-ẖòֽq׃"],[7,12,"י֥וֹם הוּא֙ וְ⁠עָדֶ֣י⁠ךָ יָב֔וֹא לְ⁠מִנִּ֥י אַשּׁ֖וּר וְ⁠עָרֵ֣י מָצ֑וֹר וּ⁠לְ⁠מִנִּ֤י מָצוֹר֙ וְ⁠עַד־נָהָ֔ר וְ⁠יָ֥ם מִ⁠יָּ֖ם וְ⁠הַ֥ר הָ⁠הָֽר׃","y֥wòm hẇʼ֙ wĕ⁠ʻáde֣y⁠ká yáb֔wòʼ lĕ⁠mini֥̇y ʼaş֖̇̌ẇr wĕ⁠ʻáré֣y máẕ֑wòr ẇ⁠lĕ⁠mini֤̇y máẕwòr֙ wĕ⁠ʻad-náhá֔r wĕ⁠yá֥m mi⁠yá֖̇m wĕ⁠ha֥r há⁠háֽr׃"],[7,13,"וְ⁠הָיְתָ֥ה הָ⁠אָ֛רֶץ לִ⁠שְׁמָמָ֖ה עַל־יֹֽשְׁבֶ֑י⁠הָ מִ⁠פְּרִ֖י מַֽעַלְלֵי⁠הֶֽם׃ס","wĕ⁠háyĕţá֥h há⁠ʼá֛reẕ li⁠şĕ̌mámá֖h ʻal-yòֽşĕ̌be֑y⁠há mi⁠pĕ̇ri֖y maֽʻalĕléy⁠heֽm׃s"],[7,14,"רְעֵ֧ה עַמְּ⁠ךָ֣ בְ⁠שִׁבְטֶ֗⁠ךָ צֹ֚אן נַֽחֲלָתֶ֔⁠ךָ שֹׁכְנִ֣י לְ⁠בָדָ֔ד יַ֖עַר בְּ⁠ת֣וֹךְ כַּרְמֶ֑ל יִרְע֥וּ בָשָׁ֛ן וְ⁠גִלְעָ֖ד כִּ⁠ימֵ֥י עוֹלָֽם׃","rĕʻé֧h ʻamĕ̇⁠ká֣ bĕ⁠şǐbĕte֗⁠ká ẕò֚ʼn naֽẖàláţe֔⁠ká şò̌kĕni֣y lĕ⁠bádá֔d ya֖ʻar bĕ̇⁠ţ֣wòkĕ kȧrĕme֑l yirĕʻ֥ẇ báşá֛̌n wĕ⁠gilĕʻá֖d ki̇⁠ymé֥y ʻwòláֽm׃"],[7,15,"כִּ⁠ימֵ֥י צֵאתְ⁠ךָ֖ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אַרְאֶ֖⁠נּוּ נִפְלָאֽוֹת׃","ki̇⁠ymé֥y ẕéʼţĕ⁠ká֖ mé⁠ʼe֣reẕ miẕĕrá֑yim ʼarĕʼe֖⁠ṅẇ nipĕláʼֽwòţ׃"],[7,16,"יִרְא֤וּ גוֹיִם֙ וְ⁠יֵבֹ֔שׁוּ מִ⁠כֹּ֖ל גְּבֽוּרָתָ֑⁠ם יָשִׂ֤ימוּ יָד֙ עַל־פֶּ֔ה אָזְנֵי⁠הֶ֖ם תֶּחֱרַֽשְׁנָה׃","yirĕʼ֤ẇ gwòyim֙ wĕ⁠yébò֔ş̌ẇ mi⁠kò֖̇l gĕ̇bֽẇráţá֑⁠m yáşî֤ymẇ yád֙ ʻal-pė֔h ʼázĕnéy⁠he֖m ţėẖèraֽşĕ̌náh׃"],[7,17,"יְלַחֲכ֤וּ עָפָר֙ כַּ⁠נָּחָ֔שׁ כְּ⁠זֹחֲלֵ֣י אֶ֔רֶץ יִרְגְּז֖וּ מִ⁠מִּסְגְּרֹֽתֵי⁠הֶ֑ם אֶל־יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ יִפְחָ֔דוּ וְ⁠יִֽרְא֖וּ מִמֶּֽ⁠ךָּ׃","yĕlaẖàk֤ẇ ʻápár֙ kȧ⁠ná̇ẖá֔ş̌ kĕ̇⁠zòẖàlé֣y ʼe֔reẕ yirĕgĕ̇z֖ẇ mi⁠mi̇sĕgĕ̇ròֽţéy⁠he֑m ʼel-yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ yipĕẖá֔dẇ wĕ⁠yiֽrĕʼ֖ẇ mimėֽ⁠ká̇׃"],[7,18,"מִי־אֵ֣ל כָּמ֗וֹ⁠ךָ נֹשֵׂ֤א עָוֺן֙ וְ⁠עֹבֵ֣ר עַל־פֶּ֔שַׁע לִ⁠שְׁאֵרִ֖ית נַחֲלָת֑⁠וֹ לֹא־הֶחֱזִ֤יק לָ⁠עַד֙ אַפּ֔⁠וֹ כִּֽי־חָפֵ֥ץ חֶ֖סֶד הֽוּא׃","miy-ʼé֣l ká̇m֗wò⁠ká nòşé֤̂ʼ ʻáwֺn֙ wĕ⁠ʻòbé֣r ʻal-pė֔şǎʻ li⁠şĕ̌ʼéri֖yţ naẖàláţ֑⁠wò lòʼ-heẖèzi֤yq lá⁠ʻad֙ ʼaṗ֔⁠wò kiֽ̇y-ẖápé֥ẕ ẖe֖sed hֽẇʼ׃"],[7,19,"יָשׁ֣וּב יְרַֽחֲמֵ֔⁠נוּ יִכְבֹּ֖שׁ עֲוֺֽנֹתֵ֑י⁠נוּ וְ⁠תַשְׁלִ֛יךְ בִּ⁠מְצֻל֥וֹת יָ֖ם כָּל־חַטֹּאותָֽ⁠ם׃","yáş֣̌ẇb yĕraֽẖàmé֔⁠nẇ yikĕbò֖̇ş̌ ʻàwֺֽnòţé֑y⁠nẇ wĕ⁠ţaşĕ̌li֛ykĕ bi̇⁠mĕẕul֥wòţ yá֖m ká̇l-ẖatò̇ʼwţáֽ⁠m׃"],[7,20,"תִּתֵּ֤ן אֱמֶת֙ לְ⁠יַֽעֲקֹ֔ב חֶ֖סֶד לְ⁠אַבְרָהָ֑ם אֲשֶׁר־נִשְׁבַּ֥עְתָּ לַ⁠אֲבֹתֵ֖י⁠נוּ מִ֥⁠ימֵי קֶֽדֶם׃","ţi̇ţé֤̇n ʼèmeţ֙ lĕ⁠yaֽʻàqò֔b ẖe֖sed lĕ⁠ʼabĕráhá֑m ʼàşěr-nişĕ̌bȧ֥ʻĕţá̇ la⁠ʼàbòţé֖y⁠nẇ mi֥⁠yméy qeֽdem׃"]],"fra-lsg1910":[[1,1,"La parole de l'Éternel fut adressée à Michée, de Moréscheth, au temps de Jotham, d'Achaz, d'Ézéchias, rois de Juda, prophétie sur Samarie et Jérusalem.","La parole de l'Éternel fut adressée à Michée, de Moréscheth, au temps de Jotham, d'Achaz, d'Ézéchias, rois de Juda, prophétie sur Samarie et Jérusalem."],[1,2,"Écoutez, vous tous, peuples! Sois attentive, terre, et ce qui est en toi! Que le Seigneur, l'Éternel, soit témoin contre vous, Le Seigneur qui est dans le palais de sa sainteté!","Écoutez, vous tous, peuples! Sois attentive, terre, et ce qui est en toi! Que le Seigneur, l'Éternel, soit témoin contre vous, Le Seigneur qui est dans le palais de sa sainteté!"],[1,3,"Car voici, l'Éternel sort de sa demeure, Il descend, il marche sur les hauteurs de la terre.","Car voici, l'Éternel sort de sa demeure, Il descend, il marche sur les hauteurs de la terre."],[1,4,"Sous lui les montagnes se fondent, Les vallées s'entr'ouvrent, Comme la cire devant le feu, Comme l'eau qui coule sur une pente.","Sous lui les montagnes se fondent, Les vallées s'entr'ouvrent, Comme la cire devant le feu, Comme l'eau qui coule sur une pente."],[1,5,"Et tout cela à cause du crime de Jacob, À cause des péchés de la maison d'Israël! Quel est le crime de Jacob? n'est-ce pas Samarie? Quels sont les hauts lieux de Juda? n'est-ce pas Jérusalem?...","Et tout cela à cause du crime de Jacob, À cause des péchés de la maison d'Israël! Quel est le crime de Jacob? n'est-ce pas Samarie? Quels sont les hauts lieux de Juda? n'est-ce pas Jérusalem?..."],[1,6,"Je ferai de Samarie un monceau de pierres dans les champs, Un lieu pour planter de la vigne; Je précipiterai ses pierres dans la vallée, Je mettrai à nu ses fondements.","Je ferai de Samarie un monceau de pierres dans les champs, Un lieu pour planter de la vigne; Je précipiterai ses pierres dans la vallée, Je mettrai à nu ses fondements."],[1,7,"Toutes ses images taillées seront brisées, Tous ses salaires impurs seront brûlés au feu, Et je ravagerai toutes ses idoles: Recueillies avec le salaire de la prostitution, Elles deviendront un salaire de prostitutions...","Toutes ses images taillées seront brisées, Tous ses salaires impurs seront brûlés au feu, Et je ravagerai toutes ses idoles: Recueillies avec le salaire de la prostitution, Elles deviendront un salaire de prostitutions..."],[1,8,"C'est pourquoi je pleurerai, je me lamenterai, Je marcherai déchaussé et nu, Je pousserai des cris comme le chacal, Et des gémissements comme l'autruche.","C'est pourquoi je pleurerai, je me lamenterai, Je marcherai déchaussé et nu, Je pousserai des cris comme le chacal, Et des gémissements comme l'autruche."],[1,9,"Car sa plaie est douloureuse; Elle s'étend jusqu'à Juda, Elle pénètre jusqu'à la porte de mon peuple, Jusqu'à Jérusalem.","Car sa plaie est douloureuse; Elle s'étend jusqu'à Juda, Elle pénètre jusqu'à la porte de mon peuple, Jusqu'à Jérusalem."],[1,10,"Ne l'annoncez point dans Gath, Ne pleurez point dans Acco! Je me roule dans la poussière à Beth Leaphra.","Ne l'annoncez point dans Gath, Ne pleurez point dans Acco! Je me roule dans la poussière à Beth Leaphra."],[1,11,"Passe, habitante de Schaphir, dans la nudité et la honte! L'habitante de Tsaanan n'ose sortir, Le deuil de Beth-Haëtsel vous prive de son abri.","Passe, habitante de Schaphir, dans la nudité et la honte! L'habitante de Tsaanan n'ose sortir, Le deuil de Beth-Haëtsel vous prive de son abri."],[1,12,"L'habitante de Maroth tremble pour son salut, Car le malheur est descendu de la part de l'Éternel Jusqu'à la porte de Jérusalem.","L'habitante de Maroth tremble pour son salut, Car le malheur est descendu de la part de l'Éternel Jusqu'à la porte de Jérusalem."],[1,13,"Attelle les coursiers à ton char, Habitante de Lakisch! Tu as été pour la fille de Sion une première cause de péché, Car en toi se sont trouvés les crimes d'Israël.","Attelle les coursiers à ton char, Habitante de Lakisch! Tu as été pour la fille de Sion une première cause de péché, Car en toi se sont trouvés les crimes d'Israël."],[1,14,"C'est pourquoi tu renonceras à Moréschet-Gath; Les maisons d'Aczib seront une source trompeuse Pour les rois d'Israël.","C'est pourquoi tu renonceras à Moréschet-Gath; Les maisons d'Aczib seront une source trompeuse Pour les rois d'Israël."],[1,15,"Je t'amènerai un nouveau maître, habitante de Maréscha; La gloire d'Israël s'en ira jusqu'à Adullam.","Je t'amènerai un nouveau maître, habitante de Maréscha; La gloire d'Israël s'en ira jusqu'à Adullam."],[1,16,"Rase-toi, coupe ta chevelure, À cause de tes enfants chéris! Rends-toi chauve comme l'aigle, Car ils s'en vont en captivité loin de toi!","Rase-toi, coupe ta chevelure, À cause de tes enfants chéris! Rends-toi chauve comme l'aigle, Car ils s'en vont en captivité loin de toi!"],[2,1,"Malheur à ceux qui méditent l'iniquité et qui forgent le mal Sur leur couche! Au point du jour ils l'exécutent, Quand ils ont le pouvoir en main.","Malheur à ceux qui méditent l'iniquité et qui forgent le mal Sur leur couche! Au point du jour ils l'exécutent, Quand ils ont le pouvoir en main."],[2,2,"Ils convoitent des champs, et ils s'en emparent, Des maisons, et ils les enlèvent; Ils portent leur violence sur l'homme et sur sa maison, Sur l'homme et sur son héritage.","Ils convoitent des champs, et ils s'en emparent, Des maisons, et ils les enlèvent; Ils portent leur violence sur l'homme et sur sa maison, Sur l'homme et sur son héritage."],[2,3,"C'est pourquoi ainsi parle l'Éternel: Voici, je médite contre cette race un malheur; Vous n'en préserverez pas vos cous, Et vous ne marcherez pas la tête levée, Car ces temps seront mauvais.","C'est pourquoi ainsi parle l'Éternel: Voici, je médite contre cette race un malheur; Vous n'en préserverez pas vos cous, Et vous ne marcherez pas la tête levée, Car ces temps seront mauvais."],[2,4,"En ce jour-là, on fera de vous un sujet de sarcasme, On poussera des cris lamentables, On dira: Nous sommes entièrement dévastés! Il donne à d'autres la part de mon peuple! Eh quoi! il me l'enlève! Il distribue nos champs à l'ennemi!...","En ce jour-là, on fera de vous un sujet de sarcasme, On poussera des cris lamentables, On dira: Nous sommes entièrement dévastés! Il donne à d'autres la part de mon peuple! Eh quoi! il me l'enlève! Il distribue nos champs à l'ennemi!..."],[2,5,"C'est pourquoi tu n'auras personne Qui étende le cordeau sur un lot, Dans l'assemblée de l'Éternel. -","C'est pourquoi tu n'auras personne Qui étende le cordeau sur un lot, Dans l'assemblée de l'Éternel. -"],[2,6,"Ne prophétisez pas! disent-ils. Qu'on ne prophétise pas de telles choses! Les invectives n'ont point de fin! -","Ne prophétisez pas! disent-ils. Qu'on ne prophétise pas de telles choses! Les invectives n'ont point de fin! -"],[2,7,"Oses-tu parler ainsi, maison de Jacob? L'Éternel est-il prompt à s'irriter? Est-ce là sa manière d'agir? Mes paroles ne sont-elles pas favorables À celui qui marche avec droiture?","Oses-tu parler ainsi, maison de Jacob? L'Éternel est-il prompt à s'irriter? Est-ce là sa manière d'agir? Mes paroles ne sont-elles pas favorables À celui qui marche avec droiture?"],[2,8,"Depuis longtemps on traite mon peuple en ennemi; Vous enlevez le manteau de dessus les vêtements De ceux qui passent avec sécurité En revenant de la guerre.","Depuis longtemps on traite mon peuple en ennemi; Vous enlevez le manteau de dessus les vêtements De ceux qui passent avec sécurité En revenant de la guerre."],[2,9,"Vous chassez de leurs maisons chéries les femmes de mon peuple, Vous ôtez pour toujours ma parure à leurs enfants.","Vous chassez de leurs maisons chéries les femmes de mon peuple, Vous ôtez pour toujours ma parure à leurs enfants."],[2,10,"Levez-vous, marchez! car ce n'est point ici un lieu de repos; À cause de la souillure, il y aura des douleurs, des douleurs violentes.","Levez-vous, marchez! car ce n'est point ici un lieu de repos; À cause de la souillure, il y aura des douleurs, des douleurs violentes."],[2,11,"Si un homme court après le vent et débite des mensonges: Je vais te prophétiser sur le vin, sur les boissons fortes! Ce sera pour ce peuple un prophète.","Si un homme court après le vent et débite des mensonges: Je vais te prophétiser sur le vin, sur les boissons fortes! Ce sera pour ce peuple un prophète."],[2,12,"Je te rassemblerai tout entier, ô Jacob! Je rassemblerai les restes d'Israël, Je les réunirai comme les brebis d'une bergerie, Comme le troupeau dans son pâturage; Il y aura un grand bruit d'hommes.","Je te rassemblerai tout entier, ô Jacob! Je rassemblerai les restes d'Israël, Je les réunirai comme les brebis d'une bergerie, Comme le troupeau dans son pâturage; Il y aura un grand bruit d'hommes."],[2,13,"Celui qui fera la brèche montera devant eux; Ils feront la brèche, franchiront la porte et en sortiront; Leur roi marchera devant eux, Et l'Éternel sera à leur tête.","Celui qui fera la brèche montera devant eux; Ils feront la brèche, franchiront la porte et en sortiront; Leur roi marchera devant eux, Et l'Éternel sera à leur tête."],[3,1,"Je dis: Écoutez, chefs de Jacob, Et princes de la maison d'Israël! N'est-ce pas à vous à connaître la justice?","Je dis: Écoutez, chefs de Jacob, Et princes de la maison d'Israël! N'est-ce pas à vous à connaître la justice?"],[3,2,"Vous haïssez le bien et vous aimez le mal; Vous leur arrachez la peau et la chair de dessus les os.","Vous haïssez le bien et vous aimez le mal; Vous leur arrachez la peau et la chair de dessus les os."],[3,3,"Ils dévorent la chair de mon peuple, Lui arrachent la peau, Et lui brisent les os; Ils le mettent en pièces comme ce qu'on cuit dans un pot, Comme de la viande dans une chaudière.","Ils dévorent la chair de mon peuple, Lui arrachent la peau, Et lui brisent les os; Ils le mettent en pièces comme ce qu'on cuit dans un pot, Comme de la viande dans une chaudière."],[3,4,"Alors ils crieront vers l'Éternel, Mais il ne leur répondra pas; Il leur cachera sa face en ce temps-là, Parce qu'ils ont fait de mauvaises actions.","Alors ils crieront vers l'Éternel, Mais il ne leur répondra pas; Il leur cachera sa face en ce temps-là, Parce qu'ils ont fait de mauvaises actions."],[3,5,"Ainsi parle l'Éternel sur les prophètes qui égarent mon peuple, Qui annoncent la paix si leurs dents ont quelque chose à mordre, Et qui publient la guerre si on ne leur met rien dans la bouche:","Ainsi parle l'Éternel sur les prophètes qui égarent mon peuple, Qui annoncent la paix si leurs dents ont quelque chose à mordre, Et qui publient la guerre si on ne leur met rien dans la bouche:"],[3,6,"À cause de cela, vous aurez la nuit..., et plus de visions! Vous aurez les ténèbres..., et plus d'oracles! Le soleil se couchera sur ces prophètes, Le jour s'obscurcira sur eux.","À cause de cela, vous aurez la nuit..., et plus de visions! Vous aurez les ténèbres..., et plus d'oracles! Le soleil se couchera sur ces prophètes, Le jour s'obscurcira sur eux."],[3,7,"Les voyants seront confus, les devins rougiront, Tous se couvriront la barbe; Car Dieu ne répondra pas.","Les voyants seront confus, les devins rougiront, Tous se couvriront la barbe; Car Dieu ne répondra pas."],[3,8,"Mais moi, je suis rempli de force, de l'esprit de l'Éternel, Je suis rempli de justice et de vigueur, Pour faire connaître à Jacob son crime, Et à Israël son péché.","Mais moi, je suis rempli de force, de l'esprit de l'Éternel, Je suis rempli de justice et de vigueur, Pour faire connaître à Jacob son crime, Et à Israël son péché."],[3,9,"Écoutez donc ceci, chefs de la maison de Jacob, Et princes de la maison d'Israël, Vous qui avez en horreur la justice, Et qui pervertissez tout ce qui est droit,","Écoutez donc ceci, chefs de la maison de Jacob, Et princes de la maison d'Israël, Vous qui avez en horreur la justice, Et qui pervertissez tout ce qui est droit,"],[3,10,"Vous qui bâtissez Sion avec le sang, Et Jérusalem avec l'iniquité!","Vous qui bâtissez Sion avec le sang, Et Jérusalem avec l'iniquité!"],[3,11,"Ses chefs jugent pour des présents, Ses sacrificateurs enseignent pour un salaire, Et ses prophètes prédisent pour de l'argent; Et ils osent s'appuyer sur l'Éternel, ils disent: L'Éternel n'est-il pas au milieu de nous? Le malheur ne nous atteindra pas.","Ses chefs jugent pour des présents, Ses sacrificateurs enseignent pour un salaire, Et ses prophètes prédisent pour de l'argent; Et ils osent s'appuyer sur l'Éternel, ils disent: L'Éternel n'est-il pas au milieu de nous? Le malheur ne nous atteindra pas."],[3,12,"C'est pourquoi, à cause de vous, Sion sera labourée comme un champ, Jérusalem deviendra un monceau de pierres, Et la montagne du temple une sommité couverte de bois.","C'est pourquoi, à cause de vous, Sion sera labourée comme un champ, Jérusalem deviendra un monceau de pierres, Et la montagne du temple une sommité couverte de bois."],[4,1,"Il arrivera, dans la suite des temps, Que la montagne de la maison de l'Éternel Sera fondée sur le sommet des montagnes, Qu'elle s'élèvera par-dessus les collines, Et que les peuples y afflueront.","Il arrivera, dans la suite des temps, Que la montagne de la maison de l'Éternel Sera fondée sur le sommet des montagnes, Qu'elle s'élèvera par-dessus les collines, Et que les peuples y afflueront."],[4,2,"Des nations s'y rendront en foule, et diront: Venez, et montons à la montagne de l'Éternel, À la maison du Dieu de Jacob, Afin qu'il nous enseigne ses voies, Et que nous marchions dans ses sentiers. Car de Sion sortira la loi, Et de Jérusalem la parole de l'Éternel.","Des nations s'y rendront en foule, et diront: Venez, et montons à la montagne de l'Éternel, À la maison du Dieu de Jacob, Afin qu'il nous enseigne ses voies, Et que nous marchions dans ses sentiers. Car de Sion sortira la loi, Et de Jérusalem la parole de l'Éternel."],[4,3,"Il sera le juge d'un grand nombre de peuples, L'arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l'épée contre une autre, Et l'on n'apprendra plus la guerre.","Il sera le juge d'un grand nombre de peuples, L'arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l'épée contre une autre, Et l'on n'apprendra plus la guerre."],[4,4,"Ils habiteront chacun sous sa vigne et sous son figuier, Et il n'y aura personne pour les troubler; Car la bouche de l'Éternel des armées a parlé.","Ils habiteront chacun sous sa vigne et sous son figuier, Et il n'y aura personne pour les troubler; Car la bouche de l'Éternel des armées a parlé."],[4,5,"Tandis que tous les peuples marchent, chacun au nom de son dieu, Nous marcherons, nous, au nom de l'Éternel, notre Dieu, À toujours et à perpétuité.","Tandis que tous les peuples marchent, chacun au nom de son dieu, Nous marcherons, nous, au nom de l'Éternel, notre Dieu, À toujours et à perpétuité."],[4,6,"En ce jour-là, dit l'Éternel, je recueillerai les boiteux, Je rassemblerai ceux qui étaient chassés, Ceux que j'avais maltraités.","En ce jour-là, dit l'Éternel, je recueillerai les boiteux, Je rassemblerai ceux qui étaient chassés, Ceux que j'avais maltraités."],[4,7,"Des boiteux je ferai un reste, De ceux qui étaient chassés une nation puissante; Et l'Éternel régnera sur eux, à la montagne de Sion, Dès lors et pour toujours.","Des boiteux je ferai un reste, De ceux qui étaient chassés une nation puissante; Et l'Éternel régnera sur eux, à la montagne de Sion, Dès lors et pour toujours."],[4,8,"Et toi, tour du troupeau, colline de la fille de Sion, À toi viendra, à toi arrivera l'ancienne domination, Le royaume de la fille de Jérusalem.","Et toi, tour du troupeau, colline de la fille de Sion, À toi viendra, à toi arrivera l'ancienne domination, Le royaume de la fille de Jérusalem."],[4,9,"Pourquoi maintenant pousses-tu des cris? N'as-tu point de roi, plus de conseiller, Pour que la douleur te saisisse comme une femme qui accouche?","Pourquoi maintenant pousses-tu des cris? N'as-tu point de roi, plus de conseiller, Pour que la douleur te saisisse comme une femme qui accouche?"],[4,10,"Fille de Sion, souffre et gémis comme une femme qui accouche! Car maintenant tu sortiras de la ville et tu habiteras dans les champs, Et tu iras jusqu'à Babylone; Là tu seras délivrée, C'est là que l'Éternel te rachètera de la main de tes ennemis.","Fille de Sion, souffre et gémis comme une femme qui accouche! Car maintenant tu sortiras de la ville et tu habiteras dans les champs, Et tu iras jusqu'à Babylone; Là tu seras délivrée, C'est là que l'Éternel te rachètera de la main de tes ennemis."],[4,11,"Maintenant plusieurs nations se sont rassemblées contre toi: Qu'elle soit profanée, disent-elles, Et que nos yeux se rassasient dans Sion!","Maintenant plusieurs nations se sont rassemblées contre toi: Qu'elle soit profanée, disent-elles, Et que nos yeux se rassasient dans Sion!"],[4,12,"Mais elles ne connaissent pas les pensées de l'Éternel, Elles ne comprennent pas ses desseins, Elles ignorent qu'il les a rassemblées comme des gerbes dans l'aire.","Mais elles ne connaissent pas les pensées de l'Éternel, Elles ne comprennent pas ses desseins, Elles ignorent qu'il les a rassemblées comme des gerbes dans l'aire."],[4,13,"Fille de Sion, lève-toi et foule! Je te ferai une corne de fer et des ongles d'airain, Et tu broieras des peuples nombreux; Tu consacreras leurs biens à l'Éternel, Leurs richesses au Seigneur de toute la terre.","Fille de Sion, lève-toi et foule! Je te ferai une corne de fer et des ongles d'airain, Et tu broieras des peuples nombreux; Tu consacreras leurs biens à l'Éternel, Leurs richesses au Seigneur de toute la terre."],[5,1,"Maintenant, fille de troupes, rassemble tes troupes! On nous assiège; Avec la verge on frappe sur la joue le juge d'Israël.","Maintenant, fille de troupes, rassemble tes troupes! On nous assiège; Avec la verge on frappe sur la joue le juge d'Israël."],[5,2,"Et toi, Bethléhem Éphrata, Petite entre les milliers de Juda, De toi sortira pour moi Celui qui dominera sur Israël, Et dont l'origine remonte aux temps anciens, Aux jours de l'éternité.","Et toi, Bethléhem Éphrata, Petite entre les milliers de Juda, De toi sortira pour moi Celui qui dominera sur Israël, Et dont l'origine remonte aux temps anciens, Aux jours de l'éternité."],[5,3,"C'est pourquoi il les livrera Jusqu'au temps où enfantera celle qui doit enfanter, Et le reste de ses frères Reviendra auprès des enfants d'Israël.","C'est pourquoi il les livrera Jusqu'au temps où enfantera celle qui doit enfanter, Et le reste de ses frères Reviendra auprès des enfants d'Israël."],[5,4,"Il se présentera, et il gouvernera avec la force de l'Éternel, Avec la majesté du nom de l'Éternel, son Dieu: Et ils auront une demeure assurée, Car il sera glorifié jusqu'aux extrémités de la terre.","Il se présentera, et il gouvernera avec la force de l'Éternel, Avec la majesté du nom de l'Éternel, son Dieu: Et ils auront une demeure assurée, Car il sera glorifié jusqu'aux extrémités de la terre."],[5,5,"C'est lui qui ramènera la paix. Lorsque l'Assyrien viendra dans notre pays, Et qu'il pénétrera dans nos palais, Nous ferons lever contre lui sept pasteurs Et huit princes du peuple.","C'est lui qui ramènera la paix. Lorsque l'Assyrien viendra dans notre pays, Et qu'il pénétrera dans nos palais, Nous ferons lever contre lui sept pasteurs Et huit princes du peuple."],[5,6,"Ils feront avec l'épée leur pâture du pays d'Assyrie Et du pays de Nimrod au dedans de ses portes. Il nous délivrera ainsi de l'Assyrien, Lorsqu'il viendra dans notre pays, Et qu'il pénétrera sur notre territoire.","Ils feront avec l'épée leur pâture du pays d'Assyrie Et du pays de Nimrod au dedans de ses portes. Il nous délivrera ainsi de l'Assyrien, Lorsqu'il viendra dans notre pays, Et qu'il pénétrera sur notre territoire."],[5,7,"Le reste de Jacob sera au milieu des peuples nombreux Comme une rosée qui vient de l'Éternel, Comme des gouttes d'eau sur l'herbe: Elles ne comptent pas sur l'homme, Elles ne dépendent pas des enfants des hommes.","Le reste de Jacob sera au milieu des peuples nombreux Comme une rosée qui vient de l'Éternel, Comme des gouttes d'eau sur l'herbe: Elles ne comptent pas sur l'homme, Elles ne dépendent pas des enfants des hommes."],[5,8,"Le reste de Jacob sera parmi les nations, Au milieu des peuples nombreux, Comme un lion parmi les bêtes de la forêt, Comme un lionceau parmi les troupeaux de brebis: Lorsqu'il passe, il foule et déchire, Et personne ne délivre.","Le reste de Jacob sera parmi les nations, Au milieu des peuples nombreux, Comme un lion parmi les bêtes de la forêt, Comme un lionceau parmi les troupeaux de brebis: Lorsqu'il passe, il foule et déchire, Et personne ne délivre."],[5,9,"Que ta main se lève sur tes adversaires, Et que tous tes ennemis soient exterminés!","Que ta main se lève sur tes adversaires, Et que tous tes ennemis soient exterminés!"],[5,10,"En ce jour-là, dit l'Éternel, J'exterminerai du milieu de toi tes chevaux, Et je détruirai tes chars;","En ce jour-là, dit l'Éternel, J'exterminerai du milieu de toi tes chevaux, Et je détruirai tes chars;"],[5,11,"J'exterminerai les villes de ton pays, Et je renverserai toutes tes forteresses;","J'exterminerai les villes de ton pays, Et je renverserai toutes tes forteresses;"],[5,12,"J'exterminerai de ta main les enchantements, Et tu n'auras plus de magiciens;","J'exterminerai de ta main les enchantements, Et tu n'auras plus de magiciens;"],[5,13,"J'exterminerai du milieu de toi tes idoles et tes statues, Et tu ne te prosterneras plus devant l'ouvrage de tes mains;","J'exterminerai du milieu de toi tes idoles et tes statues, Et tu ne te prosterneras plus devant l'ouvrage de tes mains;"],[5,14,"J'exterminerai du milieu de toi tes idoles d'Astarté, Et je détruirai tes villes.","J'exterminerai du milieu de toi tes idoles d'Astarté, Et je détruirai tes villes."],[5,15,"J'exercerai ma vengeance avec colère, avec fureur, sur les nations Qui n'ont pas écouté.","J'exercerai ma vengeance avec colère, avec fureur, sur les nations Qui n'ont pas écouté."],[6,1,"Écoutez donc ce que dit l'Éternel: Lève-toi, plaide devant les montagnes, Et que les collines entendent ta voix!...","Écoutez donc ce que dit l'Éternel: Lève-toi, plaide devant les montagnes, Et que les collines entendent ta voix!..."],[6,2,"Écoutez, montagnes, le procès de l'Éternel, Et vous, solides fondements de la terre! Car l'Éternel a un procès avec son peuple, Il veut plaider avec Israël. -","Écoutez, montagnes, le procès de l'Éternel, Et vous, solides fondements de la terre! Car l'Éternel a un procès avec son peuple, Il veut plaider avec Israël. -"],[6,3,"Mon peuple, que t'ai-je fait? En quoi t'ai-je fatigué? Réponds-moi!","Mon peuple, que t'ai-je fait? En quoi t'ai-je fatigué? Réponds-moi!"],[6,4,"Car je t'ai fait monter du pays d'Égypte, Je t'ai délivré de la maison de servitude, Et j'ai envoyé devant toi Moïse, Aaron et Marie.","Car je t'ai fait monter du pays d'Égypte, Je t'ai délivré de la maison de servitude, Et j'ai envoyé devant toi Moïse, Aaron et Marie."],[6,5,"Mon peuple, rappelle-toi ce que projetait Balak, roi de Moab, Et ce que lui répondit Balaam, fils de Beor, De Sittim à Guilgal, Afin que tu reconnaisses les bienfaits de l'Éternel.","Mon peuple, rappelle-toi ce que projetait Balak, roi de Moab, Et ce que lui répondit Balaam, fils de Beor, De Sittim à Guilgal, Afin que tu reconnaisses les bienfaits de l'Éternel."],[6,6,"Avec quoi me présenterai-je devant l'Éternel, Pour m'humilier devant le Dieu Très-Haut? Me présenterai-je avec des holocaustes, Avec des veaux d'un an?","Avec quoi me présenterai-je devant l'Éternel, Pour m'humilier devant le Dieu Très-Haut? Me présenterai-je avec des holocaustes, Avec des veaux d'un an?"],[6,7,"L'Éternel agréera-t-il des milliers de béliers, Des myriades de torrents d'huile? Donnerai-je pour mes transgressions mon premier-né, Pour le péché de mon âme le fruit de mes entrailles? -","L'Éternel agréera-t-il des milliers de béliers, Des myriades de torrents d'huile? Donnerai-je pour mes transgressions mon premier-né, Pour le péché de mon âme le fruit de mes entrailles? -"],[6,8,"On t'a fait connaître, ô homme, ce qui est bien; Et ce que l'Éternel demande de toi, C'est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu marches humblement avec ton Dieu.","On t'a fait connaître, ô homme, ce qui est bien; Et ce que l'Éternel demande de toi, C'est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu marches humblement avec ton Dieu."],[6,9,"La voix de l'Éternel crie à la ville, Et celui qui est sage craindra ton nom. Entendez la verge et celui qui l'envoie!","La voix de l'Éternel crie à la ville, Et celui qui est sage craindra ton nom. Entendez la verge et celui qui l'envoie!"],[6,10,"Y a-t-il encore dans la maison du méchant Des trésors iniques, Et un épha trop petit, objet de malédiction?","Y a-t-il encore dans la maison du méchant Des trésors iniques, Et un épha trop petit, objet de malédiction?"],[6,11,"Est-on pur avec des balances fausses, Et avec de faux poids dans le sac?","Est-on pur avec des balances fausses, Et avec de faux poids dans le sac?"],[6,12,"Ses riches sont pleins de violence, Ses habitants profèrent le mensonge, Et leur langue n'est que tromperie dans leur bouche.","Ses riches sont pleins de violence, Ses habitants profèrent le mensonge, Et leur langue n'est que tromperie dans leur bouche."],[6,13,"C'est pourquoi je te frapperai par la souffrance, Je te ravagerai à cause de tes péchés.","C'est pourquoi je te frapperai par la souffrance, Je te ravagerai à cause de tes péchés."],[6,14,"Tu mangeras sans te rassasier, Et la faim sera au dedans de toi; Tu mettras en réserve et tu ne sauveras pas, Et ce que tu sauveras, je le livrerai à l'épée.","Tu mangeras sans te rassasier, Et la faim sera au dedans de toi; Tu mettras en réserve et tu ne sauveras pas, Et ce que tu sauveras, je le livrerai à l'épée."],[6,15,"Tu sèmeras, et tu ne moissonneras pas, Tu presseras l'olive, et tu ne feras pas d'onctions avec l'huile, Tu presseras le moût, et tu ne boiras pas le vin.","Tu sèmeras, et tu ne moissonneras pas, Tu presseras l'olive, et tu ne feras pas d'onctions avec l'huile, Tu presseras le moût, et tu ne boiras pas le vin."],[6,16,"On observe les coutumes d'Omri Et toute la manière d'agir de la maison d'Achab, Et vous marchez d'après leurs conseils; C'est pourquoi je te livrerai à la destruction, Je ferai de tes habitants un sujet de raillerie, Et vous porterez l'opprobre de mon peuple.","On observe les coutumes d'Omri Et toute la manière d'agir de la maison d'Achab, Et vous marchez d'après leurs conseils; C'est pourquoi je te livrerai à la destruction, Je ferai de tes habitants un sujet de raillerie, Et vous porterez l'opprobre de mon peuple."],[7,1,"Malheur à moi! car je suis comme à la récolte des fruits, Comme au grappillage après la vendange: Il n'y a point de grappes à manger, Point de ces primeurs que mon âme désire.","Malheur à moi! car je suis comme à la récolte des fruits, Comme au grappillage après la vendange: Il n'y a point de grappes à manger, Point de ces primeurs que mon âme désire."],[7,2,"L'homme de bien a disparu du pays, Et il n'y a plus de juste parmi les hommes; Ils sont tous en embuscade pour verser le sang, Chacun tend un piège à son frère.","L'homme de bien a disparu du pays, Et il n'y a plus de juste parmi les hommes; Ils sont tous en embuscade pour verser le sang, Chacun tend un piège à son frère."],[7,3,"Leurs mains sont habiles à faire le mal: Le prince a des exigences, Le juge réclame un salaire, Le grand manifeste son avidité, Et ils font ainsi cause commune.","Leurs mains sont habiles à faire le mal: Le prince a des exigences, Le juge réclame un salaire, Le grand manifeste son avidité, Et ils font ainsi cause commune."],[7,4,"Le meilleur d'entre eux est comme une ronce, Le plus droit pire qu'un buisson d'épines. Le jour annoncé par tes prophètes, ton châtiment approche. C'est alors qu'ils seront dans la confusion.","Le meilleur d'entre eux est comme une ronce, Le plus droit pire qu'un buisson d'épines. Le jour annoncé par tes prophètes, ton châtiment approche. C'est alors qu'ils seront dans la confusion."],[7,5,"Ne crois pas à un ami, Ne te fie pas à un intime; Devant celle qui repose sur ton sein Garde les portes de ta bouche.","Ne crois pas à un ami, Ne te fie pas à un intime; Devant celle qui repose sur ton sein Garde les portes de ta bouche."],[7,6,"Car le fils outrage le père, La fille se soulève contre sa mère, La belle-fille contre sa belle-mère; Chacun a pour ennemis les gens de sa maison. -","Car le fils outrage le père, La fille se soulève contre sa mère, La belle-fille contre sa belle-mère; Chacun a pour ennemis les gens de sa maison. -"],[7,7,"Pour moi, je regarderai vers l'Éternel, Je mettrai mon espérance dans le Dieu de mon salut; Mon Dieu m'exaucera.","Pour moi, je regarderai vers l'Éternel, Je mettrai mon espérance dans le Dieu de mon salut; Mon Dieu m'exaucera."],[7,8,"Ne te réjouis pas à mon sujet, mon ennemie! Car si je suis tombée, je me relèverai; Si je suis assise dans les ténèbres, L'Éternel sera ma lumière.","Ne te réjouis pas à mon sujet, mon ennemie! Car si je suis tombée, je me relèverai; Si je suis assise dans les ténèbres, L'Éternel sera ma lumière."],[7,9,"Je supporterai la colère de l'Éternel, Puisque j'ai péché contre lui, Jusqu'à ce qu'il défende ma cause et me fasse droit; Il me conduira à la lumière, Et je contemplerai sa justice.","Je supporterai la colère de l'Éternel, Puisque j'ai péché contre lui, Jusqu'à ce qu'il défende ma cause et me fasse droit; Il me conduira à la lumière, Et je contemplerai sa justice."],[7,10,"Mon ennemie le verra et sera couverte de honte, Elle qui me disait: Où est l'Éternel, ton Dieu? Mes yeux se réjouiront à sa vue; Alors elle sera foulée aux pieds comme la boue des rues. -","Mon ennemie le verra et sera couverte de honte, Elle qui me disait: Où est l'Éternel, ton Dieu? Mes yeux se réjouiront à sa vue; Alors elle sera foulée aux pieds comme la boue des rues. -"],[7,11,"Le jour où l'on rebâtira tes murs, Ce jour-là tes limites seront reculées.","Le jour où l'on rebâtira tes murs, Ce jour-là tes limites seront reculées."],[7,12,"En ce jour, on viendra vers toi De l'Assyrie et des villes d'Égypte, De l'Égypte jusqu'au fleuve, D'une mer à l'autre, et d'une montagne à l'autre.","En ce jour, on viendra vers toi De l'Assyrie et des villes d'Égypte, De l'Égypte jusqu'au fleuve, D'une mer à l'autre, et d'une montagne à l'autre."],[7,13,"Le pays sera dévasté à cause de ses habitants, À cause du fruit de leurs oeuvres.","Le pays sera dévasté à cause de ses habitants, À cause du fruit de leurs oeuvres."],[7,14,"Pais ton peuple avec ta houlette, le troupeau de ton héritage, Qui habite solitaire dans la forêt au milieu du Carmel! Qu'ils paissent sur le Basan et en Galaad, Comme au jour d'autrefois. -","Pais ton peuple avec ta houlette, le troupeau de ton héritage, Qui habite solitaire dans la forêt au milieu du Carmel! Qu'ils paissent sur le Basan et en Galaad, Comme au jour d'autrefois. -"],[7,15,"Comme au jour où tu sortis du pays d'Égypte, Je te ferai voir des prodiges. -","Comme au jour où tu sortis du pays d'Égypte, Je te ferai voir des prodiges. -"],[7,16,"Les nations le verront, et seront confuses, Avec toute leur puissance; Elles mettront la main sur la bouche, Leurs oreilles seront assourdies.","Les nations le verront, et seront confuses, Avec toute leur puissance; Elles mettront la main sur la bouche, Leurs oreilles seront assourdies."],[7,17,"Elles lécheront la poussière, comme le serpent, Comme les reptiles de la terre; Elles seront saisies de frayeur hors de leurs forteresses; Elles trembleront devant l'Éternel, notre Dieu, Elles te craindront.","Elles lécheront la poussière, comme le serpent, Comme les reptiles de la terre; Elles seront saisies de frayeur hors de leurs forteresses; Elles trembleront devant l'Éternel, notre Dieu, Elles te craindront."],[7,18,"Quel Dieu est semblable à toi, Qui pardonnes l'iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la miséricorde.","Quel Dieu est semblable à toi, Qui pardonnes l'iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la miséricorde."],[7,19,"Il aura encore compassion de nous, Il mettra sous ses pieds nos iniquités; Tu jetteras au fond de la mer tous leurs péchés.","Il aura encore compassion de nous, Il mettra sous ses pieds nos iniquités; Tu jetteras au fond de la mer tous leurs péchés."],[7,20,"Tu témoigneras de la fidélité à Jacob, De la bonté à Abraham, Comme tu l'as juré à nos pères aux jours d'autrefois.","Tu témoigneras de la fidélité à Jacob, De la bonté à Abraham, Comme tu l'as juré à nos pères aux jours d'autrefois."]],"spa-rv1909":[[1,1,"PALABRAde JehováquefuéáMiqueasde Morasti en díasde Jotham, Achâz, y Ezechîas, reyesde Judá: lo queviósobreSamariay Jerusalem.","PALABRAde JehováquefuéáMiqueasde Morasti en díasde Jotham, Achâz, y Ezechîas, reyesde Judá: lo queviósobreSamariay Jerusalem."],[1,2,"Oid, pueblostodos: está atenta, tierra, y todo lo que en ella hay: y el SeñorJehová, el Señordesde su santotemploseatestigocontra vosotros.","Oid, pueblostodos: está atenta, tierra, y todo lo que en ella hay: y el SeñorJehová, el Señordesde su santotemploseatestigocontra vosotros."],[1,3,"Porquehe aquí, Jehovásalede su lugar, y descenderá, y hollarásobre las alturas de la tierra.","Porquehe aquí, Jehovásalede su lugar, y descenderá, y hollarásobre las alturas de la tierra."],[1,4,"Y debajode él se derretiránlos montes, y los vallesse hendiráncomo la ceradelantedel fuego, como las aguasque correnpor un precipicio.","Y debajode él se derretiránlos montes, y los vallesse hendiráncomo la ceradelantedel fuego, como las aguasque correnpor un precipicio."],[1,5,"Todoestopor la rebeliónde Jacob, y por los pecadosde la casade Israel. ¿Cuáles la rebeliónde Jacob? ¿noes Samaria? ¿Y cuálesson los excelsos de Judá? ¿noes Jerusalem?","Todoestopor la rebeliónde Jacob, y por los pecadosde la casade Israel. ¿Cuáles la rebeliónde Jacob? ¿noes Samaria? ¿Y cuálesson los excelsos de Judá? ¿noes Jerusalem?"],[1,6,"Pondrépues á Samariaen majanos de heredad, en tierrade viñas; y derramarésus piedraspor el valle, y descubrirésus fundamentos.","Pondrépues á Samariaen majanos de heredad, en tierrade viñas; y derramarésus piedraspor el valle, y descubrirésus fundamentos."],[1,7,"Y todassus estatuasserán despedazadas, y todossus donesserán quemadosen fuego, y asolarétodossus ídolos; porquede donesde rameraslos juntó, y ádonesde ramerasvolverán.","Y todassus estatuasserán despedazadas, y todossus donesserán quemadosen fuego, y asolarétodossus ídolos; porquede donesde rameraslos juntó, y ádonesde ramerasvolverán."],[1,8,"Portanto lamentaréy aullaré, y andarédespojado y desnudo; harégemido como de chacales, y lamentocomo de avestruces.","Portanto lamentaréy aullaré, y andarédespojado y desnudo; harégemido como de chacales, y lamentocomo de avestruces."],[1,9,"Porquesu llagaes dolorosa, que llegóhastaJudá; llegóhastala puertade mi pueblo, hastaJerusalem.","Porquesu llagaes dolorosa, que llegóhastaJudá; llegóhastala puertade mi pueblo, hastaJerusalem."],[1,10,"Nolo digáisen Gath, nilloréismucho: revuélcateen el polvode Beth-le-aphrah.","Nolo digáisen Gath, nilloréismucho: revuélcateen el polvode Beth-le-aphrah."],[1,11,"Pásatedesnudacon vergüenza, oh moradorade Saphir: la moradorade Saanánnosalióal llantode Beth-esel: tomaráde vosotrossu tardanza.","Pásatedesnudacon vergüenza, oh moradorade Saphir: la moradorade Saanánnosalióal llantode Beth-esel: tomaráde vosotrossu tardanza."],[1,12,"Porquela moradorade Marothtuvo dolorpor el bien; por cuanto el maldescendió de Jehováhasta la puertade Jerusalem.","Porquela moradorade Marothtuvo dolorpor el bien; por cuanto el maldescendió de Jehováhasta la puertade Jerusalem."],[1,13,"Unceal carrodromedarios, oh moradorade Lachîs, que fuiste principiode pecadoá la hijade Sión; porqueen ti se inventaron las rebelionesde Israel.","Unceal carrodromedarios, oh moradorade Lachîs, que fuiste principiode pecadoá la hijade Sión; porqueen ti se inventaron las rebelionesde Israel."],[1,14,"Por tanto, tú darásdonesá Moreseth-gath: las casasde Achzibserán en mentiraá los reyesde Israel.","Por tanto, tú darásdonesá Moreseth-gath: las casasde Achzibserán en mentiraá los reyesde Israel."],[1,15,"Aunte traeréheredero, oh moradorade Maresah: la gloriade Israelvendrá hastaAdullam.","Aunte traeréheredero, oh moradorade Maresah: la gloriade Israelvendrá hastaAdullam."],[1,16,"Mésate y trasquílateporlos hijosde tus delicias: ensancha tu calva como águila; porquefueron trasportadosdeti.","Mésate y trasquílateporlos hijosde tus delicias: ensancha tu calva como águila; porquefueron trasportadosdeti."],[2,1,"¡AYde los que piensaniniquidad, y de los que fabricanel malensus camas! Cuando vienela mañanalo ponen en obra, porquetienen en su manoel poder.","¡AYde los que piensaniniquidad, y de los que fabricanel malensus camas! Cuando vienela mañanalo ponen en obra, porquetienen en su manoel poder."],[2,2,"Y codiciaron las heredades, y robáronlas: y casas, y las tomaron: oprimieronal hombrey á su casa, al hombrey á su heredad.","Y codiciaron las heredades, y robáronlas: y casas, y las tomaron: oprimieronal hombrey á su casa, al hombrey á su heredad."],[2,3,"Por tanto, asíha dichoJehová: He aquí, yo piensosobre esta familia un mal, del cualnosacaréisvuestros cuellos, niandaréiserguidos; porqueel tiemposerá malo.","Por tanto, asíha dichoJehová: He aquí, yo piensosobre esta familia un mal, del cualnosacaréisvuestros cuellos, niandaréiserguidos; porqueel tiemposerá malo."],[2,4,"En aquel tiempose levantarásobrevosotros refrán, y se endecharáendechade lamentación, diciendo: Del todofuimos destruídos; ha cambiadola parte de mi pueblo. ¡Cómonos quitónuestroscampos! dió, repartiólosá otros.","En aquel tiempose levantarásobrevosotros refrán, y se endecharáendechade lamentación, diciendo: Del todofuimos destruídos; ha cambiadola parte de mi pueblo. ¡Cómonos quitónuestroscampos! dió, repartiólosá otros."],[2,5,"Por tanto, notendrás quien eche cordel para suerteen la congregaciónde Jehová.","Por tanto, notendrás quien eche cordel para suerteen la congregaciónde Jehová."],[2,6,"Noprofeticéis, dicená los que profetizan; noles profeticenque los ha de comprender vergüenza.","Noprofeticéis, dicená los que profetizan; noles profeticenque los ha de comprender vergüenza."],[2,7,"La que te dicescasade Jacob, ¿hase acortadoel espíritude Jehová? ¿sonéstas sus obras? ¿Mis palabrasnohacen bienal que caminaderechamente?","La que te dicescasade Jacob, ¿hase acortadoel espíritude Jehová? ¿sonéstas sus obras? ¿Mis palabrasnohacen bienal que caminaderechamente?"],[2,8,"El que ayerera mi pueblo, se ha levantadocomo enemigo: tras las vestiduras quitasteislas capasatrevidamenteá los que pasaban, comolos que vuelven de la guerra.","El que ayerera mi pueblo, se ha levantadocomo enemigo: tras las vestiduras quitasteislas capasatrevidamenteá los que pasaban, comolos que vuelven de la guerra."],[2,9,"A las mujeresde mi puebloechasteisfuera de las casasde sus delicias: ásus niñosquitasteismi perpetuaalabanza.","A las mujeresde mi puebloechasteisfuera de las casasde sus delicias: ásus niñosquitasteismi perpetuaalabanza."],[2,10,"Levantaos, y andad, que noes éstala holganza; porqueestácontaminada, corrompióse, y de grandecorrupción.","Levantaos, y andad, que noes éstala holganza; porqueestácontaminada, corrompióse, y de grandecorrupción."],[2,11,"Sihubierealgunoque andecon el viento, y finjamentirasdiciendo: Yote profetizaré de vinoy de sidra; este tal seráprofetaá este pueblo.","Sihubierealgunoque andecon el viento, y finjamentirasdiciendo: Yote profetizaré de vinoy de sidra; este tal seráprofetaá este pueblo."],[2,12,"De ciertote reunirétodo, oh Jacob: recogeréciertamenteel restode Israel: pondrélojuntocomo ovejasde Bosra, como rebañoen mitadde su majada: harán estruendopor la multitud delos hombres.","De ciertote reunirétodo, oh Jacob: recogeréciertamenteel restode Israel: pondrélojuntocomo ovejasde Bosra, como rebañoen mitadde su majada: harán estruendopor la multitud delos hombres."],[2,13,"Subirárompedordelantede ellos; romperány pasaránla puerta, y saldránpor ella: y su reypasarádelantede ellos, y á la cabezade ellos Jehová.","Subirárompedordelantede ellos; romperány pasaránla puerta, y saldránpor ella: y su reypasarádelantede ellos, y á la cabezade ellos Jehová."],[3,1,"Y DIJE: Oidahora, príncipesde Jacob, y cabezasde la casade Israel: ¿Nopertenecíaá vosotros saber el derecho?","Y DIJE: Oidahora, príncipesde Jacob, y cabezasde la casade Israel: ¿Nopertenecíaá vosotros saber el derecho?"],[3,2,"Que aborrecenlo buenoy amanlo malo, que lesquitansu piely su carnede sobrelos huesos;","Que aborrecenlo buenoy amanlo malo, que lesquitansu piely su carnede sobrelos huesos;"],[3,3,"Quecomenasimismo la carnede mi pueblo, y les desuellan su pielde sobreellos, y les quebrantan sus huesosy los rompen, como para el caldero, y como carnesen olla.","Quecomenasimismo la carnede mi pueblo, y les desuellan su pielde sobreellos, y les quebrantan sus huesosy los rompen, como para el caldero, y como carnesen olla."],[3,4,"EntoncesclamaránáJehováy noles responderá; antes esconderáde ellos surostroen aquel tiempo, por cuantohicieronmalvadas obras.","EntoncesclamaránáJehováy noles responderá; antes esconderáde ellos surostroen aquel tiempo, por cuantohicieronmalvadas obras."],[3,5,"Asíha dichoJehováacerca delos profetasque hacen errará mi pueblo, que muerden con sus dientes, y claman, Paz, y al quenoles diereque coman, aplazancontraél batalla:","Asíha dichoJehováacerca delos profetasque hacen errará mi pueblo, que muerden con sus dientes, y claman, Paz, y al quenoles diereque coman, aplazancontraél batalla:"],[3,6,"Por tanto, de la profecíase os hará noche, y oscuridaddel adivinar; y sobrelos profetasse pondráel sol, y el díase entenebrecerásobreellos.","Por tanto, de la profecíase os hará noche, y oscuridaddel adivinar; y sobrelos profetasse pondráel sol, y el díase entenebrecerásobreellos."],[3,7,"Y serán avergonzadoslos profetas, y confundiránselos adivinos; y ellos todoscubriránsu labio, porquenohay respuestade Dios.","Y serán avergonzadoslos profetas, y confundiránselos adivinos; y ellos todoscubriránsu labio, porquenohay respuestade Dios."],[3,8,"Yoempero estoy llenode fuerzadel espíritude Jehová, y de juicio, y de fortaleza, para denunciará Jacobsu rebelión, y á Israelsu pecado.","Yoempero estoy llenode fuerzadel espíritude Jehová, y de juicio, y de fortaleza, para denunciará Jacobsu rebelión, y á Israelsu pecado."],[3,9,"Oidahoraesto, cabezasde la casade Jacob, y capitanesde la casade Israel, que abomináisel juicio, y pervertístodoel derecho;","Oidahoraesto, cabezasde la casade Jacob, y capitanesde la casade Israel, que abomináisel juicio, y pervertístodoel derecho;"],[3,10,"Que edificáisá Sióncon sangre, y á Jerusalemcon injusticia;","Que edificáisá Sióncon sangre, y á Jerusalemcon injusticia;"],[3,11,"Sus cabezasjuzganpor cohecho, y sus sacerdotesenseñanpor precio, y sus profetasadivinanpor dinero; y apóyanseenJehovádiciendo: ¿Noestá Jehováentre nosotros? Novendrámalsobrenosotros.","Sus cabezasjuzganpor cohecho, y sus sacerdotesenseñanpor precio, y sus profetasadivinanpor dinero; y apóyanseenJehovádiciendo: ¿Noestá Jehováentre nosotros? Novendrámalsobrenosotros."],[3,12,"Por tanto, á causa de vosotros será Siónaradacomo campo, y Jerusalemserá majanos, y el montede la casacomo cumbresde breñal.","Por tanto, á causa de vosotros será Siónaradacomo campo, y Jerusalemserá majanos, y el montede la casacomo cumbresde breñal."],[4,1,"Y ACONTECERÁen los postrerostiempos, que el montede la casade Jehováseráconstituídopor cabecerade montes, y más altoque los collados, y correránáélpueblos.","Y ACONTECERÁen los postrerostiempos, que el montede la casade Jehováseráconstituídopor cabecerade montes, y más altoque los collados, y correránáélpueblos."],[4,2,"Y vendránmuchasgentes, y dirán: Venid, y subamosalmontede Jehová, y ála casadel Diosde Jacob; y enseñaránosen sus caminos, y andaremospor sus veredas: porquede Siónsaldrála ley, y de Jerusalemla palabrade Jehová.","Y vendránmuchasgentes, y dirán: Venid, y subamosalmontede Jehová, y ála casadel Diosde Jacob; y enseñaránosen sus caminos, y andaremospor sus veredas: porquede Siónsaldrála ley, y de Jerusalemla palabrade Jehová."],[4,3,"Y juzgaráentremuchospueblos, y corregiráfuertes genteshastamuy lejos: y martillaránsus espadaspara azadones, y sus lanzaspara hoces: noalzaráespadagentecontragente, nimásse ensayaránpara la guerra.","Y juzgaráentremuchospueblos, y corregiráfuertes genteshastamuy lejos: y martillaránsus espadaspara azadones, y sus lanzaspara hoces: noalzaráespadagentecontragente, nimásse ensayaránpara la guerra."],[4,4,"Y cada unose sentarádebajode su vidy debajode su higuera, y nohabrá quien amedrente: porquela bocade Jehováde los ejércitoslo ha hablado.","Y cada unose sentarádebajode su vidy debajode su higuera, y nohabrá quien amedrente: porquela bocade Jehováde los ejércitoslo ha hablado."],[4,5,"Bien que todoslos pueblosanduvieren cada unoen el nombrede sus dioses, nosotroscon todo andaremosen el nombrede JehovánuestroDiospara siemprey eternalmente.","Bien que todoslos pueblosanduvieren cada unoen el nombrede sus dioses, nosotroscon todo andaremosen el nombrede JehovánuestroDiospara siemprey eternalmente."],[4,6,"En aquel día, diceJehová, juntaréla coja, y recogeréla amontada, y á la que afligí;","En aquel día, diceJehová, juntaréla coja, y recogeréla amontada, y á la que afligí;"],[4,7,"Y pondréá la cojapara sucesión, y á la descarriadapara naciónrobusta: y Jehováreinarásobreellos en el montede Sióndesde ahoraparasiempre.","Y pondréá la cojapara sucesión, y á la descarriadapara naciónrobusta: y Jehováreinarásobreellos en el montede Sióndesde ahoraparasiempre."],[4,8,"Y tú, oh torredel rebaño, la fortalezade la hijade Siónvendráhastati: y el señoríoprimero, el reinovendráá la hijade Jerusalem.","Y tú, oh torredel rebaño, la fortalezade la hijade Siónvendráhastati: y el señoríoprimero, el reinovendráá la hijade Jerusalem."],[4,9,"Ahora¿por quégritastanto? ¿Nohay reyen ti? ¿Pereciótu consejero, quete ha tomadodolorcomo de mujer de parto?","Ahora¿por quégritastanto? ¿Nohay reyen ti? ¿Pereciótu consejero, quete ha tomadodolorcomo de mujer de parto?"],[4,10,"Duéletey gime, hijade Sión, como mujer de parto; porqueahorasaldrásde la ciudad, y morarásen el campo, y llegaráshastaBabilonia: allíserás librada, allíte redimiráJehováde la manode tus enemigos.","Duéletey gime, hijade Sión, como mujer de parto; porqueahorasaldrásde la ciudad, y morarásen el campo, y llegaráshastaBabilonia: allíserás librada, allíte redimiráJehováde la manode tus enemigos."],[4,11,"Ahoraempero se han juntadomuchasgentescontrati, y dicen: Sea profanada, y veannuestrosojossu deseosobre Sión.","Ahoraempero se han juntadomuchasgentescontrati, y dicen: Sea profanada, y veannuestrosojossu deseosobre Sión."],[4,12,"Mas ellosnoconocieronlos pensamientosde Jehová, nientendieronsu consejo: porlo cual losjuntócomo gavillasen la era.","Mas ellosnoconocieronlos pensamientosde Jehová, nientendieronsu consejo: porlo cual losjuntócomo gavillasen la era."],[4,13,"Levántatey trilla, hija de Sión, porquetu cuernotornaréde hierro, y tus uñas de metal, y desmenuzarás muchospueblos; y consagrarásá Jehovásus robos, y sus riquezasal Señorde todala tierra.","Levántatey trilla, hija de Sión, porquetu cuernotornaréde hierro, y tus uñas de metal, y desmenuzarás muchospueblos; y consagrarásá Jehovásus robos, y sus riquezasal Señorde todala tierra."],[5,1,"REÚNETEahoraenbandas, oh hijade bandas: noshan sitiado: con varaheriránsobre la quijadaal juezde Israel.","REÚNETEahoraenbandas, oh hijade bandas: noshan sitiado: con varaheriránsobre la quijadaal juezde Israel."],[5,2,"Mas tú, Beth-lehemEphrata, pequeñapara seren los millaresde Judá, detime saldráel que será Señoren Israel; y sus salidas son desdeel principio, desdelos díasdel siglo.","Mas tú, Beth-lehemEphrata, pequeñapara seren los millaresde Judá, detime saldráel que será Señoren Israel; y sus salidas son desdeel principio, desdelos díasdel siglo."],[5,3,"Empero los dejaráhastael tiempoque para la que ha de parir; y el restode sus hermanosse tornarácon los hijosde Israel.","Empero los dejaráhastael tiempoque para la que ha de parir; y el restode sus hermanosse tornarácon los hijosde Israel."],[5,4,"Y estará, y apacentarácon fortalezade Jehová, con grandezadel nombrede Jehovásu Dios: y asentarán; porqueahoraserá engrandecidohastalos finesde la tierra.","Y estará, y apacentarácon fortalezade Jehová, con grandezadel nombrede Jehovásu Dios: y asentarán; porqueahoraserá engrandecidohastalos finesde la tierra."],[5,5,"Y ésteseránuestrapaz. CuandoAssurviniereá nuestratierra, y cuandopisare nuestrospalacios, entonces levantaremoscontraél sietepastores, y ochohombresprincipales;","Y ésteseránuestrapaz. CuandoAssurviniereá nuestratierra, y cuandopisare nuestrospalacios, entonces levantaremoscontraél sietepastores, y ochohombresprincipales;"],[5,6,"Y comeránla tierrade Assurá cuchillo, y la tierrade Nimrodcon sus espadas: y nos librarádel Asirio, cuandovinierecontra nuestratierray hollarenuestrostérminos.","Y comeránla tierrade Assurá cuchillo, y la tierrade Nimrodcon sus espadas: y nos librarádel Asirio, cuandovinierecontra nuestratierray hollarenuestrostérminos."],[5,7,"Y seráel residuode Jacoben mediode muchospueblos, como el rocíode Jehová, como las lluviassobrela hierba, las cualesnoesperanvarón, niaguardaná hijosde hombres.","Y seráel residuode Jacoben mediode muchospueblos, como el rocíode Jehová, como las lluviassobrela hierba, las cualesnoesperanvarón, niaguardaná hijosde hombres."],[5,8,"Asimismo seráel resto de Jacobentre las gentes, en mediode muchospueblos, como el leónentre las bestiasde la montaña, como el cachorrodel leónentre las manadasde las ovejas, el cualsipasare, y hollare, y arrebatare, nohay quien escape.","Asimismo seráel resto de Jacobentre las gentes, en mediode muchospueblos, como el leónentre las bestiasde la montaña, como el cachorrodel leónentre las manadasde las ovejas, el cualsipasare, y hollare, y arrebatare, nohay quien escape."],[5,9,"Tu manose alzarásobretus enemigos, y todostus adversariosserán talados.","Tu manose alzarásobretus enemigos, y todostus adversariosserán talados."],[5,10,"Y aconteceráen aquel día, diceJehová, que haré matartus caballosde en mediode ti, y haré destruirtus carros.","Y aconteceráen aquel día, diceJehová, que haré matartus caballosde en mediode ti, y haré destruirtus carros."],[5,11,"Haré también destruirlas ciudadesde tu tierra, y arruinarétodastus fortalezas.","Haré también destruirlas ciudadesde tu tierra, y arruinarétodastus fortalezas."],[5,12,"Asimismo destruiréde tu manolas hechicerías, y nose hallaránen ti agoreros.","Asimismo destruiréde tu manolas hechicerías, y nose hallaránen ti agoreros."],[5,13,"Y haré destruirtus esculturasy tus imágenesde en mediode ti, y nuncamáste inclinarásá la obrade tus manos;","Y haré destruirtus esculturasy tus imágenesde en mediode ti, y nuncamáste inclinarásá la obrade tus manos;"],[5,14,"Y arrancarétus bosquesde en mediode ti, y destruirétus ciudades.","Y arrancarétus bosquesde en mediode ti, y destruirétus ciudades."],[5,15,"Y con iray con furorharévenganzaen las gentesquenoescucharon.","Y con iray con furorharévenganzaen las gentesquenoescucharon."],[6,1,"OIDahoralo quediceJehová: Levántate, pleitea con los montes, y oiganlos colladostu voz.","OIDahoralo quediceJehová: Levántate, pleitea con los montes, y oiganlos colladostu voz."],[6,2,"Oid, montes, y fuertesfundamentos de la tierra, el pleitode Jehová: porquetiene Jehovápleitoconsu pueblo, y altercaráconIsrael.","Oid, montes, y fuertesfundamentos de la tierra, el pleitode Jehová: porquetiene Jehovápleitoconsu pueblo, y altercaráconIsrael."],[6,3,"Pueblomío, ¿quéte he hecho, ó en quéte he molestado? Respondecontra mí.","Pueblomío, ¿quéte he hecho, ó en quéte he molestado? Respondecontra mí."],[6,4,"Porqueyo te hice subirde la tierrade Egipto, y de la casade siervos te redimí; y enviédelantede ti á Moisés, y á Aarón, y á María.","Porqueyo te hice subirde la tierrade Egipto, y de la casade siervos te redimí; y enviédelantede ti á Moisés, y á Aarón, y á María."],[6,5,"Pueblomío, acuérdateahoraquéaconsejóBalacreyde Moab, y quéle respondióBalaam, hijode Beor, desdeSittimhastaGilgal, para que conozcaslas justiciasde Jehová.","Pueblomío, acuérdateahoraquéaconsejóBalacreyde Moab, y quéle respondióBalaam, hijode Beor, desdeSittimhastaGilgal, para que conozcaslas justiciasde Jehová."],[6,6,"¿Con quéprevendré á Jehová, y adoraréal altoDios? ¿vendréante él con holocaustos, con becerrosde un año?","¿Con quéprevendré á Jehová, y adoraréal altoDios? ¿vendréante él con holocaustos, con becerrosde un año?"],[6,7,"¿AgradaráseJehováde millaresde carneros, ó de diezmilarroyosde aceite? ¿darémi primogénitopor mi rebelión, el frutode mi vientre por el pecadode mi alma?","¿AgradaráseJehováde millaresde carneros, ó de diezmilarroyosde aceite? ¿darémi primogénitopor mi rebelión, el frutode mi vientre por el pecadode mi alma?"],[6,8,"Oh hombre, él te ha declaradoquésea lo bueno, y quépida deti Jehová: solamente hacerjuicio, y amarmisericordia, y humillartepara andar con tu Dios.","Oh hombre, él te ha declaradoquésea lo bueno, y quépida deti Jehová: solamente hacerjuicio, y amarmisericordia, y humillartepara andar con tu Dios."],[6,9,"La vozde Jehováclamaá la ciudad, y el sabiomiraráá tu nombre. Oidla vara, y á quien laestablece.","La vozde Jehováclamaá la ciudad, y el sabiomiraráá tu nombre. Oidla vara, y á quien laestablece."],[6,10,"¿Hay aúnen casadel impíotesorosde impiedad, y medidaescasaque es detestable?","¿Hay aúnen casadel impíotesorosde impiedad, y medidaescasaque es detestable?"],[6,11,"¿Seré limpiocon pesofalso, y con bolsade engañosaspesas?","¿Seré limpiocon pesofalso, y con bolsade engañosaspesas?"],[6,12,"Con lo cual sus ricos se hinchieronde rapiña, y sus moradoreshablaronmentira, y su lenguaengañosaen su boca.","Con lo cual sus ricos se hinchieronde rapiña, y sus moradoreshablaronmentira, y su lenguaengañosaen su boca."],[6,13,"Por eso yotambiénte enflaqueceré hiriéndote, asolándoteportus pecados.","Por eso yotambiénte enflaqueceré hiriéndote, asolándoteportus pecados."],[6,14,"Tú comerás, y note hartarás; y tuabatimientoserá en mediode ti: tú cogerás, mas nosalvarás; y lo quesalvares, lo entregaréyo á la espada.","Tú comerás, y note hartarás; y tuabatimientoserá en mediode ti: tú cogerás, mas nosalvarás; y lo quesalvares, lo entregaréyo á la espada."],[6,15,"Tú sembrarás, mas nosegarás: pisarásaceitunas, mas note ungirás con el aceite; y mosto, mas nobeberásel vino.","Tú sembrarás, mas nosegarás: pisarásaceitunas, mas note ungirás con el aceite; y mosto, mas nobeberásel vino."],[6,16,"Porque los mandamientosde Omrise han guardado, y todaobrade la casade Achâb; y en los consejosde ellos anduvisteis, para que yo te diese en asolamiento, y tus moradorespara ser silbados. Llevaréispor tanto el oprobiode mi pueblo.","Porque los mandamientosde Omrise han guardado, y todaobrade la casade Achâb; y en los consejosde ellos anduvisteis, para que yo te diese en asolamiento, y tus moradorespara ser silbados. Llevaréispor tanto el oprobiode mi pueblo."],[7,1,"¡AYde mí! que he venido á ser como cuando han cogido los frutosdel verano, como cuando han rebuscado después de la vendimia, quenoquedaracimopara comer; mi almadeseóprimeros frutos.","¡AYde mí! que he venido á ser como cuando han cogido los frutosdel verano, como cuando han rebuscado después de la vendimia, quenoquedaracimopara comer; mi almadeseóprimeros frutos."],[7,2,"Faltóel misericordiosodela tierra, y ningunohay rectoentre los hombres: todosacechaná la sangre; cada cualarma redá su hermano.","Faltóel misericordiosodela tierra, y ningunohay rectoentre los hombres: todosacechaná la sangre; cada cualarma redá su hermano."],[7,3,"Paracompletar la maldadcon sus manos, el príncipedemanda, y el juezjuzgapor recompensa; y el grandehablael antojode sualma, y loconfirman.","Paracompletar la maldadcon sus manos, el príncipedemanda, y el juezjuzgapor recompensa; y el grandehablael antojode sualma, y loconfirman."],[7,4,"El mejorde ellos es como el cambrón; el más recto, comozarzal: el díade tus atalayas, tu visitación, viene; ahora serásu confusión.","El mejorde ellos es como el cambrón; el más recto, comozarzal: el díade tus atalayas, tu visitación, viene; ahora serásu confusión."],[7,5,"Nocreáisen amigo, niconfiéisen príncipe: de la que duermeá tu lado, guarda, noabrastu boca.","Nocreáisen amigo, niconfiéisen príncipe: de la que duermeá tu lado, guarda, noabrastu boca."],[7,6,"Porqueel hijodeshonraal padre, la hijase levantacontra la madre, la nueracontra su suegra: y los enemigosdel hombreson losde su casa.","Porqueel hijodeshonraal padre, la hijase levantacontra la madre, la nueracontra su suegra: y los enemigosdel hombreson losde su casa."],[7,7,"Yoempero á Jehováesperaré, esperaréal Diosde misalud: el Diosmíomeoirá.","Yoempero á Jehováesperaré, esperaréal Diosde misalud: el Diosmíomeoirá."],[7,8,"Tú, enemiga mía, no tehuelgues de mí: porqueaunque caí, he de levantarme; aunquemoreen tinieblas, Jehováserá mi luz.","Tú, enemiga mía, no tehuelgues de mí: porqueaunque caí, he de levantarme; aunquemoreen tinieblas, Jehováserá mi luz."],[7,9,"La irade Jehovásoportaré, porquepequécontra él, hastaquejuzguemi causay hagami juicio; él me sacaráá luz; verésu justicia.","La irade Jehovásoportaré, porquepequécontra él, hastaquejuzguemi causay hagami juicio; él me sacaráá luz; verésu justicia."],[7,10,"Y mi enemigaverá, y la cubrirávergüenza: la que medecía: ¿Dóndeestá Jehovátu Dios? Mis ojosla verán; ahoraseráholladacomo lodode las calles.","Y mi enemigaverá, y la cubrirávergüenza: la que medecía: ¿Dóndeestá Jehovátu Dios? Mis ojosla verán; ahoraseráholladacomo lodode las calles."],[7,11,"El díaen que se edificarántus muros, aquel díaserá alejadoel mandamiento.","El díaen que se edificarántus muros, aquel díaserá alejadoel mandamiento."],[7,12,"En esedíavendránhastati desdeAsiriay las ciudadesfuertes, y desdelas ciudades fuerteshastael Río, y demará mar, y demonteá monte.","En esedíavendránhastati desdeAsiriay las ciudadesfuertes, y desdelas ciudades fuerteshastael Río, y demará mar, y demonteá monte."],[7,13,"Y la tierracon sus moradoresseráasoladapor el frutode sus obras.","Y la tierracon sus moradoresseráasoladapor el frutode sus obras."],[7,14,"Apacientatu pueblocon tu cayado, el rebañode tu heredad, que morasoloen la montaña, en medio del Carmelo: pazcanen Basány Galaad, como en el tiempopasado.","Apacientatu pueblocon tu cayado, el rebañode tu heredad, que morasoloen la montaña, en medio del Carmelo: pazcanen Basány Galaad, como en el tiempopasado."],[7,15,"Yo les mostrarémaravillascomo el díaque salistede Egipto.","Yo les mostrarémaravillascomo el díaque salistede Egipto."],[7,16,"Las gentesverán, y se avergonzaránde todas sus valentías; pondránla manosobresu boca, ensordeceránsus oídos.","Las gentesverán, y se avergonzaránde todas sus valentías; pondránla manosobresu boca, ensordeceránsus oídos."],[7,17,"Lameránel polvocomo la culebra; como las serpientesde la tierra, temblaránensus encierros: despavorirsehan deJehovánuestroDios, y temerándeti.","Lameránel polvocomo la culebra; como las serpientesde la tierra, temblaránensus encierros: despavorirsehan deJehovánuestroDios, y temerándeti."],[7,18,"¿QuéDioscomo tú, que perdonas la maldad, y olvidasel pecadodel restode suheredad? Noretuvopara siempresuenojo, porquees amadorde misericordia.","¿QuéDioscomo tú, que perdonas la maldad, y olvidasel pecadodel restode suheredad? Noretuvopara siempresuenojo, porquees amadorde misericordia."],[7,19,"El tornará, él tendrá misericordiade nosotros; él sujetaránuestrasiniquidades, y echaráen los profundos de la martodosnuestros pecados.","El tornará, él tendrá misericordiade nosotros; él sujetaránuestrasiniquidades, y echaráen los profundos de la martodosnuestros pecados."],[7,20,"Otorgarás á Jacobla verdad, y á Abrahamla misericordia, quetú jurasteá nuestrospadresdesde tiemposantiguos.","Otorgarás á Jacobla verdad, y á Abrahamla misericordia, quetú jurasteá nuestrospadresdesde tiemposantiguos."]],"rus-synodal":[[1,1,"Слово Господне, которое было к Михею Морасфитину во дни Иоафама, Ахаза и Езекии, царей Иудейских, и которое открыто ему о Самарии и Иерусалиме.","Slovo Gospodne, kotoroe bylo k Miheû Morasfitinu vo dni Ioafama, Ahaza i Ezekii, carej Iudejskih, i kotoroe otkryto emu o Samarii i Ierusalime."],[1,2,"Слушайте, все народы, внимай, земля и все, что наполняет ее! Да будет Господь Бог свидетелем против вас, Господь из святого храма Своего!","Slušajte, vse narody, vnimaj, zemlâ i vse, čto napolnâet ee! Da budet Gospodʹ Bog svidetelem protiv vas, Gospodʹ iz svâtogo hrama Svoego!"],[1,3,"Ибо вот, Господь исходит от места Своего, низойдет и наступит на высоты земли, –","Ibo vot, Gospodʹ ishodit ot mesta Svoego, nizojdet i nastupit na vysoty zemli, –"],[1,4,"и горы растают под Ним, долины распадутся, как воск от огня, как воды, льющиеся с крутизны.","i gory rastaût pod Nim, doliny raspadutsâ, kak vosk ot ognâ, kak vody, lʹûŝiesâ s krutizny."],[1,5,"Все это – за нечестие Иакова, за грех дома Израилева. От кого нечестие Иакова? не от Самарии ли? Кто устроил высоты в Иудее? не Иерусалим ли?","Vse éto – za nečestie Iakova, za greh doma Izraileva. Ot kogo nečestie Iakova? ne ot Samarii li? Kto ustroil vysoty v Iudee? ne Ierusalim li?"],[1,6,"За то сделаю Самарию грудою развалин в поле, местом для разведения винограда; низрину в долину камни ее и обнажу основания ее.","Za to sdelaû Samariû grudoû razvalin v pole, mestom dlâ razvedeniâ vinograda; nizrinu v dolinu kamni ee i obnažu osnovaniâ ee."],[1,7,"Все истуканы ее будут разбиты и все любодейные дары ее сожжены будут огнем, и всех идолов ее предам разрушению, ибо из любодейных даров она устраивала их, на любодейные дары они и будут обращены.","Vse istukany ee budut razbity i vse lûbodejnye dary ee sožženy budut ognem, i vseh idolov ee predam razrušeniû, ibo iz lûbodejnyh darov ona ustraivala ih, na lûbodejnye dary oni i budut obraŝeny."],[1,8,"Об этом буду я плакать и рыдать, буду ходить, как ограбленный и обнаженный, выть, как шакалы, и плакать, как страусы,","Ob étom budu â plakatʹ i rydatʹ, budu hoditʹ, kak ograblennyj i obnažennyj, vytʹ, kak šakaly, i plakatʹ, kak strausy,"],[1,9,"потому что болезненно поражение ее, дошло до Иуды, достигло даже до ворот народа моего, до Иерусалима.","potomu čto boleznenno poraženie ee, došlo do Iudy, dostiglo daže do vorot naroda moego, do Ierusalima."],[1,10,"Не объявляйте об этом в Гефе, не плачьте там громко; но в селении Офра покрой себя пеплом.","Ne obʺâvlâjte ob étom v Gefe, ne plačʹte tam gromko; no v selenii Ofra pokroj sebâ peplom."],[1,11,"Переселяйтесь, жительницы Шафира, срамно обнаженные; не убежит и живущая в Цаане; плач в селении Ецель не даст вам остановиться в нем.","Pereselâjtesʹ, žitelʹnicy Šafira, sramno obnažennye; ne ubežit i živuŝaâ v Caane; plač v selenii Ecelʹ ne dast vam ostanovitʹsâ v nem."],[1,12,"Горюет о своем добре жительница Марофы, ибо сошло бедствие от Господа к воротам Иерусалима.","Gorûet o svoem dobre žitelʹnica Marofy, ibo sošlo bedstvie ot Gospoda k vorotam Ierusalima."],[1,13,"Запрягай в колесницу быстрых, жительница Лахиса; ты – начало греха дщери Сионовой, ибо у тебя появились преступления Израиля.","Zaprâgaj v kolesnicu bystryh, žitelʹnica Lahisa; ty – načalo greha dŝeri Sionovoj, ibo u tebâ poâvilisʹ prestupleniâ Izrailâ."],[1,14,"Посему ты посылать будешь дары в Морешеф-Геф; но селения Ахзива будут обманом для царей Израилевых.","Posemu ty posylatʹ budešʹ dary v Morešef-Gef; no seleniâ Ahziva budut obmanom dlâ carej Izrailevyh."],[1,15,"Еще наследника приведу к тебе, жительница Мореша; он пройдет до Одоллама, славы Израиля.","Eŝe naslednika privedu k tebe, žitelʹnica Moreša; on projdet do Odollama, slavy Izrailâ."],[1,16,"Сними с себя волосы, остригись, скорбя о нежно любимых сынах твоих; расширь из-за них лысину, как у линяющего орла, ибо они переселены будут от тебя.","Snimi s sebâ volosy, ostrigisʹ, skorbâ o nežno lûbimyh synah tvoih; rasširʹ iz-za nih lysinu, kak u linâûŝego orla, ibo oni pereseleny budut ot tebâ."],[2,1,"Горе замышляющим беззаконие и на ложах своих придумывающим злодеяния, которые совершают утром на рассвете, потому что есть в руке их сила!","Gore zamyšlâûŝim bezzakonie i na ložah svoih pridumyvaûŝim zlodeâniâ, kotorye soveršaût utrom na rassvete, potomu čto estʹ v ruke ih sila!"],[2,2,"Пожелают полей и берут их силою, домов – и отнимают их; обирают человека и его дом, мужа и его наследие.","Poželaût polej i berut ih siloû, domov – i otnimaût ih; obiraût čeloveka i ego dom, muža i ego nasledie."],[2,3,"Посему так говорит Господь: вот, Я помышляю навести на этот род такое бедствие, которого вы не свергнете с шеи вашей, и не будете ходить выпрямившись; ибо это время злое.","Posemu tak govorit Gospodʹ: vot, Â pomyšlâû navesti na étot rod takoe bedstvie, kotorogo vy ne svergnete s šei vašej, i ne budete hoditʹ vyprâmivšisʹ; ibo éto vremâ zloe."],[2,4,"В тот день произнесут о вас притчу и будут плакать горьким плачем и говорить: «мы совершенно разорены! удел народа моего отдан другим; как возвратится ко мне! поля наши уже разделены иноплеменникам».","V tot denʹ proiznesut o vas pritču i budut plakatʹ gorʹkim plačem i govoritʹ: «my soveršenno razoreny! udel naroda moego otdan drugim; kak vozvratitsâ ko mne! polâ naši uže razdeleny inoplemennikam»."],[2,5,"Посему не будет у тебя никого, кто бросил бы жребий для измерения в собрании пред Господом.","Posemu ne budet u tebâ nikogo, kto brosil by žrebij dlâ izmereniâ v sobranii pred Gospodom."],[2,6,"Не пророчествуйте, пророки; не пророчествуйте им, чтобы не постигло вас бесчестие.","Ne proročestvujte, proroki; ne proročestvujte im, čtoby ne postiglo vas besčestie."],[2,7,"О, называющийся домом Иакова! разве умалился Дух Господень? таковы ли действия Его? не благотворны ли слова Мои для того, кто поступает справедливо?","O, nazyvaûŝijsâ domom Iakova! razve umalilsâ Duh Gospodenʹ? takovy li dejstviâ Ego? ne blagotvorny li slova Moi dlâ togo, kto postupaet spravedlivo?"],[2,8,"Народ же, который был прежде Моим, восстал как враг, и вы отнимаете как верхнюю, так и нижнюю одежду у проходящих мирно, отвращающихся войны.","Narod že, kotoryj byl prežde Moim, vosstal kak vrag, i vy otnimaete kak verhnûû, tak i nižnûû odeždu u prohodâŝih mirno, otvraŝaûŝihsâ vojny."],[2,9,"Жен народа Моего вы изгоняете из приятных домов их; у детей их вы навсегда отнимаете украшение Мое.","Žen naroda Moego vy izgonâete iz priâtnyh domov ih; u detej ih vy navsegda otnimaete ukrašenie Moe."],[2,10,"Встаньте и уходите, ибо страна сия не есть место покоя; за нечистоту она будет разорена, и притом жестоким разорением.","Vstanʹte i uhodite, ibo strana siâ ne estʹ mesto pokoâ; za nečistotu ona budet razorena, i pritom žestokim razoreniem."],[2,11,"Если бы какой-либо ветреник выдумал ложь и сказал: «я буду проповедовать тебе о вине и сикере», то он и был бы угодным проповедником для этого народа.","Esli by kakoj-libo vetrenik vydumal ložʹ i skazal: «â budu propovedovatʹ tebe o vine i sikere», to on i byl by ugodnym propovednikom dlâ étogo naroda."],[2,12,"Непременно соберу всего тебя, Иаков, непременно соединю остатки Израиля, совокуплю их воедино, как овец в Восоре, как стадо в овечьем загоне; зашумят они от многолюдства.","Nepremenno soberu vsego tebâ, Iakov, nepremenno soedinû ostatki Izrailâ, sovokuplû ih voedino, kak ovec v Vosore, kak stado v ovečʹem zagone; zašumât oni ot mnogolûdstva."],[2,13,"Перед ними пойдет стенорушитель; они сокрушат преграды, войдут сквозь ворота и выйдут ими; и царь их пойдет перед ними, а во главе их – Господь.","Pered nimi pojdet stenorušitelʹ; oni sokrušat pregrady, vojdut skvozʹ vorota i vyjdut imi; i carʹ ih pojdet pered nimi, a vo glave ih – Gospodʹ."],[3,1,"И сказал я: слушайте, главы Иакова и князья дома Израилева: не вам ли должно знать правду?","I skazal â: slušajte, glavy Iakova i knâzʹâ doma Izraileva: ne vam li dolžno znatʹ pravdu?"],[3,2,"А вы ненавидите доброе и любите злое; сдираете с них кожу их и плоть с костей их,","A vy nenavidite dobroe i lûbite zloe; sdiraete s nih kožu ih i plotʹ s kostej ih,"],[3,3,"едите плоть народа Моего и сдираете с них кожу их, а кости их ломаете и дробите как бы в горшок, и плоть – как бы в котел.","edite plotʹ naroda Moego i sdiraete s nih kožu ih, a kosti ih lomaete i drobite kak by v goršok, i plotʹ – kak by v kotel."],[3,4,"И будут они взывать к Господу, но Он не услышит их и сокроет лицо Свое от них на то время, как они злодействуют.","I budut oni vzyvatʹ k Gospodu, no On ne uslyšit ih i sokroet lico Svoe ot nih na to vremâ, kak oni zlodejstvuût."],[3,5,"Так говорит Господь на пророков, вводящих в заблуждение народ Мой, которые грызут зубами своими – и проповедуют мир, а кто ничего не кладет им в рот, против того объявляют войну.","Tak govorit Gospodʹ na prorokov, vvodâŝih v zabluždenie narod Moj, kotorye gryzut zubami svoimi – i propoveduût mir, a kto ničego ne kladet im v rot, protiv togo obʺâvlâût vojnu."],[3,6,"Посему ночь будет вам вместо видения и тьма – вместо предвещаний; зайдет солнце над пророками, и потемнеет день над ними.","Posemu nočʹ budet vam vmesto videniâ i tʹma – vmesto predveŝanij; zajdet solnce nad prorokami, i potemneet denʹ nad nimi."],[3,7,"И устыдятся прозорливцы, и посрамлены будут гадатели, и закроют уста свои все они, потому что не будет ответа от Бога.","I ustydâtsâ prozorlivcy, i posramleny budut gadateli, i zakroût usta svoi vse oni, potomu čto ne budet otveta ot Boga."],[3,8,"А я исполнен силы Духа Господня, правоты и твердости, чтобы высказать Иакову преступление его и Израилю грех его.","A â ispolnen sily Duha Gospodnâ, pravoty i tverdosti, čtoby vyskazatʹ Iakovu prestuplenie ego i Izrailû greh ego."],[3,9,"Слушайте же это, главы дома Иаковлева и князья дома Израилева, гнушающиеся правосудием и искривляющие все прямое,","Slušajte že éto, glavy doma Iakovleva i knâzʹâ doma Izraileva, gnušaûŝiesâ pravosudiem i iskrivlâûŝie vse prâmoe,"],[3,10,"созидающие Сион кровью и Иерусалим – неправдою!","sozidaûŝie Sion krovʹû i Ierusalim – nepravdoû!"],[3,11,"Главы его судят за подарки и священники его учат за плату, и пророки его предвещают за деньги, а между тем опираются на Господа, говоря: «не среди ли нас Господь? не постигнет нас беда!»","Glavy ego sudât za podarki i svâŝenniki ego učat za platu, i proroki ego predveŝaût za denʹgi, a meždu tem opiraûtsâ na Gospoda, govorâ: «ne sredi li nas Gospodʹ? ne postignet nas beda!»"],[3,12,"Посему за вас Сион распахан будет как поле, и Иерусалим сделается грудою развалин, и гора дома сего будет лесистым холмом.","Posemu za vas Sion raspahan budet kak pole, i Ierusalim sdelaetsâ grudoû razvalin, i gora doma sego budet lesistym holmom."],[4,1,"И будет в последние дни: гора дома Господня поставлена будет во главу гор и возвысится над холмами, и потекут к ней народы.","I budet v poslednie dni: gora doma Gospodnâ postavlena budet vo glavu gor i vozvysitsâ nad holmami, i potekut k nej narody."],[4,2,"И пойдут многие народы и скажут: придите, и взойдем на гору Господню и в дом Бога Иаковлева, и Он научит нас путям Своим, и будем ходить по стезям Его, ибо от Сиона выйдет закон и слово Господне – из Иерусалима.","I pojdut mnogie narody i skažut: pridite, i vzojdem na goru Gospodnû i v dom Boga Iakovleva, i On naučit nas putâm Svoim, i budem hoditʹ po stezâm Ego, ibo ot Siona vyjdet zakon i slovo Gospodne – iz Ierusalima."],[4,3,"И будет Он судить многие народы и обличит многие племена в отдаленных странах; и перекуют они мечи свои на орала и копья свои – на серпы; не поднимет народ на народ меча, и не будут более учиться воевать.","I budet On suditʹ mnogie narody i obličit mnogie plemena v otdalennyh stranah; i perekuût oni meči svoi na orala i kopʹâ svoi – na serpy; ne podnimet narod na narod meča, i ne budut bolee učitʹsâ voevatʹ."],[4,4,"Но каждый будет сидеть под своею виноградною лозою и под своею смоковницею, и никто не будет устрашать их, ибо уста Господа Саваофа изрекли это.","No každyj budet sidetʹ pod svoeû vinogradnoû lozoû i pod svoeû smokovniceû, i nikto ne budet ustrašatʹ ih, ibo usta Gospoda Savaofa izrekli éto."],[4,5,"Ибо все народы ходят, каждый во имя своего бога; а мы будем ходить во имя Господа Бога нашего во веки веков.","Ibo vse narody hodât, každyj vo imâ svoego boga; a my budem hoditʹ vo imâ Gospoda Boga našego vo veki vekov."],[4,6,"В тот день, говорит Господь, соберу хромлющее и совокуплю разогнанное и тех, на кого Я навел бедствие.","V tot denʹ, govorit Gospodʹ, soberu hromlûŝee i sovokuplû razognannoe i teh, na kogo Â navel bedstvie."],[4,7,"И сделаю хромлющее остатком и далеко рассеянное сильным народом, и Господь будет царствовать над ними на горе Сионе отныне и до века.","I sdelaû hromlûŝee ostatkom i daleko rasseânnoe silʹnym narodom, i Gospodʹ budet carstvovatʹ nad nimi na gore Sione otnyne i do veka."],[4,8,"А ты, башня стада, холм дщери Сиона! к тебе придет и возвратится прежнее владычество, царство – к дщерям Иерусалима.","A ty, bašnâ stada, holm dŝeri Siona! k tebe pridet i vozvratitsâ prežnee vladyčestvo, carstvo – k dŝerâm Ierusalima."],[4,9,"Для чего же ты ныне так громко вопиешь? Разве нет у тебя царя? Или не стало у тебя советника, что тебя схватили муки, как рождающую?","Dlâ čego že ty nyne tak gromko vopiešʹ? Razve net u tebâ carâ? Ili ne stalo u tebâ sovetnika, čto tebâ shvatili muki, kak roždaûŝuû?"],[4,10,"Страдай и мучься болями, дщерь Сиона, как рождающая, ибо ныне ты выйдешь из города и будешь жить в поле, и дойдешь до Вавилона: там будешь спасена, там искупит тебя Господь от руки врагов твоих.","Stradaj i mučʹsâ bolâmi, dŝerʹ Siona, kak roždaûŝaâ, ibo nyne ty vyjdešʹ iz goroda i budešʹ žitʹ v pole, i dojdešʹ do Vavilona: tam budešʹ spasena, tam iskupit tebâ Gospodʹ ot ruki vragov tvoih."],[4,11,"А теперь собрались против тебя многие народы и говорят: «да будет она осквернена, и да наглядится око наше на Сион!»","A teperʹ sobralisʹ protiv tebâ mnogie narody i govorât: «da budet ona oskvernena, i da naglâditsâ oko naše na Sion!»"],[4,12,"Но они не знают мыслей Господних и не разумеют совета Его, что Он собрал их как снопы на гумно.","No oni ne znaût myslej Gospodnih i ne razumeût soveta Ego, čto On sobral ih kak snopy na gumno."],[4,13,"Встань и молоти, дщерь Сиона, ибо Я сделаю рог твой железным и копыта твои сделаю медными, и сокрушишь многие народы, и посвятишь Господу стяжания их и богатства их Владыке всей земли.","Vstanʹ i moloti, dŝerʹ Siona, ibo Â sdelaû rog tvoj železnym i kopyta tvoi sdelaû mednymi, i sokrušišʹ mnogie narody, i posvâtišʹ Gospodu stâžaniâ ih i bogatstva ih Vladyke vsej zemli."],[5,1,"Теперь ополчись, дщерь полчищ; обложили нас осадою, тростью будут бить по ланите судью Израилева.","Teperʹ opolčisʹ, dŝerʹ polčiŝ; obložili nas osadoû, trostʹû budut bitʹ po lanite sudʹû Izraileva."],[5,2,"И ты, Вифлеем-Ефрафа, мал ли ты между тысячами Иудиными? из тебя произойдет Мне Тот, Который должен быть Владыкою в Израиле и Которого происхождение из начала, от дней вечных.","I ty, Vifleem-Efrafa, mal li ty meždu tysâčami Iudinymi? iz tebâ proizojdet Mne Tot, Kotoryj dolžen bytʹ Vladykoû v Izraile i Kotorogo proishoždenie iz načala, ot dnej večnyh."],[5,3,"Посему Он оставит их до времени, доколе не родит имеющая родить; тогда возвратятся к сынам Израиля и оставшиеся братья их.","Posemu On ostavit ih do vremeni, dokole ne rodit imeûŝaâ roditʹ; togda vozvratâtsâ k synam Izrailâ i ostavšiesâ bratʹâ ih."],[5,4,"И станет Он, и будет пасти в силе Господней, в величии имени Господа Бога Своего, и они будут жить безопасно, ибо тогда Он будет великим до краев земли.","I stanet On, i budet pasti v sile Gospodnej, v veličii imeni Gospoda Boga Svoego, i oni budut žitʹ bezopasno, ibo togda On budet velikim do kraev zemli."],[5,5,"И будет Он – мир. Когда Ассур придет в нашу землю и вступит в наши чертоги, мы выставим против него семь пастырей и восемь князей.","I budet On – mir. Kogda Assur pridet v našu zemlû i vstupit v naši čertogi, my vystavim protiv nego semʹ pastyrej i vosemʹ knâzej."],[5,6,"И будут они пасти землю Ассура мечом и землю Немврода в самых воротах ее, и Он-то избавит от Ассура, когда тот придет в землю нашу и когда вступит в пределы наши.","I budut oni pasti zemlû Assura mečom i zemlû Nemvroda v samyh vorotah ee, i On-to izbavit ot Assura, kogda tot pridet v zemlû našu i kogda vstupit v predely naši."],[5,7,"И будет остаток Иакова среди многих народов как роса от Господа, как ливень на траве, и он не будет зависеть от человека и полагаться на сынов Адамовых.","I budet ostatok Iakova sredi mnogih narodov kak rosa ot Gospoda, kak livenʹ na trave, i on ne budet zavisetʹ ot čeloveka i polagatʹsâ na synov Adamovyh."],[5,8,"И будет остаток Иакова между народами, среди многих племен, как лев среди зверей лесных, как скимен среди стада овец, который, когда выступит, то попирает и терзает, и никто не спасет от него.","I budet ostatok Iakova meždu narodami, sredi mnogih plemen, kak lev sredi zverej lesnyh, kak skimen sredi stada ovec, kotoryj, kogda vystupit, to popiraet i terzaet, i nikto ne spaset ot nego."],[5,9,"Поднимется рука твоя над врагами твоими, и все неприятели твои будут истреблены.","Podnimetsâ ruka tvoâ nad vragami tvoimi, i vse nepriâteli tvoi budut istrebleny."],[5,10,"И будет в тот день, говорит Господь: истреблю коней твоих из среды твоей и уничтожу колесницы твои,","I budet v tot denʹ, govorit Gospodʹ: istreblû konej tvoih iz sredy tvoej i uničtožu kolesnicy tvoi,"],[5,11,"истреблю города в земле твоей и разрушу все укрепления твои,","istreblû goroda v zemle tvoej i razrušu vse ukrepleniâ tvoi,"],[5,12,"исторгну чародеяния из руки твоей, и гадающих по облакам не будет у тебя;","istorgnu čarodeâniâ iz ruki tvoej, i gadaûŝih po oblakam ne budet u tebâ;"],[5,13,"истреблю истуканов твоих и кумиров из среды твоей, и не будешь более поклоняться изделиям рук твоих.","istreblû istukanov tvoih i kumirov iz sredy tvoej, i ne budešʹ bolee poklonâtʹsâ izdeliâm ruk tvoih."],[5,14,"Искореню из среды твоей священные рощи твои и разорю города твои.","Iskorenû iz sredy tvoej svâŝennye roŝi tvoi i razorû goroda tvoi."],[5,15,"И совершу в гневе и негодовании мщение над народами, которые будут непослушны.","I soveršu v gneve i negodovanii mŝenie nad narodami, kotorye budut neposlušny."],[6,1,"Слушайте, что говорит Господь: встань, судись перед горами, и холмы да слышат голос твой!","Slušajte, čto govorit Gospodʹ: vstanʹ, sudisʹ pered gorami, i holmy da slyšat golos tvoj!"],[6,2,"Слушайте, горы, суд Господень, и вы, твердые основы земли: ибо у Господа суд с народом Своим, и с Израилем Он состязуется.","Slušajte, gory, sud Gospodenʹ, i vy, tverdye osnovy zemli: ibo u Gospoda sud s narodom Svoim, i s Izrailem On sostâzuetsâ."],[6,3,"Народ Мой! что сделал Я тебе и чем отягощал тебя? отвечай Мне.","Narod Moj! čto sdelal Â tebe i čem otâgoŝal tebâ? otvečaj Mne."],[6,4,"Я вывел тебя из земли Египетской и искупил тебя из дома рабства, и послал перед тобою Моисея, Аарона и Мариам.","Â vyvel tebâ iz zemli Egipetskoj i iskupil tebâ iz doma rabstva, i poslal pered toboû Moiseâ, Aarona i Mariam."],[6,5,"Народ Мой! вспомни, что замышлял Валак, царь Моавитский, и что отвечал ему Валаам, сын Веоров, и что происходило от Ситтима до Галгал, чтобы познать тебе праведные действия Господни.","Narod Moj! vspomni, čto zamyšlâl Valak, carʹ Moavitskij, i čto otvečal emu Valaam, syn Veorov, i čto proishodilo ot Sittima do Galgal, čtoby poznatʹ tebe pravednye dejstviâ Gospodni."],[6,6,"«С чем предстать мне пред Господом, преклониться пред Богом небесным? Предстать ли пред Ним со всесожжениями, с тельцами однолетними?","«S čem predstatʹ mne pred Gospodom, preklonitʹsâ pred Bogom nebesnym? Predstatʹ li pred Nim so vsesožženiâmi, s telʹcami odnoletnimi?"],[6,7,"Но можно ли угодить Господу тысячами овнов или неисчетными потоками елея? Разве дам Ему первенца моего за преступление мое и плод чрева моего – за грех души моей?»","No možno li ugoditʹ Gospodu tysâčami ovnov ili neisčetnymi potokami eleâ? Razve dam Emu pervenca moego za prestuplenie moe i plod čreva moego – za greh duši moej?»"],[6,8,"О, человек! сказано тебе, что – добро и чего требует от тебя Господь: действовать справедливо, любить дела милосердия и смиренномудренно ходить пред Богом твоим.","O, čelovek! skazano tebe, čto – dobro i čego trebuet ot tebâ Gospodʹ: dejstvovatʹ spravedlivo, lûbitʹ dela miloserdiâ i smirennomudrenno hoditʹ pred Bogom tvoim."],[6,9,"Глас Господа взывает к городу, и мудрость благоговеет пред именем Твоим: слушайте жезл и Того, Кто поставил его.","Glas Gospoda vzyvaet k gorodu, i mudrostʹ blagogoveet pred imenem Tvoim: slušajte žezl i Togo, Kto postavil ego."],[6,10,"Не находятся ли и теперь в доме нечестивого сокровища нечестия и уменьшенная мера, отвратительная?","Ne nahodâtsâ li i teperʹ v dome nečestivogo sokroviŝa nečestiâ i umenʹšennaâ mera, otvratitelʹnaâ?"],[6,11,"Могу ли я быть чистым с весами неверными и с обманчивыми гирями в суме?","Mogu li â bytʹ čistym s vesami nevernymi i s obmančivymi girâmi v sume?"],[6,12,"Так как богачи его исполнены неправды, и жители его говорят ложь, и язык их есть обман в устах их,","Tak kak bogači ego ispolneny nepravdy, i žiteli ego govorât ložʹ, i âzyk ih estʹ obman v ustah ih,"],[6,13,"то и Я неисцельно поражу тебя опустошением за грехи твои.","to i Â neiscelʹno poražu tebâ opustošeniem za grehi tvoi."],[6,14,"Ты будешь есть и не будешь сыт; пустота будет внутри тебя; будешь хранить, но не убережешь, а что сбережешь, то предам мечу.","Ty budešʹ estʹ i ne budešʹ syt; pustota budet vnutri tebâ; budešʹ hranitʹ, no ne uberežešʹ, a čto sberežešʹ, to predam meču."],[6,15,"Будешь сеять, а жать не будешь; будешь давить оливки и не будешь умащаться елеем; выжмешь виноградный сок, а вина пить не будешь.","Budešʹ seâtʹ, a žatʹ ne budešʹ; budešʹ davitʹ olivki i ne budešʹ umaŝatʹsâ eleem; vyžmešʹ vinogradnyj sok, a vina pitʹ ne budešʹ."],[6,16,"Сохранились у вас обычаи Амврия и все дела дома Ахавова, и вы поступаете по советам их; и предам Я тебя опустошению и жителей твоих посмеянию, и вы понесете поругание народа Моего.","Sohranilisʹ u vas obyčai Amvriâ i vse dela doma Ahavova, i vy postupaete po sovetam ih; i predam Â tebâ opustošeniû i žitelej tvoih posmeâniû, i vy ponesete poruganie naroda Moego."],[7,1,"Горе мне! ибо со мною теперь – как по собрании летних плодов, как по уборке винограда: ни одной ягоды для еды, ни спелого плода, которого желает душа моя.","Gore mne! ibo so mnoû teperʹ – kak po sobranii letnih plodov, kak po uborke vinograda: ni odnoj âgody dlâ edy, ni spelogo ploda, kotorogo želaet duša moâ."],[7,2,"Не стало милосердых на земле, нет правдивых между людьми; все строят ковы, чтобы проливать кровь; каждый ставит брату своему сеть.","Ne stalo miloserdyh na zemle, net pravdivyh meždu lûdʹmi; vse stroât kovy, čtoby prolivatʹ krovʹ; každyj stavit bratu svoemu setʹ."],[7,3,"Руки их обращены к тому, чтобы уметь делать зло; начальник требует подарков, и судья судит за взятки, а вельможи высказывают злые хотения души своей и извращают дело.","Ruki ih obraŝeny k tomu, čtoby umetʹ delatʹ zlo; načalʹnik trebuet podarkov, i sudʹâ sudit za vzâtki, a velʹmoži vyskazyvaût zlye hoteniâ duši svoej i izvraŝaût delo."],[7,4,"Лучший из них – как терн, и справедливый – хуже колючей изгороди, день провозвестников Твоих, посещение Твое наступает; ныне постигнет их смятение.","Lučšij iz nih – kak tern, i spravedlivyj – huže kolûčej izgorodi, denʹ provozvestnikov Tvoih, poseŝenie Tvoe nastupaet; nyne postignet ih smâtenie."],[7,5,"Не верьте другу, не полагайтесь на приятеля; от лежащей на лоне твоем стереги двери уст твоих.","Ne verʹte drugu, ne polagajtesʹ na priâtelâ; ot ležaŝej na lone tvoem steregi dveri ust tvoih."],[7,6,"Ибо сын позорит отца, дочь восстает против матери, невестка – против свекрови своей; враги человеку – домашние его.","Ibo syn pozorit otca, dočʹ vosstaet protiv materi, nevestka – protiv svekrovi svoej; vragi čeloveku – domašnie ego."],[7,7,"А я буду взирать на Господа, уповать на Бога спасения моего: Бог мой услышит меня.","A â budu vziratʹ na Gospoda, upovatʹ na Boga spaseniâ moego: Bog moj uslyšit menâ."],[7,8,"Не радуйся ради меня, неприятельница моя! хотя я упал, но встану; хотя я во мраке, но Господь – свет для меня.","Ne radujsâ radi menâ, nepriâtelʹnica moâ! hotâ â upal, no vstanu; hotâ â vo mrake, no Gospodʹ – svet dlâ menâ."],[7,9,"Гнев Господень я буду нести, потому что согрешил пред Ним, доколе Он не решит дела моего и не совершит суда надо мною; тогда Он выведет меня на свет, и я увижу правду Его.","Gnev Gospodenʹ â budu nesti, potomu čto sogrešil pred Nim, dokole On ne rešit dela moego i ne soveršit suda nado mnoû; togda On vyvedet menâ na svet, i â uvižu pravdu Ego."],[7,10,"И увидит это неприятельница моя, и стыд покроет ее, говорившую мне: «где Господь Бог твой?» Насмотрятся на нее глаза мои, как она будет попираема подобно грязи на улицах.","I uvidit éto nepriâtelʹnica moâ, i styd pokroet ee, govorivšuû mne: «gde Gospodʹ Bog tvoj?» Nasmotrâtsâ na nee glaza moi, kak ona budet popiraema podobno grâzi na ulicah."],[7,11,"В день сооружения стен твоих, в этот день отдалится определение.","V denʹ sooruženiâ sten tvoih, v étot denʹ otdalitsâ opredelenie."],[7,12,"В тот день придут к тебе из Ассирии и городов Египетских, и от Египта до реки Евфрата, и от моря до моря, и от горы до горы.","V tot denʹ pridut k tebe iz Assirii i gorodov Egipetskih, i ot Egipta do reki Evfrata, i ot morâ do morâ, i ot gory do gory."],[7,13,"А земля та будет пустынею за вину жителей ее, за плоды деяний их.","A zemlâ ta budet pustyneû za vinu žitelej ee, za plody deânij ih."],[7,14,"Паси народ Твой жезлом Твоим, овец наследия Твоего, обитающих уединенно в лесу среди Кармила; да пасутся они на Васане и Галааде, как во дни древние!","Pasi narod Tvoj žezlom Tvoim, ovec naslediâ Tvoego, obitaûŝih uedinenno v lesu sredi Karmila; da pasutsâ oni na Vasane i Galaade, kak vo dni drevnie!"],[7,15,"Как во дни исхода твоего из земли Египетской, явлю ему дивные дела.","Kak vo dni ishoda tvoego iz zemli Egipetskoj, âvlû emu divnye dela."],[7,16,"Увидят это народы и устыдятся при всем могуществе своем; положат руку на уста, уши их сделаются глухими;","Uvidât éto narody i ustydâtsâ pri vsem moguŝestve svoem; položat ruku na usta, uši ih sdelaûtsâ gluhimi;"],[7,17,"будут лизать прах как змея, как черви земные выползут они из укреплений своих; устрашатся Господа Бога нашего и убоятся Тебя.","budut lizatʹ prah kak zmeâ, kak červi zemnye vypolzut oni iz ukreplenij svoih; ustrašatsâ Gospoda Boga našego i uboâtsâ Tebâ."],[7,18,"Кто Бог, как Ты, прощающий беззаконие и не вменяющий преступления остатку наследия Твоего? не вечно гневается Он, потому что любит миловать.","Kto Bog, kak Ty, proŝaûŝij bezzakonie i ne vmenâûŝij prestupleniâ ostatku naslediâ Tvoego? ne večno gnevaetsâ On, potomu čto lûbit milovatʹ."],[7,19,"Он опять умилосердится над нами, изгладит беззакония наши. Ты ввергнешь в пучину морскую все грехи наши.","On opâtʹ umiloserditsâ nad nami, izgladit bezzakoniâ naši. Ty vvergnešʹ v pučinu morskuû vse grehi naši."],[7,20,"Ты явишь верность Иакову, милость Аврааму, которую с клятвою обещал отцам нашим от дней первых.","Ty âvišʹ vernostʹ Iakovu, milostʹ Avraamu, kotoruû s klâtvoû obeŝal otcam našim ot dnej pervyh."]],"cmn-cuv-hant":[[1,1,"當 猶大王 約坦、 亞哈斯、 希西家在位的時候， 摩利沙人 彌迦得耶和華的默示，論 撒馬利亞和 耶路撒冷。","dāng yóu dà wáng yuē tǎn, yà hā sī, xī xī jiā zài wèi de shí hòu， mó lì shā rén mí jiā dé yé hé huá de mò shì， lùn sā mǎ lì yà hé yé lù sā lěng."],[1,2,"萬民哪，你們都要聽！ 地和其上所有的，也都要側耳而聽！ 主耶和華從他的聖殿 要見證你們的不是。","wàn mín nǎ， nǐ men dōu yào tīng！ de hé qí shàng suǒ yǒu de， yě dōu yào cè ěr ér tīng！ zhǔ yé hé huá cóng tā de shèng diàn yào jiàn zhèng nǐ men de bù shì."],[1,3,"看哪，耶和華出了他的居所， 降臨步行地的高處。","kàn nǎ， yé hé huá chū le tā de jū suǒ， jiàng lín bù xíng de de gāo chù."],[1,4,"眾山在他以下必消化， 諸谷必崩裂， 如蠟化在火中， 如水沖下山坡。","zhòng shān zài tā yǐ xià bì xiāo huà， zhū gǔ bì bēng liè， rú là huà zài huǒ zhōng， rú shuǐ chōng xià shān pō."],[1,5,"這都因 雅各的罪過， 以色列家的罪惡。 雅各的罪過在哪裏呢？ 豈不是在 撒馬利亞嗎？ 猶大的邱壇在哪裏呢？ 豈不是在 耶路撒冷嗎？","zhè dōu yīn yǎ gè de zuì guò， yǐ sè liè jiā de zuì è. yǎ gè de zuì guò zài nǎ lǐ ne？ qǐ bù shì zài sā mǎ lì yà ma？ yóu dà de qiū tán zài nǎ lǐ ne？ qǐ bù shì zài yé lù sā lěng ma？"],[1,6,"所以我必使 撒馬利亞變為田野的亂堆， 又作為種葡萄之處； 也必將她的石頭倒在谷中， 露出根基來。","suǒ yǐ wǒ bì shǐ sā mǎ lì yà biàn wèi tián yě de luàn duī， yòu zuò wèi zhǒng pú táo zhī chù； yě bì jiāng tā de shí tóu dào zài gǔ zhōng， lù chū gēn jī lái."],[1,7,"她一切雕刻的偶像必被打碎； 她所得的財物必被火燒； 所有的偶像我必毀滅； 因為是從妓女雇價所聚來的， 後必歸為妓女的雇價。","tā yī qiè diāo kè de ǒu xiàng bì bèi dǎ suì； tā suǒ dé de cái wù bì bèi huǒ shāo； suǒ yǒu de ǒu xiàng wǒ bì huǐ miè； yīn wèi shì cóng jì nǚ gù jià suǒ jù lái de， hòu bì guī wèi jì nǚ de gù jià."],[1,8,"先知說：因此我必大聲哀號， 赤腳露體而行； 又要呼號如野狗， 哀鳴如鴕鳥。","xiān zhī shuō： yīn cǐ wǒ bì dà shēng āi hào， chì jiǎo lù tǐ ér xíng； yòu yào hū hào rú yě gǒu， āi míng rú tuó niǎo."],[1,9,"因為 撒馬利亞的傷痕無法醫治， 延及 猶大和 耶路撒冷我民的城門。","yīn wèi sā mǎ lì yà de shāng hén wú fǎ yī zhì， yán jí yóu dà hé yé lù sā lěng wǒ mín de chéng mén."],[1,10,"不要在 迦特報告這事， 總不要哭泣； 我在 伯‧亞弗拉滾於灰塵之中。","bù yào zài jiā tè bào gào zhè shì， zǒng bù yào kū qì； wǒ zài bó‧yà fú lā gǔn yú huī chén zhī zhōng."],[1,11,"沙斐的居民哪，你們要赤身蒙羞過去。 撒南的居民不敢出來。 伯‧以薛人的哀哭使你們無處可站。","shā fěi de jū mín nǎ， nǐ men yào chì shēn méng xiū guò qù. sā nán de jū mín bù gǎn chū lái. bó‧yǐ xuē rén de āi kū shǐ nǐ men wú chù kě zhàn."],[1,12,"瑪律的居民心甚憂急，切望得好處， 因為災禍從耶和華那裏臨到 耶路撒冷的城門。","mǎ lǜ de jū mín xīn shèn yōu jí， qiè wàng dé hǎo chù， yīn wèi zāi huò cóng yé hé huá nà lǐ lín dào yé lù sā lěng de chéng mén."],[1,13,"拉吉的居民哪，要用快馬套車； 錫安民的罪由你而起； 以色列人的罪過在你那裏顯出。","lā jí de jū mín nǎ， yào yòng kuài mǎ tào chē； xī ān mín de zuì yóu nǐ ér qǐ； yǐ sè liè rén de zuì guò zài nǐ nà lǐ xiǎn chū."],[1,14,"猶大啊，你要將禮物送給 摩利設‧迦特。 亞革悉的眾族必用詭詐待 以色列諸王。","yóu dà a， nǐ yào jiāng lǐ wù sòng gěi mó lì shè‧jiā tè. yà gé xī de zhòng zú bì yòng guǐ zhà dài yǐ sè liè zhū wáng."],[1,15,"瑪利沙的居民哪， 我必使那奪取你的來到你這裏； 以色列的尊貴人必到 亞杜蘭。","mǎ lì shā de jū mín nǎ， wǒ bì shǐ nà duó qǔ nǐ de lái dào nǐ zhè lǐ； yǐ sè liè de zūn guì rén bì dào yà dù lán."],[1,16,"猶大啊，要為你所喜愛的兒女剪除你的頭髮， 使頭光禿，要大大地光禿，如同禿鷹， 因為他們都被擄去離開你。","yóu dà a， yào wèi nǐ suǒ xǐ ài de ér nǚ jiǎn chú nǐ de tóu fà， shǐ tóu guāng tū， yào dà dà de guāng tū， rú tóng tū yīng， yīn wèi tā men dōu bèi lǔ qù lí kāi nǐ."],[2,1,"禍哉，那些在床上圖謀罪孽、造作奸惡的！ 天一發亮，因手有能力就行出來了。","huò zāi， nà xiē zài chuáng shàng tú móu zuì niè, zào zuò jiān è de！ tiān yī fā liàng， yīn shǒu yǒu néng lì jiù xíng chū lái le."],[2,2,"他們貪圖田地就佔據， 貪圖房屋便奪取； 他們欺壓人，霸佔房屋和產業。","tā men tān tú tián de jiù zhàn jù， tān tú fáng wū biàn duó qǔ； tā men qī yā rén， bà zhàn fáng wū hé chǎn yè."],[2,3,"所以耶和華如此說： 我籌劃災禍降與這族； 這禍在你們的頸項上不能解脫； 你們也不能昂首而行， 因為這時勢是惡的。","suǒ yǐ yé hé huá rú cǐ shuō： wǒ chóu huà zāi huò jiàng yǔ zhè zú； zhè huò zài nǐ men de jǐng xiàng shàng bù néng jiě tuō； nǐ men yě bù néng áng shǒu ér xíng， yīn wèi zhè shí shì shì è de."],[2,4,"到那日，必有人向你們提起悲慘的哀歌， 譏刺說：我們全然敗落了！ 耶和華將我們的分轉歸別人， 何竟使這分離開我們？ 他將我們的田地分給悖逆的人。","dào nà rì， bì yǒu rén xiàng nǐ men tí qǐ bēi cǎn de āi gē， jī cì shuō： wǒ men quán rán bài luò le！ yé hé huá jiāng wǒ men de fēn zhuǎn guī bié rén， hé jìng shǐ zhè fēn lí kāi wǒ men？ tā jiāng wǒ men de tián de fēn gěi bèi nì de rén."],[2,5,"所以在耶和華的會中， 你必沒有人拈鬮拉準繩。","suǒ yǐ zài yé hé huá de huì zhōng， nǐ bì méi yǒu rén niān jiū lā zhǔn shéng."],[2,6,"他們說：你們不可說預言； 不可向這些人說預言， 不住地羞辱 我們。","tā men shuō： nǐ men bù kě shuō yù yán； bù kě xiàng zhè xiē rén shuō yù yán， bù zhù de xiū rǔ wǒ men."],[2,7,"雅各家啊，豈可說耶和華的心不忍耐嗎？ 這些事是他所行的嗎？ 我－ 耶和華的言語豈不是與行動正直的人有益嗎？","yǎ gè jiā a， qǐ kě shuō yé hé huá de xīn bù rěn nài ma？ zhè xiē shì shì tā suǒ xíng de ma？ wǒ－ yé hé huá de yán yǔ qǐ bù shì yǔ xíng dòng zhèng zhí de rén yǒu yì ma？"],[2,8,"然而，近來我的民興起如仇敵， 從那些安然經過不願打仗之人身上剝去外衣。","rán ér， jìn lái wǒ de mín xìng qǐ rú chóu dí， cóng nà xiē ān rán jīng guò bù yuàn dǎ zhàng zhī rén shēn shàng bō qù wài yī."],[2,9,"你們將我民中的婦人從安樂家中趕出， 又將我的榮耀從她們的小孩子盡行奪去。","nǐ men jiāng wǒ mín zhōng de fù rén cóng ān lè jiā zhōng gǎn chū， yòu jiāng wǒ de róng yào cóng tā men de xiǎo hái zǐ jǐn xíng duó qù."],[2,10,"你們起來去吧！ 這不是你們安息之所； 因為污穢使人毀滅， 而且大大毀滅。","nǐ men qǐ lái qù ba！ zhè bù shì nǐ men ān xī zhī suǒ； yīn wèi wū huì shǐ rén huǐ miè， ér qiě dà dà huǐ miè."],[2,11,"若有人心存虛假，用謊言 說： 我要向你們預言得清酒和濃酒。 那人就必作這民的先知。","ruò yǒu rén xīn cún xū jiǎ， yòng huǎng yán shuō： wǒ yào xiàng nǐ men yù yán dé qīng jiǔ hé nóng jiǔ. nà rén jiù bì zuò zhè mín de xiān zhī."],[2,12,"雅各家啊，我必要聚集你們， 必要招聚 以色列剩下的人， 安置在一處，如 波斯拉的羊， 又如草場上的羊群； 因為人數 眾多就必大大喧嘩。","yǎ gè jiā a， wǒ bì yào jù jí nǐ men， bì yào zhāo jù yǐ sè liè shèng xià de rén， ān zhì zài yī chù， rú bō sī lā de yáng， yòu rú cǎo chǎng shàng de yáng qún； yīn wèi rén shù zhòng duō jiù bì dà dà xuān huā."],[2,13,"開路的在他們前面上去； 他們直闖過城門，從城門出去。 他們的王在前面行； 耶和華引導他們。","kāi lù de zài tā men qián miàn shàng qù； tā men zhí chuǎng guò chéng mén， cóng chéng mén chū qù. tā men de wáng zài qián miàn xíng； yé hé huá yǐn dǎo tā men."],[3,1,"我說： 雅各的首領， 以色列家的官長啊，你們要聽！ 你們不當知道公平嗎？","wǒ shuō： yǎ gè de shǒu lǐng， yǐ sè liè jiā de guān zhǎng a， nǐ men yào tīng！ nǐ men bù dāng zhī dào gōng píng ma？"],[3,2,"你們惡善好惡， 從人身上剝皮， 從人骨頭上剔肉，","nǐ men è shàn hǎo è， cóng rén shēn shàng bō pí， cóng rén gǔ tóu shàng tī ròu，"],[3,3,"吃我民的肉， 剝他們的皮， 打折他們的骨頭， 分成塊子像要下鍋， 又像釜中的肉。","chī wǒ mín de ròu， bō tā men de pí， dǎ zhé tā men de gǔ tóu， fēn chéng kuài zǐ xiàng yào xià guō， yòu xiàng fǔ zhōng de ròu."],[3,4,"到了 遭災的時候， 這些人必哀求耶和華， 他卻不應允他們。 那時他必照他們所行的惡事向他們掩面。","dào le zāo zāi de shí hòu， zhè xiē rén bì āi qiú yé hé huá， tā què bù yīng yǔn tā men. nà shí tā bì zhào tā men suǒ xíng de è shì xiàng tā men yǎn miàn."],[3,5,"論到使我民走差路的先知－ 他們牙齒有所嚼的， 他們就呼喊說：平安了！ 凡不供給他們吃的， 他們就預備攻擊他－ 耶和華如此說：","lùn dào shǐ wǒ mín zǒu chà lù de xiān zhī－ tā men yá chǐ yǒu suǒ jué de， tā men jiù hū hǎn shuō： píng ān le！ fán bù gōng gěi tā men chī de， tā men jiù yù bèi gōng jī tā－ yé hé huá rú cǐ shuō："],[3,6,"你們必遭遇黑夜，以致不見異象； 又必遭遇幽暗，以致不能占卜。 日頭必向你們沉落， 白晝變為黑暗。","nǐ men bì zāo yù hēi yè， yǐ zhì bù jiàn yì xiàng； yòu bì zāo yù yōu àn， yǐ zhì bù néng zhàn bo. rì tóu bì xiàng nǐ men chén luò， bái zhòu biàn wèi hēi àn."],[3,7,"先見必抱愧， 占卜的必蒙羞， 都必摀着嘴唇， 因為神不應允他們。","xiān jiàn bì bào kuì， zhàn bo de bì méng xiū， dōu bì wǔ zhe zuǐ chún， yīn wèi shén bù yīng yǔn tā men."],[3,8,"至於我，我藉耶和華的靈， 滿有力量、公平、才能， 可以向 雅各說明他的過犯， 向 以色列指出他的罪惡。","zhì yú wǒ， wǒ jí yé hé huá de líng， mǎn yǒu lì liàng, gōng píng, cái néng， kě yǐ xiàng yǎ gè shuō míng tā de guò fàn， xiàng yǐ sè liè zhǐ chū tā de zuì è."],[3,9,"雅各家的首領、 以色列家的官長啊， 當聽我的話！ 你們厭惡公平， 在一切事上屈枉正直；","yǎ gè jiā de shǒu lǐng, yǐ sè liè jiā de guān zhǎng a， dāng tīng wǒ de huà！ nǐ men yàn è gōng píng， zài yī qiè shì shàng qū wǎng zhèng zhí；"],[3,10,"以人血建立 錫安， 以罪孽建造 耶路撒冷。","yǐ rén xuè jiàn lì xī ān， yǐ zuì niè jiàn zào yé lù sā lěng."],[3,11,"首領為賄賂行審判； 祭司為雇價施訓誨； 先知為銀錢行占卜。 他們卻倚賴耶和華，說： 耶和華不是在我們中間嗎？ 災禍必不臨到我們。","shǒu lǐng wèi huì lù xíng shěn pàn； jì sī wèi gù jià shī xùn huì； xiān zhī wèi yín qián xíng zhàn bo. tā men què yǐ lài yé hé huá， shuō： yé hé huá bù shì zài wǒ men zhōng jiān ma？ zāi huò bì bù lín dào wǒ men."],[3,12,"所以因你們的緣故， 錫安必被耕種像一塊田， 耶路撒冷必變為亂堆； 這殿的山必像叢林的高處。","suǒ yǐ yīn nǐ men de yuán gù， xī ān bì bèi gēng zhǒng xiàng yī kuài tián， yé lù sā lěng bì biàn wèi luàn duī； zhè diàn de shān bì xiàng cóng lín de gāo chù."],[4,1,"末後的日子， 耶和華殿的山必堅立， 超乎諸山，高舉過於萬嶺； 萬民都要流歸這山。","mò hòu de rì zǐ， yé hé huá diàn de shān bì jiān lì， chāo hū zhū shān， gāo jǔ guò yú wàn lǐng； wàn mín dōu yào liú guī zhè shān."],[4,2,"必有許多國的民前往，說： 來吧，我們登耶和華的山， 奔 雅各神的殿。 主必將他的道教訓我們； 我們也要行他的路。 因為訓誨必出於 錫安； 耶和華的言語必出於 耶路撒冷。","bì yǒu xǔ duō guó de mín qián wǎng， shuō： lái ba， wǒ men dēng yé hé huá de shān， bēn yǎ gè shén de diàn. zhǔ bì jiāng tā de dào jiào xùn wǒ men； wǒ men yě yào xíng tā de lù. yīn wèi xùn huì bì chū yú xī ān； yé hé huá de yán yǔ bì chū yú yé lù sā lěng."],[4,3,"他必在多國的民中施行審判， 為遠方強盛的國斷定是非。 他們要將刀打成誆頭， 把槍打成鐮刀。 這國不舉刀攻擊那國； 他們也不再學習戰事。","tā bì zài duō guó de mín zhōng shī xíng shěn pàn， wèi yuǎn fāng qiáng shèng de guó duàn dìng shì fēi. tā men yào jiāng dāo dǎ chéng kuāng tóu， bǎ qiāng dǎ chéng lián dāo. zhè guó bù jǔ dāo gōng jī nà guó； tā men yě bù zài xué xí zhàn shì."],[4,4,"人人都要坐在自己葡萄樹下 和無花果樹下，無人驚嚇。 這是萬軍之耶和華親口說的。","rén rén dōu yào zuò zài zì jǐ pú táo shù xià hé wú huā guǒ shù xià， wú rén jīng xià. zhè shì wàn jūn zhī yé hé huá qīn kǒu shuō de."],[4,5,"萬民各奉己神的名而行； 我們卻永永遠遠奉耶和華－我們神的名而行。","wàn mín gè fèng jǐ shén de míng ér xíng； wǒ men què yǒng yǒng yuǎn yuǎn fèng yé hé huá－wǒ men shén de míng ér xíng."],[4,6,"耶和華說：到那日， 我必聚集瘸腿的， 招聚被趕出的和我所懲治的。","yé hé huá shuō： dào nà rì， wǒ bì jù jí qué tuǐ de， zhāo jù bèi gǎn chū de hé wǒ suǒ chéng zhì de."],[4,7,"我必使瘸腿的為餘剩之民， 使趕到遠方的為強盛之民。 耶和華要在 錫安山作王治理他們， 從今直到永遠。","wǒ bì shǐ qué tuǐ de wèi yú shèng zhī mín， shǐ gǎn dào yuǎn fāng de wèi qiáng shèng zhī mín. yé hé huá yào zài xī ān shān zuò wáng zhì lǐ tā men， cóng jīn zhí dào yǒng yuǎn."],[4,8,"你這羊群的高臺、 錫安城的山哪， 從前的權柄－ 就是 耶路撒冷民的國權－ 必歸與你。","nǐ zhè yáng qún de gāo tái, xī ān chéng de shān nǎ， cóng qián de quán bǐng－ jiù shì yé lù sā lěng mín de guó quán－ bì guī yǔ nǐ."],[4,9,"現在你為何大聲哭號呢？ 疼痛抓住你彷彿產難的婦人， 是因你中間沒有君王嗎？ 你的謀士滅亡了嗎？","xiàn zài nǐ wèi hé dà shēng kū hào ne？ téng tòng zhuā zhù nǐ páng fú chǎn nán de fù rén， shì yīn nǐ zhōng jiān méi yǒu jūn wáng ma？ nǐ de móu shì miè wáng le ma？"],[4,10,"錫安的民哪， 你要疼痛劬勞，彷彿產難的婦人； 因為你必從城裏出來， 住在田野，到 巴比倫去。 在那裏要蒙解救； 在那裏耶和華必救贖你脫離仇敵的手。","xī ān de mín nǎ， nǐ yào téng tòng qú láo， páng fú chǎn nán de fù rén； yīn wèi nǐ bì cóng chéng lǐ chū lái， zhù zài tián yě， dào bā bǐ lún qù. zài nà lǐ yào méng jiě jiù； zài nà lǐ yé hé huá bì jiù shú nǐ tuō lí chóu dí de shǒu."],[4,11,"現在有許多國的民聚集攻擊你，說： 願 錫安被玷污！ 願我們親眼見她 遭報！","xiàn zài yǒu xǔ duō guó de mín jù jí gōng jī nǐ， shuō： yuàn xī ān bèi diàn wū！ yuàn wǒ men qīn yǎn jiàn tā zāo bào！"],[4,12,"他們卻不知道耶和華的意念， 也不明白他的籌劃。 他聚集他們，好像把禾捆聚到禾場一樣。","tā men què bù zhī dào yé hé huá de yì niàn， yě bù míng bái tā de chóu huà. tā jù jí tā men， hǎo xiàng bǎ hé kǔn jù dào hé chǎng yī yàng."],[4,13,"錫安的民哪，起來踹穀吧！ 我必使你的角成為鐵， 使你的蹄成為銅。 你必打碎多國的民， 將他們的財獻與耶和華， 將他們的貨獻與普天下的主。","xī ān de mín nǎ， qǐ lái chuài gǔ ba！ wǒ bì shǐ nǐ de jiǎo chéng wèi tiě， shǐ nǐ de tí chéng wèi tóng. nǐ bì dǎ suì duō guó de mín， jiāng tā men de cái xiàn yǔ yé hé huá， jiāng tā men de huò xiàn yǔ pǔ tiān xià de zhǔ."],[5,1,"成群的民哪，現在你要聚集成隊； 因為仇敵圍攻我們， 要用杖擊打 以色列審判者的臉。","chéng qún de mín nǎ， xiàn zài nǐ yào jù jí chéng duì； yīn wèi chóu dí wéi gōng wǒ men， yào yòng zhàng jī dǎ yǐ sè liè shěn pàn zhě de liǎn."],[5,2,"伯利恆的 以法他啊， 你在 猶大諸城中為小， 將來必有一位從你那裏出來， 在 以色列中為我作掌權的； 他的根源從亙古，從太初就有。","bó lì héng de yǐ fǎ tā a， nǐ zài yóu dà zhū chéng zhōng wèi xiǎo， jiāng lái bì yǒu yī wèi cóng nǐ nà lǐ chū lái， zài yǐ sè liè zhōng wèi wǒ zuò zhǎng quán de； tā de gēn yuán cóng gèn gǔ， cóng tài chū jiù yǒu."],[5,3,"耶和華必將 以色列人交付 敵人， 直等那生產的婦人生下子來。 那時掌權者其餘的弟兄 必歸到 以色列人那裏。","yé hé huá bì jiāng yǐ sè liè rén jiāo fù dí rén， zhí děng nà shēng chǎn de fù rén shēng xià zǐ lái. nà shí zhǎng quán zhě qí yú de dì xiōng bì guī dào yǐ sè liè rén nà lǐ."],[5,4,"他必起來，倚靠耶和華的大能， 並耶和華－他神之名的威嚴， 牧養 他的羊群。 他們要 安然居住； 因為他必日見尊大，直到地極。","tā bì qǐ lái， yǐ kào yé hé huá de dà néng， bìng yé hé huá－tā shén zhī míng de wēi yán， mù yǎng tā de yáng qún. tā men yào ān rán jū zhù； yīn wèi tā bì rì jiàn zūn dà， zhí dào de jí."],[5,5,"這位必作 我們的平安。 當 亞述人進入我們的地境， 踐踏宮殿的時候， 我們就立起七個牧者， 八個首領攻擊他。","zhè wèi bì zuò wǒ men de píng ān. dāng yà shù rén jìn rù wǒ men de de jìng， jiàn tà gōng diàn de shí hòu， wǒ men jiù lì qǐ qī gè mù zhě， bā gè shǒu lǐng gōng jī tā."],[5,6,"他們必用刀劍毀壞 亞述地 和 寧錄地的關口。 亞述人進入我們的地境踐踏的時候， 他必拯救我們。","tā men bì yòng dāo jiàn huǐ huài yà shù de hé níng lù de de guān kǒu. yà shù rén jìn rù wǒ men de de jìng jiàn tà de shí hòu， tā bì zhěng jiù wǒ men."],[5,7,"雅各餘剩的人必在多國的民中， 如從耶和華那裏降下的露水， 又如甘霖降在草上； 不仗賴人 力，也不等候世人 之功。","yǎ gè yú shèng de rén bì zài duō guó de mín zhōng， rú cóng yé hé huá nà lǐ jiàng xià de lù shuǐ， yòu rú gān lín jiàng zài cǎo shàng； bù zhàng lài rén lì， yě bù děng hòu shì rén zhī gōng."],[5,8,"雅各餘剩的人必在多國多民中， 如林間百獸中的獅子， 又如少壯獅子在羊群中。 他若經過就必踐踏撕裂， 無人搭救。","yǎ gè yú shèng de rén bì zài duō guó duō mín zhōng， rú lín jiān bǎi shòu zhōng de shī zǐ， yòu rú shǎo zhuàng shī zǐ zài yáng qún zhōng. tā ruò jīng guò jiù bì jiàn tà sī liè， wú rén dā jiù."],[5,9,"願你的手舉起，高過敵人！ 願你的仇敵都被剪除！","yuàn nǐ de shǒu jǔ qǐ， gāo guò dí rén！ yuàn nǐ de chóu dí dōu bèi jiǎn chú！"],[5,10,"耶和華說：到那日， 我必從你中間剪除馬匹， 毀壞車輛，","yé hé huá shuō： dào nà rì， wǒ bì cóng nǐ zhōng jiān jiǎn chú mǎ pǐ， huǐ huài chē liàng，"],[5,11,"也必從你國中除滅城邑， 拆毀一切的保障，","yě bì cóng nǐ guó zhōng chú miè chéng yì， chāi huǐ yī qiè de bǎo zhàng，"],[5,12,"又必除掉你手中的邪術； 你那裏也不再有占卜的。","yòu bì chú diào nǐ shǒu zhōng de xié shù； nǐ nà lǐ yě bù zài yǒu zhàn bo de."],[5,13,"我必從你中間除滅雕刻的偶像和柱像， 你就不再跪拜自己手所造的。","wǒ bì cóng nǐ zhōng jiān chú miè diāo kè de ǒu xiàng hé zhù xiàng， nǐ jiù bù zài guì bài zì jǐ shǒu suǒ zào de."],[5,14,"我必從你中間拔出木偶， 又毀滅你的城邑。","wǒ bì cóng nǐ zhōng jiān bá chū mù ǒu， yòu huǐ miè nǐ de chéng yì."],[5,15,"我也必在怒氣和忿怒中向那不聽從的列國施報。","wǒ yě bì zài nù qì hé fèn nù zhōng xiàng nà bù tīng cóng de liè guó shī bào."],[6,1,"以色列人哪，當聽耶和華的話！ 要起來向山嶺爭辯， 使岡陵聽你的話。","yǐ sè liè rén nǎ， dāng tīng yé hé huá de huà！ yào qǐ lái xiàng shān lǐng zhēng biàn， shǐ gāng líng tīng nǐ de huà."],[6,2,"山嶺和地永久的根基啊， 要聽耶和華爭辯的話！ 因為耶和華要與他的百姓爭辯， 與 以色列爭論。","shān lǐng hé de yǒng jiǔ de gēn jī a， yào tīng yé hé huá zhēng biàn de huà！ yīn wèi yé hé huá yào yǔ tā de bǎi xìng zhēng biàn， yǔ yǐ sè liè zhēng lùn."],[6,3,"我的百姓啊，我向你做了甚麼呢？ 我在甚麼事上使你厭煩？ 你可以對我證明。","wǒ de bǎi xìng a， wǒ xiàng nǐ zuò le shèn me ne？ wǒ zài shèn me shì shàng shǐ nǐ yàn fán？ nǐ kě yǐ duì wǒ zhèng míng."],[6,4,"我曾將你從 埃及地領出來， 從作奴僕之家救贖你； 我也差遣 摩西、 亞倫，和 米利暗在你前面行。","wǒ céng jiāng nǐ cóng āi jí de lǐng chū lái， cóng zuò nú pú zhī jiā jiù shú nǐ； wǒ yě chà qiǎn mó xī, yà lún， hé mǐ lì àn zài nǐ qián miàn xíng."],[6,5,"我的百姓啊，你們當追念 摩押王 巴勒所設的謀 和 比珥的兒子 巴蘭回答他的話， 並你們從 什亭到 吉甲 所遇見的事， 好使你們知道耶和華公義的作為。","wǒ de bǎi xìng a， nǐ men dāng zhuī niàn mó yā wáng bā lēi suǒ shè de móu hé bǐ ěr de ér zǐ bā lán huí dá tā de huà， bìng nǐ men cóng shén tíng dào jí jiǎ suǒ yù jiàn de shì， hǎo shǐ nǐ men zhī dào yé hé huá gōng yì de zuò wèi."],[6,6,"我朝見耶和華， 在至高神面前跪拜，當獻上甚麼呢？ 豈可獻一歲的牛犢為燔祭嗎？","wǒ cháo jiàn yé hé huá， zài zhì gāo shén miàn qián guì bài， dāng xiàn shàng shèn me ne？ qǐ kě xiàn yī suì de niú dú wèi fán jì ma？"],[6,7,"耶和華豈喜悅千千的公羊， 或是萬萬的油河嗎？ 我豈可為自己的罪過獻我的長子嗎？ 為心中的罪惡獻我身所生的嗎？","yé hé huá qǐ xǐ yuè qiān qiān de gōng yáng， huò shì wàn wàn de yóu hé ma？ wǒ qǐ kě wèi zì jǐ de zuì guò xiàn wǒ de zhǎng zǐ ma？ wèi xīn zhōng de zuì è xiàn wǒ shēn suǒ shēng de ma？"],[6,8,"世人哪，耶和華已指示你何為善。 他向你所要的是甚麼呢？ 只要你行公義，好憐憫， 存謙卑的心，與你的神同行。","shì rén nǎ， yé hé huá yǐ zhǐ shì nǐ hé wèi shàn. tā xiàng nǐ suǒ yào de shì shèn me ne？ zhǐ yào nǐ xíng gōng yì， hǎo lián mǐn， cún qiān bēi de xīn， yǔ nǐ de shén tóng xíng."],[6,9,"耶和華向這城呼叫， 智慧人必敬畏他的名。 你們當聽是誰派定刑杖的懲罰。","yé hé huá xiàng zhè chéng hū jiào， zhì huì rén bì jìng wèi tā de míng. nǐ men dāng tīng shì shuí pài dìng xíng zhàng de chéng fá."],[6,10,"惡人家中不仍有非義之財 和可惡的小升斗嗎？","è rén jiā zhōng bù réng yǒu fēi yì zhī cái hé kě è de xiǎo shēng dòu ma？"],[6,11,"我若用不公道的天平和囊中詭詐的法碼， 豈可算為清潔呢？","wǒ ruò yòng bù gōng dào de tiān píng hé náng zhōng guǐ zhà de fǎ mǎ， qǐ kě suàn wèi qīng jié ne？"],[6,12,"城裏的富戶滿行強暴； 其中的居民也說謊言， 口中的舌頭是詭詐的。","chéng lǐ de fù hù mǎn xíng qiáng bào； qí zhōng de jū mín yě shuō huǎng yán， kǒu zhōng de shé tóu shì guǐ zhà de."],[6,13,"因此，我擊打你， 使你的傷痕甚重， 使你因你的罪惡荒涼。","yīn cǐ， wǒ jī dǎ nǐ， shǐ nǐ de shāng hén shèn zhòng， shǐ nǐ yīn nǐ de zuì è huāng liáng."],[6,14,"你要吃，卻吃不飽； 你的虛弱必顯在你中間。 你必挪去，卻不得救護； 所救護的，我必交給刀劍。","nǐ yào chī， què chī bù bǎo； nǐ de xū ruò bì xiǎn zài nǐ zhōng jiān. nǐ bì nuó qù， què bù dé jiù hù； suǒ jiù hù de， wǒ bì jiāo gěi dāo jiàn."],[6,15,"你必撒種，卻不得收割； 踹橄欖，卻不得油抹身； 踹葡萄，卻不得酒喝。","nǐ bì sā zhǒng， què bù dé shōu gē； chuài gǎn lǎn， què bù dé yóu mǒ shēn； chuài pú táo， què bù dé jiǔ hē."],[6,16,"因為你守 暗利的惡規， 行 亞哈家一切所行的， 順從他們的計謀； 因此，我必使你荒涼， 使你的居民令人嗤笑， 你們也必擔當我民的羞辱。","yīn wèi nǐ shǒu àn lì de è guī， xíng yà hā jiā yī qiè suǒ xíng de， shùn cóng tā men de jì móu； yīn cǐ， wǒ bì shǐ nǐ huāng liáng， shǐ nǐ de jū mín lìng rén chī xiào， nǐ men yě bì dān dāng wǒ mín de xiū rǔ."],[7,1,"哀哉！我好像夏天的果子已被收盡， 又像摘了葡萄所剩下的， 沒有一掛可吃的； 我心羨慕初熟的無花果。","āi zāi！ wǒ hǎo xiàng xià tiān de guǒ zǐ yǐ bèi shōu jǐn， yòu xiàng zhāi le pú táo suǒ shèng xià de， méi yǒu yī guà kě chī de； wǒ xīn xiàn mù chū shú de wú huā guǒ."],[7,2,"地上虔誠人滅盡； 世間沒有正直人； 各人埋伏，要殺人流血， 都用網羅獵取弟兄。","de shàng qián chéng rén miè jǐn； shì jiān méi yǒu zhèng zhí rén； gè rén mái fú， yào shā rén liú xuè， dōu yòng wǎng luó liè qǔ dì xiōng."],[7,3,"他們雙手作惡； 君王徇情面，審判官要賄賂； 位分大的吐出惡意， 都彼此結聯行惡。","tā men shuāng shǒu zuò è； jūn wáng xùn qíng miàn， shěn pàn guān yào huì lù； wèi fēn dà de tǔ chū è yì， dōu bǐ cǐ jié lián xíng è."],[7,4,"他們最好的，不過是蒺藜； 最正直的，不過是荊棘籬笆。 你守望者 說，降罰的日子已經來到。 他們必擾亂不安。","tā men zuì hǎo de， bù guò shì jí lí； zuì zhèng zhí de， bù guò shì jīng jí lí bā. nǐ shǒu wàng zhě shuō， jiàng fá de rì zǐ yǐ jīng lái dào. tā men bì rǎo luàn bù ān."],[7,5,"不要倚賴鄰舍； 不要信靠密友。 要守住你的口； 不要向你懷中的妻提說。","bù yào yǐ lài lín shě； bù yào xìn kào mì yǒu. yào shǒu zhù nǐ de kǒu； bù yào xiàng nǐ huái zhōng de qī tí shuō."],[7,6,"因為，兒子藐視父親； 女兒抗拒母親； 媳婦抗拒婆婆； 人的仇敵就是自己家裏的人。","yīn wèi， ér zǐ miǎo shì fù qīn； nǚ ér kàng jù mǔ qīn； xí fù kàng jù pó pó； rén de chóu dí jiù shì zì jǐ jiā lǐ de rén."],[7,7,"至於我，我要仰望耶和華， 要等候那救我的神； 我的神必應允我。","zhì yú wǒ， wǒ yào yǎng wàng yé hé huá， yào děng hòu nà jiù wǒ de shén； wǒ de shén bì yīng yǔn wǒ."],[7,8,"我的仇敵啊，不要向我誇耀。 我雖跌倒，卻要起來； 我雖坐在黑暗裏， 耶和華卻作我的光。","wǒ de chóu dí a， bù yào xiàng wǒ kuā yào. wǒ suī diē dào， què yào qǐ lái； wǒ suī zuò zài hēi àn lǐ， yé hé huá què zuò wǒ de guāng."],[7,9,"我要忍受耶和華的惱怒； 因我得罪了他， 直等他為我辨屈，為我伸冤。 他必領我到光明中； 我必得見他的公義。","wǒ yào rěn shòu yé hé huá de nǎo nù； yīn wǒ dé zuì le tā， zhí děng tā wèi wǒ biàn qū， wèi wǒ shēn yuān. tā bì lǐng wǒ dào guāng míng zhōng； wǒ bì dé jiàn tā de gōng yì."],[7,10,"那時我的仇敵， 就是曾對我說「耶和華－你神在哪裏」的， 他一看見這事就被羞愧遮蓋。 我必親眼見他 遭報； 他必被踐踏，如同街上的泥土。","nà shí wǒ de chóu dí， jiù shì céng duì wǒ shuō‘yé hé huá－nǐ shén zài nǎ lǐ’ de， tā yī kàn jiàn zhè shì jiù bèi xiū kuì zhē gài. wǒ bì qīn yǎn jiàn tā zāo bào； tā bì bèi jiàn tà， rú tóng jiē shàng de ní tǔ."],[7,11,"以色列啊，日子必到， 你的牆垣必重修； 到那日，你的境界必開展。","yǐ sè liè a， rì zǐ bì dào， nǐ de qiáng yuán bì zhòng xiū； dào nà rì， nǐ de jìng jiè bì kāi zhǎn."],[7,12,"當那日，人必從 亞述， 從 埃及的城邑， 從 埃及到大河， 從這海到那海， 從這山到那山， 都歸到你這裏。","dāng nà rì， rén bì cóng yà shù， cóng āi jí de chéng yì， cóng āi jí dào dà hé， cóng zhè hǎi dào nà hǎi， cóng zhè shān dào nà shān， dōu guī dào nǐ zhè lǐ."],[7,13,"然而，這地因居民的緣故， 又因他們行事的結果，必然荒涼。","rán ér， zhè de yīn jū mín de yuán gù， yòu yīn tā men xíng shì de jié guǒ， bì rán huāng liáng."],[7,14,"求 耶和華在 迦密山的樹林中， 用你的杖牧放你獨居的民， 就是你產業的羊群。 求你容他們在 巴珊和 基列得食物，像古時一樣。","qiú yé hé huá zài jiā mì shān de shù lín zhōng， yòng nǐ de zhàng mù fàng nǐ dú jū de mín， jiù shì nǐ chǎn yè de yáng qún. qiú nǐ róng tā men zài bā shān hé jī liè dé shí wù， xiàng gǔ shí yī yàng."],[7,15,"耶和華說： 我要把奇事顯給他們看， 好像出 埃及地的時候一樣。","yé hé huá shuō： wǒ yào bǎ qí shì xiǎn gěi tā men kàn， hǎo xiàng chū āi jí de de shí hòu yī yàng."],[7,16,"列國看見這事就必為自己的勢力慚愧； 他們必用手摀口，掩耳不聽。","liè guó kàn jiàn zhè shì jiù bì wèi zì jǐ de shì lì cán kuì； tā men bì yòng shǒu wǔ kǒu， yǎn ěr bù tīng."],[7,17,"他們必舔土如蛇， 又如土中腹行的物， 戰戰兢兢地出他們的營寨。 他們必戰懼投降耶和華， 也必因我們的神而懼怕。","tā men bì tiǎn tǔ rú shé， yòu rú tǔ zhōng fù xíng de wù， zhàn zhàn jīng jīng de chū tā men de yíng zhài. tā men bì zhàn jù tóu jiàng yé hé huá， yě bì yīn wǒ men de shén ér jù pà."],[7,18,"神啊，有何神像你，赦免罪孽， 饒恕你產業之餘民的罪過， 不永遠懷怒，喜愛施恩？","shén a， yǒu hé shén xiàng nǐ， shè miǎn zuì niè， ráo shù nǐ chǎn yè zhī yú mín de zuì guò， bù yǒng yuǎn huái nù， xǐ ài shī ēn？"],[7,19,"必再憐憫我們， 將我們的罪孽踏在腳下， 又將我們的一切罪投於深海。","bì zài lián mǐn wǒ men， jiāng wǒ men de zuì niè tà zài jiǎo xià， yòu jiāng wǒ men de yī qiè zuì tóu yú shēn hǎi."],[7,20,"你必按古時起誓應許我們列祖的話， 向 雅各發誠實， 向 亞伯拉罕施慈愛。","nǐ bì àn gǔ shí qǐ shì yīng xǔ wǒ men liè zǔ de huà， xiàng yǎ gè fā chéng shí， xiàng yà bó lā hǎn shī cí ài."]],"arb-vandyck":[[1,1,"قَوْلُ ٱلرَّبِّ ٱلَّذِي صَارَ إِلَى مِيخَا ٱلْمُورَشْتِيِّ فِي أَيَّامِ يُوثَامَ وَآحَازَ وَحَزَقِيَّا مُلُوكِ يَهُوذَا، ٱلَّذِي رَآهُ عَلَى ٱلسَّامِرَةِ وَأُورُشَلِيمَ:","qaẘlu ٱlrãbĩ ٱlãdẖī ṣāra ại̹lay̱ mīkẖā ٱl̊mūrasẖ̊tīĩ fī ạảyãạmi yūtẖāma wā̂ḥāza waḥazaqīãạ mulūki yahūdẖā, ٱlãdẖī rā̂hu ʿalay̱ ٱlsãạmiraẗi wāủwrusẖalīma:"],[1,2,"اِسْمَعُوا أَيُّهَا ٱلشُّعُوبُ جَمِيعُكُمْ. أَصْغِي أَيَّتُهَا ٱلْأَرْضُ وَمِلْؤُهَا. وَلْيَكُنِ ٱلسَّيِّدُ ٱلرَّبُّ شَاهِدًا عَلَيْكُمُ، ٱلسَّيِّدُ مِنْ هَيْكَلِ قُدْسِهِ.","ạis̊maʿūạ ạảyũhā ٱlsẖũʿūbu jamīʿukum̊. ạảṣ̊gẖī ạảyãtuhā ٱl̊ạảr̊ḍu wamil̊wủhā. wal̊yakuni ٱlsãyĩdu ٱlrãbũ sẖāhidaⁿạ ʿalaẙkumu, ٱlsãyĩdu min̊ haẙkali qud̊sihi."],[1,3,"فَإِنَّهُ هُوَذَا ٱلرَّبُّ يَخْرُجُ مِنْ مَكَانِهِ وَيَنْزِلُ وَيَمْشِي عَلَى شَوَامِخِ ٱلْأَرْضِ،","fāi̹nãhu hūadẖā ٱlrãbũ yakẖ̊ruju min̊ makānihi wayan̊zilu wayam̊sẖī ʿalay̱ sẖawāmikẖi ٱl̊ạảr̊ḍi,"],[1,4,"فَتَذُوبُ ٱلْجِبَالُ تَحْتَهُ، وَتَنْشَقُّ ٱلْوِدْيَانُ كَٱلشَّمْعِ قُدَّامَ ٱلنَّارِ. كَٱلْمَاءِ ٱلْمُنْصَبِّ فِي مُنْحَدَرٍ.","fatadẖūbu ٱl̊jibālu taḥ̊tahu, watan̊sẖaqũ ٱl̊wid̊yānu kaٱlsẖãm̊ʿi qudãạma ٱlnãạri. kaٱl̊māʾi ٱl̊mun̊ṣabĩ fī mun̊ḥadariⁿ."],[1,5,"كُلُّ هَذَا مِنْ أَجْلِ إِثْمِ يَعْقُوبَ، وَمِنْ أَجْلِ خَطِيَّةِ بَيْتِ إِسْرَائِيلَ. مَا هُوَ ذَنْبُ يَعْقُوبَ؟ أَلَيْسَ هُوَ ٱلسَّامِرَةَ؟ وَمَا هِيَ مُرْتَفَعَاتُ يَهُوذَا؟ أَلَيْسَتْ هِيَ أُورُشَلِيمَ؟","kulũ hadẖā min̊ ạảj̊li ại̹tẖ̊mi yaʿ̊qūba, wamin̊ ạảj̊li kẖaṭīãẗi baẙti ại̹s̊rāyỉyla. mā hūa dẖan̊bu yaʿ̊qūba? ạảlaẙsa hūa ٱlsãạmiraẗa? wamā hīa mur̊tafaʿātu yahūdẖā? ạảlaẙsat̊ hīa ạủwrusẖalīma?"],[1,6,"«فَأَجْعَلُ ٱلسَّامِرَةَ خَرِبَةً فِي ٱلْبَرِّيَّةِ، مَغَارِسَ لِلْكُرُومِ، وَأُلْقِي حِجَارَتَهَا إِلَى ٱلْوَادِي، وَأَكْشِفُ أُسُسَهَا.","«fāảj̊ʿalu ٱlsãạmiraẗa kẖaribaẗaⁿ fī ٱl̊barĩyãẗi, magẖārisa lil̊kurūmi, wāủl̊qī ḥijāratahā ại̹lay̱ ٱl̊wādī, wāảk̊sẖifu ạủsusahā."],[1,7,"وَجَمِيعُ تَمَاثِيلِهَا ٱلْمَنْحُوتَةِ تُحَطَّمُ، وَكُلُّ أَعْقَارِهَا تُحْرَقُ بِٱلنَّارِ، وَجَمِيعُ أَصْنَامِهَا أَجْعَلُهَا خَرَابًا، لِأَنَّهَا مِنْ عُقْرِ ٱلزَّانِيَةِ جَمَعَتْهَا وَإِلَى عُقْرِ ٱلزَّانِيَةِ تَعُودُ».","wajamīʿu tamātẖīlihā ٱl̊man̊ḥūtaẗi tuḥaṭãmu, wakulũ ạảʿ̊qārihā tuḥ̊raqu biٱlnãạri, wajamīʿu ạảṣ̊nāmihā ạảj̊ʿaluhā kẖarābaⁿạ, liạảnãhā min̊ ʿuq̊ri ٱlzãạnīaẗi jamaʿat̊hā wāi̹lay̱ ʿuq̊ri ٱlzãạnīaẗi taʿūdu»."],[1,8,"مِنْ أَجْلِ ذَلِكَ أَنُوحُ وَأُوَلْوِلُ. أَمْشِي حَافِيًا وَعُرْيَانًا. أَصْنَعُ نَحِيبًا كَبَنَاتِ آوَى، وَنَوْحًا كَرِعَالِ ٱلنَّعَامِ.","min̊ ạảj̊li dẖalika ạảnūḥu wāủwal̊wilu. ạảm̊sẖī ḥāfīaⁿạ waʿur̊yānaⁿạ. ạảṣ̊naʿu naḥībaⁿạ kabanāti ậway̱, wanaẘḥaⁿạ kariʿāli ٱlnãʿāmi."],[1,9,"لِأَنَّ جِرَاحَاتِهَا عَدِيمَةُ ٱلشِّفَاءِ، لِأَنَّهَا قَدْ أَتَتْ إِلَى يَهُوذَا، وَصَلَتْ إِلَى بَابِ شَعْبِي إِلَى أُورُشَلِيمَ.","liạảnã jirāḥātihā ʿadīmaẗu ٱlsẖĩfāʾi, liạảnãhā qad̊ ạảtat̊ ại̹lay̱ yahūdẖā, waṣalat̊ ại̹lay̱ bābi sẖaʿ̊bī ại̹lay̱ ạủwrusẖalīma."],[1,10,"لَا تُخْبِرُوا فِي جَتَّ، لَا تَبْكُوا فِي عَكَّاءَ. تَمَرَّغِي فِي ٱلتُّرَابِ فِي بَيْتِ عَفْرَةَ.","lā tukẖ̊birūạ fī jatã, lā tab̊kūạ fī ʿakãạʾa. tamarãgẖī fī ٱltũrābi fī baẙti ʿaf̊raẗa."],[1,11,"اُعْبُرِي يَا سَاكِنَةَ شَافِيرَ عُرْيَانَةً وَخَجِلَةً. ٱلسَّاكِنَةُ فِي صَانَانَ لَا تَخْرُجُ. نَوْحُ بَيْتِ هَأَيْصِلَ يَأْخُذُ عِنْدَكُمْ مَقَامَهُ،","ạuʿ̊burī yā sākinaẗa sẖāfīra ʿur̊yānaẗaⁿ wakẖajilaẗaⁿ. ٱlsãạkinaẗu fī ṣānāna lā takẖ̊ruju. naẘḥu baẙti hāảẙṣila yā̊̉kẖudẖu ʿin̊dakum̊ maqāmahu,"],[1,12,"لِأَنَّ ٱلسَّاكِنَةَ فِي مَارُوثَ ٱغْتَمَّتْ لِأَجْلِ خَيْرَاتِهَا، لِأَنَّ شَرًّا قَدْ نَزَلَ مِنْ عِنْدِ ٱلرَّبِّ إِلَى بَابِ أُورُشَلِيمَ.","liạảnã ٱlsãạkinaẗa fī mārūtẖa ٱgẖ̊tamãt̊ liạảj̊li kẖaẙrātihā, liạảnã sẖaraⁿ̃ạ qad̊ nazala min̊ ʿin̊di ٱlrãbĩ ại̹lay̱ bābi ạủwrusẖalīma."],[1,13,"شُدِّي ٱلْمَرْكَبَةَ بِٱلْجَوَادِ يَا سَاكِنَةَ لَاخِيشَ، هِيَ أَوَّلُ خَطِيَّةٍ لِٱبْنَةِ صِهْيَوْنَ، لِأَنَّهُ فِيكِ وُجِدَتْ ذُنُوبُ إِسْرَائِيلَ.","sẖudĩy ٱl̊mar̊kabaẗa biٱl̊jawādi yā sākinaẗa lākẖīsẖa, hīa ạảwãlu kẖaṭīãẗiⁿ liٱb̊naẗi ṣih̊yaẘna, liạảnãhu fīki wujidat̊ dẖunūbu ại̹s̊rāyỉyla."],[1,14,"لِذَلِكَ تُعْطِينَ إِطْلَاقًا لِمُورَشَةِ جَتَّ. تَصِيرُ بُيُوتُ أَكْزِيبَ كَاذِبَةً لِمُلُوكِ إِسْرَائِيلَ.","lidẖalika tuʿ̊ṭīna ại̹ṭ̊lāqaⁿạ limūrasẖaẗi jatã. taṣīru buyūtu ạảk̊zība kādẖibaẗaⁿ limulūki ại̹s̊rāyỉyla."],[1,15,"آتِي إِلَيْكِ أَيْضًا بِٱلْوَارِثِ يَا سَاكِنَةَ مَرِيشَةَ. يَأْتِي إِلَى عَدُلَّامَ مَجْدُ إِسْرَائِيلَ.","ậtī ại̹laẙki ạảẙḍaⁿạ biٱl̊wāritẖi yā sākinaẗa marīsẖaẗa. yā̊̉tī ại̹lay̱ ʿadulãạma maj̊du ại̹s̊rāyỉyla."],[1,16,"كُونِي قَرْعَاءَ وَجُزِّي مِنْ أَجْلِ بَنِي تَنَعُّمِكِ. وَسِّعِي قَرْعَتَكِ كَٱلنَّسْرِ، لِأَنَّهُمْ قَدِ ٱنْتَفَوْا عَنْكِ.","kūnī qar̊ʿāʾa wajuzĩy min̊ ạảj̊li banī tanaʿũmiki. wasĩʿī qar̊ʿataki kaٱlnãs̊ri, liạảnãhum̊ qadi ٱn̊tafaẘạ ʿan̊ki."],[2,1,"وَيْلٌ لِلْمُفْتَكِرِينَ بِٱلْبُطْلِ، وَٱلصَّانِعِينَ ٱلشَّرَّ عَلَى مَضَاجِعِهِمْ! فِي نُورِ ٱلصَّبَاحِ يَفْعَلُونَهُ لِأَنَّهُ فِي قُدْرَةِ يَدِهِمْ.","waẙluⁿ lil̊muf̊takirīna biٱl̊buṭ̊li, waٱlṣãạniʿīna ٱlsẖãrã ʿalay̱ maḍājiʿihim̊! fī nūri ٱlṣãbāḥi yaf̊ʿalūnahu liạảnãhu fī qud̊raẗi yadihim̊."],[2,2,"فَإِنَّهُمْ يَشْتَهُونَ ٱلْحُقُولَ وَيَغْتَصِبُونَهَا، وَٱلْبُيُوتَ وَيَأْخُذُونَهَا، وَيَظْلِمُونَ ٱلرَّجُلَ وَبَيْتَهُ وَٱلْإِنْسَانَ وَمِيرَاثَهُ.","fāi̹nãhum̊ yasẖ̊tahūna ٱl̊ḥuqūla wayagẖ̊taṣibūnahā, waٱl̊buyūta wayā̊̉kẖudẖūnahā, wayaẓ̊limūna ٱlrãjula wabaẙtahu waٱl̊ại̹n̊sāna wamīrātẖahu."],[2,3,"لِذَلِكَ هَكَذَا قَالَ ٱلرَّبُّ: «هَأَنَذَا أَفْتَكِرُ عَلَى هَذِهِ ٱلْعَشِيرَةِ بِشَرٍّ لَا تُزِيلُونَ مِنْهُ أَعْنَاقَكُمْ، وَلَا تَسْلُكُونَ بِٱلتَّشَامُخِ لِأَنَّهُ زَمَانٌ رَدِيءٌ.","lidẖalika hakadẖā qāla ٱlrãbũ: «hāảnadẖā ạảf̊takiru ʿalay̱ hadẖihi ٱl̊ʿasẖīraẗi bisẖariⁿ̃ lā tuzīlūna min̊hu ạảʿ̊nāqakum̊, walā tas̊lukūna biٱltãsẖāmukẖi liạảnãhu zamānuⁿ radīʾuⁿ."],[2,4,"«فِي ذَلِكَ ٱلْيَوْمِ يُنْطَقُ عَلَيْكُمْ بِهَجْوٍ وَيُرْثَى بِمَرْثَاةٍ، وَيُقَالُ: خَرِبْنَا خَرَابًا. بَدَلَ نَصِيبِ شَعْبِي. كَيْفَ يَنْزِعُهُ عَنِّي؟ يَقْسِمُ لِلْمُرْتَدِّ حُقُولَنَا».","«fī dẖalika ٱl̊yaẘmi yun̊ṭaqu ʿalaẙkum̊ bihaj̊wiⁿ wayur̊tẖay̱ bimar̊tẖāẗiⁿ, wayuqālu: kẖarib̊nā kẖarābaⁿạ. badala naṣībi sẖaʿ̊bī. kaẙfa yan̊ziʿuhu ʿanĩy? yaq̊simu lil̊mur̊tadĩ ḥuqūlanā»."],[2,5,"لِذَلِكَ لَا يَكُونُ لَكَ مَنْ يُلْقِي حَبْلًا فِي نَصِيبٍ بَيْنَ جَمَاعَةِ ٱلرَّبِّ.","lidẖalika lā yakūnu laka man̊ yul̊qī ḥab̊laⁿạ fī naṣībiⁿ baẙna jamāʿaẗi ٱlrãbĩ."],[2,6,"يَتَنَبَّأُونَ قَائِلِينَ: «لَا تَتَنَبَّأُوا». لَا يَتَنَبَّأُونَ عَنْ هَذِهِ ٱلْأُمُورِ. لَا يَزُولُ ٱلْعَارُ.","yatanabãạủwna qāyỉlīna: «lā tatanabãạủwạ». lā yatanabãạủwna ʿan̊ hadẖihi ٱl̊ạủmūri. lā yazūlu ٱl̊ʿāru."],[2,7,"أَيُّهَا ٱلْمُسَمَّى بَيْتَ يَعْقُوبَ، هَلْ قَصُرَتْ رُوحُ ٱلرَّبِّ؟ أَهَذِهِ أَفْعَالُهُ؟ «أَلَيْسَتْ أَقْوَالِي صَالِحَةً نَحْوَ مَنْ يَسْلُكُ بِٱلِٱسْتِقَامَةِ؟","ạảyũhā ٱl̊musamãy̱ baẙta yaʿ̊qūba, hal̊ qaṣurat̊ rūḥu ٱlrãbĩ? ạảhadẖihi ạảf̊ʿāluhu? «ạảlaẙsat̊ ạảq̊wālī ṣāliḥaẗaⁿ naḥ̊wa man̊ yas̊luku biٱliٱs̊tiqāmaẗi?"],[2,8,"وَلَكِنْ بِٱلْأَمْسِ قَامَ شَعْبِي كَعَدُوٍّ. تَنْزِعُونَ ٱلرِّدَاءَ عَنِ ٱلثَّوْبِ مِنَ ٱلْمُجْتَازِينَ بِٱلطُّمَأْنِينَةِ، وَمِنَ ٱلرَّاجِعِينَ مِنَ ٱلْقِتَالِ.","walakin̊ biٱl̊ạảm̊si qāma sẖaʿ̊bī kaʿadūiⁿ̃. tan̊ziʿūna ٱlrĩdāʾa ʿani ٱltẖãẘbi mina ٱl̊muj̊tāzīna biٱlṭũmā̊̉nīnaẗi, wamina ٱlrãạjiʿīna mina ٱl̊qitāli."],[2,9,"تَطْرُدُونَ نِسَاءَ شَعْبِي مِنْ بَيْتِ تَنَعُّمِهِنَّ. تَأْخُذُونَ عَنْ أَطْفَالِهِنَّ زِينَتِي إِلَى ٱلْأَبَدِ.","taṭ̊rudūna nisāʾa sẖaʿ̊bī min̊ baẙti tanaʿũmihinã. tā̊̉kẖudẖūna ʿan̊ ạảṭ̊fālihinã zīnatī ại̹lay̱ ٱl̊ạảbadi."],[2,10,"«قُومُوا وَٱذْهَبُوا، لِأَنَّهُ لَيْسَتْ هَذِهِ هِيَ ٱلرَّاحَةَ. مِنْ أَجْلِ نَجَاسَةٍ تُهْلِكُ وَٱلْهَلَاكُ شَدِيدٌ.","«qūmūạ waٱdẖ̊habūạ, liạảnãhu laẙsat̊ hadẖihi hīa ٱlrãạḥaẗa. min̊ ạảj̊li najāsaẗiⁿ tuh̊liku waٱl̊halāku sẖadīduⁿ."],[2,11,"لَوْ كَانَ أَحَدٌ وَهُوَ سَالِكٌ بِٱلرِّيحِ وَٱلْكَذِبِ يَكْذِبُ قَائِلًا: أَتَنَبَّأُ لَكَ عَنِ ٱلْخَمْرِ وَٱلْمُسْكِرِ لَكَانَ هُوَ نَبِيَّ هَذَا ٱلشَّعْبِ!","laẘ kāna ạảḥaduⁿ wahūa sālikuⁿ biٱlrĩyḥi waٱl̊kadẖibi yak̊dẖibu qāyỉlaⁿạ: ạảtanabãạủ laka ʿani ٱl̊kẖam̊ri waٱl̊mus̊kiri lakāna hūa nabīã hadẖā ٱlsẖãʿ̊bi!"],[2,12,"«إِنِّي أَجْمَعُ جَمِيعَكَ يَا يَعْقُوبُ. أَضُمُّ بَقِيَّةَ إِسْرَائِيلَ. أَضَعُهُمْ مَعًا كَغَنَمِ ٱلْحَظِيرَةِ، كَقَطِيعٍ فِي وَسَطِ مَرْعَاهُ يَضِجُّ مِنَ ٱلنَّاسِ.","«ại̹nĩy ạảj̊maʿu jamīʿaka yā yaʿ̊qūbu. ạảḍumũ baqīãẗa ại̹s̊rāyỉyla. ạảḍaʿuhum̊ maʿaⁿạ kagẖanami ٱl̊ḥaẓīraẗi, kaqaṭīʿiⁿ fī wasaṭi mar̊ʿāhu yaḍijũ mina ٱlnãạsi."],[2,13,"قَدْ صَعِدَ ٱلْفَاتِكُ أَمَامَهُمْ. يَقْتَحِمُونَ وَيَعْبُرُونَ مِنَ ٱلْبَابِ، وَيَخْرُجُونَ مِنْهُ، وَيَجْتَازُ مَلِكُهُمْ أَمَامَهُمْ، وَٱلرَّبُّ فِي رَأْسِهِمْ».","qad̊ ṣaʿida ٱl̊fātiku ạảmāmahum̊. yaq̊taḥimūna wayaʿ̊burūna mina ٱl̊bābi, wayakẖ̊rujūna min̊hu, wayaj̊tāzu malikuhum̊ ạảmāmahum̊, waٱlrãbũ fī rā̊̉sihim̊»."],[3,1,"وَقُلْتُ: «ٱسْمَعُوا يَا رُؤَسَاءَ يَعْقُوبَ، وَقُضَاةَ بَيْتِ إِسْرَائِيلَ. أَلَيْسَ لَكُمْ أَنْ تَعْرِفُوا ٱلْحَقَّ؟","waqul̊tu: «ٱs̊maʿūạ yā rūảsāʾa yaʿ̊qūba, waquḍāẗa baẙti ại̹s̊rāyỉyla. ạảlaẙsa lakum̊ ạản̊ taʿ̊rifūạ ٱl̊ḥaqã?"],[3,2,"ٱلْمُبْغِضِينَ ٱلْخَيْرَ وَٱلْمُحِبِّينَ ٱلشَّرَّ، ٱلنَّازِعِينَ جُلُودَهُمْ عَنْهُمْ، وَلَحْمَهُمْ عَنْ عِظَامِهِمْ.","ٱl̊mub̊gẖiḍīna ٱl̊kẖaẙra waٱl̊muḥibĩyna ٱlsẖãrã, ٱlnãạziʿīna julūdahum̊ ʿan̊hum̊, walaḥ̊mahum̊ ʿan̊ ʿiẓāmihim̊."],[3,3,"وَٱلَّذِينَ يَأْكُلُونَ لَحْمَ شَعْبِي، وَيَكْشُطُونَ جِلْدَهُمْ عَنْهُمْ، وَيُهَشِّمُونَ عِظَامَهُمْ، وَيُشَقِّقُونَ كَمَا فِي ٱلْقِدْرِ، وَكَٱللَّحْمِ فِي وَسَطِ ٱلْمِقْلَى».","waٱlãdẖīna yā̊̉kulūna laḥ̊ma sẖaʿ̊bī, wayak̊sẖuṭūna jil̊dahum̊ ʿan̊hum̊, wayuhasẖĩmūna ʿiẓāmahum̊, wayusẖaqĩqūna kamā fī ٱl̊qid̊ri, wakaٱllãḥ̊mi fī wasaṭi ٱl̊miq̊lay̱»."],[3,4,"حِينَئِذٍ يَصْرُخُونَ إِلَى ٱلرَّبِّ فَلَا يُجِيبُهُمْ، بَلْ يَسْتُرُ وَجْهَهُ عَنْهُمْ فِي ذَلِكَ ٱلْوَقْتِ كَمَا أَسَاءُوا أَعْمَالَهُمْ.","ḥīnayỉdẖiⁿ yaṣ̊rukẖūna ại̹lay̱ ٱlrãbĩ falā yujībuhum̊, bal̊ yas̊turu waj̊hahu ʿan̊hum̊ fī dẖalika ٱl̊waq̊ti kamā ạảsāʾūạ ạảʿ̊mālahum̊."],[3,5,"هَكَذَا قَالَ ٱلرَّبُّ عَلَى ٱلْأَنْبِيَاءِ ٱلَّذِينَ يُضِلُّونَ شَعْبِي، ٱلَّذِينَ يَنْهَشُونَ بِأَسْنَانِهِمْ، وَيُنَادُونَ: «سَلَامٌ»! وَٱلَّذِي لَا يَجْعَلُ فِي أَفْوَاهِهِمْ شَيْئًا، يَفْتَحُونَ عَلَيْهِ حَرْبًا:","hakadẖā qāla ٱlrãbũ ʿalay̱ ٱl̊ạản̊bīāʾi ٱlãdẖīna yuḍilũwna sẖaʿ̊bī, ٱlãdẖīna yan̊hasẖūna biạảs̊nānihim̊, wayunādūna: «salāmuⁿ»! waٱlãdẖī lā yaj̊ʿalu fī ạảf̊wāhihim̊ sẖaẙyaⁿ̉ạ, yaf̊taḥūna ʿalaẙhi ḥar̊baⁿạ:"],[3,6,"«لِذَلِكَ تَكُونُ لَكُمْ لَيْلَةٌ بِلَا رُؤْيَا. ظَلَامٌ لَكُمْ بِدُونِ عِرَافَةٍ. وَتَغِيبُ ٱلشَّمْسُ عَنِ ٱلْأَنْبِيَاءِ، وَيُظْلِمُ عَلَيْهِمِ ٱلنَّهَارُ.","«lidẖalika takūnu lakum̊ laẙlaẗuⁿ bilā rū̊̉yā. ẓalāmuⁿ lakum̊ bidūni ʿirāfaẗiⁿ. watagẖību ٱlsẖãm̊su ʿani ٱl̊ạản̊bīāʾi, wayuẓ̊limu ʿalaẙhimi ٱlnãhāru."],[3,7,"فَيَخْزَى ٱلرَّاؤُونَ، وَيَخْجَلُ ٱلْعَرَّافُونَ، وَيُغَطُّونَ كُلُّهُمْ شَوَارِبَهُمْ، لِأَنَّهُ لَيْسَ جَوَابٌ مِنَ ٱللهِ».","fayakẖ̊zay̱ ٱlrãạwủwna, wayakẖ̊jalu ٱl̊ʿarãạfūna, wayugẖaṭũwna kulũhum̊ sẖawāribahum̊, liạảnãhu laẙsa jawābuⁿ mina ٱllhi»."],[3,8,"لَكِنَّنِي أَنَا مَلْآنٌ قُوَّةَ رُوحِ ٱلرَّبِّ وَحَقًّا وَبَأْسًا، لِأُخَبِّرَ يَعْقُوبَ بِذَنْبِهِ وَإِسْرَائِيلَ بِخَطِيَّتِهِ.","lakinãnī ạảnā mal̊ậnuⁿ qūãẗa rūḥi ٱlrãbĩ waḥaqaⁿ̃ạ wabā̊̉saⁿạ, liạủkẖabĩra yaʿ̊qūba bidẖan̊bihi wāi̹s̊rāyỉyla bikẖaṭīãtihi."],[3,9,"اِسْمَعُوا هَذَا يَا رُؤَسَاءَ بَيْتِ يَعْقُوبَ وَقُضَاةَ بَيْتِ إِسْرَائِيلَ، ٱلَّذِينَ يَكْرَهُونَ ٱلْحَقَّ وَيُعَوِّجُونَ كُلَّ مُسْتَقِيمٍ.","ạis̊maʿūạ hadẖā yā rūảsāʾa baẙti yaʿ̊qūba waquḍāẗa baẙti ại̹s̊rāyỉyla, ٱlãdẖīna yak̊rahūna ٱl̊ḥaqã wayuʿawĩjūna kulã mus̊taqīmiⁿ."],[3,10,"ٱلَّذِينَ يَبْنُونَ صِهْيَوْنَ بِٱلدِّمَاءِ، وَأُورُشَلِيمَ بِٱلظُّلْمِ.","ٱlãdẖīna yab̊nūna ṣih̊yaẘna biٱldĩmāʾi, wāủwrusẖalīma biٱlẓũl̊mi."],[3,11,"رُؤَسَاؤُهَا يَقْضُونَ بِٱلرَّشْوَةِ، وَكَهَنَتُهَا يُعَلِّمُونَ بِٱلْأُجْرَةِ، وَأَنْبِيَاؤُهَا يَعْرِفُونَ بِٱلْفِضَّةِ، وَهُمْ يَتَوَكَّلُونَ عَلَى ٱلرَّبِّ قَائِلِينَ: «أَلَيْسَ ٱلرَّبُّ فِي وَسَطِنَا؟ لَا يَأْتِي عَلَيْنَا شَرٌّ!».","rūảsāwủhā yaq̊ḍūna biٱlrãsẖ̊waẗi, wakahanatuhā yuʿalĩmūna biٱl̊ạủj̊raẗi, wāản̊bīāwủhā yaʿ̊rifūna biٱl̊fiḍãẗi, wahum̊ yatawakãlūna ʿalay̱ ٱlrãbĩ qāyỉlīna: «ạảlaẙsa ٱlrãbũ fī wasaṭinā? lā yā̊̉tī ʿalaẙnā sẖaruⁿ̃!»."],[3,12,"لِذَلِكَ بِسَبَبِكُمْ تُفْلَحُ صِهْيَوْنُ كَحَقْلٍ، وَتَصِيرُ أُورُشَلِيمُ خِرَبًا، وَجَبَلُ ٱلْبَيْتِ شَوَامِخَ وَعْرٍ.","lidẖalika bisababikum̊ tuf̊laḥu ṣih̊yaẘnu kaḥaq̊liⁿ, wataṣīru ạủwrusẖalīmu kẖirabaⁿạ, wajabalu ٱl̊baẙti sẖawāmikẖa waʿ̊riⁿ."],[4,1,"وَيَكُونُ فِي آخِرِ ٱلْأَيَّامِ أَنَّ جَبَلَ بَيْتِ ٱلرَّبِّ يَكُونُ ثَابِتًا فِي رَأْسِ ٱلْجِبَالِ، وَيَرْتَفِعُ فَوْقَ ٱلتِّلَالِ، وَتَجْرِي إِلَيْهِ شُعُوبٌ.","wayakūnu fī ậkẖiri ٱl̊ạảyãạmi ạảnã jabala baẙti ٱlrãbĩ yakūnu tẖābitaⁿạ fī rā̊̉si ٱl̊jibāli, wayar̊tafiʿu faẘqa ٱltĩlāli, wataj̊rī ại̹laẙhi sẖuʿūbuⁿ."],[4,2,"وَتَسِيرُ أُمَمٌ كَثِيرَةٌ وَيَقُولُونَ: «هَلُمَّ نَصْعَدْ إِلَى جَبَلِ ٱلرَّبِّ، وَإِلَى بَيْتِ إِلَهِ يَعْقُوبَ، فَيُعَلِّمَنَا مِنْ طُرُقِهِ، وَنَسْلُكَ فِي سُبُلِهِ». لِأَنَّهُ مِنْ صِهْيَوْنَ تَخْرُجُ ٱلشَّرِيعَةُ، وَمِنْ أُورُشَلِيمَ كَلِمَةُ ٱلرَّبِّ.","watasīru ạủmamuⁿ katẖīraẗuⁿ wayaqūlūna: «halumã naṣ̊ʿad̊ ại̹lay̱ jabali ٱlrãbĩ, wāi̹lay̱ baẙti ại̹lahi yaʿ̊qūba, fayuʿalĩmanā min̊ ṭuruqihi, wanas̊luka fī subulihi». liạảnãhu min̊ ṣih̊yaẘna takẖ̊ruju ٱlsẖãrīʿaẗu, wamin̊ ạủwrusẖalīma kalimaẗu ٱlrãbĩ."],[4,3,"فَيَقْضِي بَيْنَ شُعُوبٍ كَثِيرِينَ. يُنْصِفُ لِأُمَمٍ قَوِيَّةٍ بَعِيدَةٍ، فَيَطْبَعُونَ سُيُوفَهُمْ سِكَكًا، وَرِمَاحَهُمْ مَنَاجِلَ. لَا تَرْفَعُ أُمَّةٌ عَلَى أُمَّةٍ سَيْفًا، وَلَا يَتَعَلَّمُونَ ٱلْحَرْبَ فِي مَا بَعْدُ.","fayaq̊ḍī baẙna sẖuʿūbiⁿ katẖīrīna. yun̊ṣifu liạủmamiⁿ qawīãẗiⁿ baʿīdaẗiⁿ, fayaṭ̊baʿūna suyūfahum̊ sikakaⁿạ, warimāḥahum̊ manājila. lā tar̊faʿu ạủmãẗuⁿ ʿalay̱ ạủmãẗiⁿ saẙfaⁿạ, walā yataʿalãmūna ٱl̊ḥar̊ba fī mā baʿ̊du."],[4,4,"بَلْ يَجْلِسُونَ كُلُّ وَاحِدٍ تَحْتَ كَرْمَتِهِ وَتَحْتَ تِينَتِهِ، وَلَا يَكُونُ مَنْ يُرْعِبُ، لِأَنَّ فَمَ رَبِّ ٱلْجُنُودِ تَكَلَّمَ.","bal̊ yaj̊lisūna kulũ wāḥidiⁿ taḥ̊ta kar̊matihi wataḥ̊ta tīnatihi, walā yakūnu man̊ yur̊ʿibu, liạảnã fama rabĩ ٱl̊junūdi takalãma."],[4,5,"لِأَنَّ جَمِيعَ ٱلشُّعُوبِ يَسْلُكُونَ كُلُّ وَاحِدٍ بِٱسْمِ إِلَهِهِ، وَنَحْنُ نَسْلُكُ بِٱسْمِ ٱلرَّبِّ إِلَهِنَا إِلَى ٱلدَّهْرِ وَٱلْأَبَدِ.","liạảnã jamīʿa ٱlsẖũʿūbi yas̊lukūna kulũ wāḥidiⁿ biٱs̊mi ại̹lahihi, wanaḥ̊nu nas̊luku biٱs̊mi ٱlrãbĩ ại̹lahinā ại̹lay̱ ٱldãh̊ri waٱl̊ạảbadi."],[4,6,"«فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَجْمَعُ ٱلظَّالِعَةَ، وَأَضُمُّ ٱلْمَطْرُودَةَ، وَٱلَّتِي أَضْرَرْتُ بِهَا","«fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảj̊maʿu ٱlẓãạliʿaẗa, wāảḍumũ ٱl̊maṭ̊rūdaẗa, waٱlãtī ạảḍ̊rar̊tu bihā"],[4,7,"وَأَجْعَلُ ٱلظَّالِعَةَ بَقِيَّةً، وَٱلْمُقْصَاةَ أُمَّةً قَوِيَّةً، وَيَمْلِكُ ٱلرَّبُّ عَلَيْهِمْ فِي جَبَلِ صِهْيَوْنَ مِنَ ٱلْآنَ إِلَى ٱلْأَبَدِ.","wāảj̊ʿalu ٱlẓãạliʿaẗa baqīãẗaⁿ, waٱl̊muq̊ṣāẗa ạủmãẗaⁿ qawīãẗaⁿ, wayam̊liku ٱlrãbũ ʿalaẙhim̊ fī jabali ṣih̊yaẘna mina ٱl̊ậna ại̹lay̱ ٱl̊ạảbadi."],[4,8,"وَأَنْتَ يَا بُرْجَ ٱلْقَطِيعِ، أَكَمَةَ بِنْتِ صِهْيَوْنَ إِلَيْكِ يَأْتِي. وَيَجِيءُ ٱلْحُكْمُ ٱلْأَوَّلُ مُلْكُ بِنْتِ أُورُشَلِيمَ».","wāản̊ta yā bur̊ja ٱl̊qaṭīʿi, ạảkamaẗa bin̊ti ṣih̊yaẘna ại̹laẙki yā̊̉tī. wayajīʾu ٱl̊ḥuk̊mu ٱl̊ạảwãlu mul̊ku bin̊ti ạủwrusẖalīma»."],[4,9,"اَلْآنَ لِمَاذَا تَصْرُخِينَ صُرَاخًا؟ أَلَيْسَ فِيكِ مَلِكٌ، أَمْ هَلَكَ مُشِيرُكِ حَتَّى أَخَذَكِ وَجَعٌ كَٱلْوَالِدَةِ؟","ạal̊ậna limādẖā taṣ̊rukẖīna ṣurākẖaⁿạ? ạảlaẙsa fīki malikuⁿ, ạảm̊ halaka musẖīruki ḥatãy̱ ạảkẖadẖaki wajaʿuⁿ kaٱl̊wālidaẗi?"],[4,10,"تَلَوَّيِ، ٱدْفَعِي يَا بِنْتَ صِهْيَوْنَ كَٱلْوَالِدَةِ، لِأَنَّكِ ٱلْآنَ تَخْرُجِينَ مِنَ ٱلْمَدِينَةِ، وَتَسْكُنِينَ فِي ٱلْبَرِّيَّةِ، وَتَأْتِينَ إِلَى بَابِلَ. هُنَاكَ تُنْقَذِينَ. هُنَاكَ يَفْدِيكِ ٱلرَّبُّ مِنْ يَدِ أَعْدَائِكِ.","talawãyi, ٱd̊faʿī yā bin̊ta ṣih̊yaẘna kaٱl̊wālidaẗi, liạảnãki ٱl̊ậna takẖ̊rujīna mina ٱl̊madīnaẗi, watas̊kunīna fī ٱl̊barĩyãẗi, watā̊̉tīna ại̹lay̱ bābila. hunāka tun̊qadẖīna. hunāka yaf̊dīki ٱlrãbũ min̊ yadi ạảʿ̊dāyỉki."],[4,11,"وَٱلْآنَ قَدِ ٱجْتَمَعَتْ عَلَيْكِ أُمَمٌ كَثِيرَةٌ، ٱلَّذِينَ يَقُولُونَ: «لِتَتَدَنَّسْ وَلْتَتَفَرَّسْ عُيُونُنَا فِي صِهْيَوْنَ».","waٱl̊ậna qadi ٱj̊tamaʿat̊ ʿalaẙki ạủmamuⁿ katẖīraẗuⁿ, ٱlãdẖīna yaqūlūna: «litatadanãs̊ wal̊tatafarãs̊ ʿuyūnunā fī ṣih̊yaẘna»."],[4,12,"وَهُمْ لَا يَعْرِفُونَ أَفْكَارَ ٱلرَّبِّ وَلَا يَفْهَمُونَ قَصْدَهُ، إِنَّهُ قَدْ جَمَعَهُمْ كَحُزَمٍ إِلَى ٱلْبَيْدَرِ.","wahum̊ lā yaʿ̊rifūna ạảf̊kāra ٱlrãbĩ walā yaf̊hamūna qaṣ̊dahu, ại̹nãhu qad̊ jamaʿahum̊ kaḥuzamiⁿ ại̹lay̱ ٱl̊baẙdari."],[4,13,"«قُومِي وَدُوسِي يَا بِنْتَ صِهْيَوْنَ، لِأَنِّي أَجْعَلُ قَرْنَكِ حَدِيدًا، وَأَظْلَافَكِ أَجْعَلُهَا نُحَاسًا، فَتَسْحَقِينَ شُعُوبًا كَثِيرِينَ، وَأُحَرِّمُ غَنِيمَتَهُمْ لِلرَّبِّ، وَثَرْوَتَهُمْ لِسَيِّدِ كُلِّ ٱلْأَرْضِ».","«qūmī wadūsī yā bin̊ta ṣih̊yaẘna, liạảnĩy ạảj̊ʿalu qar̊naki ḥadīdaⁿạ, wāảẓ̊lāfaki ạảj̊ʿaluhā nuḥāsaⁿạ, fatas̊ḥaqīna sẖuʿūbaⁿạ katẖīrīna, wāủḥarĩmu gẖanīmatahum̊ lilrãbĩ, watẖar̊watahum̊ lisayĩdi kulĩ ٱl̊ạảr̊ḍi»."],[5,1,"اَلْآنَ تَتَجَيَّشِينَ يَا بِنْتَ ٱلْجُيُوشِ. قَدْ أَقَامَ عَلَيْنَا مِتْرَسَةً. يَضْرِبُونَ قَاضِيَ إِسْرَائِيلَ بِقَضِيبٍ عَلَى خَدِّهِ.","ạal̊ậna tatajayãsẖīna yā bin̊ta ٱl̊juyūsẖi. qad̊ ạảqāma ʿalaẙnā mit̊rasaẗaⁿ. yaḍ̊ribūna qāḍīa ại̹s̊rāyỉyla biqaḍībiⁿ ʿalay̱ kẖadĩhi."],[5,2,"«أَمَّا أَنْتِ يَا بَيْتَ لَحْمِ أَفْرَاتَةَ، وَأَنْتِ صَغِيرَةٌ أَنْ تَكُونِي بَيْنَ أُلُوفِ يَهُوذَا، فَمِنْكِ يَخْرُجُ لِي ٱلَّذِي يَكُونُ مُتَسَلِّطًا عَلَى إِسْرَائِيلَ، وَمَخَارِجُهُ مُنْذُ ٱلْقَدِيمِ، مُنْذُ أَيَّامِ ٱلْأَزَلِ».","«ạảmãạ ạản̊ti yā baẙta laḥ̊mi ạảf̊rātaẗa, wāản̊ti ṣagẖīraẗuⁿ ạản̊ takūnī baẙna ạủlūfi yahūdẖā, famin̊ki yakẖ̊ruju lī ٱlãdẖī yakūnu mutasalĩṭaⁿạ ʿalay̱ ại̹s̊rāyỉyla, wamakẖārijuhu mun̊dẖu ٱl̊qadīmi, mun̊dẖu ạảyãạmi ٱl̊ạảzali»."],[5,3,"لِذَلِكَ يُسَلِّمُهُمْ إِلَى حِينَمَا تَكُونُ قَدْ وَلَدَتْ وَالِدَةٌ، ثُمَّ تَرْجِعُ بَقِيَّةُ إِخْوَتِهِ إِلَى بَنِي إِسْرَائِيلَ.","lidẖalika yusalĩmuhum̊ ại̹lay̱ ḥīnamā takūnu qad̊ waladat̊ wālidaẗuⁿ, tẖumã tar̊jiʿu baqīãẗu ại̹kẖ̊watihi ại̹lay̱ banī ại̹s̊rāyỉyla."],[5,4,"وَيَقِفُ وَيَرْعَى بِقُدْرَةِ ٱلرَّبِّ، بِعَظَمَةِ ٱسْمِ ٱلرَّبِّ إِلَهِهِ، وَيَثْبُتُونَ. لِأَنَّهُ ٱلْآنَ يَتَعَظَّمُ إِلَى أَقَاصِي ٱلْأَرْضِ.","wayaqifu wayar̊ʿay̱ biqud̊raẗi ٱlrãbĩ, biʿaẓamaẗi ٱs̊mi ٱlrãbĩ ại̹lahihi, wayatẖ̊butūna. liạảnãhu ٱl̊ậna yataʿaẓãmu ại̹lay̱ ạảqāṣī ٱl̊ạảr̊ḍi."],[5,5,"وَيَكُونُ هَذَا سَلَامًا. إِذَا دَخَلَ أَشُّورُ فِي أَرْضِنَا، وَإِذَا دَاسَ فِي قُصُورِنَا، نُقِيمُ عَلَيْهِ سَبْعَةَ رُعَاةٍ وَثَمَانِيَةً مِنْ أُمَرَاءِ ٱلنَّاسِ،","wayakūnu hadẖā salāmaⁿạ. ại̹dẖā dakẖala ạảsẖũwru fī ạảr̊ḍinā, wāi̹dẖā dāsa fī quṣūrinā, nuqīmu ʿalaẙhi sab̊ʿaẗa ruʿāẗiⁿ watẖamānīaẗaⁿ min̊ ạủmarāʾi ٱlnãạsi,"],[5,6,"فَيَرْعَوْنَ أَرْضَ أَشُّورَ بِٱلسَّيْفِ، وَأَرْضَ نِمْرُودَ فِي أَبْوَابِهَا، فَيَنْفُذُ مِنْ أَشُّورَ إِذَا دَخَلَ أَرْضَنَا وَإِذَا دَاسَ تُخُومَنَا.","fayar̊ʿaẘna ạảr̊ḍa ạảsẖũwra biٱlsãẙfi, wāảr̊ḍa nim̊rūda fī ạảb̊wābihā, fayan̊fudẖu min̊ ạảsẖũwra ại̹dẖā dakẖala ạảr̊ḍanā wāi̹dẖā dāsa tukẖūmanā."],[5,7,"وَتَكُونُ بَقِيَّةُ يَعْقُوبَ فِي وَسَطِ شُعُوبٍ كَثِيرِينَ كَٱلنَّدَى مِنْ عِنْدِ ٱلرَّبِّ، كَٱلْوَابِلِ عَلَى ٱلْعُشْبِ ٱلَّذِي لَا يَنْتَظِرُ إِنْسَانًا وَلَا يَصْبِرُ لِبَنِي ٱلْبَشَرِ.","watakūnu baqīãẗu yaʿ̊qūba fī wasaṭi sẖuʿūbiⁿ katẖīrīna kaٱlnãday̱ min̊ ʿin̊di ٱlrãbĩ, kaٱl̊wābili ʿalay̱ ٱl̊ʿusẖ̊bi ٱlãdẖī lā yan̊taẓiru ại̹n̊sānaⁿạ walā yaṣ̊biru libanī ٱl̊basẖari."],[5,8,"وَتَكُونُ بَقِيَّةُ يَعْقُوبَ بَيْنَ ٱلْأُمَمِ فِي وَسَطِ شُعُوبٍ كَثِيرِينَ كَٱلْأَسَدِ بَيْنَ وُحُوشِ ٱلْوَعْرِ، كَشِبْلِ ٱلْأَسَدِ بَيْنَ قُطْعَانِ ٱلْغَنَمِ، ٱلَّذِي إِذَا عَبَرَ يَدُوسُ وَيَفْتَرِسُ وَلَيْسَ مَنْ يُنْقِذُ.","watakūnu baqīãẗu yaʿ̊qūba baẙna ٱl̊ạủmami fī wasaṭi sẖuʿūbiⁿ katẖīrīna kaٱl̊ạảsadi baẙna wuḥūsẖi ٱl̊waʿ̊ri, kasẖib̊li ٱl̊ạảsadi baẙna quṭ̊ʿāni ٱl̊gẖanami, ٱlãdẖī ại̹dẖā ʿabara yadūsu wayaf̊tarisu walaẙsa man̊ yun̊qidẖu."],[5,9,"لِتَرْتَفِعْ يَدُكَ عَلَى مُبْغِضِيكَ وَيَنْقَرِضْ كُلُّ أَعْدَائِكَ.","litar̊tafiʿ̊ yaduka ʿalay̱ mub̊gẖiḍīka wayan̊qariḍ̊ kulũ ạảʿ̊dāyỉka."],[5,10,"«وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَنِّي أَقْطَعُ خَيْلَكَ مِنْ وَسَطِكَ، وَأُبِيدُ مَرْكَبَاتِكَ.","«wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảnĩy ạảq̊ṭaʿu kẖaẙlaka min̊ wasaṭika, wāủbīdu mar̊kabātika."],[5,11,"وَأَقْطَعُ مُدُنَ أَرْضِكَ، وَأَهْدِمُ كُلَّ حُصُونِكَ.","wāảq̊ṭaʿu muduna ạảr̊ḍika, wāảh̊dimu kulã ḥuṣūnika."],[5,12,"وَأَقْطَعُ ٱلسِّحْرَ مِنْ يَدِكَ، وَلَا يَكُونُ لَكَ عَائِفُونَ.","wāảq̊ṭaʿu ٱlsĩḥ̊ra min̊ yadika, walā yakūnu laka ʿāyỉfūna."],[5,13,"وَأَقْطَعُ تَمَاثِيلَكَ ٱلْمَنْحُوتَةَ وَأَنْصَابَكَ مِنْ وَسَطِكَ، فَلَا تَسْجُدُ لِعَمَلِ يَدَيْكَ فِي مَا بَعْدُ.","wāảq̊ṭaʿu tamātẖīlaka ٱl̊man̊ḥūtaẗa wāản̊ṣābaka min̊ wasaṭika, falā tas̊judu liʿamali yadaẙka fī mā baʿ̊du."],[5,14,"وَأَقْلَعُ سَوَارِيَكَ مِنْ وَسَطِكَ وَأُبِيدُ مُدُنَكَ.","wāảq̊laʿu sawārīaka min̊ wasaṭika wāủbīdu mudunaka."],[5,15,"وَبِغَضَبٍ وَغَيْظٍ أَنْتَقِمُ مِنَ ٱلْأُمَمِ ٱلَّذِينَ لَمْ يَسْمَعُوا».","wabigẖaḍabiⁿ wagẖaẙẓiⁿ ạản̊taqimu mina ٱl̊ạủmami ٱlãdẖīna lam̊ yas̊maʿūạ»."],[6,1,"اِسْمَعُوا مَا قَالَهُ ٱلرَّبُّ: «قُمْ خَاصِمْ لَدَى ٱلْجِبَالِ وَلْتَسْمَعِ ٱلتِّلَالُ صَوْتَكَ.","ạis̊maʿūạ mā qālahu ٱlrãbũ: «qum̊ kẖāṣim̊ laday̱ ٱl̊jibāli wal̊tas̊maʿi ٱltĩlālu ṣaẘtaka."],[6,2,"اِسْمَعِي خُصُومَةَ ٱلرَّبِّ أَيَّتُهَا ٱلْجِبَالُ وَيَا أُسُسَ ٱلْأَرْضِ ٱلدَّائِمَةَ. فَإِنَّ لِلرَّبِّ خُصُومَةً مَعَ شَعْبِهِ وَهُوَ يُحَاكِمُ إِسْرَائِيلَ:","ạis̊maʿī kẖuṣūmaẗa ٱlrãbĩ ạảyãtuhā ٱl̊jibālu wayā ạủsusa ٱl̊ạảr̊ḍi ٱldãạyỉmaẗa. fāi̹nã lilrãbĩ kẖuṣūmaẗaⁿ maʿa sẖaʿ̊bihi wahūa yuḥākimu ại̹s̊rāyỉyla:"],[6,3,"«يَا شَعْبِي، مَاذَا صَنَعْتُ بِكَ وَبِمَاذَا أَضْجَرْتُكَ؟ ٱشْهَدْ عَلَيَّ!","«yā sẖaʿ̊bī, mādẖā ṣanaʿ̊tu bika wabimādẖā ạảḍ̊jar̊tuka? ٱsẖ̊had̊ ʿalayã!"],[6,4,"إِنِّي أَصْعَدْتُكَ مِنْ أَرْضِ مِصْرَ، وَفَكَكْتُكَ مِنْ بَيْتِ ٱلْعُبُودِيَّةِ، وَأَرْسَلْتُ أَمَامَكَ مُوسَى وَهَارُونَ وَمَرْيَمَ.","ại̹nĩy ạảṣ̊ʿad̊tuka min̊ ạảr̊ḍi miṣ̊ra, wafakak̊tuka min̊ baẙti ٱl̊ʿubūdīãẗi, wāảr̊sal̊tu ạảmāmaka mūsay̱ wahārūna wamar̊yama."],[6,5,"يَا شَعْبِي ٱذْكُرْ بِمَاذَا تَآمَرَ بَالَاقُ مَلِكُ مُوآبَ، وَبِمَاذَا أَجَابَهُ بَلْعَامُ بْنُ بَعُورَ، مِنْ شِطِّيمَ إِلَى ٱلْجِلْجَالِ، لِكَيْ تَعْرِفَ إِجَادَةَ ٱلرَّبِّ».","yā sẖaʿ̊bī ٱdẖ̊kur̊ bimādẖā tā̂mara bālāqu maliku mūậba, wabimādẖā ạảjābahu bal̊ʿāmu b̊nu baʿūra, min̊ sẖiṭĩyma ại̹lay̱ ٱl̊jil̊jāli, likaẙ taʿ̊rifa ại̹jādaẗa ٱlrãbĩ»."],[6,6,"بِمَ أَتَقَدَّمُ إِلَى ٱلرَّبِّ وَأَنْحَنِي لِلإِلَهِ ٱلْعَلِيِّ؟ هَلْ أَتَقَدَّمُ بِمُحْرَقَاتٍ، بِعُجُولٍ أَبْنَاءِ سَنَةٍ؟","bima ạảtaqadãmu ại̹lay̱ ٱlrãbĩ wāản̊ḥanī lilại̹lahi ٱl̊ʿalīĩ? hal̊ ạảtaqadãmu bimuḥ̊raqātiⁿ, biʿujūliⁿ ạảb̊nāʾi sanaẗiⁿ?"],[6,7,"هَلْ يُسَرُّ ٱلرَّبُّ بِأُلُوفِ ٱلْكِبَاشِ، بِرِبَوَاتِ أَنْهَارِ زَيْتٍ؟ هَلْ أُعْطِي بِكْرِي عَنْ مَعْصِيَتِي، ثَمَرَةَ جَسَدِي عَنْ خَطِيَّةِ نَفْسِي؟","hal̊ yusarũ ٱlrãbũ biạủlūfi ٱl̊kibāsẖi, biribawāti ạản̊hāri zaẙtiⁿ? hal̊ ạủʿ̊ṭī bik̊rī ʿan̊ maʿ̊ṣīatī, tẖamaraẗa jasadī ʿan̊ kẖaṭīãẗi naf̊sī?"],[6,8,"قَدْ أَخْبَرَكَ أَيُّهَا ٱلْإِنْسَانُ مَا هُوَ صَالِحٌ، وَمَاذَا يَطْلُبُهُ مِنْكَ ٱلرَّبُّ، إِلَّا أَنْ تَصْنَعَ ٱلْحَقَّ وَتُحِبَّ ٱلرَّحْمَةَ، وَتَسْلُكَ مُتَوَاضِعًا مَعَ إِلَهِكَ.","qad̊ ạảkẖ̊baraka ạảyũhā ٱl̊ại̹n̊sānu mā hūa ṣāliḥuⁿ, wamādẖā yaṭ̊lubuhu min̊ka ٱlrãbũ, ại̹lãạ ạản̊ taṣ̊naʿa ٱl̊ḥaqã watuḥibã ٱlrãḥ̊maẗa, watas̊luka mutawāḍiʿaⁿạ maʿa ại̹lahika."],[6,9,"صَوْتُ ٱلرَّبِّ يُنَادِي لِلْمَدِينَةِ، وَٱلْحِكْمَةُ تَرَى ٱسْمَكَ: «اِسْمَعُوا لِلْقَضِيبِ وَمَنْ رَسَمَهُ.","ṣaẘtu ٱlrãbĩ yunādī lil̊madīnaẗi, waٱl̊ḥik̊maẗu taray̱ ٱs̊maka: «ạis̊maʿūạ lil̊qaḍībi waman̊ rasamahu."],[6,10,"أَفِي بَيْتِ ٱلشِّرِّيرِ بَعْدُ كُنُوزُ شَرٍّ وَإِيفَةٌ نَاقِصَةٌ مَلْعُونَةٌ؟","ạảfī baẙti ٱlsẖĩrĩyri baʿ̊du kunūzu sẖariⁿ̃ wāi̹yfaẗuⁿ nāqiṣaẗuⁿ mal̊ʿūnaẗuⁿ?"],[6,11,"هَلْ أَتَزَكَّى مَعَ مَوَازِينِ ٱلشَّرِّ وَمَعَ كِيسِ مَعَايِيرِ ٱلْغِشِّ؟","hal̊ ạảtazakãy̱ maʿa mawāzīni ٱlsẖãrĩ wamaʿa kīsi maʿāyīri ٱl̊gẖisẖĩ?"],[6,12,"فَإِنَّ أَغْنِيَاءَهَا مَلْآنُونَ ظُلْمًا، وَسُكَّانَهَا يَتَكَلَّمُونَ بِٱلْكَذِبِ، وَلِسَانَهُمْ فِي فَمِهِمْ غَاشٌّ.","fāi̹nã ạảgẖ̊nīāʾahā mal̊ậnūna ẓul̊maⁿạ, wasukãạnahā yatakalãmūna biٱl̊kadẖibi, walisānahum̊ fī famihim̊ gẖāsẖuⁿ̃."],[6,13,"فَأَنَا قَدْ جَعَلْتُ جُرُوحَكَ عَدِيمَةَ ٱلشِّفَاءِ، مُخْرِبًا مِنْ أَجْلِ خَطَايَاكَ.","fāảnā qad̊ jaʿal̊tu jurūḥaka ʿadīmaẗa ٱlsẖĩfāʾi, mukẖ̊ribaⁿạ min̊ ạảj̊li kẖaṭāyāka."],[6,14,"أَنْتَ تَأْكُلُ وَلَا تَشْبَعُ، وَجُوعُكَ فِي جَوْفِكَ. وَتُعَزِّلُ وَلَا تُنَجِّي، وَٱلَّذِي تُنَجِّيهِ أَدْفَعُهُ إِلَى ٱلسَّيْفِ.","ạản̊ta tā̊̉kulu walā tasẖ̊baʿu, wajūʿuka fī jaẘfika. watuʿazĩlu walā tunajĩy, waٱlãdẖī tunajĩyhi ạảd̊faʿuhu ại̹lay̱ ٱlsãẙfi."],[6,15,"أَنْتَ تَزْرَعُ وَلَا تَحْصُدُ. أَنْتَ تَدُوسُ زَيْتُونًا وَلَا تَدَّهِنُ بِزَيْتٍ، وَسُلَافَةً وَلَا تَشْرَبُ خَمْرًا.","ạản̊ta taz̊raʿu walā taḥ̊ṣudu. ạản̊ta tadūsu zaẙtūnaⁿạ walā tadãhinu bizaẙtiⁿ, wasulāfaẗaⁿ walā tasẖ̊rabu kẖam̊raⁿạ."],[6,16,"وَتُحْفَظُ فَرَائِضُ: عُمْرِي، وَجَمِيعُ أَعْمَالِ بَيْتِ: أَخْآبَ، وَتَسْلُكُونَ بِمَشُورَاتِهِمْ، لِكَيْ أُسَلِّمَكَ لِلْخَرَابِ، وَسُكَّانَهَا لِلصَّفِيرِ، فَتَحْمِلُونَ عَارَ شَعْبِي».","watuḥ̊faẓu farāyỉḍu: ʿum̊rī, wajamīʿu ạảʿ̊māli baẙti: ạảkẖ̊ậba, watas̊lukūna bimasẖūrātihim̊, likaẙ ạủsalĩmaka lil̊kẖarābi, wasukãạnahā lilṣãfīri, fataḥ̊milūna ʿāra sẖaʿ̊bī»."],[7,1,"وَيْلٌ لِي! لِأَنِّي صِرْتُ كَجَنَى ٱلصَّيْفِ، كَخُصَاصَةِ ٱلْقِطَافِ، لَا عُنْقُودَ لِلْأَكْلِ وَلَا بَاكُورَةَ تِينَةٍ ٱشْتَهَتْهَا نَفْسِي.","waẙluⁿ lī! liạảnĩy ṣir̊tu kajanay̱ ٱlṣãẙfi, kakẖuṣāṣaẗi ٱl̊qiṭāfi, lā ʿun̊qūda lil̊ạảk̊li walā bākūraẗa tīnaẗiⁿ ٱsẖ̊tahat̊hā naf̊sī."],[7,2,"قَدْ بَادَ ٱلتَّقِيُّ مِنَ ٱلْأَرْضِ، وَلَيْسَ مُسْتَقِيمٌ بَيْنَ ٱلنَّاسِ. جَمِيعُهُمْ يَكْمُنُونَ لِلدِّمَاءِ، يَصْطَادُونَ بَعْضُهُمْ بَعْضًا بِشَبَكَةٍ.","qad̊ bāda ٱltãqīũ mina ٱl̊ạảr̊ḍi, walaẙsa mus̊taqīmuⁿ baẙna ٱlnãạsi. jamīʿuhum̊ yak̊munūna lildĩmāʾi, yaṣ̊ṭādūna baʿ̊ḍuhum̊ baʿ̊ḍaⁿạ bisẖabakaẗiⁿ."],[7,3,"اَلْيَدَانِ إِلَى ٱلشَّرِّ مُجْتَهِدَتَانِ. ٱلرَّئِيسُ طَالِبٌ وَٱلْقَاضِي بِٱلْهَدِيَّةِ، وَٱلْكَبِيرُ مُتَكَلِّمٌ بِهَوَى نَفْسِهِ فَيُعَكِّشُونَهَا.","ạal̊yadāni ại̹lay̱ ٱlsẖãrĩ muj̊tahidatāni. ٱlrãyỉysu ṭālibuⁿ waٱl̊qāḍī biٱl̊hadīãẗi, waٱl̊kabīru mutakalĩmuⁿ bihaway̱ naf̊sihi fayuʿakĩsẖūnahā."],[7,4,"أَحْسَنُهُمْ مِثْلُ ٱلْعَوْسَجِ، وَأَعْدَلُهُمْ مِنْ سِيَاجِ ٱلشَّوْكِ. يَوْمَ مُرَاقِبِيكَ عِقَابُكَ قَدْ جَاءَ. ٱلْآنَ يَكُونُ ٱرْتِبَاكُهُمْ.","ạảḥ̊sanuhum̊ mitẖ̊lu ٱl̊ʿaẘsaji, wāảʿ̊daluhum̊ min̊ sīāji ٱlsẖãẘki. yaẘma murāqibīka ʿiqābuka qad̊ jāʾa. ٱl̊ậna yakūnu ٱr̊tibākuhum̊."],[7,5,"لَا تَأْتَمِنُوا صَاحِبًا. لَا تَثِقُوا بِصَدِيقٍ. ٱحْفَظْ أَبْوَابَ فَمِكَ عَنِ ٱلْمُضْطَجِعَةِ فِي حِضْنِكَ.","lā tā̊̉taminūạ ṣāḥibaⁿạ. lā tatẖiqūạ biṣadīqiⁿ. ٱḥ̊faẓ̊ ạảb̊wāba famika ʿani ٱl̊muḍ̊ṭajiʿaẗi fī ḥiḍ̊nika."],[7,6,"لِأَنَّ ٱلِٱبْنَ مُسْتَهِينٌ بِٱلْأَبِ، وَٱلْبِنْتَ قَائِمَةٌ عَلَى أُمِّهَا، وَٱلْكَنَّةَ عَلَى حَمَاتِهَا، وَأَعْدَاءُ ٱلْإِنْسَانِ أَهْلُ بَيْتِهِ.","liạảnã ٱliٱb̊na mus̊tahīnuⁿ biٱl̊ạảbi, waٱl̊bin̊ta qāyỉmaẗuⁿ ʿalay̱ ạủmĩhā, waٱl̊kanãẗa ʿalay̱ ḥamātihā, wāảʿ̊dāʾu ٱl̊ại̹n̊sāni ạảh̊lu baẙtihi."],[7,7,"وَلَكِنَّنِي أُرَاقِبُ ٱلرَّبَّ، أَصْبِرُ لِإِلَهِ خَلَاصِي. يَسْمَعُنِي إِلَهِي.","walakinãnī ạủrāqibu ٱlrãbã, ạảṣ̊biru liại̹lahi kẖalāṣī. yas̊maʿunī ại̹lahī."],[7,8,"لَا تَشْمَتِي بِي يَا عَدُوَّتِي، إِذَا سَقَطْتُ أَقُومُ. إِذَا جَلَسْتُ فِي ٱلظُّلْمَةِ فَٱلرَّبُّ نُورٌ لِي.","lā tasẖ̊matī bī yā ʿadūãtī, ại̹dẖā saqaṭ̊tu ạảqūmu. ại̹dẖā jalas̊tu fī ٱlẓũl̊maẗi faٱlrãbũ nūruⁿ lī."],[7,9,"أَحْتَمِلُ غَضَبَ ٱلرَّبِّ لِأَنِّي أَخْطَأْتُ إِلَيْهِ، حَتَّى يُقِيمَ دَعْوَايَ وَيُجْرِيَ حَقِّي. سَيُخْرِجُنِي إِلَى ٱلنُّورِ، سَأَنْظُرُ بِرَّهُ.","ạảḥ̊tamilu gẖaḍaba ٱlrãbĩ liạảnĩy ạảkẖ̊ṭā̊̉tu ại̹laẙhi, ḥatãy̱ yuqīma daʿ̊wāya wayuj̊rīa ḥaqĩy. sayukẖ̊rijunī ại̹lay̱ ٱlnũwri, sāản̊ẓuru birãhu."],[7,10,"وَتَرَى عَدُوَّتِي فَيُغَطِّيهَا ٱلْخِزْيُ، ٱلْقَائِلَةُ لِي: «أَيْنَ هُوَ ٱلرَّبُّ إِلَهُكِ؟» عَيْنَايَ سَتَنْظُرَانِ إِلَيْهَا. اَلْآنَ تَصِيرُ لِلدَّوْسِ كَطِينِ ٱلْأَزِقَّةِ.","wataray̱ ʿadūãtī fayugẖaṭĩyhā ٱl̊kẖiz̊yu, ٱl̊qāyỉlaẗu lī: «ạảẙna hūa ٱlrãbũ ại̹lahuki?» ʿaẙnāya satan̊ẓurāni ại̹laẙhā. ạal̊ậna taṣīru lildãẘsi kaṭīni ٱl̊ạảziqãẗi."],[7,11,"يَوْمَ بِنَاءِ حِيطَانِكِ، ذَلِكَ ٱلْيَوْمَ يَبْعُدُ ٱلْمِيعَادُ.","yaẘma bināʾi ḥīṭāniki, dẖalika ٱl̊yaẘma yab̊ʿudu ٱl̊mīʿādu."],[7,12,"هُوَ يَوْمٌ يَأْتُونَ إِلَيْكِ مِنْ أَشُّورَ وَمُدُنِ مِصْرَ، وَمِنْ مِصْرَ إِلَى ٱلنَّهْرِ. وَمِنَ ٱلْبَحْرِ إِلَى ٱلْبَحْرِ. وَمِنَ ٱلْجَبَلِ إِلَى ٱلْجَبَلِ.","hūa yaẘmuⁿ yā̊̉tūna ại̹laẙki min̊ ạảsẖũwra wamuduni miṣ̊ra, wamin̊ miṣ̊ra ại̹lay̱ ٱlnãh̊ri. wamina ٱl̊baḥ̊ri ại̹lay̱ ٱl̊baḥ̊ri. wamina ٱl̊jabali ại̹lay̱ ٱl̊jabali."],[7,13,"وَلَكِنْ تَصِيرُ ٱلْأَرْضُ خَرِبَةً بِسَبَبِ سُكَّانِهَا، مِنْ أَجْلِ ثَمَرِ أَفْعَالِهِمْ.","walakin̊ taṣīru ٱl̊ạảr̊ḍu kẖaribaẗaⁿ bisababi sukãạnihā, min̊ ạảj̊li tẖamari ạảf̊ʿālihim̊."],[7,14,"اِرْعَ بِعَصَاكَ شَعْبَكَ غَنَمَ مِيرَاثِكَ، سَاكِنَةً وَحْدَهَا فِي وَعْرٍ فِي وَسَطِ ٱلْكَرْمَلِ. لِتَرْعَ فِي بَاشَانَ وَجِلْعَادَ كَأَيَّامِ ٱلْقِدَمِ.","ạir̊ʿa biʿaṣāka sẖaʿ̊baka gẖanama mīrātẖika, sākinaẗaⁿ waḥ̊dahā fī waʿ̊riⁿ fī wasaṭi ٱl̊kar̊mali. litar̊ʿa fī bāsẖāna wajil̊ʿāda kāảyãạmi ٱl̊qidami."],[7,15,"«كَأَيَّامِ خُرُوجِكَ مِنْ أَرْضِ مِصْرَ أُرِيهِ عَجَائِبَ».","«kāảyãạmi kẖurūjika min̊ ạảr̊ḍi miṣ̊ra ạủrīhi ʿajāyỉba»."],[7,16,"يَنْظُرُ ٱلْأُمَمُ وَيَخْجَلُونَ مِنْ كُلِّ بَطْشِهِمْ. يَضَعُونَ أَيْدِيَهُمْ عَلَى أَفْوَاهِهِمْ، وَتَصُمُّ آذَانُهُمْ.","yan̊ẓuru ٱl̊ạủmamu wayakẖ̊jalūna min̊ kulĩ baṭ̊sẖihim̊. yaḍaʿūna ạảẙdīahum̊ ʿalay̱ ạảf̊wāhihim̊, wataṣumũ ậdẖānuhum̊."],[7,17,"يَلْحَسُونَ ٱلتُّرَابَ كَٱلْحَيَّةِ، كَزَوَاحِفِ ٱلْأَرْضِ. يَخْرُجُونَ بِٱلرِّعْدَةِ مِنْ حُصُونِهِمْ، يَأْتُونَ بِٱلرُّعْبِ إِلَى ٱلرَّبِّ إِلَهِنَا وَيَخَافُونَ مِنْكَ.","yal̊ḥasūna ٱltũrāba kaٱl̊ḥayãẗi, kazawāḥifi ٱl̊ạảr̊ḍi. yakẖ̊rujūna biٱlrĩʿ̊daẗi min̊ ḥuṣūnihim̊, yā̊̉tūna biٱlrũʿ̊bi ại̹lay̱ ٱlrãbĩ ại̹lahinā wayakẖāfūna min̊ka."],[7,18,"مَنْ هُوَ إِلَهٌ مِثْلُكَ غَافِرٌ ٱلْإِثْمَ وَصَافِحٌ عَنِ ٱلذَّنْبِ لِبَقِيَّةِ مِيرَاثِهِ! لَا يَحْفَظُ إِلَى ٱلْأَبَدِ غَضَبَهُ، فَإِنَّهُ يُسَرُّ بِٱلرَّأْفَةِ.","man̊ hūa ại̹lahuⁿ mitẖ̊luka gẖāfiruⁿ ٱl̊ại̹tẖ̊ma waṣāfiḥuⁿ ʿani ٱldẖãn̊bi libaqīãẗi mīrātẖihi! lā yaḥ̊faẓu ại̹lay̱ ٱl̊ạảbadi gẖaḍabahu, fāi̹nãhu yusarũ biٱlrãạ̊̉faẗi."],[7,19,"يَعُودُ يَرْحَمُنَا، يَدُوسُ آثَامَنَا، وَتُطْرَحُ فِي أَعْمَاقِ ٱلْبَحْرِ جَمِيعُ خَطَايَاهُمْ.","yaʿūdu yar̊ḥamunā, yadūsu ậtẖāmanā, watuṭ̊raḥu fī ạảʿ̊māqi ٱl̊baḥ̊ri jamīʿu kẖaṭāyāhum̊."],[7,20,"تَصْنَعُ ٱلْأَمَانَةَ لِيَعْقُوبَ وَٱلرَّأْفَةَ لِإِبْرَاهِيمَ، ٱللَّتَيْنِ حَلَفْتَ لِآبَائِنَا مُنْذُ أَيَّامِ ٱلْقِدَمِ.","taṣ̊naʿu ٱl̊ạảmānaẗa līaʿ̊qūba waٱlrãạ̊̉faẗa liại̹b̊rāhīma, ٱllãtaẙni ḥalaf̊ta liậbāyỉnā mun̊dẖu ạảyãạmi ٱl̊qidami."]],"bis-obbr":[[1,1,"Bifo, long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we trifala i king long Juda,* Hae God i stap toktok long Profet Maeka, wan man Juda blong vilej ya Moreset. Hem i stap soemaot ol vison* long hem, mo long ol vison ya, hem i stap tokbaot ol man blong taon ya Sameria,* we i kaptel blong Isrel,* mo ol man blong taon ya Jerusalem,* we i kaptel blong Juda.","Bifo, long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we trifala i king long Juda,* Hae God i stap toktok long Profet Maeka, wan man Juda blong vilej ya Moreset. Hem i stap soemaot ol vison* long hem, mo long ol vison ya, hem i stap tokbaot ol man blong taon ya Sameria,* we i kaptel blong Isrel,* mo ol man blong taon ya Jerusalem,* we i kaptel blong Juda."],[1,2,"Nao Profet Maeka i talem se, “Olgeta man long evri ples. Yufala i lesin gud. Olgeta man long wol. Yufala i harem tok blong mi. Hae God i Masta* blong yumi, mo hem bambae i talemaot ol poen blong hem agens long yufala. !Yufala i lesin! Hem i stap long haos* blong hem long heven, i stap toktok i kam.","Nao Profet Maeka i talem se, “Olgeta man long evri ples. Yufala i lesin gud. Olgeta man long wol. Yufala i harem tok blong mi. Hae God i Masta* blong yumi, mo hem bambae i talemaot ol poen blong hem agens long yufala. !Yufala i lesin! Hem i stap long haos* blong hem long heven, i stap toktok i kam."],[1,3,"Bambae hem i aot long haos ya blong hem, i kamdaon, i wokbaot long top blong ol hil.","Bambae hem i aot long haos ya blong hem, i kamdaon, i wokbaot long top blong ol hil."],[1,4,"Nao ol hil ya bambae oli ronaot, olsem kandel we i stap klosap long faea. Bambae oli ron bigwan olsem wota, oli folem ol krik i kamdaon, olsem wota we i aot long hil, i ron bigwan i kam.","Nao ol hil ya bambae oli ronaot, olsem kandel we i stap klosap long faea. Bambae oli ron bigwan olsem wota, oli folem ol krik i kamdaon, olsem wota we i aot long hil, i ron bigwan i kam."],[1,5,"“Ol samting ya bambae i kamtru olsem, from we yumi ol laen* blong Isrel,* yumi evriwan i mekem sin, mo yumi stap girap agens long God. Ol man Isrel. ?Yufala i stap girap agens long hem, be stamba blong hem hu? Yufala long Sameria* nomo i stamba blong hem. Ol man Juda.* ?Yufala i stap mekem wosip long ol narafala god, be hu i stamba blong hem? !Yufala long Jerusalem* nomo i stamba blong hem!","“Ol samting ya bambae i kamtru olsem, from we yumi ol laen* blong Isrel,* yumi evriwan i mekem sin, mo yumi stap girap agens long God. Ol man Isrel. ?Yufala i stap girap agens long hem, be stamba blong hem hu? Yufala long Sameria* nomo i stamba blong hem. Ol man Juda.* ?Yufala i stap mekem wosip long ol narafala god, be hu i stamba blong hem? !Yufala long Jerusalem* nomo i stamba blong hem!"],[1,6,"Nao from samting ya, Hae God i talem se, ‘Ol man Isrel. Bigfala taon ya Sameria, bambae mi mi spolemgud. Bambae mi brebrekem ol haos blong hem, we ol ston blong hem bambae i stap long ol hip olbaot long open ples, nao ples blong hem bambae i kam ples blong planem rop ya grep* nomo. Ol ston blong taon ya, bambae mi kafsaedem i go long krik, nao oli ron i godaon, mo fandesen blong taon ya bambae i stap nating nomo long klia ples.","Nao from samting ya, Hae God i talem se, ‘Ol man Isrel. Bigfala taon ya Sameria, bambae mi mi spolemgud. Bambae mi brebrekem ol haos blong hem, we ol ston blong hem bambae i stap long ol hip olbaot long open ples, nao ples blong hem bambae i kam ples blong planem rop ya grep* nomo. Ol ston blong taon ya, bambae mi kafsaedem i go long krik, nao oli ron i godaon, mo fandesen blong taon ya bambae i stap nating nomo long klia ples."],[1,7,"Ol aedol we yufala i laekem tumas, bambae ol enemi blong yufala oli brebrekem long ol smosmol pis, mo ol presen we yufala i stap givim long ol woman pris we yufala i stap go slip wetem olgeta long haos blong ol god ya blong yufala, bambae ol enemi ya oli bonem evriwan. Ol aedol ya blong yufala bambae oli kam hip blong doti nomo. Ol samting ya we yufala ol man Sameria i kasem blong yusum long wosip blong yufala, ol enemi blong yufala bambae oli kam tekemaot, blong go givim long ol woman pris blong ol god blong olgeta.’ ”","Ol aedol we yufala i laekem tumas, bambae ol enemi blong yufala oli brebrekem long ol smosmol pis, mo ol presen we yufala i stap givim long ol woman pris we yufala i stap go slip wetem olgeta long haos blong ol god ya blong yufala, bambae ol enemi ya oli bonem evriwan. Ol aedol ya blong yufala bambae oli kam hip blong doti nomo. Ol samting ya we yufala ol man Sameria i kasem blong yusum long wosip blong yufala, ol enemi blong yufala bambae oli kam tekemaot, blong go givim long ol woman pris blong ol god blong olgeta.’ ”"],[1,8,"Nao profet i talem se, “From ol samting ya, mi harem se bambae mi mas krae we mi krae bigwan. Bambae mi mas tekemaot klos blong mi mo sandel blong mi, mi stap wokbaot olsem man we i stap krae from dedman, blong soemaot we mi mi harem nogud tumas. Bambae mi stap singaot bigwan olsem wael dog ya jakol,* mo mi mas singaot nogud olsem bigfala pijin ya ostrij.*","Nao profet i talem se, “From ol samting ya, mi harem se bambae mi mas krae we mi krae bigwan. Bambae mi mas tekemaot klos blong mi mo sandel blong mi, mi stap wokbaot olsem man we i stap krae from dedman, blong soemaot we mi mi harem nogud tumas. Bambae mi stap singaot bigwan olsem wael dog ya jakol,* mo mi mas singaot nogud olsem bigfala pijin ya ostrij.*"],[1,9,"Sik ya we i kasem ol man Sameria i olsem wan bigfala soa long leg blong man, we neva i save kam gud bakegen samtaem. Mo sem samting i kam kasem yumi finis long Juda. Mi luk we ol enemi blong yumi oli stap spolem ples ya blong yumi, kam kasem doa* blong bigfala taon ya Jerusalem, we ol man ples blong mi oli stap long hem.”","Sik ya we i kasem ol man Sameria i olsem wan bigfala soa long leg blong man, we neva i save kam gud bakegen samtaem. Mo sem samting i kam kasem yumi finis long Juda. Mi luk we ol enemi blong yumi oli stap spolem ples ya blong yumi, kam kasem doa* blong bigfala taon ya Jerusalem, we ol man ples blong mi oli stap long hem.”"],[1,10,"Nao long vison* ya, Profet Maeka i gohed, i talem se, “Ol man Juda.* !Yufala i no go talemaot long ol man Filistia long taon ya Gat, we yumi lus long faet! !Yufala i no letem olgeta oli luk we yufala i stap krae! Ol man blong taon ya Betleafra oli stap rol olbaot long asis blong soemaot we tingting blong olgeta i foldaon finis.","Nao long vison* ya, Profet Maeka i gohed, i talem se, “Ol man Juda.* !Yufala i no go talemaot long ol man Filistia long taon ya Gat, we yumi lus long faet! !Yufala i no letem olgeta oli luk we yufala i stap krae! Ol man blong taon ya Betleafra oli stap rol olbaot long asis blong soemaot we tingting blong olgeta i foldaon finis."],[1,11,"Ol man blong taon ya Safiri, naoia oli stap go wok slef* long narafala kantri, we oli neked nomo, mo oli sem tumas. Mo ol man blong taon ya Jahanan oli fraet blong kam afsaed long taon blong olgeta. Mo olgeta blong taon ya Betejel oli stap krae from ol man blong olgeta we oli ded. Yufala i no save go haed long ples blong olgeta.","Ol man blong taon ya Safiri, naoia oli stap go wok slef* long narafala kantri, we oli neked nomo, mo oli sem tumas. Mo ol man blong taon ya Jahanan oli fraet blong kam afsaed long taon blong olgeta. Mo olgeta blong taon ya Betejel oli stap krae from ol man blong olgeta we oli ded. Yufala i no save go haed long ples blong olgeta."],[1,12,"Mo olgeta blong taon ya Marot oli stap harem nogud, oli wantem tumas blong man i kam sevem olgeta. Be bigfala trabol ya, Hae God nomo i tekem i kam, mo i stap klosap finis long doa* blong Jerusalem.*","Mo olgeta blong taon ya Marot oli stap harem nogud, oli wantem tumas blong man i kam sevem olgeta. Be bigfala trabol ya, Hae God nomo i tekem i kam, mo i stap klosap finis long doa* blong Jerusalem.*"],[1,13,"Ol man Lakis. Yufala i mas fasem ol kat blong yufala long ol hos blong yufala, yufala i ronwe. Yufala nao i faswan blong folem rabis fasin blong ol man Isrel,* nao yufala i pulum ol man Jerusalem blong oli mekem sin.","Ol man Lakis. Yufala i mas fasem ol kat blong yufala long ol hos blong yufala, yufala i ronwe. Yufala nao i faswan blong folem rabis fasin blong ol man Isrel,* nao yufala i pulum ol man Jerusalem blong oli mekem sin."],[1,14,"Ol man Juda.* I taem blong yumi evriwan i talem tata long taon ya Moresetgat, from we ol enemi oli stap kam blong holem taon ya. Mo ol man long taon ya Aksib bambae oli no save givhan long ol king blong yumi, nao ol king ya bambae oli harem nogud.","Ol man Juda.* I taem blong yumi evriwan i talem tata long taon ya Moresetgat, from we ol enemi oli stap kam blong holem taon ya. Mo ol man long taon ya Aksib bambae oli no save givhan long ol king blong yumi, nao ol king ya bambae oli harem nogud."],[1,15,"“Ol man Maresa. I no longtaem Hae God bambae i letem ol enemi blong yumi oli kam holem taon ya blong yufala. Nao ol gudgudfala lida blong yumi bambae oli ronwe, oli go haed long ol hol long ston long ples ya Adulam.","“Ol man Maresa. I no longtaem Hae God bambae i letem ol enemi blong yumi oli kam holem taon ya blong yufala. Nao ol gudgudfala lida blong yumi bambae oli ronwe, oli go haed long ol hol long ston long ples ya Adulam."],[1,16,"Ol man Juda. Yufala i mas katem hea blong yufala, blong soemaot we yufala i harem nogud tumas, yufala i stap krae from ol pikinini ya blong yufala, we yufala i lavem olgeta tumas. Yufala i mas katemaot olgeta hea blong yufala, we bambae yufala i bolhed nomo, olsem pijin ya valja,* from we ol enemi blong yumi bambae oli kam tekemaot ol pikinini blong yumi, blong oli go wok slef* long ples blong olgeta.”","Ol man Juda. Yufala i mas katem hea blong yufala, blong soemaot we yufala i harem nogud tumas, yufala i stap krae from ol pikinini ya blong yufala, we yufala i lavem olgeta tumas. Yufala i mas katemaot olgeta hea blong yufala, we bambae yufala i bolhed nomo, olsem pijin ya valja,* from we ol enemi blong yumi bambae oli kam tekemaot ol pikinini blong yumi, blong oli go wok slef* long ples blong olgeta.”"],[2,1,"Nao Profet Maeka i talem se, “!Sore tumas long yufala ya we yufala i no save slip long naet, yufala i stap tingbaot ol rabis plan blong yufala gogo kasem delaet! Long moning, taem yufala i gat janis, be oltaem yufala i stap gohed blong wokem ol plan ya blong yufala.","Nao Profet Maeka i talem se, “!Sore tumas long yufala ya we yufala i no save slip long naet, yufala i stap tingbaot ol rabis plan blong yufala gogo kasem delaet! Long moning, taem yufala i gat janis, be oltaem yufala i stap gohed blong wokem ol plan ya blong yufala."],[2,2,"Taem yufala i wantem graon blong narafala man, yufala i girap, yufala i go tekem isi nomo, mo taem yufala i wantem haos blong narafala man, yufala i girap, yufala i go tekemaot. I no gat man we i naf blong blokem yufala, blong holemtaet graon blong hem, mo haos blong hem, mo ol samting we bambae ol pikinini blong hem oli holem biaen long hem.","Taem yufala i wantem graon blong narafala man, yufala i girap, yufala i go tekem isi nomo, mo taem yufala i wantem haos blong narafala man, yufala i girap, yufala i go tekemaot. I no gat man we i naf blong blokem yufala, blong holemtaet graon blong hem, mo haos blong hem, mo ol samting we bambae ol pikinini blong hem oli holem biaen long hem."],[2,3,"“Nao from samting ya, Hae God i talem se, ‘Mi mi stap mekem plan blong tekem bigfala trabol i kam kasem yufala, mo bambae yufala i no gat rod blong ronwe. Bambae yufala i luk we oltaem nomo, yufala i stap long trabol, nao bambae yufala i no moa save flas, olsem we yufala i stap mekem naoia.","“Nao from samting ya, Hae God i talem se, ‘Mi mi stap mekem plan blong tekem bigfala trabol i kam kasem yufala, mo bambae yufala i no gat rod blong ronwe. Bambae yufala i luk we oltaem nomo, yufala i stap long trabol, nao bambae yufala i no moa save flas, olsem we yufala i stap mekem naoia."],[2,4,"Biaen long taem ya, ol man bambae oli stap jikim yufala from bigfala trabol ya we bambae i kam kasem yufala. Mo bambae oli wokem wan singsing blong talemaot trabol ya we yufala i foldaon long hem. Bambae oli save singsing se, “!Naoia yumi kam nogud olgeta! Olgeta graon blong yumi, Hae God i tekemaot finis i gowe long yumi. Hem i givim long olgeta ya we oli holem yumi blong yumi go wok slef* blong olgeta.”","Biaen long taem ya, ol man bambae oli stap jikim yufala from bigfala trabol ya we bambae i kam kasem yufala. Mo bambae oli wokem wan singsing blong talemaot trabol ya we yufala i foldaon long hem. Bambae oli save singsing se, “!Naoia yumi kam nogud olgeta! Olgeta graon blong yumi, Hae God i tekemaot finis i gowe long yumi. Hem i givim long olgeta ya we oli holem yumi blong yumi go wok slef* blong olgeta.”"],[2,5,"“ ‘Nao from samting ya, long taem ya we bambae mi givimbak ol graon ya, mo ol man blong mi oli stap seraot graon ya bakegen, bambae i no gat man i save stanap long nem blong yufala, blong karem graon blong yufala.’ ”","“ ‘Nao from samting ya, long taem ya we bambae mi givimbak ol graon ya, mo ol man blong mi oli stap seraot graon ya bakegen, bambae i no gat man i save stanap long nem blong yufala, blong karem graon blong yufala.’ ”"],[2,6,"Nao profet i talem se, “Yufala i stap tok strong long mi, yufala i talem se, ‘!Ei! !Yu no stap prij agens long mifala olsem! I nogud yu stap tokbaot ol samting ya oltaem. God i no save mekem mifala i sem.","Nao profet i talem se, “Yufala i stap tok strong long mi, yufala i talem se, ‘!Ei! !Yu no stap prij agens long mifala olsem! I nogud yu stap tokbaot ol samting ya oltaem. God i no save mekem mifala i sem."],[2,7,"!Yumi ol laen* blong Isrel* ya! ?Yu ting se God i save singaot* trabol i kam long yumi? ?Yu ting se tingting blong hem i save finis long yumi? !Fasin blong hem i no olsem! Oltaem hem i stap tok gud long ol man we oli stap folem stret fasin.’ ”","!Yumi ol laen* blong Isrel* ya! ?Yu ting se God i save singaot* trabol i kam long yumi? ?Yu ting se tingting blong hem i save finis long yumi? !Fasin blong hem i no olsem! Oltaem hem i stap tok gud long ol man we oli stap folem stret fasin.’ ”"],[2,8,"Be profet i talemaot we Hae God i tok agens long olgeta, i talem se, “!Olgeta! Oltaem yufala i girap, yufala i stap faet agens long ol man blong mi, olsem we oli enemi blong yufala. Taem olgeta oli kambak long faet, we oli ting se bambae i no moa gat wan samting i save spolem olgeta, be yufala i girap, yufala i go tekemaot ol klos ya we oli stap werem, yufala i karem i blong yufala.","Be profet i talemaot we Hae God i tok agens long olgeta, i talem se, “!Olgeta! Oltaem yufala i girap, yufala i stap faet agens long ol man blong mi, olsem we oli enemi blong yufala. Taem olgeta oli kambak long faet, we oli ting se bambae i no moa gat wan samting i save spolem olgeta, be yufala i girap, yufala i go tekemaot ol klos ya we oli stap werem, yufala i karem i blong yufala."],[2,9,"Ol woman blong ol man blong mi oli laekem ol haos blong olgeta tumas, be yufala i girap, yufala i go ronemaot olgeta i gowe. Mo i gat promes blong mi i stap long ol pikinini blong olgeta, se bambae mi blesem olgeta, be oltaem, yufala i stap blokem olgeta, blong oli no save kasem.","Ol woman blong ol man blong mi oli laekem ol haos blong olgeta tumas, be yufala i girap, yufala i go ronemaot olgeta i gowe. Mo i gat promes blong mi i stap long ol pikinini blong olgeta, se bambae mi blesem olgeta, be oltaem, yufala i stap blokem olgeta, blong oli no save kasem."],[2,10,"Naoia i no moa gat ples blong haed blong yufala long ples ya. !Yufala i girap! !Yufala i gowe! Ol enemi blong yufala bambae oli kam spolemgud olgeta ples ya, from ol sin ya blong yufala.","Naoia i no moa gat ples blong haed blong yufala long ples ya. !Yufala i girap! !Yufala i gowe! Ol enemi blong yufala bambae oli kam spolemgud olgeta ples ya, from ol sin ya blong yufala."],[2,11,"“Yufala i wantem tumas blong lesin long man we tok blong hem i blong giaman nomo, i blong trikim man. Man we i stap talem se, ‘Tru mi talem long yufala, bambae i no longtaem, ples blong yumi i fulap gud long waen, mo ol narafala dring olsem,’ hemia nao prija we yufala i glad long hem.”","“Yufala i wantem tumas blong lesin long man we tok blong hem i blong giaman nomo, i blong trikim man. Man we i stap talem se, ‘Tru mi talem long yufala, bambae i no longtaem, ples blong yumi i fulap gud long waen, mo ol narafala dring olsem,’ hemia nao prija we yufala i glad long hem.”"],[2,12,"Nao profet i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* I gat taem i stap kam, we mi bambae mi kam lukaot olgeta ya we oli kamaot biaen long yufala we i no ded long ol trabol ya. Nao bambae mi tekem olgeta evriwan oli kam wanples bakegen. Bambae mi mekem olsem man blong lukaot long sipsip, we i tekem ol sipsip blong hem oli kambak long fenis blong olgeta. Bambae ples blong yufala i stap fulap bakegen long man, olsem ples blong gudfala gras, we oltaem i gat fulap sipsip i stap long hem.”","Nao profet i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* I gat taem i stap kam, we mi bambae mi kam lukaot olgeta ya we oli kamaot biaen long yufala we i no ded long ol trabol ya. Nao bambae mi tekem olgeta evriwan oli kam wanples bakegen. Bambae mi mekem olsem man blong lukaot long sipsip, we i tekem ol sipsip blong hem oli kambak long fenis blong olgeta. Bambae ples blong yufala i stap fulap bakegen long man, olsem ples blong gudfala gras, we oltaem i gat fulap sipsip i stap long hem.”"],[2,13,"Nao profet i talem se, “Long taem ya, God bambae i openem rod blong ol man blong hem, we bambae i tekemaot olgeta long kantri ya longwe we bambae oli stap wok slef* long hem, i lidim olgeta i kam. Bambae oli kamaot long ol taon ya longwe, nao bambae oli fri. Hae God nomo bambae i king blong olgeta, mo hem bambae i stap lidim olgeta oli aot long ples ya, oli kam.”","Nao profet i talem se, “Long taem ya, God bambae i openem rod blong ol man blong hem, we bambae i tekemaot olgeta long kantri ya longwe we bambae oli stap wok slef* long hem, i lidim olgeta i kam. Bambae oli kamaot long ol taon ya longwe, nao bambae oli fri. Hae God nomo bambae i king blong olgeta, mo hem bambae i stap lidim olgeta oli aot long ples ya, oli kam.”"],[3,1,"Nao Profet Maeka i tok long ol lida blong ol laen* blong Isrel,* i talem se, “Olgeta. Yufala i lesin long tok blong mi. Yufala i lida blong ol man ya blong mi. Mo wok blong yufala i blong jajem olgeta long stret fasin.","Nao Profet Maeka i tok long ol lida blong ol laen* blong Isrel,* i talem se, “Olgeta. Yufala i lesin long tok blong mi. Yufala i lida blong ol man ya blong mi. Mo wok blong yufala i blong jajem olgeta long stret fasin."],[3,2,"Be yufala i girap, yufala i tanem baksaed long stret fasin, yufala i agens long hem, nao yufala i wantem mekem ol rabis fasin nomo. Taem yufala i jajem ol man, i olsem we yufala i stap tekemaot skin blong olgeta we oli laef yet, nao yufala i stap terem mit blong olgeta i kamaot long bun blong olgeta.","Be yufala i girap, yufala i tanem baksaed long stret fasin, yufala i agens long hem, nao yufala i wantem mekem ol rabis fasin nomo. Taem yufala i jajem ol man, i olsem we yufala i stap tekemaot skin blong olgeta we oli laef yet, nao yufala i stap terem mit blong olgeta i kamaot long bun blong olgeta."],[3,3,"Yufala i stap kakae olgeta. Yufala i stap teremaot skin blong olgeta, yufala i stap brekem bun blong olgeta, mo yufala i stap katkatem olgeta long ol smosmol pis, olsem we man i stap katkatem mit blong putum i go long sospen.","Yufala i stap kakae olgeta. Yufala i stap teremaot skin blong olgeta, yufala i stap brekem bun blong olgeta, mo yufala i stap katkatem olgeta long ol smosmol pis, olsem we man i stap katkatem mit blong putum i go long sospen."],[3,4,"I gat taem i stap kam we bambae yufala i krae i go long Hae God blong i givhan long yufala, be bambae hem i no save ansa long yufala. Bambae hem i no save harem prea blong yufala, from we yufala i stap mekem ol fasin ya we i no stret.","I gat taem i stap kam we bambae yufala i krae i go long Hae God blong i givhan long yufala, be bambae hem i no save ansa long yufala. Bambae hem i no save harem prea blong yufala, from we yufala i stap mekem ol fasin ya we i no stret."],[3,5,"“Ol profet. Yufala i stap giaman long ol man blong yumi, yufala i stap pulum olgeta oli go krangke. Taem man i pem yufala, yufala i promes se bambae hem i gat pis, be taem man i no pem yufala, yufala i talem se bambae i no longtaem, faet i kam. Nao from samting ya, Hae God i talem long yufala se,","“Ol profet. Yufala i stap giaman long ol man blong yumi, yufala i stap pulum olgeta oli go krangke. Taem man i pem yufala, yufala i promes se bambae hem i gat pis, be taem man i no pem yufala, yufala i talem se bambae i no longtaem, faet i kam. Nao from samting ya, Hae God i talem long yufala se,"],[3,6,"‘Ol profet. Naoia klosap wok ya blong yufala i finis. Bambae yufala i no moa save luk vison* bakegen, mo bambae yufala i no moa save talemaot ol samting we bambae i hapen long fiuja, from we yufala i stap lidim ol man blong mi oli gorong.","‘Ol profet. Naoia klosap wok ya blong yufala i finis. Bambae yufala i no moa save luk vison* bakegen, mo bambae yufala i no moa save talemaot ol samting we bambae i hapen long fiuja, from we yufala i stap lidim ol man blong mi oli gorong."],[3,7,"Mo sipos ol man oli luk we ol samting ya we yufala i stap talemaot oli no kamtru, bambae yufala i sem bigwan. Taem yufala i luk we mi mi no save ansa long yufala, bambae yufala i harem nogud tumas.’ ”","Mo sipos ol man oli luk we ol samting ya we yufala i stap talemaot oli no kamtru, bambae yufala i sem bigwan. Taem yufala i luk we mi mi no save ansa long yufala, bambae yufala i harem nogud tumas.’ ”"],[3,8,"Mo profet i talem se, “Be mi, oltaem Hae God i stap givim paoa long mi. Oltaem, hem i stap mekem Spirit blong hem i kam bigwan long mi, i holem mi, mo i stap mekem mi mi savegud ol stret fasin blong jajem man. Mo hem i stap mekem tingting blong mi i strong blong mi save talemaot ol sin blong ol man ya blong hem, stret long fes blong olgeta.","Mo profet i talem se, “Be mi, oltaem Hae God i stap givim paoa long mi. Oltaem, hem i stap mekem Spirit blong hem i kam bigwan long mi, i holem mi, mo i stap mekem mi mi savegud ol stret fasin blong jajem man. Mo hem i stap mekem tingting blong mi i strong blong mi save talemaot ol sin blong ol man ya blong hem, stret long fes blong olgeta."],[3,9,"“Ol lida blong ol laen blong Isrel. Yufala i mas lesin long mi. Yufala i stap tanem baksaed long stret fasin blong jajem man. Yufala i stap tanem ol stret fasin i kam rabis fasin nomo.","“Ol lida blong ol laen blong Isrel. Yufala i mas lesin long mi. Yufala i stap tanem baksaed long stret fasin blong jajem man. Yufala i stap tanem ol stret fasin i kam rabis fasin nomo."],[3,10,"Bigfala taon ya Jerusalem,* hem i taon blong Hae God, be yufala i stap tekem mane long fasin blong kilim man i ded, mo long rabis fasin blong jajem man, nao yufala i stap yusum ol mane ya blong bildimap taon ya.","Bigfala taon ya Jerusalem,* hem i taon blong Hae God, be yufala i stap tekem mane long fasin blong kilim man i ded, mo long rabis fasin blong jajem man, nao yufala i stap yusum ol mane ya blong bildimap taon ya."],[3,11,"Ol jaj long taon ya, oltaem oli stap letem ol man oli pem olgeta blong oli folem tingting blong olgeta, blong oli jajem man long fasin we i no stret. Mo ol pris* tu, oli save talemaot mining blong ol loa blong God, long ol man nomo we oli save pem olgeta from. Mo ol profet tu, oli stap talemaot mining blong ol vison, be blong kasem mane nomo. Be oltaem, olgeta ya oli stap ting se Hae God bambae i lukaot long olgeta. Oltaem oli stap talem se, ‘Hae God i stap wetem yumi ya. Trabol i no save kasem yumi.’","Ol jaj long taon ya, oltaem oli stap letem ol man oli pem olgeta blong oli folem tingting blong olgeta, blong oli jajem man long fasin we i no stret. Mo ol pris* tu, oli save talemaot mining blong ol loa blong God, long ol man nomo we oli save pem olgeta from. Mo ol profet tu, oli stap talemaot mining blong ol vison, be blong kasem mane nomo. Be oltaem, olgeta ya oli stap ting se Hae God bambae i lukaot long olgeta. Oltaem oli stap talem se, ‘Hae God i stap wetem yumi ya. Trabol i no save kasem yumi.’"],[3,12,"“Nao from ol rabis fasin ya blong yufala, Hae God bambae i tekem ol enemi blong yumi oli kam spolemgud bigfala taon ya Jerusalem, we bambae oli mekem i kam bigfala hip blong ol ston blong ol haos we oli brobrok. Olgeta ya bambae oli brebrekem graon long tabu hil* ya Saeon* we haos* blong Hae God i stap long hem, oli mekem i kam olsem ples blong garen nomo, nao bambae bigfala bus i kam kavremap hil ya.”","“Nao from ol rabis fasin ya blong yufala, Hae God bambae i tekem ol enemi blong yumi oli kam spolemgud bigfala taon ya Jerusalem, we bambae oli mekem i kam bigfala hip blong ol ston blong ol haos we oli brobrok. Olgeta ya bambae oli brebrekem graon long tabu hil* ya Saeon* we haos* blong Hae God i stap long hem, oli mekem i kam olsem ples blong garen nomo, nao bambae bigfala bus i kam kavremap hil ya.”"],[4,1,"Nao Profet Maeka i talem se, “Olgeta. I gat taem i stap kam we hil* ya we haos* blong Hae God i stap long hem bambae i kam hae moa, i winim ol narafala hil. Mo ol man blong plante ples long wol bambae oli save wokbaot blong kam long hem.","Nao Profet Maeka i talem se, “Olgeta. I gat taem i stap kam we hil* ya we haos* blong Hae God i stap long hem bambae i kam hae moa, i winim ol narafala hil. Mo ol man blong plante ples long wol bambae oli save wokbaot blong kam long hem."],[4,2,"Olgeta ya bambae oli kam, oli talem se, ‘Hae God i God blong Jekob.* Yufala i kam. Yumi go antap long hil ya blong hem. Yumi go mekem wosip long haos blong hem. Hem bambae i tijim yumi long ol fasin we hem i wantem blong yumi folem, nao bambae yumi save folem ol rod we hem i jusumaot, from we oltaem, tok blong hem i stap kamaot // long taon ya Jerusalem,* mo oltaem, long hil ya Saeon,* hem i stap tijim ol man blong hem // long ol loa blong hem.’","Olgeta ya bambae oli kam, oli talem se, ‘Hae God i God blong Jekob.* Yufala i kam. Yumi go antap long hil ya blong hem. Yumi go mekem wosip long haos blong hem. Hem bambae i tijim yumi long ol fasin we hem i wantem blong yumi folem, nao bambae yumi save folem ol rod we hem i jusumaot, from we oltaem, tok blong hem i stap kamaot // long taon ya Jerusalem,* mo oltaem, long hil ya Saeon,* hem i stap tijim ol man blong hem // long ol loa blong hem.’"],[4,3,"“Hem bambae i jajem ol trabol blong ol man blong plante ples, mo bambae i stretem ol rao blong ol kantri we oli gat paoa, nating we oli stap klosap no longwe. Long taem ya, ol man bambae oli hamarem ol naef blong faet blong olgeta, gogo oli kam aean blong digim graon. Mo ol spia blong olgeta, bambae oli wokem olgeta oli kam huknaef blong katem gru blong ol grep* blong olgeta. Nao olbaot long wol, ol man bambae oli no moa save girap blong go kilim ol narafala man, neva bambae oli save mekemrere bakegen blong go mekem faet.","“Hem bambae i jajem ol trabol blong ol man blong plante ples, mo bambae i stretem ol rao blong ol kantri we oli gat paoa, nating we oli stap klosap no longwe. Long taem ya, ol man bambae oli hamarem ol naef blong faet blong olgeta, gogo oli kam aean blong digim graon. Mo ol spia blong olgeta, bambae oli wokem olgeta oli kam huknaef blong katem gru blong ol grep* blong olgeta. Nao olbaot long wol, ol man bambae oli no moa save girap blong go kilim ol narafala man, neva bambae oli save mekemrere bakegen blong go mekem faet."],[4,4,"Olgeta man bambae oli stap gud, mo oli gat pis olwe. Bambae oli save stap gud long ol plantesen blong grep blong olgeta, mo oli save sidaon aninit long ol figtri* blong olgeta. Bambae i no moa gat man blong mekem olgeta oli fraet. Hae God i gat olgeta paoa, mo hemia tok blong hem.”","Olgeta man bambae oli stap gud, mo oli gat pis olwe. Bambae oli save stap gud long ol plantesen blong grep blong olgeta, mo oli save sidaon aninit long ol figtri* blong olgeta. Bambae i no moa gat man blong mekem olgeta oli fraet. Hae God i gat olgeta paoa, mo hemia tok blong hem.”"],[4,5,"“Nating we olgeta man long wol ya oli stap mekem wosip long ol god blong olgeta, mo oli stap obei long olgeta, be yumi ya, Hae God i God blong yumi, mo bambae yumi stap mekem wosip long hem, mo yumi stap obei long hem oltaem nomo, gogo i no save finis.”","“Nating we olgeta man long wol ya oli stap mekem wosip long ol god blong olgeta, mo oli stap obei long olgeta, be yumi ya, Hae God i God blong yumi, mo bambae yumi stap mekem wosip long hem, mo yumi stap obei long hem oltaem nomo, gogo i no save finis.”"],[4,6,"Nao Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Bambae mi mi panisim yufala. Bambae yufala i aot long ples ya, yufala i go stap long wan narafala kantri longwe, yufala i stap wok slef,* we bambae yufala i stap harem nogud tumas from. Bambae yufala i no gat paoa nating, olsem man we haf bodi blong hem i ded finis. Be i gat taem i stap kam, we bambae mi tekem olgeta we i stap kamaot biaen long smol haf blong yufala we bambae oli stap, oli kam wanples bakegen. Bambae mi givim niufala laef long olgeta. Bambae mi mekem olgeta oli kam plante bakegen, we bambae oli kam wan kantri we i gat paoa. Olgeta ya bambae oli stap long hil ya Saeon,* mo mi bambae mi king blong olgeta olwe, gogo i no save finis.","Nao Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Bambae mi mi panisim yufala. Bambae yufala i aot long ples ya, yufala i go stap long wan narafala kantri longwe, yufala i stap wok slef,* we bambae yufala i stap harem nogud tumas from. Bambae yufala i no gat paoa nating, olsem man we haf bodi blong hem i ded finis. Be i gat taem i stap kam, we bambae mi tekem olgeta we i stap kamaot biaen long smol haf blong yufala we bambae oli stap, oli kam wanples bakegen. Bambae mi givim niufala laef long olgeta. Bambae mi mekem olgeta oli kam plante bakegen, we bambae oli kam wan kantri we i gat paoa. Olgeta ya bambae oli stap long hil ya Saeon,* mo mi bambae mi king blong olgeta olwe, gogo i no save finis.",7],[4,8,"“Jerusalem.* Yu yu olsem wajhaos* blong mi, we mi mi stap long yu blong lukaot gud long ol sipsip blong mi. Bambae king blong yu i kambak, i stap long yu bakegen, nao bambae i stap rul long olgeta ples, olsem we i stap mekem fastaem.","“Jerusalem.* Yu yu olsem wajhaos* blong mi, we mi mi stap long yu blong lukaot gud long ol sipsip blong mi. Bambae king blong yu i kambak, i stap long yu bakegen, nao bambae i stap rul long olgeta ples, olsem we i stap mekem fastaem."],[4,9,"“Ol man Jerusalem. ?Yufala i stap krae tumas olsem from wanem? ?Yufala i stap harem nogud tumas olsem woman we i bonem pikinini, be from wanem? ?Yufala i harem nogud from we yufala i no moa gat king blong yufala, mo ol haeman blong yufala oli ded evriwan finis?","“Ol man Jerusalem. ?Yufala i stap krae tumas olsem from wanem? ?Yufala i stap harem nogud tumas olsem woman we i bonem pikinini, be from wanem? ?Yufala i harem nogud from we yufala i no moa gat king blong yufala, mo ol haeman blong yufala oli ded evriwan finis?"],[4,10,"Olgeta. I stret nomo blong yufala i harem nogud, yufala i stap tantanem yufala, mo yufala i stap singaot bigwan olsem woman we i bonem pikinini. Bambae i no longtaem, ol enemi oli fosem yufala blong yufala i aot long taon ya blong yufala, nao yufala i go stap long open ples nomo. Bambae oli tekem yufala i go long Babilonia, be biaen, mi bambae mi sevem olgeta we oli kamaot biaen long yufala, mi tekemaot olgeta long han blong ol enemi ya blong yufala, oli kambak.”","Olgeta. I stret nomo blong yufala i harem nogud, yufala i stap tantanem yufala, mo yufala i stap singaot bigwan olsem woman we i bonem pikinini. Bambae i no longtaem, ol enemi oli fosem yufala blong yufala i aot long taon ya blong yufala, nao yufala i go stap long open ples nomo. Bambae oli tekem yufala i go long Babilonia, be biaen, mi bambae mi sevem olgeta we oli kamaot biaen long yufala, mi tekemaot olgeta long han blong ol enemi ya blong yufala, oli kambak.”"],[4,11,"Mo bakegen, Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Naoia, ol man blong plante kantri oli kam hivap finis blong mekem faet agens long yufala. Oli stap taltalem se, ‘!Yumi mas spolem taon ya Jerusalem*! !Yumi mas mekem taon ya i kam nogud olgeta!’","Mo bakegen, Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Naoia, ol man blong plante kantri oli kam hivap finis blong mekem faet agens long yufala. Oli stap taltalem se, ‘!Yumi mas spolem taon ya Jerusalem*! !Yumi mas mekem taon ya i kam nogud olgeta!’"],[4,12,"Olgeta ya oli stap tok olsem, be oli no save nating tingting blong mi. Oli no save we mi mi tekem olgeta i kam wanples long ples ya, blong mi panisim olgeta, mi flatemgud olgeta, olsem we man i tekem ol hed blong wit* i kam wanples blong buluk i stap purumpurumbut long hem blong tekemaot ol kakae blong hem.","Olgeta ya oli stap tok olsem, be oli no save nating tingting blong mi. Oli no save we mi mi tekem olgeta i kam wanples long ples ya, blong mi panisim olgeta, mi flatemgud olgeta, olsem we man i tekem ol hed blong wit* i kam wanples blong buluk i stap purumpurumbut long hem blong tekemaot ol kakae blong hem."],[4,13,"!Yufala i girap! !Yufala i go givim panis long olgeta! Mi bambae mi mekem yufala i gat paoa. Bambae yufala i strong olsem bul we hon blong hem, aean, mo leg blong hem daon, bras. Bambae yufala i flatemgud ol man blong plante kantri. Nao ol samting we olgeta ya oli bin winim long taem blong faet, bambae yufala i save givim i kam long mi, we mi mi Hae God, mi Masta* blong olgeta man long wol.”","!Yufala i girap! !Yufala i go givim panis long olgeta! Mi bambae mi mekem yufala i gat paoa. Bambae yufala i strong olsem bul we hon blong hem, aean, mo leg blong hem daon, bras. Bambae yufala i flatemgud ol man blong plante kantri. Nao ol samting we olgeta ya oli bin winim long taem blong faet, bambae yufala i save givim i kam long mi, we mi mi Hae God, mi Masta* blong olgeta man long wol.”"],[5,1,"Nao profet i talem se, “!Ol man Jerusalem! !Yumi mas tekem ol soldia blong yumi i kam wanples! !Naoia ol enemi blong yumi oli raonem yumi finis! !Oli stap mekem i nogud long king blong yumi, blong mekem hem i sem!”","Nao profet i talem se, “!Ol man Jerusalem! !Yumi mas tekem ol soldia blong yumi i kam wanples! !Naoia ol enemi blong yumi oli raonem yumi finis! !Oli stap mekem i nogud long king blong yumi, blong mekem hem i sem!”"],[5,2,"Nao Profet Maeka i talemaot we Hae God i talem se, “Yufala long taon ya Betlehem, long distrik ya Efrata long Juda,* taon ya blong yufala i wan smol taon long ol narafala taon we oli stap raonabaot long yufala, be mi bambae mi mekem we wan pikinini* bambae i kamaot long yufala, we hem bambae i rul long ol laen* blong Isrel.* Man ya, stamba blong hem, wan olfala bubu blong yufala bifo.”","Nao Profet Maeka i talemaot we Hae God i talem se, “Yufala long taon ya Betlehem, long distrik ya Efrata long Juda,* taon ya blong yufala i wan smol taon long ol narafala taon we oli stap raonabaot long yufala, be mi bambae mi mekem we wan pikinini* bambae i kamaot long yufala, we hem bambae i rul long ol laen* blong Isrel.* Man ya, stamba blong hem, wan olfala bubu blong yufala bifo.”"],[5,3,"Nao profet i talem se, “Be fastaem, Hae God bambae i letem yumi i go stap long han blong ol enemi blong yumi, gogo kasem taem we woman ya we bambae i bonem pikinini ya, hem i bonem pikinini ya blong hem. Taem pikinini ya i bon, olgeta man ples blong hem we oli go stap wok slef* long narafala kantri, bambae oli kam joen wanples bakegen long ol man ples blong olgeta.","Nao profet i talem se, “Be fastaem, Hae God bambae i letem yumi i go stap long han blong ol enemi blong yumi, gogo kasem taem we woman ya we bambae i bonem pikinini ya, hem i bonem pikinini ya blong hem. Taem pikinini ya i bon, olgeta man ples blong hem we oli go stap wok slef* long narafala kantri, bambae oli kam joen wanples bakegen long ol man ples blong olgeta."],[5,4,"Taem pikinini ya i kamtru, hem bambae i lukaot gud long ol man blong hem. Hem bambae i man blong Hae God, mo bambae hem i rul long olgeta long paoa ya we Hae God bambae i givim long hem, mo bambae hem i karem nem ya King, we i nem blong Hae God nomo. Nao long taem ya, ol man blong hem bambae oli stap gud, from we olgeta man olbaot long wol bambae oli luksave we hem i gat paoa.","Taem pikinini ya i kamtru, hem bambae i lukaot gud long ol man blong hem. Hem bambae i man blong Hae God, mo bambae hem i rul long olgeta long paoa ya we Hae God bambae i givim long hem, mo bambae hem i karem nem ya King, we i nem blong Hae God nomo. Nao long taem ya, ol man blong hem bambae oli stap gud, from we olgeta man olbaot long wol bambae oli luksave we hem i gat paoa."],[5,5,"“Yufala i stap talem se, ‘Sipos ol man Asiria oli kam long ples blong yumi, mo oli stat kam insaed long ol haos blong yumi, bambae yumi save sanem ol nambawan lida blong yumi wetem ol soldia blong olgeta, blong go faet agens long olgeta. Nao ol strong soldia ya blong yumi bambae oli winim ol man Asiria ya, oli kilim olgeta i ded.’ Be sipos ol man Asiria oli kam long ples ya, mo oli stat kam insaed long graon blong yumi, man ya bambae i blokem olgeta, mo hem bambae i mekem we yumi gat pis.”","“Yufala i stap talem se, ‘Sipos ol man Asiria oli kam long ples blong yumi, mo oli stat kam insaed long ol haos blong yumi, bambae yumi save sanem ol nambawan lida blong yumi wetem ol soldia blong olgeta, blong go faet agens long olgeta. Nao ol strong soldia ya blong yumi bambae oli winim ol man Asiria ya, oli kilim olgeta i ded.’ Be sipos ol man Asiria oli kam long ples ya, mo oli stat kam insaed long graon blong yumi, man ya bambae i blokem olgeta, mo hem bambae i mekem we yumi gat pis.”",6],[5,7,"Nao Profet Maeka i gohed i talem se, “Bambae yumi ol laen* blong Isrel,* yumi go wok slef* long ol narafala kantri, be long taem ya ol laen ya blong yumi we bambae oli stap laef yet long ol kantri ya, bambae oli stap givhan gud long ol man raonabaot long olgeta. Bambae oli olsem wota blong naet, no smosmol ren, we Hae God i stap sanem i kam blong mekem kakae i gru gud. Mo ol man ya, oltaem nomo bambae oli stap luk long God blong i givhan long olgeta, oli no save luk long man.","Nao Profet Maeka i gohed i talem se, “Bambae yumi ol laen* blong Isrel,* yumi go wok slef* long ol narafala kantri, be long taem ya ol laen ya blong yumi we bambae oli stap laef yet long ol kantri ya, bambae oli stap givhan gud long ol man raonabaot long olgeta. Bambae oli olsem wota blong naet, no smosmol ren, we Hae God i stap sanem i kam blong mekem kakae i gru gud. Mo ol man ya, oltaem nomo bambae oli stap luk long God blong i givhan long olgeta, oli no save luk long man."],[5,8,"Be bambae olgeta oli stap long medel blong ol man ya olsem laeon tu, we i stap lukaot anamol long bus no sipsip long open ples, blong i kakae. Taem laeon olsem i faenem sipsip, bambae i jam long hem wantaem, i terem long ol smosmol pis, mo i no gat man i save blokem.","Be bambae olgeta oli stap long medel blong ol man ya olsem laeon tu, we i stap lukaot anamol long bus no sipsip long open ples, blong i kakae. Taem laeon olsem i faenem sipsip, bambae i jam long hem wantaem, i terem long ol smosmol pis, mo i no gat man i save blokem."],[5,9,"Long fasin ya nao, bambae olgeta ya oli go mekem faet long ol enemi blong olgeta, we bambae oli winim olgeta, oli spolem olgeta evriwan.”","Long fasin ya nao, bambae olgeta ya oli go mekem faet long ol enemi blong olgeta, we bambae oli winim olgeta, oli spolem olgeta evriwan.”"],[5,10,"Nao profet i talemaot we Hae God i talem se, “Long taem ya, bambae mi mi tekemaot ol hos blong yufala, mo bambae mi spolem ol kat blong faet blong yufala, blong tingting blong yufala i no moa stap long ol samting ya.","Nao profet i talemaot we Hae God i talem se, “Long taem ya, bambae mi mi tekemaot ol hos blong yufala, mo bambae mi spolem ol kat blong faet blong yufala, blong tingting blong yufala i no moa stap long ol samting ya."],[5,11,"Bambae mi spolem ol bigbigfala taon long kantri blong yufala, mo bambae mi brekemdaon ol strong ples blong haed blong yufala.","Bambae mi spolem ol bigbigfala taon long kantri blong yufala, mo bambae mi brekemdaon ol strong ples blong haed blong yufala."],[5,12,"Bambae mi tekemaot ol tabu ston blong yufala we yufala i stap trastem olgeta, mo bambae mi kilim ol kleva ya we oli stap talemaot ol samting we bambae i hapen long fiuja, gogo i no moa gat wan i stap.","Bambae mi tekemaot ol tabu ston blong yufala we yufala i stap trastem olgeta, mo bambae mi kilim ol kleva ya we oli stap talemaot ol samting we bambae i hapen long fiuja, gogo i no moa gat wan i stap."],[5,13,"Ol aedol blong yufala mo ol longlongfala ston ya we yufala i stanemap blong mekem wosip long olgeta, bambae mi spolem olgeta, blong yufala i no moa save mekem wosip long ol samting ya bakegen we yufala nomo i wokem.","Ol aedol blong yufala mo ol longlongfala ston ya we yufala i stanemap blong mekem wosip long olgeta, bambae mi spolem olgeta, blong yufala i no moa save mekem wosip long ol samting ya bakegen we yufala nomo i wokem."],[5,14,"Bambae mi brekemdaon ol pija blong woman god ya Asera* we oli stap olbaot long kantri blong yufala, mo bambae mi spolem ol taon blong yufala.","Bambae mi brekemdaon ol pija blong woman god ya Asera* we oli stap olbaot long kantri blong yufala, mo bambae mi spolem ol taon blong yufala."],[5,15,"Mo bambae mi panisim ol man blong ol kantri raonabaot long yufala, we oli stap mekem mi mi kros tumas from we oli no save obei long mi.”","Mo bambae mi panisim ol man blong ol kantri raonabaot long yufala, we oli stap mekem mi mi kros tumas from we oli no save obei long mi.”"],[6,1,"Nao Profet Maeka i talem se, “Olgeta. Yufala i lesin gud long ol tok we Hae God bambae i talem agens long yufala. “Hae God. Plis yu kam, yu talemaot ol poen blong yu long fes blong ol bigbigfala hil ya, blong oli save harem. Yu tok strong, blong oli save kasem tok blong yu.","Nao Profet Maeka i talem se, “Olgeta. Yufala i lesin gud long ol tok we Hae God bambae i talem agens long yufala. “Hae God. Plis yu kam, yu talemaot ol poen blong yu long fes blong ol bigbigfala hil ya, blong oli save harem. Yu tok strong, blong oli save kasem tok blong yu."],[6,2,"“Ol bigbigfala hil. !Yufala i stamba blong wol ya! !Yufala i stap bifo olgeta! Yufala i lesin gud long ol poen ya we Hae God bambae i talemaot. Mifala ya we i laen* blong Isrel,* mifala i man blong hem, be hem i gat poen agens long mifala, we hem i wantem talemaot.”","“Ol bigbigfala hil. !Yufala i stamba blong wol ya! !Yufala i stap bifo olgeta! Yufala i lesin gud long ol poen ya we Hae God bambae i talemaot. Mifala ya we i laen* blong Isrel,* mifala i man blong hem, be hem i gat poen agens long mifala, we hem i wantem talemaot.”"],[6,3,"Nao profet i talemaot we Hae God i talem se, “Ol man blong mi. ?Tingting blong yufala i nogud from wanem? ?Mi mi putum wanem long yufala we i hevi tumas, we yufala i harem se yufala i no save karem? !I gud yufala i traem talem long mi!","Nao profet i talemaot we Hae God i talem se, “Ol man blong mi. ?Tingting blong yufala i nogud from wanem? ?Mi mi putum wanem long yufala we i hevi tumas, we yufala i harem se yufala i no save karem? !I gud yufala i traem talem long mi!"],[6,4,"Taem ol olfala bubu blong yufala oli stap long Ijip bifo, mi nao mi tekemaot olgeta i kam long ples ya. Olgeta oli stap wok slef* long kantri ya, be mi tekemaot olgeta, mi mekem olgeta oli fri. Moses mo Eron mo Meriam, mi nao mi sanem trifala, blong trifala i lidim olgeta i kam.","Taem ol olfala bubu blong yufala oli stap long Ijip bifo, mi nao mi tekemaot olgeta i kam long ples ya. Olgeta oli stap wok slef* long kantri ya, be mi tekemaot olgeta, mi mekem olgeta oli fri. Moses mo Eron mo Meriam, mi nao mi sanem trifala, blong trifala i lidim olgeta i kam."],[6,5,"Ol man blong mi. Yufala i mas tingbaot ol samting ya we King Balak, king blong ol man Moab bifo i wantem mekem agens long olgeta ya, mo ansa we Balam, we papa blong hem Beo i givim long hem. Mo yufala i mas tingbaot ol samting ya we i hapen long rod, long taem ya we olgeta oli aot long ples ya Sitim we oli stap long hem, oli kam stap long ples ya Gilgal. I gud yufala i tingting gud long ol samting ya bakegen, nao bambae yufala i save ol samting ya we mi mekem long taem ya blong sevem olgeta.”","Ol man blong mi. Yufala i mas tingbaot ol samting ya we King Balak, king blong ol man Moab bifo i wantem mekem agens long olgeta ya, mo ansa we Balam, we papa blong hem Beo i givim long hem. Mo yufala i mas tingbaot ol samting ya we i hapen long rod, long taem ya we olgeta oli aot long ples ya Sitim we oli stap long hem, oli kam stap long ples ya Gilgal. I gud yufala i tingting gud long ol samting ya bakegen, nao bambae yufala i save ol samting ya we mi mekem long taem ya blong sevem olgeta.”"],[6,6,"Nao Profet Maeka i talem se, “?Hae God i God blong heven, mo sipos mi mi go blong mekem wosip long hem, bambae mi karem wanem samting blong mekem sakrefaes long hem? ?Bambae mi tekem ol yang buluk we i nambawan, blong bonem blong givim long hem?","Nao Profet Maeka i talem se, “?Hae God i God blong heven, mo sipos mi mi go blong mekem wosip long hem, bambae mi karem wanem samting blong mekem sakrefaes long hem? ?Bambae mi tekem ol yang buluk we i nambawan, blong bonem blong givim long hem?"],[6,7,"?No sipos mi givim plante taosen sipsip long hem, bambae hem i save glad? ?No sipos mi stap karem fulap olifoel* i kam long hem, bambae hem i save harem gud? ?No sipos mi kilim fasbon pikinini boe blong mi, mi givim long hem, sakrefaes ya i save pemaot sin blong mi? !Nogat!","?No sipos mi givim plante taosen sipsip long hem, bambae hem i save glad? ?No sipos mi stap karem fulap olifoel* i kam long hem, bambae hem i save harem gud? ?No sipos mi kilim fasbon pikinini boe blong mi, mi givim long hem, sakrefaes ya i save pemaot sin blong mi? !Nogat!"],[6,8,"Ol samting we i gud blong mekem, Hae God i talemaot finis long yumi. Hem i God blong yumi, mo hem i wantem blong yumi stap mekem ol fasin we i stret gud, mo blong yumi stap soemaot we yumi lavem ol man tumas, mo blong yumi stap fren gud wetem hem long evri haf blong laef blong yumi, we tingting blong yumi i stap daon.”","Ol samting we i gud blong mekem, Hae God i talemaot finis long yumi. Hem i God blong yumi, mo hem i wantem blong yumi stap mekem ol fasin we i stret gud, mo blong yumi stap soemaot we yumi lavem ol man tumas, mo blong yumi stap fren gud wetem hem long evri haf blong laef blong yumi, we tingting blong yumi i stap daon.”"],[6,9,"Mo Profet Maeka i gohed i talem se, “Man we i waes i mas fraet long Hae God, i mas ona gud long hem. Naoia, hem i stap singaot long yumi long taon ya se, ‘Yufala evriwan we i stap hivap long taon ya, yufala i lesin gud.","Mo Profet Maeka i gohed i talem se, “Man we i waes i mas fraet long Hae God, i mas ona gud long hem. Naoia, hem i stap singaot long yumi long taon ya se, ‘Yufala evriwan we i stap hivap long taon ya, yufala i lesin gud."],[6,10,"Long ol haos blong ol man nogud, i gat ol gudgudfala samting we oli stap winim long ol fasin we i no stret. Long ol stoa blong olgeta, ol skel mo ol kap blong makem ol samting, oli blong giaman nomo. Fasin ya i nogud we i nogud, mi mi no laekem nating, mi agens long hem.","Long ol haos blong ol man nogud, i gat ol gudgudfala samting we oli stap winim long ol fasin we i no stret. Long ol stoa blong olgeta, ol skel mo ol kap blong makem ol samting, oli blong giaman nomo. Fasin ya i nogud we i nogud, mi mi no laekem nating, mi agens long hem."],[6,11,"Mi mi no save fogivim man we i stap yusum skel we i blong giaman nomo.","Mi mi no save fogivim man we i stap yusum skel we i blong giaman nomo."],[6,12,"Oltaem long ples ya, ol rijman oli stap ravem ol puaman, mo yufala evriwan i man blong giaman. !I no gat man i save trastem yufala!","Oltaem long ples ya, ol rijman oli stap ravem ol puaman, mo yufala evriwan i man blong giaman. !I no gat man i save trastem yufala!"],[6,13,"Mo from we yufala i stap mekem sin olsem, naoia mi mi stat finis blong daonem yufala, blong mekem yufala i kam nogud.","Mo from we yufala i stap mekem sin olsem, naoia mi mi stat finis blong daonem yufala, blong mekem yufala i kam nogud."],[6,14,"Oltaem bambae yufala i kakae, be neva bambae yufala i save harem gud. !Bambae yufala i stap hanggri olwe nomo! Bambae yufala i tekem plante samting long ol narafala man, be ol samting ya bambae oli no save stap longtaem long han blong yufala. Mo ol samting we yufala i ting se yufala i stap holem, bambae mi mi spolem evriwan long taem blong faet.","Oltaem bambae yufala i kakae, be neva bambae yufala i save harem gud. !Bambae yufala i stap hanggri olwe nomo! Bambae yufala i tekem plante samting long ol narafala man, be ol samting ya bambae oli no save stap longtaem long han blong yufala. Mo ol samting we yufala i ting se yufala i stap holem, bambae mi mi spolem evriwan long taem blong faet."],[6,15,"Long yia ya, bambae yufala i planem garen, be bambae yufala i no save karem kakae blong hem i kam. Mo bambae yufala i wokem plante olifoel,* be bambae yufala i no save yusum oel ya. Mo bambae yufala i wokem plante waen, be bambae yufala i no save dring waen ya.","Long yia ya, bambae yufala i planem garen, be bambae yufala i no save karem kakae blong hem i kam. Mo bambae yufala i wokem plante olifoel,* be bambae yufala i no save yusum oel ya. Mo bambae yufala i wokem plante waen, be bambae yufala i no save dring waen ya."],[6,16,"Samting ya bambae i kasem yufala olsem, from we yufala i stap folem ol rabis fasin blong tufala king ya bifo, King Omri mo pikinini blong hem King Ehab. Oltaem, yufala i wantem tumas blong folem ol tingting blong tufala ya, nao from samting ya, bambae mi mi spolem yufala, nao ol man blong olgeta ples long wol bambae oli stap lukluk nogud long yufala, oli stap ting rabis nomo long yufala.”","Samting ya bambae i kasem yufala olsem, from we yufala i stap folem ol rabis fasin blong tufala king ya bifo, King Omri mo pikinini blong hem King Ehab. Oltaem, yufala i wantem tumas blong folem ol tingting blong tufala ya, nao from samting ya, bambae mi mi spolem yufala, nao ol man blong olgeta ples long wol bambae oli stap lukluk nogud long yufala, oli stap ting rabis nomo long yufala.”"],[7,1,"Nao Profet Maeka i talem se, “!Naoia tingting blong mi i foldaon olgeta! Mi mi olsem man we i hanggri tumas, i stap go olbaot blong lukaot frut blong i kakae, be i no moa gat frut long ol figtri,* mo long ol rop blong grep* tu. Ol gudfala fig, mo ol grep, ol man oli tekem evriwan finis.","Nao Profet Maeka i talem se, “!Naoia tingting blong mi i foldaon olgeta! Mi mi olsem man we i hanggri tumas, i stap go olbaot blong lukaot frut blong i kakae, be i no moa gat frut long ol figtri,* mo long ol rop blong grep* tu. Ol gudfala fig, mo ol grep, ol man oli tekem evriwan finis."],[7,2,"Naoia, long kantri ya, i no moa gat man i stap we fasin blong hem i stret, mo we tingting blong hem i stap strong long God. Olgeta evriwan i stap lukaot rod blong kilim man i ded. Ol man oli stap ronem ol man ples blong olgeta bakegen blong kilim olgeta i ded.","Naoia, long kantri ya, i no moa gat man i stap we fasin blong hem i stret, mo we tingting blong hem i stap strong long God. Olgeta evriwan i stap lukaot rod blong kilim man i ded. Ol man oli stap ronem ol man ples blong olgeta bakegen blong kilim olgeta i ded."],[7,3,"Ol man oli waes gud blong mekem ol rabis fasin. Oltaem long kot, ol haeman wetem ol jaj oli stap askem long man blong i pem olgeta, blong oli save haedem rong blong hem. Taem wan man we i gat paoa i wantem wan samting we i no stret, hem i save go talem long olgeta ya, nao wantaem nomo, olgeta oli stap joen wanples blong mekem.","Ol man oli waes gud blong mekem ol rabis fasin. Oltaem long kot, ol haeman wetem ol jaj oli stap askem long man blong i pem olgeta, blong oli save haedem rong blong hem. Taem wan man we i gat paoa i wantem wan samting we i no stret, hem i save go talem long olgeta ya, nao wantaem nomo, olgeta oli stap joen wanples blong mekem."],[7,4,"Nating we sam long olgeta ya, fasin blong olgeta i stret lelebet winim ol narawan, be olgeta tu oli no stret nating long fes blong God, oli olsem rabis gras nomo.” Nao profet i talem long ol man se, “Olgeta. Ol profet ya bifo, we Hae God i sanem olgeta olsem wajman blong wekemap yumi, oli talem finis, se taem blong panis bambae i kam, mo taem ya i kamtru finis. Ol trabol ya we oli tokbaot, oli stap kamtru nao.","Nating we sam long olgeta ya, fasin blong olgeta i stret lelebet winim ol narawan, be olgeta tu oli no stret nating long fes blong God, oli olsem rabis gras nomo.” Nao profet i talem long ol man se, “Olgeta. Ol profet ya bifo, we Hae God i sanem olgeta olsem wajman blong wekemap yumi, oli talem finis, se taem blong panis bambae i kam, mo taem ya i kamtru finis. Ol trabol ya we oli tokbaot, oli stap kamtru nao."],[7,5,"Olgeta we oli stap raonabaot long yufala, be bambae yufala i no bilif long tok blong olgeta, mo ol fren blong yufala, bambae yufala i no trastem olgeta. Yufala i mas lukaot gud long ol tok we yufala i stap talem. Nating we yufala i stap toktok wetem woman blong yufala nomo, be yufala i mas lukaot gud.","Olgeta we oli stap raonabaot long yufala, be bambae yufala i no bilif long tok blong olgeta, mo ol fren blong yufala, bambae yufala i no trastem olgeta. Yufala i mas lukaot gud long ol tok we yufala i stap talem. Nating we yufala i stap toktok wetem woman blong yufala nomo, be yufala i mas lukaot gud."],[7,6,"Long taem ya, ol pikinini bambae oli stap ting rabis long ol papa blong olgeta, mo ol gel bambae oli stap girap agens long ol mama blong olgeta. Ol yang woman bambae oli stap rao long mama blong ol man blong olgeta. Olgeta we oli blong wan haos nomo bambae oli stap enemi long olgeta bakegen.","Long taem ya, ol pikinini bambae oli stap ting rabis long ol papa blong olgeta, mo ol gel bambae oli stap girap agens long ol mama blong olgeta. Ol yang woman bambae oli stap rao long mama blong ol man blong olgeta. Olgeta we oli blong wan haos nomo bambae oli stap enemi long olgeta bakegen."],[7,7,"“Be mi, Hae God i God blong mi, mo oltaem bambae mi putum tingting blong mi i stap strong long hem nomo, from we mi save se hem bambae i harem mi. Bambae mi stap wet long hem, from we hem nao bambae i kam sevem mi.”","“Be mi, Hae God i God blong mi, mo oltaem bambae mi putum tingting blong mi i stap strong long hem nomo, from we mi save se hem bambae i harem mi. Bambae mi stap wet long hem, from we hem nao bambae i kam sevem mi.”"],[7,8,"Nao profet i talem se, “Nating we yumi foldaon finis, be ol enemi blong yumi oli no gat rod nating blong laf long yumi, from we bambae yumi girap bakegen yet. Naoia yumi stap long tudak, be Hae God bambae i givim laet long yumi.","Nao profet i talem se, “Nating we yumi foldaon finis, be ol enemi blong yumi oli no gat rod nating blong laf long yumi, from we bambae yumi girap bakegen yet. Naoia yumi stap long tudak, be Hae God bambae i givim laet long yumi."],[7,9,"Yumi mekem sin agens long hem, yumi mekem hem i kros, nao from samting ya, yumi mas mekem tingting blong yumi i stap daon, blong karem kros ya blong hem gogo hem bambae i faet long saed blong yumi bakegen, mo bambae i stretem ol fasin nogud ya we ol enemi blong yumi oli mekem long yumi. Bambae hem i tekemaot yumi long tudak, yumi kam long delaet bakegen. Bambae yumi stap gogo, yumi luk we hem bambae i sevem yumi.","Yumi mekem sin agens long hem, yumi mekem hem i kros, nao from samting ya, yumi mas mekem tingting blong yumi i stap daon, blong karem kros ya blong hem gogo hem bambae i faet long saed blong yumi bakegen, mo bambae i stretem ol fasin nogud ya we ol enemi blong yumi oli mekem long yumi. Bambae hem i tekemaot yumi long tudak, yumi kam long delaet bakegen. Bambae yumi stap gogo, yumi luk we hem bambae i sevem yumi."],[7,10,"Nao long taem ya, ol enemi blong yumi bambae oli luk samting ya, mo tingting blong olgeta bambae i foldaon, oli sem, from we bifo oli bin jikim yumi, oli talem se, ‘?Wehem Hae God ya we i God blong yufala?’ Bambae yumi luk we hem bambae i winim olgeta, i purumbut long olgeta, olsem we man i wokbaot long sofmad long rod.","Nao long taem ya, ol enemi blong yumi bambae oli luk samting ya, mo tingting blong olgeta bambae i foldaon, oli sem, from we bifo oli bin jikim yumi, oli talem se, ‘?Wehem Hae God ya we i God blong yufala?’ Bambae yumi luk we hem bambae i winim olgeta, i purumbut long olgeta, olsem we man i wokbaot long sofmad long rod."],[7,11,"“Ol man Jerusalem.* I gat taem i stap kam we ol man blong taon ya bambae oli stanemap bigfala stonwol blong taon ya bakegen. Long taem ya, bambae ples blong yufala i kam bigwan moa.","“Ol man Jerusalem.* I gat taem i stap kam we ol man blong taon ya bambae oli stanemap bigfala stonwol blong taon ya bakegen. Long taem ya, bambae ples blong yufala i kam bigwan moa."],[7,12,"Long taem ya, olgeta we bambae oli kamaot biaen long yumi, we bambae oli stap olbaot long ol narafala kantri, bambae oli kambak long taon ya bakegen. Olgeta we oli stap long Asiria long is, wetem olgeta we oli stap long Ijip long saot, mo olgeta we oli stap olbaot klosap long Yufretes Reva, mo olgeta we oli stap long ol narafala ples daon long solwota, mo long ol ples antap long hil, olgeta evriwan bambae oli kambak, oli stap wanples bakegen.","Long taem ya, olgeta we bambae oli kamaot biaen long yumi, we bambae oli stap olbaot long ol narafala kantri, bambae oli kambak long taon ya bakegen. Olgeta we oli stap long Asiria long is, wetem olgeta we oli stap long Ijip long saot, mo olgeta we oli stap olbaot klosap long Yufretes Reva, mo olgeta we oli stap long ol narafala ples daon long solwota, mo long ol ples antap long hil, olgeta evriwan bambae oli kambak, oli stap wanples bakegen."],[7,13,"Be olgeta ples olbaot long wol ya, bambae oli kam draeples, from we ol man blong hem oli stap mekem ol fasin we i nogud.”","Be olgeta ples olbaot long wol ya, bambae oli kam draeples, from we ol man blong hem oli stap mekem ol fasin we i nogud.”"],[7,14,"Nao Profet Maeka i prea, i talem se, “Hae God. Mifala i man blong yu. Mifala i olsem ol sipsip blong yu we yu nomo yu jusumaot mifala. Plis yu lukaot gud long mifala, olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem. Ol sipsip ya blong yu oli stap wanwan olbaot long draeples, be olbaot long ples blong mifala, i gat ol gudfala gras i stap nating. Plis yu letem olgeta oli kam kakae long gudfala graon ya long Basan mo long Gilead, olsem we oli stap kakae long hem bifo.","Nao Profet Maeka i prea, i talem se, “Hae God. Mifala i man blong yu. Mifala i olsem ol sipsip blong yu we yu nomo yu jusumaot mifala. Plis yu lukaot gud long mifala, olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem. Ol sipsip ya blong yu oli stap wanwan olbaot long draeples, be olbaot long ples blong mifala, i gat ol gudfala gras i stap nating. Plis yu letem olgeta oli kam kakae long gudfala graon ya long Basan mo long Gilead, olsem we oli stap kakae long hem bifo."],[7,15,"“Hae God, yu yu God blong mifala. Plis yu kam mekem ol merikel long medel blong mifala bakegen, olsem we yu mekem bifo, long medel blong ol olfala blong mifala, long taem ya we yu tekemaot olgeta long Ijip.","“Hae God, yu yu God blong mifala. Plis yu kam mekem ol merikel long medel blong mifala bakegen, olsem we yu mekem bifo, long medel blong ol olfala blong mifala, long taem ya we yu tekemaot olgeta long Ijip."],[7,16,"Nating we ol man blong ol narafala kantri, oli strong mo oli gat paoa, be taem oli luk ol merikel ya, bambae oli harem nogud. Tingting blong olgeta bambae i foldaon, nao bambae oli satem maot blong olgeta, mo oli blokem sora blong olgeta.","Nating we ol man blong ol narafala kantri, oli strong mo oli gat paoa, be taem oli luk ol merikel ya, bambae oli harem nogud. Tingting blong olgeta bambae i foldaon, nao bambae oli satem maot blong olgeta, mo oli blokem sora blong olgeta."],[7,17,"Bambae oli fraet tumas, oli seksek, nao oli stap kamkamaot long ol strong ples blong haed blong olgeta, we oli stap pulum bel blong olgeta long asis blong graon olsem snek. Mo from we oli fraet tumas, bambae oli tanem tingting blong olgeta blong ona long yu.","Bambae oli fraet tumas, oli seksek, nao oli stap kamkamaot long ol strong ples blong haed blong olgeta, we oli stap pulum bel blong olgeta long asis blong graon olsem snek. Mo from we oli fraet tumas, bambae oli tanem tingting blong olgeta blong ona long yu."],[7,18,"“Hae God. I no gat wan narafala god we i olsem yu. Bambae yu save fogivim olgeta we oli stap kamaot biaen long mifala, yu save tekemaot ol sin blong olgeta. Taem yu yu kros, be kros blong yu i no save stap longtaem. Oltaem yu yu glad blong soemaot long mifala we yu stap lavem mifala tumas.","“Hae God. I no gat wan narafala god we i olsem yu. Bambae yu save fogivim olgeta we oli stap kamaot biaen long mifala, yu save tekemaot ol sin blong olgeta. Taem yu yu kros, be kros blong yu i no save stap longtaem. Oltaem yu yu glad blong soemaot long mifala we yu stap lavem mifala tumas."],[7,19,"Hae God. Mifala i save se yu bambae yu sore bakegen long mifala, yu tekemaot sin blong mifala i gowe long mifala, olsem we yu purumbut long hem i godaon long graon, yu sakem i godaon olgeta long medel solwota.","Hae God. Mifala i save se yu bambae yu sore bakegen long mifala, yu tekemaot sin blong mifala i gowe long mifala, olsem we yu purumbut long hem i godaon long graon, yu sakem i godaon olgeta long medel solwota."],[7,20,"Mifala evriwan i laen* blong Ebraham, mo Jekob,* mo bambae yu yu save soemaot long mifala we yu stap holemstrong ol promes blong yu, mo oltaem yu stap lavem man tumas, olsem we yu promes blong mekem long ol olfala bubu blong mifala bifo.”","Mifala evriwan i laen* blong Ebraham, mo Jekob,* mo bambae yu yu save soemaot long mifala we yu stap holemstrong ol promes blong yu, mo oltaem yu stap lavem man tumas, olsem we yu promes blong mekem long ol olfala bubu blong mifala bifo.”"]],"hbo-wlc":[[1,1,"דְּבַר־יְהוָ֣ה ׀ אֲשֶׁ֣ר הָיָ֗ה אֶל־מִיכָה֙ הַמֹּ֣רַשְׁתִּ֔י בִּימֵ֥י יוֹתָ֛ם אָחָ֥ז יְחִזְקִיָּ֖ה מַלְכֵ֣י יְהוּדָ֑ה אֲשֶׁר־חָזָ֥ה עַל־שֹׁמְר֖וֹן וִירֽוּשָׁלִָֽם׃","dĕ̇bar-yĕhwá֣h ׀ ʼàşě֣r háyá֗h ʼel-miykáh֙ hamò֣̇raşĕ̌ţi̇֔y bi̇ymé֥y ywòţá֛m ʼáẖá֥z yĕẖizĕqiyá֖̇h malĕké֣y yĕhẇdá֑h ʼàşěr-ẖázá֥h ʻal-şò̌mĕr֖wòn wiyrֽẇşá̌liáֽm׃"],[1,2,"שִׁמְעוּ֙ עַמִּ֣ים כֻּלָּ֔ם הַקְשִׁ֖יבִי אֶ֣רֶץ וּמְלֹאָ֑הּ וִיהִי֩ אֲדֹנָ֨י יְהוִ֤ה בָּכֶם֙ לְעֵ֔ד אֲדֹנָ֖י מֵהֵיכַ֥ל קָדְשֽׁוֹ׃","şǐmĕʻẇ֙ ʻami֣̇ym ku̇lá̇֔m haqĕşǐ֖ybiy ʼe֣reẕ ẇmĕlòʼá֑ḣ wiyhiy֩ ʼàdòná֨y yĕhwi֤h bá̇kem֙ lĕʻé֔d ʼàdòná֖y méhéyka֥l qádĕşֽ̌wò׃"],[1,3,"כִּֽי־הִנֵּ֥ה יְהוָ֖ה יֹצֵ֣א מִמְּקוֹמ֑וֹ וְיָרַ֥ד וְדָרַ֖ךְ עַל־במותי אָֽרֶץ׃","kiֽ̇y-hiné֥̇h yĕhwá֖h yòẕé֣ʼ mimĕ̇qwòm֑wò wĕyára֥d wĕdára֖kĕ ʻal-bmwţy ʼáֽreẕ׃"],[1,4,"וְנָמַ֤סּוּ הֶֽהָרִים֙ תַּחְתָּ֔יו וְהָעֲמָקִ֖ים יִתְבַּקָּ֑עוּ כַּדּוֹנַג֙ מִפְּנֵ֣י הָאֵ֔שׁ כְּמַ֖יִם מֻגָּרִ֥ים בְּמוֹרָֽד׃","wĕnáma֤ṡẇ heֽháriym֙ ţȧẖĕţá̇֔yw wĕháʻàmáqi֖ym yiţĕbȧqá֑̇ʻẇ kȧḋwònag֙ mipĕ̇né֣y háʼé֔ş̌ kĕ̇ma֖yim mugá̇ri֥ym bĕ̇mwòráֽd׃"],[1,5,"בְּפֶ֤שַׁע יַֽעֲקֹב֙ כָּל־זֹ֔את וּבְחַטֹּ֖אות בֵּ֣ית יִשְׂרָאֵ֑ל מִֽי־פֶ֣שַׁע יַעֲקֹ֗ב הֲלוֹא֙ שֹֽׁמְר֔וֹן וּמִי֙ בָּמ֣וֹת יְהוּדָ֔ה הֲל֖וֹא יְרוּשָׁלִָֽם׃","bĕ̇pe֤şǎʻ yaֽʻàqòb֙ ká̇l-zò֔ʼţ ẇbĕẖatò֖̇ʼwţ bé֣̇yţ yişĕ̂ráʼé֑l miֽy-pe֣şǎʻ yaʻàqò֗b hàlwòʼ֙ şòֽ̌mĕr֔wòn ẇmiy֙ bá̇m֣wòţ yĕhẇdá֔h hàl֖wòʼ yĕrẇşá̌liáֽm׃"],[1,6,"וְשַׂמְתִּ֥י שֹׁמְר֛וֹן לְעִ֥י הַשָּׂדֶ֖ה לְמַטָּ֣עֵי כָ֑רֶם וְהִגַּרְתִּ֤י לַגַּי֙ אֲבָנֶ֔יהָ וִיסֹדֶ֖יהָ אֲגַלֶּֽה׃","wĕşâmĕţi֥̇y şò̌mĕr֛wòn lĕʻi֥y haşá̇̂de֖h lĕmatá֣̇ʻéy ká֑rem wĕhigȧrĕţi֤̇y lagȧy֙ ʼàbáne֔yhá wiysòde֖yhá ʼàgalėֽh׃"],[1,7,"וְכָל־פְּסִילֶ֣יהָ יֻכַּ֗תּוּ וְכָל־אֶתְנַנֶּ֙יהָ֙ יִשָּׂרְפ֣וּ בָאֵ֔שׁ וְכָל־עֲצַבֶּ֖יהָ אָשִׂ֣ים שְׁמָמָ֑ה כִּ֠י מֵאֶתְנַ֤ן זוֹנָה֙ קִבָּ֔צָה וְעַד־אֶתְנַ֥ן זוֹנָ֖ה יָשֽׁוּבוּ׃","wĕkál-pĕ̇siyle֣yhá yukȧ֗ţ̇ẇ wĕkál-ʼeţĕnanė֙yhá֙ yişá̇̂rĕp֣ẇ báʼé֔ş̌ wĕkál-ʻàẕabė֖yhá ʼáşî֣ym şĕ̌mámá֑h ki̇֠y méʼeţĕna֤n zwònáh֙ qibá̇֔ẕáh wĕʻad-ʼeţĕna֥n zwòná֖h yáşֽ̌ẇbẇ׃"],[1,8,"עַל־זֹאת֙ אֶסְפְּדָ֣ה וְאֵילִ֔ילָה אֵילְכָ֥ה שילל וְעָר֑וֹם אֶעֱשֶׂ֤ה מִסְפֵּד֙ כַּתַּנִּ֔ים וְאֵ֖בֶל כִּבְנ֥וֹת יַעֲנָֽה׃","ʻal-zòʼţ֙ ʼesĕpĕ̇dá֣h wĕʼéyli֔yláh ʼéylĕká֥h şyll wĕʻár֑wòm ʼeʻèşê֤h misĕpé̇d֙ kȧţȧni̇֔ym wĕʼé֖bel ki̇bĕn֥wòţ yaʻànáֽh׃"],[1,9,"כִּ֥י אֲנוּשָׁ֖ה מַכּוֹתֶ֑יהָ כִּי־בָ֙אָה֙ עַד־יְהוּדָ֔ה נָגַ֛ע עַד־שַׁ֥עַר עַמִּ֖י עַד־יְרוּשָׁלִָֽם׃","ki֥̇y ʼànẇşá֖̌h mak̇wòţe֑yhá ki̇y-bá֙ʼáh֙ ʻad-yĕhẇdá֔h nága֛ʻ ʻad-şǎ֥ʻar ʻami֖̇y ʻad-yĕrẇşá̌liáֽm׃"],[1,10,"בְּגַת֙ אַל־תַּגִּ֔ידוּ בָּכ֖וֹ אַל־תִּבְכּ֑וּ בְּבֵ֣ית לְעַפְרָ֔ה עָפָ֖ר התפלשתי׃","bĕ̇gaţ֙ ʼal-ţȧgi̇֔ydẇ bá̇k֖wò ʼal-ţi̇bĕk֑̇ẇ bĕ̇bé֣yţ lĕʻapĕrá֔h ʻápá֖r hţplşţy׃"],[1,11,"עִבְרִ֥י לָכֶ֛ם יוֹשֶׁ֥בֶת שָׁפִ֖יר עֶרְיָה־בֹ֑שֶׁת לֹ֤א יָֽצְאָה֙ יוֹשֶׁ֣בֶת צַֽאֲנָ֔ן מִסְפַּד֙ בֵּ֣ית הָאֵ֔צֶל יִקַּ֥ח מִכֶּ֖ם עֶמְדָּתֽוֹ׃","ʻibĕri֥y láke֛m ywòşě֥beţ şá̌pi֖yr ʻerĕyáh-bò֑şěţ lò֤ʼ yáֽẕĕʼáh֙ ywòşě֣beţ ẕaֽʼàná֔n misĕpȧd֙ bé֣̇yţ háʼé֔ẕel yiqȧ֥ẖ mikė֖m ʻemĕdá̇ţֽwò׃"],[1,12,"כִּֽי־חָ֥לָֽה לְט֖וֹב יוֹשֶׁ֣בֶת מָר֑וֹת כִּֽי־יָ֤רַד רָע֙ מֵאֵ֣ת יְהוָ֔ה לְשַׁ֖עַר יְרוּשָׁלִָֽם׃","kiֽ̇y-ẖá֥láֽh lĕt֖wòb ywòşě֣beţ már֑wòţ kiֽ̇y-yá֤rad ráʻ֙ méʼé֣ţ yĕhwá֔h lĕşǎ֖ʻar yĕrẇşá̌liáֽm׃"],[1,13,"רְתֹ֧ם הַמֶּרְכָּבָ֛ה לָרֶ֖כֶשׁ יוֹשֶׁ֣בֶת לָכִ֑ישׁ רֵאשִׁ֨ית חַטָּ֥את הִיא֙ לְבַת־צִיּ֔וֹן כִּי־בָ֥ךְ נִמְצְא֖וּ פִּשְׁעֵ֥י יִשְׂרָאֵֽל׃","rĕţò֧m hamėrĕká̇bá֛h láre֖keş̌ ywòşě֣beţ láki֑yş̌ réʼşǐ֨yţ ẖatá֥̇ʼţ hiyʼ֙ lĕbaţ-ẕiẏ֔wòn ki̇y-bá֥kĕ nimĕẕĕʼ֖ẇ pi̇şĕ̌ʻé֥y yişĕ̂ráʼéֽl׃"],[1,14,"לָכֵן֙ תִּתְּנִ֣י שִׁלּוּחִ֔ים עַ֖ל מוֹרֶ֣שֶׁת גַּ֑ת בָּתֵּ֤י אַכְזִיב֙ לְאַכְזָ֔ב לְמַלְכֵ֖י יִשְׂרָאֵֽל׃","lákén֙ ţi̇ţĕ̇ni֣y şǐl̇ẇẖi֔ym ʻa֖l mwòre֣şěţ gȧ֑ţ bá̇ţé֤̇y ʼakĕziyb֙ lĕʼakĕzá֔b lĕmalĕké֖y yişĕ̂ráʼéֽl׃"],[1,15,"עֹ֗ד הַיֹּרֵשׁ֙ אָ֣בִי לָ֔ךְ יוֹשֶׁ֖בֶת מָֽרֵשָׁ֑ה עַד־עֲדֻּלָּ֥ם יָב֖וֹא כְּב֥וֹד יִשְׂרָאֵֽל׃","ʻò֗d hayò̇réş̌֙ ʼá֣biy lá֔kĕ ywòşě֖beţ máֽréşá֑̌h ʻad-ʻàdu̇lá֥̇m yáb֖wòʼ kĕ̇b֥wòd yişĕ̂ráʼéֽl׃"],[1,16,"קָרְחִ֣י וָגֹ֔זִּי עַל־בְּנֵ֖י תַּעֲנוּגָ֑יִךְ הַרְחִ֤בִי קָרְחָתֵךְ֙ כַּנֶּ֔שֶׁר כִּ֥י גָל֖וּ מִמֵּֽךְ׃ ס","qárĕẖi֣y wágò֔zi̇y ʻal-bĕ̇né֖y ţȧʻànẇgá֑yikĕ harĕẖi֤biy qárĕẖáţékĕ֙ kȧnė֔şěr ki֥̇y gál֖ẇ miméֽ̇kĕ׃ s"],[2,1,"ה֧וֹי חֹֽשְׁבֵי־אָ֛וֶן וּפֹ֥עֲלֵי רָ֖ע עַל־מִשְׁכְּבוֹתָ֑ם בְּא֤וֹר הַבֹּ֙קֶר֙ יַעֲשׂ֔וּהָ כִּ֥י יֶשׁ־לְאֵ֖ל יָדָֽם׃","h֧wòy ẖòֽşĕ̌béy-ʼá֛wen ẇpò֥ʻàléy rá֖ʻ ʻal-mişĕ̌kĕ̇bwòţá֑m bĕ̇ʼ֤wòr habò̇֙qer֙ yaʻàş̂֔ẇhá ki֥̇y yeş̌-lĕʼé֖l yádáֽm׃"],[2,2,"וְחָמְד֤וּ שָׂדוֹת֙ וְגָזָ֔לוּ וּבָתִּ֖ים וְנָשָׂ֑אוּ וְעָֽשְׁקוּ֙ גֶּ֣בֶר וּבֵית֔וֹ וְאִ֖ישׁ וְנַחֲלָתֽוֹ׃ פ","wĕẖámĕd֤ẇ şá̂dwòţ֙ wĕgázá֔lẇ ẇbáţi֖̇ym wĕnáşá֑̂ʼẇ wĕʻáֽşĕ̌qẇ֙ gė֣ber ẇbéyţ֔wò wĕʼi֖yş̌ wĕnaẖàláţֽwò׃ p"],[2,3,"לָכֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְנִ֥י חֹשֵׁ֛ב עַל־הַמִּשְׁפָּחָ֥ה הַזֹּ֖את רָעָ֑ה אֲ֠שֶׁר לֹֽא־תָמִ֨ישׁוּ מִשָּׁ֜ם צַוְּארֹֽתֵיכֶ֗ם וְלֹ֤א תֵֽלְכוּ֙ רוֹמָ֔ה כִּ֛י עֵ֥ת רָעָ֖ה הִֽיא׃","láké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕni֥y ẖòşé֛̌b ʻal-hami̇şĕ̌pá̇ẖá֥h hazò֖̇ʼţ ráʻá֑h ʼà֠şěr lòֽʼ-ţámi֨yş̌ẇ mişá̇̌֜m ẕawĕ̇ʼròֽţéyke֗m wĕlò֤ʼ ţéֽlĕkẇ֙ rwòmá֔h ki֛̇y ʻé֥ţ ráʻá֖h hiֽyʼ׃"],[2,4,"בַּיּ֨וֹם הַה֜וּא יִשָּׂ֧א עֲלֵיכֶ֣ם מָשָׁ֗ל וְנָהָ֨ה נְהִ֤י נִֽהְיָה֙ אָמַר֙ שָׁד֣וֹד נְשַׁדֻּ֔נוּ חֵ֥לֶק עַמִּ֖י יָמִ֑יר אֵ֚יךְ יָמִ֣ישׁ לִ֔י לְשׁוֹבֵ֥ב שָׂדֵ֖ינוּ יְחַלֵּֽק׃","bȧẏ֨wòm hah֜ẇʼ yişá֧̇̂ʼ ʻàléyke֣m máşá̌֗l wĕnáhá֨h nĕhi֤y niֽhĕyáh֙ ʼámar֙ şá̌d֣wòd nĕşǎdu̇֔nẇ ẖé֥leq ʻami֖̇y yámi֑yr ʼé֚ykĕ yámi֣yş̌ li֔y lĕş̌wòbé֥b şá̂dé֖ynẇ yĕẖaléֽ̇q׃"],[2,5,"לָכֵן֙ לֹֽא־יִֽהְיֶ֣ה לְךָ֔ מַשְׁלִ֥יךְ חֶ֖בֶל בְּגוֹרָ֑ל בִּקְהַ֖ל יְהוָֽה׃","lákén֙ lòֽʼ-yiֽhĕye֣h lĕká֔ maşĕ̌li֥ykĕ ẖe֖bel bĕ̇gwòrá֑l bi̇qĕha֖l yĕhwáֽh׃"],[2,6,"אַל־תַּטִּ֖פוּ יַטִּיפ֑וּן לֹֽא־יַטִּ֣פוּ לָאֵ֔לֶּה לֹ֥א יִסַּ֖ג כְּלִמּֽוֹת׃","ʼal-ţȧti֖̇pẇ yati̇yp֑ẇn lòֽʼ-yati֣̇pẇ láʼé֔lėh lò֥ʼ yisȧ֖g kĕ̇liṁֽwòţ׃"],[2,7,"הֶאָמ֣וּר בֵּֽית־יַעֲקֹ֗ב הֲקָצַר֙ ר֣וּחַ יְהוָ֔ה אִם־אֵ֖לֶּה מַעֲלָלָ֑יו הֲל֤וֹא דְבָרַ֨י יֵיטִ֔יבוּ עִ֖ם הַיָּשָׁ֥ר הוֹלֵֽךְ׃","heʼám֣ẇr béֽ̇yţ-yaʻàqò֗b hàqáẕar֙ r֣ẇẖa yĕhwá֔h ʼim-ʼé֖lėh maʻàlálá֑yw hàl֤wòʼ dĕbára֨y yéyti֔ybẇ ʻi֖m hayá̇şá֥̌r hwòléֽkĕ׃"],[2,8,"וְאֶתְמ֗וּל עַמִּי֙ לְאוֹיֵ֣ב יְקוֹמֵ֔ם מִמּ֣וּל שַׂלְמָ֔ה אֶ֖דֶר תַּפְשִׁט֑וּן מֵעֹבְרִ֣ים בֶּ֔טַח שׁוּבֵ֖י מִלְחָמָֽה׃","wĕʼeţĕm֗ẇl ʻami̇y֙ lĕʼwòyé֣b yĕqwòmé֔m miṁ֣ẇl şâlĕmá֔h ʼe֖der ţȧpĕşǐt֑ẇn méʻòbĕri֣ym bė֔taẖ ş̌ẇbé֖y milĕẖámáֽh׃"],[2,9,"נְשֵׁ֤י עַמִּי֙ תְּגָ֣רְשׁ֔וּן מִבֵּ֖ית תַּֽעֲנֻגֶ֑יהָ מֵעַל֙ עֹֽלָלֶ֔יהָ תִּקְח֥וּ הֲדָרִ֖י לְעוֹלָֽם׃","nĕşé֤̌y ʻami̇y֙ ţĕ̇gá֣rĕş̌֔ẇn mibé֖̇yţ ţȧֽʻànuge֑yhá méʻal֙ ʻòֽlále֔yhá ţi̇qĕẖ֥ẇ hàdári֖y lĕʻwòláֽm׃"],[2,10,"ק֣וּמוּ וּלְכ֔וּ כִּ֥י לֹא־זֹ֖את הַמְּנוּחָ֑ה בַּעֲב֥וּר טָמְאָ֛ה תְּחַבֵּ֖ל וְחֶ֥בֶל נִמְרָֽץ׃","q֣ẇmẇ ẇlĕk֔ẇ ki֥̇y lòʼ-zò֖ʼţ hamĕ̇nẇẖá֑h bȧʻàb֥ẇr támĕʼá֛h ţĕ̇ẖabé֖̇l wĕẖe֥bel nimĕráֽẕ׃"],[2,11,"לוּ־אִ֞ישׁ הֹלֵ֥ךְ ר֙וּחַ֙ וָשֶׁ֣קֶר כִּזֵּ֔ב אַטִּ֣ף לְךָ֔ לַיַּ֖יִן וְלַשֵּׁכָ֑ר וְהָיָ֥ה מַטִּ֖יף הָעָ֥ם הַזֶּֽה׃","lẇ-ʼi֞yş̌ hòlé֥kĕ r֙ẇẖa֙ wáşě֣qer ki̇zé̇֔b ʼati֣̇p lĕká֔ layȧ֖yin wĕlaşé̇̌ká֑r wĕháyá֥h mati֖̇yp háʻá֥m hazėֽh׃"],[2,12,"אָסֹ֨ף אֶאֱסֹ֜ף יַעֲקֹ֣ב כֻּלָּ֗ךְ קַבֵּ֤ץ אֲקַבֵּץ֙ שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל יַ֥חַד אֲשִׂימֶ֖נּוּ כְּצֹ֣אן בָּצְרָ֑ה כְּעֵ֙דֶר֙ בְּת֣וֹךְ הַדָּֽבְר֔וֹ תְּהִימֶ֖נָה מֵאָדָֽם׃","ʼásò֨p ʼeʼèsò֜p yaʻàqò֣b ku̇lá̇֗kĕ qabé֤̇ẕ ʼàqabé̇ẕ֙ şĕ̌ʼéri֣yţ yişĕ̂ráʼé֔l ya֥ẖad ʼàşîyme֖ṅẇ kĕ̇ẕò֣ʼn bá̇ẕĕrá֑h kĕ̇ʻé֙der֙ bĕ̇ţ֣wòkĕ hadáֽ̇bĕr֔wò ţĕ̇hiyme֖náh méʼádáֽm׃"],[2,13,"עָלָ֤ה הַפֹּרֵץ֙ לִפְנֵיהֶ֔ם פָּֽרְצוּ֙ וַֽיַּעֲבֹ֔רוּ שַׁ֖עַר וַיֵּ֣צְאוּ ב֑וֹ וַיַּעֲבֹ֤ר מַלְכָּם֙ לִפְנֵיהֶ֔ם וַיהוָ֖ה בְּרֹאשָֽׁם׃ פ","ʻálá֤h hapò̇réẕ֙ lipĕnéyhe֔m páֽ̇rĕẕẇ֙ waֽyȧʻàbò֔rẇ şǎ֖ʻar wayé֣̇ẕĕʼẇ b֑wò wayȧʻàbò֤r malĕká̇m֙ lipĕnéyhe֔m wayhwá֖h bĕ̇ròʼşáֽ̌m׃ p"],[3,1,"וָאֹמַ֗ר שִׁמְעוּ־נָא֙ רָאשֵׁ֣י יַעֲקֹ֔ב וּקְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הֲל֣וֹא לָכֶ֔ם לָדַ֖עַת אֶת־הַמִּשְׁפָּֽט ׃","wáʼòma֗r şǐmĕʻẇ-náʼ֙ ráʼşé֣̌y yaʻàqò֔b ẇqĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l hàl֣wòʼ láke֔m láda֖ʻaţ ʼeţ-hami̇şĕ̌páֽ̇t ׃"],[3,2,"שֹׂ֥נְאֵי ט֖וֹב וְאֹ֣הֲבֵי רעה גֹּזְלֵ֤י עוֹרָם֙ מֵֽעֲלֵיהֶ֔ם וּשְׁאֵרָ֖ם מֵעַ֥ל עַצְמוֹתָֽם׃","şò֥̂nĕʼéy t֖wòb wĕʼò֣hàbéy rʻh gò̇zĕlé֤y ʻwòrám֙ méֽʻàléyhe֔m ẇşĕ̌ʼérá֖m méʻa֥l ʻaẕĕmwòţáֽm׃"],[3,3,"וַאֲשֶׁ֣ר אָכְלוּ֮ שְׁאֵ֣ר עַמִּי֒ וְעוֹרָם֙ מֵעֲלֵיהֶ֣ם הִפְשִׁ֔יטוּ וְאֶת־עַצְמֹֽתֵיהֶ֖ם פִּצֵּ֑חוּ וּפָרְשׂוּ֙ כַּאֲשֶׁ֣ר בַּסִּ֔יר וּכְבָשָׂ֖ר בְּת֥וֹךְ קַלָּֽחַת׃","waʼàşě֣r ʼákĕlẇ֮ şĕ̌ʼé֣r ʻami̇y֒ wĕʻwòrám֙ méʻàléyhe֣m hipĕşǐ֔ytẇ wĕʼeţ-ʻaẕĕmòֽţéyhe֖m pi̇ẕé֑̇ẖẇ ẇpárĕş̂ẇ֙ kȧʼàşě֣r bȧsi̇֔yr ẇkĕbáşá֖̂r bĕ̇ţ֥wòkĕ qaláֽ̇ẖaţ׃"],[3,4,"אָ֚ז יִזְעֲק֣וּ אֶל־יְהוָ֔ה וְלֹ֥א יַעֲנֶ֖ה אוֹתָ֑ם וְיַסְתֵּ֨ר פָּנָ֤יו מֵהֶם֙ בָּעֵ֣ת הַהִ֔יא כַּאֲשֶׁ֥ר הֵרֵ֖עוּ מַעַלְלֵיהֶֽם׃ פ","ʼá֚z yizĕʻàq֣ẇ ʼel-yĕhwá֔h wĕlò֥ʼ yaʻàne֖h ʼwòţá֑m wĕyasĕţé̇֨r pá̇ná֤yw méhem֙ bá̇ʻé֣ţ hahi֔yʼ kȧʼàşě֥r héré֖ʻẇ maʻalĕléyheֽm׃ p"],[3,5,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־הַנְּבִיאִ֖ים הַמַּתְעִ֣ים אֶת־עַמִּ֑י הַנֹּשְׁכִ֤ים בְּשִׁנֵּיהֶם֙ וְקָרְא֣וּ שָׁל֔וֹם וַאֲשֶׁר֙ לֹא־יִתֵּ֣ן עַל־פִּיהֶ֔ם וְקִדְּשׁ֥וּ עָלָ֖יו מִלְחָמָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-hanĕ̇biyʼi֖ym hamȧţĕʻi֣ym ʼeţ-ʻami֑̇y hanò̇şĕ̌ki֤ym bĕ̇şǐné̇yhem֙ wĕqárĕʼ֣ẇ şá̌l֔wòm waʼàşěr֙ lòʼ-yiţé֣̇n ʻal-pi̇yhe֔m wĕqidĕ̇ş֥̌ẇ ʻálá֖yw milĕẖámáֽh׃"],[3,6,"לָכֵ֞ן לַ֤יְלָה לָכֶם֙ מֵֽחָז֔וֹן וְחָשְׁכָ֥ה לָכֶ֖ם מִקְּסֹ֑ם וּבָ֤אָה הַשֶּׁ֙מֶשׁ֙ עַל־הַנְּבִיאִ֔ים וְקָדַ֥ר עֲלֵיהֶ֖ם הַיּֽוֹם׃","láké֞n la֤yĕláh lákem֙ méֽẖáz֔wòn wĕẖáşĕ̌ká֥h láke֖m miqĕ̇sò֑m ẇbá֤ʼáh haşė̌֙meş̌֙ ʻal-hanĕ̇biyʼi֔ym wĕqáda֥r ʻàléyhe֖m haẏֽwòm׃"],[3,7,"וּבֹ֣שׁוּ הַחֹזִ֗ים וְחָֽפְרוּ֙ הַקֹּ֣סְמִ֔ים וְעָט֥וּ עַל־שָׂפָ֖ם כֻּלָּ֑ם כִּ֛י אֵ֥ין מַעֲנֵ֖ה אֱלֹהִֽים׃","ẇbò֣ş̌ẇ haẖòzi֗ym wĕẖáֽpĕrẇ֙ haqò֣̇sĕmi֔ym wĕʻát֥ẇ ʻal-şá̂pá֖m ku̇lá֑̇m ki֛̇y ʼé֥yn maʻàné֖h ʼèlòhiֽym׃"],[3,8,"וְאוּלָ֗ם אָנֹכִ֞י מָלֵ֤אתִי כֹ֙חַ֙ אֶת־ר֣וּחַ יְהוָ֔ה וּמִשְׁפָּ֖ט וּגְבוּרָ֑ה לְהַגִּ֤יד לְיַֽעֲקֹב֙ פִּשְׁע֔וֹ וּלְיִשְׂרָאֵ֖ל חַטָּאתֽוֹ׃ ס","wĕʼẇlá֗m ʼánòki֞y málé֤ʼţiy kò֙ẖa֙ ʼeţ-r֣ẇẖa yĕhwá֔h ẇmişĕ̌pá֖̇t ẇgĕbẇrá֑h lĕhagi֤̇yd lĕyaֽʻàqòb֙ pi̇şĕ̌ʻ֔wò ẇlĕyişĕ̂ráʼé֖l ẖatá̇ʼţֽwò׃ s"],[3,9,"שִׁמְעוּ־נָ֣א זֹ֗את רָאשֵׁי֙ בֵּ֣ית יַעֲקֹ֔ב וּקְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הַֽמֲתַעֲבִ֣ים מִשְׁפָּ֔ט וְאֵ֥ת כָּל־הַיְשָׁרָ֖ה יְעַקֵּֽשׁוּ׃","şǐmĕʻẇ-ná֣ʼ zò֗ʼţ ráʼşé̌y֙ bé֣̇yţ yaʻàqò֔b ẇqĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l haֽmàţaʻàbi֣ym mişĕ̌pá̇֔t wĕʼé֥ţ ká̇l-hayĕşá̌rá֖h yĕʻaqéֽ̇ş̌ẇ׃"],[3,10,"בֹּנֶ֥ה צִיּ֖וֹן בְּדָמִ֑ים וִירוּשָׁלִַ֖ם בְּעַוְלָֽה׃","bò̇ne֥h ẕiẏ֖wòn bĕ̇dámi֑ym wiyrẇşá̌lia֖m bĕ̇ʻawĕláֽh׃"],[3,11,"רָאשֶׁ֣יהָ ׀ בְּשֹׁ֣חַד יִשְׁפֹּ֗טוּ וְכֹהֲנֶ֙יהָ֙ בִּמְחִ֣יר יוֹר֔וּ וּנְבִיאֶ֖יהָ בְּכֶ֣סֶף יִקְסֹ֑מוּ וְעַל־יְהוָה֙ יִשָּׁעֵ֣נוּ לֵאמֹ֔ר הֲל֤וֹא יְהוָה֙ בְּקִרְבֵּ֔נוּ לֹֽא־תָב֥וֹא עָלֵ֖ינוּ רָעָֽה׃","ráʼşě֣yhá ׀ bĕ̇şò֣̌ẖad yişĕ̌pò̇֗tẇ wĕkòhàne֙yhá֙ bi̇mĕẖi֣yr ywòr֔ẇ ẇnĕbiyʼe֖yhá bĕ̇ke֣sep yiqĕsò֑mẇ wĕʻal-yĕhwáh֙ yişá̇̌ʻé֣nẇ léʼmò֔r hàl֤wòʼ yĕhwáh֙ bĕ̇qirĕbé̇֔nẇ lòֽʼ-ţáb֥wòʼ ʻálé֖ynẇ ráʻáֽh׃"],[3,12,"לָכֵן֙ בִּגְלַלְכֶ֔ם צִיּ֖וֹן שָׂדֶ֣ה תֵֽחָרֵ֑שׁ וִירוּשָׁלִַ֙ם֙ עִיִּ֣ין תִּֽהְיֶ֔ה וְהַ֥ר הַבַּ֖יִת לְבָמ֥וֹת יָֽעַר׃ פ","lákén֙ bi̇gĕlalĕke֔m ẕiẏ֖wòn şá̂de֣h ţéֽẖáré֑ş̌ wiyrẇşá̌lia֙m֙ ʻiyi֣̇yn ţiֽ̇hĕye֔h wĕha֥r habȧ֖yiţ lĕbám֥wòţ yáֽʻar׃ p"],[4,1,"וְהָיָ֣ה ׀ בְּאַחֲרִ֣ית הַיָּמִ֗ים יִ֠הְיֶה הַ֣ר בֵּית־יְהוָ֤ה נָכוֹן֙ בְּרֹ֣אשׁ הֶהָרִ֔ים וְנִשָּׂ֥א ה֖וּא מִגְּבָע֑וֹת וְנָהֲר֥וּ עָלָ֖יו עַמִּֽים׃","wĕháyá֣h ׀ bĕ̇ʼaẖàri֣yţ hayá̇mi֗ym yi֠hĕyeh ha֣r bé̇yţ-yĕhwá֤h nákwòn֙ bĕ̇rò֣ʼş̌ hehári֔ym wĕnişá֥̇̂ʼ h֖ẇʼ migĕ̇báʻ֑wòţ wĕnáhàr֥ẇ ʻálá֖yw ʻamiֽ̇ym׃"],[4,2,"וְֽהָלְכ֞וּ גּוֹיִ֣ם רַבִּ֗ים וְאָֽמְרוּ֙ לְכ֣וּ ׀ וְנַעֲלֶ֣ה אֶל־הַר־יְהוָ֗ה וְאֶל־בֵּית֙ אֱלֹהֵ֣י יַעֲקֹ֔ב וְיוֹרֵ֙נוּ֙ מִדְּרָכָ֔יו וְנֵלְכָ֖ה בְּאֹֽרְחֹתָ֑יו כִּ֤י מִצִּיּוֹן֙ תֵּצֵ֣א תוֹרָ֔ה וּדְבַר־יְהוָ֖ה מִירוּשָׁלִָֽם׃","wĕֽhálĕk֞ẇ ġwòyi֣m rabi̇֗ym wĕʼáֽmĕrẇ֙ lĕk֣ẇ ׀ wĕnaʻàle֣h ʼel-har-yĕhwá֗h wĕʼel-bé̇yţ֙ ʼèlòhé֣y yaʻàqò֔b wĕywòré֙nẇ֙ midĕ̇ráká֔yw wĕnélĕká֖h bĕ̇ʼòֽrĕẖòţá֑yw ki֤̇y miẕi̇ẏwòn֙ ţé̇ẕé֣ʼ ţwòrá֔h ẇdĕbar-yĕhwá֖h miyrẇşá̌liáֽm׃"],[4,3,"וְשָׁפַ֗ט בֵּ֚ין עַמִּ֣ים רַבִּ֔ים וְהוֹכִ֛יחַ לְגוֹיִ֥ם עֲצֻמִ֖ים עַד־רָח֑וֹק וְכִתְּת֨וּ חַרְבֹתֵיהֶ֜ם לְאִתִּ֗ים וַחֲנִיתֹֽתֵיהֶם֙ לְמַזְמֵר֔וֹת לֹֽא־יִשְׂא֞וּ גּ֤וֹי אֶל־גּוֹי֙ חֶ֔רֶב וְלֹא־יִלְמְד֥וּן ע֖וֹד מִלְחָמָֽה׃","wĕşá̌pa֗t bé֚̇yn ʻami֣̇ym rabi̇֔ym wĕhwòki֛yẖa lĕgwòyi֥m ʻàẕumi֖ym ʻad-ráẖ֑wòq wĕkiţĕ̇ţ֨ẇ ẖarĕbòţéyhe֜m lĕʼiţi̇֗ym waẖàniyţòֽţéyhem֙ lĕmazĕmér֔wòţ lòֽʼ-yişĕ̂ʼ֞ẇ ġ֤wòy ʼel-ġwòy֙ ẖe֔reb wĕlòʼ-yilĕmĕd֥ẇn ʻ֖wòd milĕẖámáֽh׃"],[4,4,"וְיָשְׁב֗וּ אִ֣ישׁ תַּ֧חַת גַּפְנ֛וֹ וְתַ֥חַת תְּאֵנָת֖וֹ וְאֵ֣ין מַחֲרִ֑יד כִּי־פִ֛י יְהוָ֥ה צְבָא֖וֹת דִּבֵּֽר׃","wĕyáşĕ̌b֗ẇ ʼi֣yş̌ ţȧ֧ẖaţ gȧpĕn֛wò wĕţa֥ẖaţ ţĕ̇ʼénáţ֖wò wĕʼé֣yn maẖàri֑yd ki̇y-pi֛y yĕhwá֥h ẕĕbáʼ֖wòţ di̇béֽ̇r׃"],[4,5,"כִּ֚י כָּל־הָ֣עַמִּ֔ים יֵלְכ֕וּ אִ֖ישׁ בְּשֵׁ֣ם אֱלֹהָ֑יו וַאֲנַ֗חְנוּ נֵלֵ֛ךְ בְּשֵׁם־יְהוָ֥ה אֱלֹהֵ֖ינוּ לְעוֹלָ֥ם וָעֶֽד׃ פ","ki֚̇y ká̇l-há֣ʻami̇֔ym yélĕk֕ẇ ʼi֖yş̌ bĕ̇şé֣̌m ʼèlòhá֑yw waʼàna֗ẖĕnẇ nélé֛kĕ bĕ̇şé̌m-yĕhwá֥h ʼèlòhé֖ynẇ lĕʻwòlá֥m wáʻeֽd׃ p"],[4,6,"בַּיּ֨וֹם הַה֜וּא נְאֻם־יְהוָ֗ה אֹֽסְפָה֙ הַצֹּ֣לֵעָ֔ה וְהַנִּדָּחָ֖ה אֲקַבֵּ֑צָה וַאֲשֶׁ֖ר הֲרֵעֹֽתִי׃","bȧẏ֨wòm hah֜ẇʼ nĕʼum-yĕhwá֗h ʼòֽsĕpáh֙ haẕò֣̇léʻá֔h wĕhani̇dá̇ẖá֖h ʼàqabé֑̇ẕáh waʼàşě֖r hàréʻòֽţiy׃"],[4,7,"וְשַׂמְתִּ֤י אֶת־הַצֹּֽלֵעָה֙ לִשְׁאֵרִ֔ית וְהַנַּהֲלָאָ֖ה לְג֣וֹי עָצ֑וּם וּמָלַ֨ךְ יְהוָ֤ה עֲלֵיהֶם֙ בְּהַ֣ר צִיּ֔וֹן מֵעַתָּ֖ה וְעַד־עוֹלָֽם׃ פ","wĕşâmĕţi֤̇y ʼeţ-haẕòֽ̇léʻáh֙ lişĕ̌ʼéri֔yţ wĕhanȧhàláʼá֖h lĕg֣wòy ʻáẕ֑ẇm ẇmála֨kĕ yĕhwá֤h ʻàléyhem֙ bĕ̇ha֣r ẕiẏ֔wòn méʻaţá֖̇h wĕʻad-ʻwòláֽm׃ p"],[4,8,"וְאַתָּ֣ה מִגְדַּל־עֵ֗דֶר עֹ֛פֶל בַּת־צִיּ֖וֹן עָדֶ֣יךָ תֵּאתֶ֑ה וּבָאָ֗ה הַמֶּמְשָׁלָה֙ הָרִ֣אשֹׁנָ֔ה מַמְלֶ֖כֶת לְבַ֥ת־יְרוּשָׁלִָֽם׃","wĕʼaţá֣̇h migĕdȧl-ʻé֗der ʻò֛pel bȧţ-ẕiẏ֖wòn ʻáde֣yká ţé̇ʼţe֑h ẇbáʼá֗h hamėmĕşá̌láh֙ hári֣ʼşò̌ná֔h mamĕle֖keţ lĕba֥ţ-yĕrẇşá̌liáֽm׃"],[4,9,"עַתָּ֕ה לָ֥מָּה תָרִ֖יעִי רֵ֑עַ הֲמֶ֣לֶךְ אֵֽין־בָּ֗ךְ אִֽם־יוֹעֲצֵךְ֙ אָבָ֔ד כִּֽי־הֶחֱזִיקֵ֥ךְ חִ֖יל כַּיּוֹלֵדָֽה׃","ʻaţá̇֕h lá֥má̇h ţári֖yʻiy ré֑ʻa hàme֣lekĕ ʼéֽyn-bá̇֗kĕ ʼiֽm-ywòʻàẕékĕ֙ ʼábá֔d kiֽ̇y-heẖèziyqé֥kĕ ẖi֖yl kȧẏwòlédáֽh׃"],[4,10,"ח֧וּלִי וָגֹ֛חִי בַּת־צִיּ֖וֹן כַּיּֽוֹלֵדָ֑ה כִּֽי־עַתָּה֩ תֵצְאִ֨י מִקִּרְיָ֜ה וְשָׁכַ֣נְתְּ בַּשָּׂדֶ֗ה וּבָ֤את עַד־בָּבֶל֙ שָׁ֣ם תִּנָּצֵ֔לִי שָׁ֚ם יִגְאָלֵ֣ךְ יְהוָ֔ה מִכַּ֖ף אֹיְבָֽיִךְ׃","ẖ֧ẇliy wágò֛ẖiy bȧţ-ẕiẏ֖wòn kȧẏֽwòlédá֑h kiֽ̇y-ʻaţá̇h֩ ţéẕĕʼi֨y miqi̇rĕyá֜h wĕşá̌ka֣nĕţĕ̇ bȧşá̇̂de֗h ẇbá֤ʼţ ʻad-bá̇bel֙ şá֣̌m ţi̇ná̇ẕé֔liy şá֚̌m yigĕʼálé֣kĕ yĕhwá֔h mikȧ֖p ʼòyĕbáֽyikĕ׃"],[4,11,"וְעַתָּ֛ה נֶאֶסְפ֥וּ עָלַ֖יִךְ גּוֹיִ֣ם רַבִּ֑ים הָאֹמְרִ֣ים תֶּחֱנָ֔ף וְתַ֥חַז בְּצִיּ֖וֹן עֵינֵֽינוּ׃","wĕʻaţá֛̇h neʼesĕp֥ẇ ʻála֖yikĕ ġwòyi֣m rabi֑̇ym háʼòmĕri֣ym ţėẖèná֔p wĕţa֥ẖaz bĕ̇ẕiẏ֖wòn ʻéynéֽynẇ׃"],[4,12,"וְהֵ֗מָּה לֹ֤א יָֽדְעוּ֙ מַחְשְׁב֣וֹת יְהוָ֔ה וְלֹ֥א הֵבִ֖ינוּ עֲצָת֑וֹ כִּ֥י קִבְּצָ֖ם כֶּעָמִ֥יר גֹּֽרְנָה׃","wĕhé֗má̇h lò֤ʼ yáֽdĕʻẇ֙ maẖĕşĕ̌b֣wòţ yĕhwá֔h wĕlò֥ʼ hébi֖ynẇ ʻàẕáţ֑wò ki֥̇y qibĕ̇ẕá֖m kėʻámi֥yr gòֽ̇rĕnáh׃"],[4,13,"ק֧וּמִי וָד֣וֹשִׁי בַת־צִיּ֗וֹן כִּֽי־קַרְנֵ֞ךְ אָשִׂ֤ים בַּרְזֶל֙ וּפַרְסֹתַ֙יִךְ֙ אָשִׂ֣ים נְחוּשָׁ֔ה וַהֲדִקּ֖וֹת עַמִּ֣ים רַבִּ֑ים וְהַחֲרַמְתִּ֤י לַֽיהוָה֙ בִּצְעָ֔ם וְחֵילָ֖ם לַאֲד֥וֹן כָּל־הָאָֽרֶץ׃","q֧ẇmiy wád֣wòşǐy baţ-ẕiẏ֗wòn kiֽ̇y-qarĕné֞kĕ ʼáşî֤ym bȧrĕzel֙ ẇparĕsòţa֙yikĕ֙ ʼáşî֣ym nĕẖẇşá̌֔h wahàdiq֖̇wòţ ʻami֣̇ym rabi֑̇ym wĕhaẖàramĕţi֤̇y laֽyhwáh֙ bi̇ẕĕʻá֔m wĕẖéylá֖m laʼàd֥wòn ká̇l-háʼáֽreẕ׃"],[4,14,"עַתָּה֙ תִּתְגֹּדְדִ֣י בַת־גְּד֔וּד מָצ֖וֹר שָׂ֣ם עָלֵ֑ינוּ בַּשֵּׁ֙בֶט֙ יַכּ֣וּ עַֽל־הַלְּחִ֔י אֵ֖ת שֹׁפֵ֥ט יִשְׂרָאֵֽל׃ ס","ʻaţá̇h֙ ţi̇ţĕgò̇dĕdi֣y baţ-gĕ̇d֔ẇd máẕ֖wòr şá֣̂m ʻálé֑ynẇ bȧşé̇̌֙bet֙ yak֣̇ẇ ʻaֽl-halĕ̇ẖi֔y ʼé֖ţ şò̌pé֥t yişĕ̂ráʼéֽl׃ s"],[5,1,"וְאַתָּ֞ה בֵּֽית־לֶ֣חֶם אֶפְרָ֗תָה צָעִיר֙ לִֽהְיוֹת֙ בְּאַלְפֵ֣י יְהוּדָ֔ה מִמְּךָ֙ לִ֣י יֵצֵ֔א לִֽהְי֥וֹת מוֹשֵׁ֖ל בְּיִשְׂרָאֵ֑ל וּמוֹצָאֹתָ֥יו מִקֶּ֖דֶם מִימֵ֥י עוֹלָֽם׃","wĕʼaţá̇֞h béֽ̇yţ-le֣ẖem ʼepĕrá֗ţáh ẕáʻiyr֙ liֽhĕywòţ֙ bĕ̇ʼalĕpé֣y yĕhẇdá֔h mimĕ̇ká֙ li֣y yéẕé֔ʼ liֽhĕy֥wòţ mwòşé֖̌l bĕ̇yişĕ̂ráʼé֑l ẇmwòẕáʼòţá֥yw miqė֖dem miymé֥y ʻwòláֽm׃"],[5,2,"לָכֵ֣ן יִתְּנֵ֔ם עַד־עֵ֥ת יוֹלֵדָ֖ה יָלָ֑דָה וְיֶ֣תֶר אֶחָ֔יו יְשׁוּב֖וּן עַל־בְּנֵ֥י יִשְׂרָאֵֽל׃","láké֣n yiţĕ̇né֔m ʻad-ʻé֥ţ ywòlédá֖h yálá֑dáh wĕye֣ţer ʼeẖá֔yw yĕş̌ẇb֖ẇn ʻal-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[5,3,"וְעָמַ֗ד וְרָעָה֙ בְּעֹ֣ז יְהוָ֔ה בִּגְא֕וֹן שֵׁ֖ם יְהוָ֣ה אֱלֹהָ֑יו וְיָשָׁ֕בוּ כִּֽי־עַתָּ֥ה יִגְדַּ֖ל עַד־אַפְסֵי־אָֽרֶץ׃","wĕʻáma֗d wĕráʻáh֙ bĕ̇ʻò֣z yĕhwá֔h bi̇gĕʼ֕wòn şé֖̌m yĕhwá֣h ʼèlòhá֑yw wĕyáşá̌֕bẇ kiֽ̇y-ʻaţá֥̇h yigĕdȧ֖l ʻad-ʼapĕséy-ʼáֽreẕ׃"],[5,4,"וְהָיָ֥ה זֶ֖ה שָׁל֑וֹם אַשּׁ֣וּר ׀ כִּֽי־יָב֣וֹא בְאַרְצֵ֗נוּ וְכִ֤י יִדְרֹךְ֙ בְּאַרְמְנֹתֵ֔ינוּ וַהֲקֵמֹ֤נוּ עָלָיו֙ שִׁבְעָ֣ה רֹעִ֔ים וּשְׁמֹנָ֖ה נְסִיכֵ֥י אָדָֽם׃","wĕháyá֥h ze֖h şá̌l֑wòm ʼaş֣̇̌ẇr ׀ kiֽ̇y-yáb֣wòʼ bĕʼarĕẕé֗nẇ wĕki֤y yidĕròkĕ֙ bĕ̇ʼarĕmĕnòţé֔ynẇ wahàqémò֤nẇ ʻáláyw֙ şǐbĕʻá֣h ròʻi֔ym ẇşĕ̌mòná֖h nĕsiyké֥y ʼádáֽm׃"],[5,5,"וְרָע֞וּ אֶת־אֶ֤רֶץ אַשּׁוּר֙ בַּחֶ֔רֶב וְאֶת־אֶ֥רֶץ נִמְרֹ֖ד בִּפְתָחֶ֑יהָ וְהִצִּיל֙ מֵֽאַשּׁ֔וּר כִּֽי־יָב֣וֹא בְאַרְצֵ֔נוּ וְכִ֥י יִדְרֹ֖ךְ בִּגְבוּלֵֽנוּ׃ ס","wĕráʻ֞ẇ ʼeţ-ʼe֤reẕ ʼaş̇̌ẇr֙ bȧẖe֔reb wĕʼeţ-ʼe֥reẕ nimĕrò֖d bi̇pĕţáẖe֑yhá wĕhiẕi̇yl֙ méֽʼaş̇̌֔ẇr kiֽ̇y-yáb֣wòʼ bĕʼarĕẕé֔nẇ wĕki֥y yidĕrò֖kĕ bi̇gĕbẇléֽnẇ׃ s"],[5,6,"וְהָיָ֣ה ׀ שְׁאֵרִ֣ית יַעֲקֹ֗ב בְּקֶ֙רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּטַל֙ מֵאֵ֣ת יְהוָ֔ה כִּרְבִיבִ֖ים עֲלֵי־עֵ֑שֶׂב אֲשֶׁ֤ר לֹֽא־יְקַוֶּה֙ לְאִ֔ישׁ וְלֹ֥א יְיַחֵ֖ל לִבְנֵ֥י אָדָֽם׃","wĕháyá֣h ׀ şĕ̌ʼéri֣yţ yaʻàqò֗b bĕ̇qe֙reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇tal֙ méʼé֣ţ yĕhwá֔h ki̇rĕbiybi֖ym ʻàléy-ʻé֑şêb ʼàşě֤r lòֽʼ-yĕqawėh֙ lĕʼi֔yş̌ wĕlò֥ʼ yĕyaẖé֖l libĕné֥y ʼádáֽm׃"],[5,7,"וְהָיָה֩ שְׁאֵרִ֨ית יַעֲקֹ֜ב בַּגּוֹיִ֗ם בְּקֶ֙רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּאַרְיֵה֙ בְּבַהֲמ֣וֹת יַ֔עַר כִּכְפִ֖יר בְּעֶדְרֵי צֹ֑אן אֲשֶׁ֧ר אִם עָבַ֛ר וְרָמַ֥ס וְטָרַ֖ף וְאֵ֥ין מַצִּֽיל׃","wĕháyáh֩ şĕ̌ʼéri֨yţ yaʻàqò֜b bȧġwòyi֗m bĕ̇qe֙reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇ʼarĕyéh֙ bĕ̇bahàm֣wòţ ya֔ʻar ki̇kĕpi֖yr bĕ̇ʻedĕréy ẕò֑ʼn ʼàşě֧r ʼim ʻába֛r wĕráma֥s wĕtára֖p wĕʼé֥yn maẕiֽ̇yl׃"],[5,8,"תָּרֹ֥ם יָדְךָ֖ עַל־צָרֶ֑יךָ וְכָל־אֹיְבֶ֖יךָ יִכָּרֵֽתוּ׃ פ","ţá̇rò֥m yádĕká֖ ʻal-ẕáre֑yká wĕkál-ʼòyĕbe֖yká yiká̇réֽţẇ׃ p"],[5,9,"וְהָיָ֤ה בַיּוֹם־הַהוּא֙ נְאֻם־יְהוָ֔ה וְהִכְרַתִּ֥י סוּסֶ֖יךָ מִקִּרְבֶּ֑ךָ וְהַאֲבַדְתִּ֖י מַרְכְּבֹתֶֽיךָ׃","wĕháyá֤h baẏwòm-hahẇʼ֙ nĕʼum-yĕhwá֔h wĕhikĕraţi֥̇y sẇse֖yká miqi̇rĕbė֑ká wĕhaʼàbadĕţi֖̇y marĕkĕ̇bòţeֽyká׃"],[5,10,"וְהִכְרַתִּ֖י עָרֵ֣י אַרְצֶ֑ךָ וְהָרַסְתִּ֖י כָּל־מִבְצָרֶֽיךָ׃","wĕhikĕraţi֖̇y ʻáré֣y ʼarĕẕe֑ká wĕhárasĕţi֖̇y ká̇l-mibĕẕáreֽyká׃"],[5,11,"וְהִכְרַתִּ֥י כְשָׁפִ֖ים מִיָּדֶ֑ךָ וּֽמְעוֹנְנִ֖ים לֹ֥א יִֽהְיוּ־לָֽךְ׃","wĕhikĕraţi֥̇y kĕşá̌pi֖ym miyá̇de֑ká ẇֽmĕʻwònĕni֖ym lò֥ʼ yiֽhĕyẇ-láֽkĕ׃"],[5,12,"וְהִכְרַתִּ֧י פְסִילֶ֛יךָ וּמַצֵּבוֹתֶ֖יךָ מִקִּרְבֶּ֑ךָ וְלֹֽא־תִשְׁתַּחֲוֶ֥ה ע֖וֹד לְמַעֲשֵׂ֥ה יָדֶֽיךָ׃","wĕhikĕraţi֧̇y pĕsiyle֛yká ẇmaẕé̇bwòţe֖yká miqi̇rĕbė֑ká wĕlòֽʼ-ţişĕ̌ţȧẖàwe֥h ʻ֖wòd lĕmaʻàşé֥̂h yádeֽyká׃"],[5,13,"וְנָתַשְׁתִּ֥י אֲשֵׁירֶ֖יךָ מִקִּרְבֶּ֑ךָ וְהִשְׁמַדְתִּ֖י עָרֶֽיךָ׃","wĕnáţaşĕ̌ţi֥̇y ʼàşé̌yre֖yká miqi̇rĕbė֑ká wĕhişĕ̌madĕţi֖̇y ʻáreֽyká׃"],[5,14,"וְעָשִׂ֜יתִי בְּאַ֧ף וּבְחֵמָ֛ה נָקָ֖ם אֶת־הַגּוֹיִ֑ם אֲשֶׁ֖ר לֹ֥א שָׁמֵֽעוּ׃ ס","wĕʻáşî֜yţiy bĕ̇ʼa֧p ẇbĕẖémá֛h náqá֖m ʼeţ-haġwòyi֑m ʼàşě֖r lò֥ʼ şá̌méֽʻẇ׃ s"],[6,1,"שִׁמְעוּ־נָ֕א אֵ֥ת אֲשֶׁר־יְהוָ֖ה אֹמֵ֑ר ק֚וּם רִ֣יב אֶת־הֶהָרִ֔ים וְתִשְׁמַ֥עְנָה הַגְּבָע֖וֹת קוֹלֶֽךָ׃","şǐmĕʻẇ-ná֕ʼ ʼé֥ţ ʼàşěr-yĕhwá֖h ʼòmé֑r q֚ẇm ri֣yb ʼeţ-hehári֔ym wĕţişĕ̌ma֥ʻĕnáh hagĕ̇báʻ֖wòţ qwòleֽká׃"],[6,2,"שִׁמְע֤וּ הָרִים֙ אֶת־רִ֣יב יְהוָ֔ה וְהָאֵתָנִ֖ים מֹ֣סְדֵי אָ֑רֶץ כִּ֣י רִ֤יב לַֽיהוָה֙ עִם־עַמּ֔וֹ וְעִם־יִשְׂרָאֵ֖ל יִתְוַכָּֽח׃","şǐmĕʻ֤ẇ háriym֙ ʼeţ-ri֣yb yĕhwá֔h wĕháʼéţáni֖ym mò֣sĕdéy ʼá֑reẕ ki֣̇y ri֤yb laֽyhwáh֙ ʻim-ʻaṁ֔wò wĕʻim-yişĕ̂ráʼé֖l yiţĕwakáֽ̇ẖ׃"],[6,3,"עַמִּ֛י מֶה־עָשִׂ֥יתִי לְךָ֖ וּמָ֣ה הֶלְאֵתִ֑יךָ עֲנֵ֥ה בִּֽי׃","ʻami֛̇y meh-ʻáşî֥yţiy lĕká֖ ẇmá֣h helĕʼéţi֑yká ʻàné֥h biֽ̇y׃"],[6,4,"כִּ֤י הֶעֱלִתִ֙יךָ֙ מֵאֶ֣רֶץ מִצְרַ֔יִם וּמִבֵּ֥ית עֲבָדִ֖ים פְּדִיתִ֑יךָ וָאֶשְׁלַ֣ח לְפָנֶ֔יךָ אֶת־מֹשֶׁ֖ה אַהֲרֹ֥ן וּמִרְיָֽם׃","ki֤̇y heʻèliţi֙yká֙ méʼe֣reẕ miẕĕra֔yim ẇmibé֥̇yţ ʻàbádi֖ym pĕ̇diyţi֑yká wáʼeşĕ̌la֣ẖ lĕpáne֔yká ʼeţ-mòşě֖h ʼahàrò֥n ẇmirĕyáֽm׃"],[6,5,"עַמִּ֗י זְכָר־נָא֙ מַה־יָּעַ֗ץ בָּלָק֙ מֶ֣לֶךְ מוֹאָ֔ב וּמֶה־עָנָ֥ה אֹת֖וֹ בִּלְעָ֣ם בֶּן־בְּע֑וֹר מִן־הַשִּׁטִּים֙ עַד־הַגִּלְגָּ֔ל לְמַ֕עַן דַּ֖עַת צִדְק֥וֹת יְהוָֽה׃","ʻami̇֗y zĕkár-náʼ֙ mah-yá̇ʻa֗ẕ bá̇láq֙ me֣lekĕ mwòʼá֔b ẇmeh-ʻáná֥h ʼòţ֖wò bi̇lĕʻá֣m bėn-bĕ̇ʻ֑wòr min-haşi̇̌ti̇ym֙ ʻad-hagi̇lĕgá̇֔l lĕma֕ʻan dȧ֖ʻaţ ẕidĕq֥wòţ yĕhwáֽh׃"],[6,6,"בַּמָּה֙ אֲקַדֵּ֣ם יְהוָ֔ה אִכַּ֖ף לֵאלֹהֵ֣י מָר֑וֹם הַאֲקַדְּמֶ֣נּוּ בְעוֹל֔וֹת בַּעֲגָלִ֖ים בְּנֵ֥י שָׁנָֽה׃","bȧmá̇h֙ ʼàqadé֣̇m yĕhwá֔h ʼikȧ֖p léʼlòhé֣y már֑wòm haʼàqadĕ̇me֣ṅẇ bĕʻwòl֔wòţ bȧʻàgáli֖ym bĕ̇né֥y şá̌náֽh׃"],[6,7,"הֲיִרְצֶ֤ה יְהוָה֙ בְּאַלְפֵ֣י אֵילִ֔ים בְּרִֽבְב֖וֹת נַֽחֲלֵי־שָׁ֑מֶן הַאֶתֵּ֤ן בְּכוֹרִי֙ פִּשְׁעִ֔י פְּרִ֥י בִטְנִ֖י חַטַּ֥את נַפְשִֽׁי׃","hàyirĕẕe֤h yĕhwáh֙ bĕ̇ʼalĕpé֣y ʼéyli֔ym bĕ̇riֽbĕb֖wòţ naֽẖàléy-şá֑̌men haʼeţé֤̇n bĕ̇kwòriy֙ pi̇şĕ̌ʻi֔y pĕ̇ri֥y bitĕni֖y ẖatȧ֥ʼţ napĕşǐֽy׃"],[6,8,"הִגִּ֥יד לְךָ֛ אָדָ֖ם מַה־טּ֑וֹב וּמָֽה־יְהוָ֞ה דּוֹרֵ֣שׁ מִמְּךָ֗ כִּ֣י אִם־עֲשׂ֤וֹת מִשְׁפָּט֙ וְאַ֣הֲבַת חֶ֔סֶד וְהַצְנֵ֥עַ לֶ֖כֶת עִם־אֱלֹהֶֽיךָ׃ פ","higi֥̇yd lĕká֛ ʼádá֖m mah-ṫ֑wòb ẇmáֽh-yĕhwá֞h ḋwòré֣ş̌ mimĕ̇ká֗ ki֣̇y ʼim-ʻàş֤̂wòţ mişĕ̌pá̇t֙ wĕʼa֣hàbaţ ẖe֔sed wĕhaẕĕné֥ʻa le֖keţ ʻim-ʼèlòheֽyká׃ p"],[6,9,"ק֤וֹל יְהוָה֙ לָעִ֣יר יִקְרָ֔א וְתוּשִׁיָּ֖ה יִרְאֶ֣ה שְׁמֶ֑ךָ שִׁמְע֥וּ מַטֶּ֖ה וּמִ֥י יְעָדָֽהּ׃","q֤wòl yĕhwáh֙ láʻi֣yr yiqĕrá֔ʼ wĕţẇşǐyá֖̇h yirĕʼe֣h şĕ̌me֑ká şǐmĕʻ֥ẇ matė֖h ẇmi֥y yĕʻádáֽḣ׃"],[6,10,"ע֗וֹד הַאִשׁ֙ בֵּ֣ית רָשָׁ֔ע אֹצְר֖וֹת רֶ֑שַׁע וְאֵיפַ֥ת רָז֖וֹן זְעוּמָֽה׃","ʻ֗wòd haʼiş̌֙ bé֣̇yţ ráşá̌֔ʻ ʼòẕĕr֖wòţ re֑şǎʻ wĕʼéypa֥ţ ráz֖wòn zĕʻẇmáֽh׃"],[6,11,"הַאֶזְכֶּ֖ה בְּמֹ֣אזְנֵי רֶ֑שַׁע וּבְכִ֖יס אַבְנֵ֥י מִרְמָֽה׃","haʼezĕkė֖h bĕ̇mò֣ʼzĕnéy re֑şǎʻ ẇbĕki֖ys ʼabĕné֥y mirĕmáֽh׃"],[6,12,"אֲשֶׁ֤ר עֲשִׁירֶ֙יהָ֙ מָלְא֣וּ חָמָ֔ס וְיֹשְׁבֶ֖יהָ דִּבְּרוּ־שָׁ֑קֶר וּלְשׁוֹנָ֖ם רְמִיָּ֥ה בְּפִיהֶֽם׃","ʼàşě֤r ʻàşǐyre֙yhá֙ málĕʼ֣ẇ ẖámá֔s wĕyòşĕ̌be֖yhá di̇bĕ̇rẇ-şá֑̌qer ẇlĕş̌wòná֖m rĕmiyá֥̇h bĕ̇piyheֽm׃"],[6,13,"וְגַם־אֲנִ֖י הֶחֱלֵ֣יתִי הַכּוֹתֶ֑ךָ הַשְׁמֵ֖ם עַל־חַטֹּאתֶֽךָ׃","wĕgam-ʼàni֖y heẖèlé֣yţiy hak̇wòţe֑ká haşĕ̌mé֖m ʻal-ẖatò̇ʼţeֽká׃"],[6,14,"אַתָּ֤ה תֹאכַל֙ וְלֹ֣א תִשְׂבָּ֔ע וְיֶשְׁחֲךָ֖ בְּקִרְבֶּ֑ךָ וְתַסֵּג֙ וְלֹ֣א תַפְלִ֔יט וַאֲשֶׁ֥ר תְּפַלֵּ֖ט לַחֶ֥רֶב אֶתֵּֽן׃","ʼaţá֤̇h ţòʼkal֙ wĕlò֣ʼ ţişĕ̂bá̇֔ʻ wĕyeşĕ̌ẖàká֖ bĕ̇qirĕbė֑ká wĕţasé̇g֙ wĕlò֣ʼ ţapĕli֔yt waʼàşě֥r ţĕ̇palé֖̇t laẖe֥reb ʼeţéֽ̇n׃"],[6,15,"אַתָּ֥ה תִזְרַ֖ע וְלֹ֣א תִקְצ֑וֹר אַתָּ֤ה תִדְרֹֽךְ־זַ֙יִת֙ וְלֹא־תָס֣וּךְ שֶׁ֔מֶן וְתִיר֖וֹשׁ וְלֹ֥א תִשְׁתֶּה־יָּֽיִן׃","ʼaţá֥̇h ţizĕra֖ʻ wĕlò֣ʼ ţiqĕẕ֑wòr ʼaţá֤̇h ţidĕròֽkĕ-za֙yiţ֙ wĕlòʼ-ţás֣ẇkĕ şě֔men wĕţiyr֖wòş̌ wĕlò֥ʼ ţişĕ̌ţėh-yáֽ̇yin׃"],[6,16,"וְיִשְׁתַּמֵּ֞ר חֻקּ֣וֹת עָמְרִ֗י וְכֹל֙ מַעֲשֵׂ֣ה בֵית־אַחְאָ֔ב וַתֵּלְכ֖וּ בְּמֹֽעֲצוֹתָ֑ם לְמַעַן֩ תִּתִּ֨י אֹתְךָ֜ לְשַׁמָּ֗ה וְיֹשְׁבֶ֙יהָ֙ לִשְׁרֵקָ֔ה וְחֶרְפַּ֥ת עַמִּ֖י תִּשָּֽׂאוּ׃ פ","wĕyişĕ̌ţȧmé̇֞r ẖuq֣̇wòţ ʻámĕri֗y wĕkòl֙ maʻàşé֣̂h béyţ-ʼaẖĕʼá֔b waţé̇lĕk֖ẇ bĕ̇mòֽʻàẕwòţá֑m lĕmaʻan֩ ţi̇ţi̇֨y ʼòţĕká֜ lĕşǎmá̇֗h wĕyòşĕ̌be֙yhá֙ lişĕ̌réqá֔h wĕẖerĕpȧ֥ţ ʻami֖̇y ţi̇şáֽ̇̂ʼẇ׃ p"],[7,1,"אַ֣לְלַי לִ֗י כִּ֤י הָיִ֙יתִי֙ כְּאָסְפֵּי־קַ֔יִץ כְּעֹלְלֹ֖ת בָּצִ֑יר אֵין־אֶשְׁכּ֣וֹל לֶאֱכ֔וֹל בִּכּוּרָ֖ה אִוְּתָ֥ה נַפְשִֽׁי׃","ʼa֣lĕlay li֗y ki֤̇y háyi֙yţiy֙ kĕ̇ʼásĕpé̇y-qa֔yiẕ kĕ̇ʻòlĕlò֖ţ bá̇ẕi֑yr ʼéyn-ʼeşĕ̌k֣̇wòl leʼèk֔wòl bi̇k̇ẇrá֖h ʼiwĕ̇ţá֥h napĕşǐֽy׃"],[7,2,"אָבַ֤ד חָסִיד֙ מִן־הָאָ֔רֶץ וְיָשָׁ֥ר בָּאָדָ֖ם אָ֑יִן כֻּלָּם֙ לְדָמִ֣ים יֶאֱרֹ֔בוּ אִ֥ישׁ אֶת־אָחִ֖יהוּ יָצ֥וּדוּ חֵֽרֶם׃","ʼába֤d ẖásiyd֙ min-háʼá֔reẕ wĕyáşá֥̌r bá̇ʼádá֖m ʼá֑yin ku̇lá̇m֙ lĕdámi֣ym yeʼèrò֔bẇ ʼi֥yş̌ ʼeţ-ʼáẖi֖yhẇ yáẕ֥ẇdẇ ẖéֽrem׃"],[7,3,"עַל־הָרַ֤ע כַּפַּ֙יִם֙ לְהֵיטִ֔יב הַשַּׂ֣ר שֹׁאֵ֔ל וְהַשֹּׁפֵ֖ט בַּשִׁלּ֑וּם וְהַגָּד֗וֹל דֹּבֵ֨ר הַוַּ֥ת נַפְשׁ֛וֹ ה֖וּא וַֽיְעַבְּתֽוּהָ׃","ʻal-hára֤ʻ kȧpȧ֙yim֙ lĕhéyti֔yb haşȧ֣̂r şò̌ʼé֔l wĕhaşò̇̌pé֖t bȧşǐl֑̇ẇm wĕhagá̇d֗wòl dò̇bé֨r hawȧ֥ţ napĕş֛̌wò h֖ẇʼ waֽyĕʻabĕ̇ţֽẇhá׃"],[7,4,"טוֹבָ֣ם כְּחֵ֔דֶק יָשָׁ֖ר מִמְּסוּכָ֑ה י֤וֹם מְצַפֶּ֙יךָ֙ פְּקֻדָּתְךָ֣ בָ֔אָה עַתָּ֥ה תִהְיֶ֖ה מְבוּכָתָֽם׃","twòbá֣m kĕ̇ẖé֔deq yáşá֖̌r mimĕ̇sẇká֑h y֤wòm mĕẕapė֙yká֙ pĕ̇qudá̇ţĕká֣ bá֔ʼáh ʻaţá֥̇h ţihĕye֖h mĕbẇkáţáֽm׃"],[7,5,"אַל־תַּאֲמִ֣ינוּ בְרֵ֔עַ אַֽל־תִּבְטְח֖וּ בְּאַלּ֑וּף מִשֹּׁכֶ֣בֶת חֵיקֶ֔ךָ שְׁמֹ֖ר פִּתְחֵי־פִֽיךָ׃","ʼal-ţȧʼàmi֣ynẇ bĕré֔ʻa ʼaֽl-ţi̇bĕtĕẖ֖ẇ bĕ̇ʼal֑̇ẇp mişò̇̌ke֣beţ ẖéyqe֔ká şĕ̌mò֖r pi̇ţĕẖéy-piֽyká׃"],[7,6,"כִּֽי־בֵן֙ מְנַבֵּ֣ל אָ֔ב בַּ֚ת קָמָ֣ה בְאִמָּ֔הּ כַּלָּ֖ה בַּחֲמֹתָ֑הּ אֹיְבֵ֥י אִ֖ישׁ אַנְשֵׁ֥י בֵיתֽוֹ׃","kiֽ̇y-bén֙ mĕnabé֣̇l ʼá֔b bȧ֚ţ qámá֣h bĕʼimá̇֔ḣ kȧlá֖̇h bȧẖàmòţá֑ḣ ʼòyĕbé֥y ʼi֖yş̌ ʼanĕşé֥̌y béyţֽwò׃"],[7,7,"וַאֲנִי֙ בַּיהוָ֣ה אֲצַפֶּ֔ה אוֹחִ֖ילָה לֵאלֹהֵ֣י יִשְׁעִ֑י יִשְׁמָעֵ֖נִי אֱלֹהָֽי׃","waʼàniy֙ bȧyhwá֣h ʼàẕapė֔h ʼwòẖi֖yláh léʼlòhé֣y yişĕ̌ʻi֑y yişĕ̌máʻé֖niy ʼèlòháֽy׃"],[7,8,"אַֽל־תִּשְׂמְחִ֤י אֹיַ֙בְתִּי֙ לִ֔י כִּ֥י נָפַ֖לְתִּי קָ֑מְתִּי כִּֽי־אֵשֵׁ֣ב בַּחֹ֔שֶׁךְ יְהוָ֖ה א֥וֹר לִֽי׃ ס","ʼaֽl-ţi̇şĕ̂mĕẖi֤y ʼòya֙bĕţi̇y֙ li֔y ki֥̇y nápa֖lĕţi̇y qá֑mĕţi̇y kiֽ̇y-ʼéşé֣̌b bȧẖò֔şěkĕ yĕhwá֖h ʼ֥wòr liֽy׃ s"],[7,9,"זַ֤עַף יְהוָה֙ אֶשָּׂ֔א כִּ֥י חָטָ֖אתִי ל֑וֹ עַד֩ אֲשֶׁ֨ר יָרִ֤יב רִיבִי֙ וְעָשָׂ֣ה מִשְׁפָּטִ֔י יוֹצִיאֵ֣נִי לָא֔וֹר אֶרְאֶ֖ה בְּצִדְקָתֽוֹ׃","za֤ʻap yĕhwáh֙ ʼeşá̇̂֔ʼ ki֥̇y ẖátá֖ʼţiy l֑wò ʻad֩ ʼàşě֨r yári֤yb riybiy֙ wĕʻáşá֣̂h mişĕ̌pá̇ti֔y ywòẕiyʼé֣niy láʼ֔wòr ʼerĕʼe֖h bĕ̇ẕidĕqáţֽwò׃"],[7,10,"וְתֵרֶ֤א אֹיַ֙בְתִּי֙ וּתְכַסֶּ֣הָ בוּשָׁ֔ה הָאֹמְרָ֣ה אֵלַ֔י אַיּ֖וֹ יְהוָ֣ה אֱלֹהָ֑יִךְ עֵינַי֙ תִּרְאֶ֣ינָּה בָּ֔הּ עַתָּ֛ה תִּֽהְיֶ֥ה לְמִרְמָ֖ס כְּטִ֥יט חוּצֽוֹת׃","wĕţére֤ʼ ʼòya֙bĕţi̇y֙ ẇţĕkasė֣há bẇşá̌֔h háʼòmĕrá֣h ʼéla֔y ʼaẏ֖wò yĕhwá֣h ʼèlòhá֑yikĕ ʻéynay֙ ţi̇rĕʼe֣yná̇h bá̇֔ḣ ʻaţá֛̇h ţiֽ̇hĕye֥h lĕmirĕmá֖s kĕ̇ti֥yt ẖẇẕֽwòţ׃"],[7,11,"י֖וֹם לִבְנ֣וֹת גְּדֵרָ֑יִךְ י֥וֹם הַה֖וּא יִרְחַק־חֹֽק׃","y֖wòm libĕn֣wòţ gĕ̇dérá֑yikĕ y֥wòm hah֖ẇʼ yirĕẖaq-ẖòֽq׃"],[7,12,"י֥וֹם הוּא֙ וְעָדֶ֣יךָ יָב֔וֹא לְמִנִּ֥י אַשּׁ֖וּר וְעָרֵ֣י מָצ֑וֹר וּלְמִנִּ֤י מָצוֹר֙ וְעַד־נָהָ֔ר וְיָ֥ם מִיָּ֖ם וְהַ֥ר הָהָֽר׃","y֥wòm hẇʼ֙ wĕʻáde֣yká yáb֔wòʼ lĕmini֥̇y ʼaş֖̇̌ẇr wĕʻáré֣y máẕ֑wòr ẇlĕmini֤̇y máẕwòr֙ wĕʻad-náhá֔r wĕyá֥m miyá֖̇m wĕha֥r háháֽr׃"],[7,13,"וְהָיְתָ֥ה הָאָ֛רֶץ לִשְׁמָמָ֖ה עַל־יֹֽשְׁבֶ֑יהָ מִפְּרִ֖י מַֽעַלְלֵיהֶֽם׃ ס","wĕháyĕţá֥h háʼá֛reẕ lişĕ̌mámá֖h ʻal-yòֽşĕ̌be֑yhá mipĕ̇ri֖y maֽʻalĕléyheֽm׃ s"],[7,14,"רְעֵ֧ה עַמְּךָ֣ בְשִׁבְטֶ֗ךָ צֹ֚אן נַֽחֲלָתֶ֔ךָ שֹׁכְנִ֣י לְבָדָ֔ד יַ֖עַר בְּת֣וֹךְ כַּרְמֶ֑ל יִרְע֥וּ בָשָׁ֛ן וְגִלְעָ֖ד כִּימֵ֥י עוֹלָֽם׃","rĕʻé֧h ʻamĕ̇ká֣ bĕşǐbĕte֗ká ẕò֚ʼn naֽẖàláţe֔ká şò̌kĕni֣y lĕbádá֔d ya֖ʻar bĕ̇ţ֣wòkĕ kȧrĕme֑l yirĕʻ֥ẇ báşá֛̌n wĕgilĕʻá֖d ki̇ymé֥y ʻwòláֽm׃"],[7,15,"כִּימֵ֥י צֵאתְךָ֖ מֵאֶ֣רֶץ מִצְרָ֑יִם אַרְאֶ֖נּוּ נִפְלָאֽוֹת׃","ki̇ymé֥y ẕéʼţĕká֖ méʼe֣reẕ miẕĕrá֑yim ʼarĕʼe֖ṅẇ nipĕláʼֽwòţ׃"],[7,16,"יִרְא֤וּ גוֹיִם֙ וְיֵבֹ֔שׁוּ מִכֹּ֖ל גְּבֽוּרָתָ֑ם יָשִׂ֤ימוּ יָד֙ עַל־פֶּ֔ה אָזְנֵיהֶ֖ם תֶּחֱרַֽשְׁנָה׃","yirĕʼ֤ẇ gwòyim֙ wĕyébò֔ş̌ẇ mikò֖̇l gĕ̇bֽẇráţá֑m yáşî֤ymẇ yád֙ ʻal-pė֔h ʼázĕnéyhe֖m ţėẖèraֽşĕ̌náh׃"],[7,17,"יְלַחֲכ֤וּ עָפָר֙ כַּנָּחָ֔שׁ כְּזֹחֲלֵ֣י אֶ֔רֶץ יִרְגְּז֖וּ מִמִּסְגְּרֹֽתֵיהֶ֑ם אֶל־יְהוָ֤ה אֱלֹהֵ֙ינוּ֙ יִפְחָ֔דוּ וְיִֽרְא֖וּ מִמֶּֽךָּ׃","yĕlaẖàk֤ẇ ʻápár֙ kȧná̇ẖá֔ş̌ kĕ̇zòẖàlé֣y ʼe֔reẕ yirĕgĕ̇z֖ẇ mimi̇sĕgĕ̇ròֽţéyhe֑m ʼel-yĕhwá֤h ʼèlòhé֙ynẇ֙ yipĕẖá֔dẇ wĕyiֽrĕʼ֖ẇ mimėֽká̇׃"],[7,18,"מִי־אֵ֣ל כָּמ֗וֹךָ נֹשֵׂ֤א עָוֺן֙ וְעֹבֵ֣ר עַל־פֶּ֔שַׁע לִשְׁאֵרִ֖ית נַחֲלָת֑וֹ לֹא־הֶחֱזִ֤יק לָעַד֙ אַפּ֔וֹ כִּֽי־חָפֵ֥ץ חֶ֖סֶד הֽוּא׃","miy-ʼé֣l ká̇m֗wòká nòşé֤̂ʼ ʻáwֺn֙ wĕʻòbé֣r ʻal-pė֔şǎʻ lişĕ̌ʼéri֖yţ naẖàláţ֑wò lòʼ-heẖèzi֤yq láʻad֙ ʼaṗ֔wò kiֽ̇y-ẖápé֥ẕ ẖe֖sed hֽẇʼ׃"],[7,19,"יָשׁ֣וּב יְרַֽחֲמֵ֔נוּ יִכְבֹּ֖שׁ עֲוֺֽנֹתֵ֑ינוּ וְתַשְׁלִ֛יךְ בִּמְצֻל֥וֹת יָ֖ם כָּל־חַטֹּאותָֽם׃","yáş֣̌ẇb yĕraֽẖàmé֔nẇ yikĕbò֖̇ş̌ ʻàwֺֽnòţé֑ynẇ wĕţaşĕ̌li֛ykĕ bi̇mĕẕul֥wòţ yá֖m ká̇l-ẖatò̇ʼwţáֽm׃"],[7,20,"תִּתֵּ֤ן אֱמֶת֙ לְיַֽעֲקֹ֔ב חֶ֖סֶד לְאַבְרָהָ֑ם אֲשֶׁר־נִשְׁבַּ֥עְתָּ לַאֲבֹתֵ֖ינוּ מִ֥ימֵי קֶֽדֶם׃","ţi̇ţé֤̇n ʼèmeţ֙ lĕyaֽʻàqò֔b ẖe֖sed lĕʼabĕráhá֑m ʼàşěr-nişĕ̌bȧ֥ʻĕţá̇ laʼàbòţé֖ynẇ mi֥yméy qeֽdem׃"]],"fra-giguet-lxx":[[1,1,"Et la parole de Dieu vint à Michée, fils de Morasthi, aux jours de Joatham, Achaz et Ézéchias, rois de Juda, sur les choses qu’il vit concernant Samarie et Jérusalem.","Et la parole de Dieu vint à Michée, fils de Morasthi, aux jours de Joatham, Achaz et Ézéchias, rois de Juda, sur les choses qu’il vit concernant Samarie et Jérusalem."],[1,2,"Écoutez, peuples, ces paroles; que toute la terre soit attentive, et tous ceux qu’elle contient. Et le Seigneur Maître sera parmi nous comme un témoignage, le Seigneur du haut de sa maison sainte.","Écoutez, peuples, ces paroles; que toute la terre soit attentive, et tous ceux qu’elle contient. Et le Seigneur Maître sera parmi nous comme un témoignage, le Seigneur du haut de sa maison sainte."],[1,3,"Car voilà que le Seigneur sortira du lieu où il réside, et il descendra, et il marchera sur les hauteurs de la terre.","Car voilà que le Seigneur sortira du lieu où il réside, et il descendra, et il marchera sur les hauteurs de la terre."],[1,4,"Et sous lui les montagnes seront émues, et les vallées fondront comme la cire devant le feu, et comme les eaux d’une cataracte.","Et sous lui les montagnes seront émues, et les vallées fondront comme la cire devant le feu, et comme les eaux d’une cataracte."],[1,5,"Et tout cela arrivera à cause de l’impiété de Jacob et des péchés de la maison d’Israël. Quelle est l’impiété de Jacob? n’est-ce pas Samarie? Quel est le péché de Juda? n’est-ce pas Jérusalem?","Et tout cela arrivera à cause de l’impiété de Jacob et des péchés de la maison d’Israël. Quelle est l’impiété de Jacob? n’est-ce pas Samarie? Quel est le péché de Juda? n’est-ce pas Jérusalem?"],[1,6,"Je rendrai Samarie comme la cabane d’un garde de vergers dans les champs, comme un plant de vigne; et j’arracherai ses pierres pour les jeter dans le ravin, et je mettrai à découvert ses fondations.","Je rendrai Samarie comme la cabane d’un garde de vergers dans les champs, comme un plant de vigne; et j’arracherai ses pierres pour les jeter dans le ravin, et je mettrai à découvert ses fondations."],[1,7,"Et toutes ses statues tomberont; et tous les salaires qu’elle a reçus seront livrés aux flammes; et j’anéantirai toutes ses idoles; car elle a amassé des salaires de prostitution; et de ces salaires de prostitution elle s’est enrichie.","Et toutes ses statues tomberont; et tous les salaires qu’elle a reçus seront livrés aux flammes; et j’anéantirai toutes ses idoles; car elle a amassé des salaires de prostitution; et de ces salaires de prostitution elle s’est enrichie."],[1,8,"À cause de cela, elle se frappera la poitrine et se lamentera; elle ira nue et déchaussée; ses lamentations seront comme les sifflements du dragon, et ses plaintes comme celles des filles des Sirènes.","À cause de cela, elle se frappera la poitrine et se lamentera; elle ira nue et déchaussée; ses lamentations seront comme les sifflements du dragon, et ses plaintes comme celles des filles des Sirènes."],[1,9,"Car la plaie l’accable; sa plaie s’est étendue jusqu’en Juda, et touche aux portes de mon peuple, à Jérusalem.","Car la plaie l’accable; sa plaie s’est étendue jusqu’en Juda, et touche aux portes de mon peuple, à Jérusalem."],[1,10,"O vous, gens de Geth, ne vous glorifiez pas; vous, gens d’Énacim, n’édifiez pas avec les ruines du temple par dérision; mais répandez de la poussière sur vos tétes par dérision de vous-mêmes!","O vous, gens de Geth, ne vous glorifiez pas; vous, gens d’Énacim, n’édifiez pas avec les ruines du temple par dérision; mais répandez de la poussière sur vos tétes par dérision de vous-mêmes!"],[1,11,"La populeuse Sennaar, qui habite en joie ses villes, n’en est point sortie pour pleurer une maison voisine; elle entendra votre plainte douloureuse.","La populeuse Sennaar, qui habite en joie ses villes, n’en est point sortie pour pleurer une maison voisine; elle entendra votre plainte douloureuse."],[1,12,"Qui a commencé à faire du bien à celle qui habitait dans la douleur? Car les maux sont aussi descendus, par le Seigneur, jusqu’aux portes de Jérusalem,","Qui a commencé à faire du bien à celle qui habitait dans la douleur? Car les maux sont aussi descendus, par le Seigneur, jusqu’aux portes de Jérusalem,"],[1,13,"Avec le tumulte des chars et des cavaliers. Celle qui demeure en Lachis est pour la fille de Sion le principe de son péché; car en toi se sont trouvées les impiétés d’Israël.","Avec le tumulte des chars et des cavaliers. Celle qui demeure en Lachis est pour la fille de Sion le principe de son péché; car en toi se sont trouvées les impiétés d’Israël."],[1,14,"À cause de cela, le Seigneur enverra des vengeurs jusqu’aux héritages de Geth, et jusqu’aux maisons vaines qui ont été vanités pour les rois d’Israël.","À cause de cela, le Seigneur enverra des vengeurs jusqu’aux héritages de Geth, et jusqu’aux maisons vaines qui ont été vanités pour les rois d’Israël."],[1,15,"Et ils emmèneront tes héritiers, ô toi qui demeures en Lachis! L’héritage de gloire de la fille d’Israël ne subsistera pas au delà d’Odollam.","Et ils emmèneront tes héritiers, ô toi qui demeures en Lachis! L’héritage de gloire de la fille d’Israël ne subsistera pas au delà d’Odollam."],[1,16,"Rase-toi, coupe ta chevelure à cause de tes enfants, qui font tes délices; dilate ton veuvage comme un aigle; car on les a emmenés en captivité hors de toi.","Rase-toi, coupe ta chevelure à cause de tes enfants, qui font tes délices; dilate ton veuvage comme un aigle; car on les a emmenés en captivité hors de toi."],[2,1,"Ils se préparent des peines; même sur leurs couches, ils songent à faire le mal; ils le font, dès que le jour paraît, parce qu’ils n’ont pas élevé les mains vers Dieu.","Ils se préparent des peines; même sur leurs couches, ils songent à faire le mal; ils le font, dès que le jour paraît, parce qu’ils n’ont pas élevé les mains vers Dieu."],[2,2,"Ils ont désiré des champs, et ils ont dépouillé des orphelins; ils ont opprimé des familles; ils ont pris l’un avec sa demeure, l’autre avec son héritage.","Ils ont désiré des champs, et ils ont dépouillé des orphelins; ils ont opprimé des familles; ils ont pris l’un avec sa demeure, l’autre avec son héritage."],[2,3,"À cause de cela, le Seigneur a dit: Voilà que je pense à me venger de cette tribu; vous ne relèverez plus la tête, et vous ne marcherez plus droit d’un pas superbe, parce que les temps sont mauvais.","À cause de cela, le Seigneur a dit: Voilà que je pense à me venger de cette tribu; vous ne relèverez plus la tête, et vous ne marcherez plus droit d’un pas superbe, parce que les temps sont mauvais."],[2,4,"En ces jours-là, vous serez des sujets de fables, et l’on chantera sur vous une lamentation, disant: Nous sommes accablés de misère; la part de mon peuple a été mesurée au cordeau, et nul n’était là pour empêcher le ravisseur et le mettre en fuite, et nos champs ont été partagés.","En ces jours-là, vous serez des sujets de fables, et l’on chantera sur vous une lamentation, disant: Nous sommes accablés de misère; la part de mon peuple a été mesurée au cordeau, et nul n’était là pour empêcher le ravisseur et le mettre en fuite, et nos champs ont été partagés."],[2,5,"À cause de cela, nul n’étendra plus le cordeau pour te faire ta part de terre. Dans l’Église du Seigneur,","À cause de cela, nul n’étendra plus le cordeau pour te faire ta part de terre. Dans l’Église du Seigneur,"],[2,6,"Ne versez point de larmes, et qu’on ne pleure point sur ces choses; car il ne rétractera pas ses reproches,","Ne versez point de larmes, et qu’on ne pleure point sur ces choses; car il ne rétractera pas ses reproches,"],[2,7,"Celui qui dit: La maison de Jacob a irrité l’Esprit du Seigneur. N’est-ce point sa coutume? Les paroles du Seigneur ne sont-elles pas justes sur ce peuple? Et n’ont-elles pas cheminé avec droiture?","Celui qui dit: La maison de Jacob a irrité l’Esprit du Seigneur. N’est-ce point sa coutume? Les paroles du Seigneur ne sont-elles pas justes sur ce peuple? Et n’ont-elles pas cheminé avec droiture?"],[2,8,"Jadis mon peuple s’est soulevé en ennemi contre sa paix. On l’a écorché et on lui a enlevé la peau comme pour lui ôter l’espérance, dans les brisements de la guerre.","Jadis mon peuple s’est soulevé en ennemi contre sa paix. On l’a écorché et on lui a enlevé la peau comme pour lui ôter l’espérance, dans les brisements de la guerre."],[2,9,"Les chefs de mon peuple seront précipités de leurs maisons de délices; et à cause de leurs mœurs perverses, ils ont été rejetés. Allez aux montagnes éternelles.","Les chefs de mon peuple seront précipités de leurs maisons de délices; et à cause de leurs mœurs perverses, ils ont été rejetés. Allez aux montagnes éternelles."],[2,10,"Lève-toi et marche; car il n’est plus pour toi de repos à cause de ton impureté. Vous êtes perdus de corruption;","Lève-toi et marche; car il n’est plus pour toi de repos à cause de ton impureté. Vous êtes perdus de corruption;"],[2,11,"Vous avez fui quand personne ne vous poursuivait. L’esprit du mal a produit le mensonge, il s’est infiltré en toi comme le vin et l’ivresse. Et voici ce qui arrivera: d’une goutte de sang de ce peuple,","Vous avez fui quand personne ne vous poursuivait. L’esprit du mal a produit le mensonge, il s’est infiltré en toi comme le vin et l’ivresse. Et voici ce qui arrivera: d’une goutte de sang de ce peuple,"],[2,12,"Il en naîtra la réunion de Jacob et de toutes ses tribus; je recueillerai avec amour les restes d’Israël, et je les ferai retourner au même lieu. Comme des brebis dans l’angoisse, comme un menu troupeau au milieu de son parc, ils s’élanceront des contrées des hommes,","Il en naîtra la réunion de Jacob et de toutes ses tribus; je recueillerai avec amour les restes d’Israël, et je les ferai retourner au même lieu. Comme des brebis dans l’angoisse, comme un menu troupeau au milieu de son parc, ils s’élanceront des contrées des hommes,"],[2,13,"À travers la brèche ouverte devant eux; ils en ont franchi l’ouverture, ils ont passé la porte par où ils étaient sortis; leur roi est devant eux, et le Seigneur sera le premier à leur tête.","À travers la brèche ouverte devant eux; ils en ont franchi l’ouverture, ils ont passé la porte par où ils étaient sortis; leur roi est devant eux, et le Seigneur sera le premier à leur tête."],[3,1,"Et il dira: Écoutez maintenant ces paroles, princes de la maison de Jacob, restes de la maison d’Israël; n’est-ce pas à vous de connaître le jugement?","Et il dira: Écoutez maintenant ces paroles, princes de la maison de Jacob, restes de la maison d’Israël; n’est-ce pas à vous de connaître le jugement?"],[3,2,"Ceux qui haïssent le bien et cherchent le mal, arrachent eux-mêmes la peau de leur corps et la chair de leurs os.","Ceux qui haïssent le bien et cherchent le mal, arrachent eux-mêmes la peau de leur corps et la chair de leurs os."],[3,3,"De même qu’ils ont mangé les chairs de mon peuple, qu’ils l’ont écorché pour lui enlever la peau, qu’ils ont rompu ses os, qu’ils l’ont dépecé, comme les viandes qu’on fait cuire dans une marmite ou une chaudière:","De même qu’ils ont mangé les chairs de mon peuple, qu’ils l’ont écorché pour lui enlever la peau, qu’ils ont rompu ses os, qu’ils l’ont dépecé, comme les viandes qu’on fait cuire dans une marmite ou une chaudière:"],[3,4,"De même ils crieront au Seigneur, et il ne les écoutera pas; et en ce temps-là il détournera d’eux sa face, parce qu’ils ont fait le mal en leurs pratiques contre le peuple.","De même ils crieront au Seigneur, et il ne les écoutera pas; et en ce temps-là il détournera d’eux sa face, parce qu’ils ont fait le mal en leurs pratiques contre le peuple."],[3,5,"Voici ce que dit le Seigneur contre les prophètes qui égarent mon peuple, qui mordent à pleines dents, qui lui annoncent la paix, et qui, si rien n’est donné à leur bouche, excitent la guerre contre lui:","Voici ce que dit le Seigneur contre les prophètes qui égarent mon peuple, qui mordent à pleines dents, qui lui annoncent la paix, et qui, si rien n’est donné à leur bouche, excitent la guerre contre lui:"],[3,6,"À cause de cela, la nuit sera pour vous sans visions, il y aura pour vous ténèbres sans prophéties; et le soleil se couchera sur les prophètes, et pour eux le jour sera obscurci.","À cause de cela, la nuit sera pour vous sans visions, il y aura pour vous ténèbres sans prophéties; et le soleil se couchera sur les prophètes, et pour eux le jour sera obscurci."],[3,7,"Et les voyants qui devinent les songes seront confondus, et les devins seront moqués, et tout le monde parlera contre eux, parce qu’il n’y aura personne pour les écouter.","Et les voyants qui devinent les songes seront confondus, et les devins seront moqués, et tout le monde parlera contre eux, parce qu’il n’y aura personne pour les écouter."],[3,8,"Pour moi, je me remplirai de force, inspiré par le Seigneur, par le jugement et l’autorité, pour faire connaître ses impiétés à Jacob et ses péchés à Israël.","Pour moi, je me remplirai de force, inspiré par le Seigneur, par le jugement et l’autorité, pour faire connaître ses impiétés à Jacob et ses péchés à Israël."],[3,9,"Écoutez donc ces paroles, chefs de la maison de Jacob, restes de la maison d’Israël, vous qui haïssez la justice et pervertissez toute droiture,","Écoutez donc ces paroles, chefs de la maison de Jacob, restes de la maison d’Israël, vous qui haïssez la justice et pervertissez toute droiture,"],[3,10,"Qui bâtissez Sion dans le sang et Jérusalem dans l’iniquité.","Qui bâtissez Sion dans le sang et Jérusalem dans l’iniquité."],[3,11,"Les princes de Jérusalem ont jugé pour des présents; ses prêtres ont parlé pour un salaire; ses prophètes ont prédit pour de l’argent, et ils se sont reposés sur le Seigneur, disant: Est-ce que le Seigneur n’est pas avec nous? Jamais il ne nous arrivera malheur.","Les princes de Jérusalem ont jugé pour des présents; ses prêtres ont parlé pour un salaire; ses prophètes ont prédit pour de l’argent, et ils se sont reposés sur le Seigneur, disant: Est-ce que le Seigneur n’est pas avec nous? Jamais il ne nous arrivera malheur."],[3,12,"À cause de cela, à cause de vous, la charrue passera sur Sion comme sur un champ; Jérusalem ressemblera à la cabane d’un garde de vergers, et la montagne du temple sera une forêt de chênes.","À cause de cela, à cause de vous, la charrue passera sur Sion comme sur un champ; Jérusalem ressemblera à la cabane d’un garde de vergers, et la montagne du temple sera une forêt de chênes."],[4,1,"Et voici ce qui arrivera: au dernier jour, la montagne du Seigneur apparaîtra; on la verra au-dessus des cimes des monts; elle s’élèvera plus haut que les collines. Et les peuples auront hâte de s’en approcher;","Et voici ce qui arrivera: au dernier jour, la montagne du Seigneur apparaîtra; on la verra au-dessus des cimes des monts; elle s’élèvera plus haut que les collines. Et les peuples auront hâte de s’en approcher;"],[4,2,"Et les gentils viendront en grand nombre, et diront Venons, montons sur la montagne du Seigneur, et au temple du Dieu de Jacob. On nous en montrera le chemin, et nous cheminerons en ses sentiers; car de Sion sortira la loi, et de Jérusalem la parole du Seigneur.","Et les gentils viendront en grand nombre, et diront Venons, montons sur la montagne du Seigneur, et au temple du Dieu de Jacob. On nous en montrera le chemin, et nous cheminerons en ses sentiers; car de Sion sortira la loi, et de Jérusalem la parole du Seigneur."],[4,3,"Et il jugera entre beaucoup de peuples, et il châtiera, même au loin, des nations puissantes; et chez elles on forgera les glaives pour en faire des socs de charrue, et des javelines pour en faire des faux; de nation à nation, on ne s’attaquera plus par l’épée, on n’apprendra plus à combattre.","Et il jugera entre beaucoup de peuples, et il châtiera, même au loin, des nations puissantes; et chez elles on forgera les glaives pour en faire des socs de charrue, et des javelines pour en faire des faux; de nation à nation, on ne s’attaquera plus par l’épée, on n’apprendra plus à combattre."],[4,4,"Et chacun se reposera sous sa vigne et sous son figuier; et nul ne leur inspirera de crainte, parce que le Seigneur tout-puissant l’a dit de sa bouche.","Et chacun se reposera sous sa vigne et sous son figuier; et nul ne leur inspirera de crainte, parce que le Seigneur tout-puissant l’a dit de sa bouche."],[4,5,"Tous les peuples alors suivront chacun sa voie; mais nous, nous marcherons au nom du Seigneur, notre Dieu, dans tous les siècles et au delà.","Tous les peuples alors suivront chacun sa voie; mais nous, nous marcherons au nom du Seigneur, notre Dieu, dans tous les siècles et au delà."],[4,6,"En ce jour, dit le Seigneur, je réunirai celle qui a le cœur contrit et celle que j’avais repoussée, et j’accueillerai ceux que j’avais chassés;","En ce jour, dit le Seigneur, je réunirai celle qui a le cœur contrit et celle que j’avais repoussée, et j’accueillerai ceux que j’avais chassés;"],[4,7,"Et je mettrai en réserve celle qui a eu le cœur contrit; et je ferai une nation puissante de celle que j’avais repoussée; et le Seigneur règnera sur elles en la montagne de Sion, depuis ce moment jusqu’à la fin des siècles.","Et je mettrai en réserve celle qui a eu le cœur contrit; et je ferai une nation puissante de celle que j’avais repoussée; et le Seigneur règnera sur elles en la montagne de Sion, depuis ce moment jusqu’à la fin des siècles."],[4,8,"Et toi, vieille tour du troupeau, Sion, ma fille, la principauté te reviendra et rentrera dans tes murs; et le premier royaume de Babylone reviendra à ma fille Jérusalem.","Et toi, vieille tour du troupeau, Sion, ma fille, la principauté te reviendra et rentrera dans tes murs; et le premier royaume de Babylone reviendra à ma fille Jérusalem."],[4,9,"Et maintenant pourquoi as - tu connu le malheur? n’avais-tu pas un roi? Ou ta raison avait-elle péri pour que tu aies senti les douleurs de l’enfantement?","Et maintenant pourquoi as - tu connu le malheur? n’avais-tu pas un roi? Ou ta raison avait-elle péri pour que tu aies senti les douleurs de l’enfantement?"],[4,10,"Souffre et prends courage, et approche, Sion, ma fille; souffre comme une femme qui enfante; car bientôt tu sortiras de tes murs, tu dresseras tes tentes dans la plaine, et tu iras jusqu’à Babylone; puis le Seigneur ton Dieu t’en délivrera, et il te tirera des mains de tes ennemis.","Souffre et prends courage, et approche, Sion, ma fille; souffre comme une femme qui enfante; car bientôt tu sortiras de tes murs, tu dresseras tes tentes dans la plaine, et tu iras jusqu’à Babylone; puis le Seigneur ton Dieu t’en délivrera, et il te tirera des mains de tes ennemis."],[4,11,"Et maintenant, contre toi maintes nations se sont rassemblées, elles disaient: Réjouissons-nous, et que nos yeux surveillent Sion!","Et maintenant, contre toi maintes nations se sont rassemblées, elles disaient: Réjouissons-nous, et que nos yeux surveillent Sion!"],[4,12,"Mais elles ne savaient pas la pensée du Seigneur; elles n’avaient point compris ses conseils; car il les avait rassemblées comme des gerbes dans une aire.","Mais elles ne savaient pas la pensée du Seigneur; elles n’avaient point compris ses conseils; car il les avait rassemblées comme des gerbes dans une aire."],[4,13,"Lève-toi, Sion, ma fille, tombe sur elles comme le fléau; je te donnerai des cornes de fer; je te couvrirai d’armes d’airain, et tu briseras maintes nations, et tu consacreras leurs grains nombreux au Seigneur, et leurs richesses au Seigneur de toute la terre.","Lève-toi, Sion, ma fille, tombe sur elles comme le fléau; je te donnerai des cornes de fer; je te couvrirai d’armes d’airain, et tu briseras maintes nations, et tu consacreras leurs grains nombreux au Seigneur, et leurs richesses au Seigneur de toute la terre."],[5,1,"Maintenant la fille sera investie; le Seigneur a ordonné que nous fussions assiégés, et l’on battra de verges les joues des tribus d’Israël.","Maintenant la fille sera investie; le Seigneur a ordonné que nous fussions assiégés, et l’on battra de verges les joues des tribus d’Israël."],[5,2,"Et toi, Bethlehem, maison d’Éphratha, toi si petite parmi les milliers des fils de Juda, de toi me sortira un rejeton pour être prince d’Israël, et ses origines existent depuis le commencement, de toute éternité.","Et toi, Bethlehem, maison d’Éphratha, toi si petite parmi les milliers des fils de Juda, de toi me sortira un rejeton pour être prince d’Israël, et ses origines existent depuis le commencement, de toute éternité."],[5,3,"À cause de cela, le Seigneur les fera attendre jusqu’au temps de celle qui doit enfanter; elle enfantera, et les restes de leurs frères reviendront aux fils d’Israël.","À cause de cela, le Seigneur les fera attendre jusqu’au temps de celle qui doit enfanter; elle enfantera, et les restes de leurs frères reviendront aux fils d’Israël."],[5,4,"Et le Seigneur s’arrêtera, et il surveillera, et il fera paître son troupeau dans sa force, et ils demeureront dans la gloire du Seigneur leur Dieu. Car alors ils seront glorifiés jusqu’aux extrémités de la terre.","Et le Seigneur s’arrêtera, et il surveillera, et il fera paître son troupeau dans sa force, et ils demeureront dans la gloire du Seigneur leur Dieu. Car alors ils seront glorifiés jusqu’aux extrémités de la terre."],[5,5,"Et ce sera la paix, quand Assur aura envahi votre terre et marché sur vos champs; ensuite sept pasteurs et huit morsures d’hommes seront suscités contre lui.","Et ce sera la paix, quand Assur aura envahi votre terre et marché sur vos champs; ensuite sept pasteurs et huit morsures d’hommes seront suscités contre lui."],[5,6,"Et ils gouverneront Assur par le glaive, et la terre de Nebrod par des retranchements; et le Seigneur vous délivrera d’Assur, après que celui-ci aura envahi votre territoire, et marché sur vos frontières.","Et ils gouverneront Assur par le glaive, et la terre de Nebrod par des retranchements; et le Seigneur vous délivrera d’Assur, après que celui-ci aura envahi votre territoire, et marché sur vos frontières."],[5,7,"Et les restes de Jacob seront parmi les gentils au milieu de maintes nations comme la rosée qui tombe envoyée par le Seigneur, et comme des agneaux dans un pré, afin que nuls ne se rassemblent parmi les fils des hommes.","Et les restes de Jacob seront parmi les gentils au milieu de maintes nations comme la rosée qui tombe envoyée par le Seigneur, et comme des agneaux dans un pré, afin que nuls ne se rassemblent parmi les fils des hommes."],[5,8,"Et les restes de Jacob seront, parmi les gentils, au milieu de maintes nations, comme un lion dans une forêt avec du bétail, et comme un lionceau avec un troupeau de brebis. Partout où il passe, il déchire et ravit, et nul n’est capable de le détruire.","Et les restes de Jacob seront, parmi les gentils, au milieu de maintes nations, comme un lion dans une forêt avec du bétail, et comme un lionceau avec un troupeau de brebis. Partout où il passe, il déchire et ravit, et nul n’est capable de le détruire."],[5,9,"Ta main se lèvera sur ceux qui t’oppriment, et tous tes ennemis seront exterminés.","Ta main se lèvera sur ceux qui t’oppriment, et tous tes ennemis seront exterminés."],[5,10,"Et en ce jour voici ce qui arrivera, dit le Seigneur: Je ferai périr tes chevaux au milieu de toi, et je briserai tes chars;","Et en ce jour voici ce qui arrivera, dit le Seigneur: Je ferai périr tes chevaux au milieu de toi, et je briserai tes chars;"],[5,11,"Je raserai les villes de ta terre, et je détruirai tes forteresses.","Je raserai les villes de ta terre, et je détruirai tes forteresses."],[5,12,"J’ôterai de ta main les sortilèges, et il n’y aura plus de devins avec toi.","J’ôterai de ta main les sortilèges, et il n’y aura plus de devins avec toi."],[5,13,"J’anéantirai tes statues et tes colonnes, et tu n’adoreras plus les œuvres de tes mains.","J’anéantirai tes statues et tes colonnes, et tu n’adoreras plus les œuvres de tes mains."],[5,14,"Je déracinerai les bois sacrés du milieu de tes champs, et j’effacerai tes cités.","Je déracinerai les bois sacrés du milieu de tes champs, et j’effacerai tes cités."],[5,15,"Et dans les transports de ma colère je tirerai vengeance des gentils, parce qu’ils ne m’auront point entendu.","Et dans les transports de ma colère je tirerai vengeance des gentils, parce qu’ils ne m’auront point entendu."],[6,1,"Écoutez donc la parole: Le Seigneur, le Seigneur a dit: Lève-toi, annonce le jugement aux montagnes, et que les collines entendent ta voix!","Écoutez donc la parole: Le Seigneur, le Seigneur a dit: Lève-toi, annonce le jugement aux montagnes, et que les collines entendent ta voix!"],[6,2,"Écoutez, montagnes, le jugement du Seigneur, et vous aussi, vallées, fondements de la terre; car le Seigneur vient en jugement devant son peuple, et il plaidera avec Israël.","Écoutez, montagnes, le jugement du Seigneur, et vous aussi, vallées, fondements de la terre; car le Seigneur vient en jugement devant son peuple, et il plaidera avec Israël."],[6,3,"Mon peuple, que t’ai-je fait? En quoi t’ai-je contristé? En quoi t’ai-je déplu? Réponds-moi.","Mon peuple, que t’ai-je fait? En quoi t’ai-je contristé? En quoi t’ai-je déplu? Réponds-moi."],[6,4,"Est-ce parce que je t’ai fait sortir de la terre d’Égypte, que je t’ai affranchi de la maison de servitude, et que j’ai envoyé devant toi Moïse, Aaron et Marie?","Est-ce parce que je t’ai fait sortir de la terre d’Égypte, que je t’ai affranchi de la maison de servitude, et que j’ai envoyé devant toi Moïse, Aaron et Marie?"],[6,5,"Mon peuple, souviens-toi donc de ce qu’a médité contre toi Balac, roi de Moab, et de la réponse que lui a rapportée Balaam, fils de Béor, depuis Sétim jusqu’à Galgala, afin que l’on connût la justice du Seigneur.","Mon peuple, souviens-toi donc de ce qu’a médité contre toi Balac, roi de Moab, et de la réponse que lui a rapportée Balaam, fils de Béor, depuis Sétim jusqu’à Galgala, afin que l’on connût la justice du Seigneur."],[6,6,"Comment prendrai-je le Seigneur? Comment serai-je agréable à mon Dieu très-haut? Le prendrai-je par des holocaustes, par des veaux d’un an?","Comment prendrai-je le Seigneur? Comment serai-je agréable à mon Dieu très-haut? Le prendrai-je par des holocaustes, par des veaux d’un an?"],[6,7,"Le Seigneur accueillera-t-il des milliers de béliers, des myriades de chèvres grasses? Donnerai-je, pour mes impiétés, les premiers - nés de mes troupeaux, et, pour les péchés de mon âme, le fruit de mes entrailles?","Le Seigneur accueillera-t-il des milliers de béliers, des myriades de chèvres grasses? Donnerai-je, pour mes impiétés, les premiers - nés de mes troupeaux, et, pour les péchés de mon âme, le fruit de mes entrailles?"],[6,8,"O homme, faut-il te dire ce qui est bon? Est-ce que le Seigneur demande de toi quelque chose, sinon que tu pratiques la justice, que tu aimes la miséricorde, et que tu sois prêt à cheminer avec le Seigneur ton Dieu?","O homme, faut-il te dire ce qui est bon? Est-ce que le Seigneur demande de toi quelque chose, sinon que tu pratiques la justice, que tu aimes la miséricorde, et que tu sois prêt à cheminer avec le Seigneur ton Dieu?"],[6,9,"La voix du Seigneur sera invoquée dans la ville, et sauvera ceux qui craignent son nom. Écoute, tribu: Qui donc mettra l’ordre en ta cité?","La voix du Seigneur sera invoquée dans la ville, et sauvera ceux qui craignent son nom. Écoute, tribu: Qui donc mettra l’ordre en ta cité?"],[6,10,"Est-ce le feu? Est-ce la maison de l’impie amassant des trésors iniques, avec une insolente impiété?","Est-ce le feu? Est-ce la maison de l’impie amassant des trésors iniques, avec une insolente impiété?"],[6,11,"Sera-t-il absous, l’homme injuste avec ses fausses balances et ses faux poids en un sac?","Sera-t-il absous, l’homme injuste avec ses fausses balances et ses faux poids en un sac?"],[6,12,"Car c’est ainsi que ceux qui demeurent dans la ville ont amassé leurs richesses impies; et ils ne disent que des mensonges, et dans leur bouche leur langue s’est enorgueillie.","Car c’est ainsi que ceux qui demeurent dans la ville ont amassé leurs richesses impies; et ils ne disent que des mensonges, et dans leur bouche leur langue s’est enorgueillie."],[6,13,"Et moi je commencerai par te frapper, et je t’effacerai à cause de tes crimes.","Et moi je commencerai par te frapper, et je t’effacerai à cause de tes crimes."],[6,14,"Tu mangeras, et ne seras point rassasié, et il y aura sur toi des ténèbres; et le Seigneur se détournera; tu ne seras point, sauvée; et ceux qui échapperont seront livrés au glaive.","Tu mangeras, et ne seras point rassasié, et il y aura sur toi des ténèbres; et le Seigneur se détournera; tu ne seras point, sauvée; et ceux qui échapperont seront livrés au glaive."],[6,15,"Tu sèmeras et ne moissonneras pas; tu pressureras l’olive, et tu ne seras pas oint de son huile; tu pressureras la grappe, et tu n’en boiras pas le vin; et les lois de mon peuple seront abolies.","Tu sèmeras et ne moissonneras pas; tu pressureras l’olive, et tu ne seras pas oint de son huile; tu pressureras la grappe, et tu n’en boiras pas le vin; et les lois de mon peuple seront abolies."],[6,16,"Car tu as gardé les ordonnances de Zambri, et","Car tu as gardé les ordonnances de Zambri, et"],[7,1,"Malheur à moi! me voilà comme celui qui ramasse du chaume en la moisson, ou qui cueille un grappillon de la vendange, n’ayant pas à lui une seule grappe pour en manger les prémices; malheur à mon âme!","Malheur à moi! me voilà comme celui qui ramasse du chaume en la moisson, ou qui cueille un grappillon de la vendange, n’ayant pas à lui une seule grappe pour en manger les prémices; malheur à mon âme!"],[7,2,"Car le juste a péri sur la terre; et parmi les hommes il n’en est pas qui marche droit. Tous sont en justice pour avoir versé le sang; et chacun d’eux accable son prochain sous l’oppression.","Car le juste a péri sur la terre; et parmi les hommes il n’en est pas qui marche droit. Tous sont en justice pour avoir versé le sang; et chacun d’eux accable son prochain sous l’oppression."],[7,3,"Et leurs mains sont prêtes à faire le mal. Le prince exige; le juge dit des paroles douces; et voici le désir de son âme: Je prendrai leurs biens,","Et leurs mains sont prêtes à faire le mal. Le prince exige; le juge dit des paroles douces; et voici le désir de son âme: Je prendrai leurs biens,"],[7,4,"Comme le ver qui ronge, marchant décemment au jour de la visite. Malheur! Vos vengeances, Seigneur, sont venues, et maintenant vont venir leurs lamentations.","Comme le ver qui ronge, marchant décemment au jour de la visite. Malheur! Vos vengeances, Seigneur, sont venues, et maintenant vont venir leurs lamentations."],[7,5,"Ne vous fiez pas à vos amis, n’espérez pas en vos princes; garde-toi même de ton épouse, et ne lui confie quoi que ce soit.","Ne vous fiez pas à vos amis, n’espérez pas en vos princes; garde-toi même de ton épouse, et ne lui confie quoi que ce soit."],[7,6,"Car le fils outragera le père; la fille se révoltera contre sa mère, la bru contre sa belle-mère; l’homme aura pour ennemis tous ceux de sa maison.","Car le fils outragera le père; la fille se révoltera contre sa mère, la bru contre sa belle-mère; l’homme aura pour ennemis tous ceux de sa maison."],[7,7,"Pour moi, je regarderai le Seigneur; j’attendrai le Dieu mon Sauveur, et mon Dieu m’exaucera.","Pour moi, je regarderai le Seigneur; j’attendrai le Dieu mon Sauveur, et mon Dieu m’exaucera."],[7,8,"Ne m’insulte pas, ô mon ennemie, parçe que je suis tombée, je me relèverai; car, si je suis à terre dans les ténèbres, le Seigneur m’éclairera.","Ne m’insulte pas, ô mon ennemie, parçe que je suis tombée, je me relèverai; car, si je suis à terre dans les ténèbres, le Seigneur m’éclairera."],[7,9,"Parce que j’ai péché contre le Seigneur, je supporterai sa colère jusqu’à ce qu’il ait reconnu juste ma cause. Et alors il me rendra justice, et il me ramènera à la lumière, et je verrai son équité.","Parce que j’ai péché contre le Seigneur, je supporterai sa colère jusqu’à ce qu’il ait reconnu juste ma cause. Et alors il me rendra justice, et il me ramènera à la lumière, et je verrai son équité."],[7,10,"Et mon ennemie verra cela; et elle sera couverte de honte, celle qui dit maintenant: Où est le Seigneur ton Dieu? Mes yeux la regarderont alors, et elle sera foulée aux pieds comme la boue des rues.","Et mon ennemie verra cela; et elle sera couverte de honte, celle qui dit maintenant: Où est le Seigneur ton Dieu? Mes yeux la regarderont alors, et elle sera foulée aux pieds comme la boue des rues."],[7,11,"Voici le jour où l’on enduit la brique; ce jour sera celui de ta destruction, et ce jour-là tes lois seront effacées.","Voici le jour où l’on enduit la brique; ce jour sera celui de ta destruction, et ce jour-là tes lois seront effacées."],[7,12,"Et tes villes seront mises au niveau du sol; elles seront partagées entre les Assyriens; et tes forteresses seront partagées, depuis Tyr jusqu’au fleuve, d’une mer à l’autre, et d’une montagne à l’autre.","Et tes villes seront mises au niveau du sol; elles seront partagées entre les Assyriens; et tes forteresses seront partagées, depuis Tyr jusqu’au fleuve, d’une mer à l’autre, et d’une montagne à l’autre."],[7,13,"Et ta terre et tous ceux qui l’habitent seront désolés, à cause des fruits de leur convoitise.","Et ta terre et tous ceux qui l’habitent seront désolés, à cause des fruits de leur convoitise."],[7,14,"Votre verge à la main, Seigneur, paissez les brebis de votre héritage, qui d’elles-mêmes se sont abritées dans la forêt du Carmel. Elles trouveront leur pâture en Basan et Galaad, comme aux jours d’autrefois,","Votre verge à la main, Seigneur, paissez les brebis de votre héritage, qui d’elles-mêmes se sont abritées dans la forêt du Carmel. Elles trouveront leur pâture en Basan et Galaad, comme aux jours d’autrefois,"],[7,15,"Comme aux jours où vous nous avez fait sortir d’Égypte. Vous verrez des prodiges;","Comme aux jours où vous nous avez fait sortir d’Égypte. Vous verrez des prodiges;"],[7,16,"Et les gentils les verront aussi, et ils en seront confondus malgré toute leur puissance, ils se mettront la main sur la bouche, et leurs oreilles n’entendront plus.","Et les gentils les verront aussi, et ils en seront confondus malgré toute leur puissance, ils se mettront la main sur la bouche, et leurs oreilles n’entendront plus."],[7,17,"Ils lécheront la terre comme les serpents qui rampent dans la poussière; ils seront pleins de trouble dans l’enceinte de leurs remparts; ils seront hors d’eux-mêmes, à cause du Seigneur notre Dieu, et ils auront peur de lui.","Ils lécheront la terre comme les serpents qui rampent dans la poussière; ils seront pleins de trouble dans l’enceinte de leurs remparts; ils seront hors d’eux-mêmes, à cause du Seigneur notre Dieu, et ils auront peur de lui."],[7,18,"Qui donc est Dieu comme vous, qui ôtez les péchés, et passez sous silence les impiétés de ce qui reste de votre héritage! Le Seigneur n’a point maintenu le témoignage de sa colère; il se complaît en sa miséricorde;","Qui donc est Dieu comme vous, qui ôtez les péchés, et passez sous silence les impiétés de ce qui reste de votre héritage! Le Seigneur n’a point maintenu le témoignage de sa colère; il se complaît en sa miséricorde;"],[7,19,"Il reviendra; il aura compassion de nous; il submergera nos iniquités; il jettera nos péchés au fond de la mer.","Il reviendra; il aura compassion de nous; il submergera nos iniquités; il jettera nos péchés au fond de la mer."],[7,20,"Il fera ses dons à Jacob, en vérité; il sera miséricordieux envers Abraham, comme il l’a juré à nos pères aux jours d’autrefois.","Il fera ses dons à Jacob, en vérité; il sera miséricordieux envers Abraham, comme il l’a juré à nos pères aux jours d’autrefois."]],"ell-vamvas1850":[[1,1,"Ο λόγος του Κυρίου ο γενόμενος προς Μιχαίαν τον Μωρασθίτην εν ταις ημέραις Ιωάθαμ, Άχαζ και Εζεκίου, βασιλέων του Ιούδα, τον οποίον είδε περί Σαμαρείας και Ιερουσαλήμ.","O lógos tou Kyríou o genómenos pros Michaían ton Mōrasthítēn en tais ēmérais Iōátham, Áchaz kai Ezekíou, basiléōn tou Ioúda, ton opoíon eíde perí Samareías kai Ierousalḗm."],[1,2,"Ακούσατε, πάντες οι λαοί· πρόσεχε, γη, και το πλήρωμα αυτής, και ας ήναι Κύριος ο Θεός μάρτυς εις εσάς, ο Κύριος εκ του ναού του αγίου αυτού.","Akoúsate, pántes oi laoí: próseche, gē, kai to plḗrōma autḗs, kai as ḗnai Kýrios o Theós mártys eis esás, o Kýrios ek tou naoú tou agíou autoú."],[1,3,"Διότι ιδού, ο Κύριος εξέρχεται εκ του τόπου αυτού και θέλει καταβή και πατήσει επί τα ύψη της γης.","Dióti idoú, o Kýrios exérchetai ek tou tópou autoú kai thélei katabḗ kai patḗsei epí ta ýpsē tēs gēs."],[1,4,"Και τα όρη θέλουσιν αναλύσει υποκάτω αυτού και αι κοιλάδες θέλουσι διασχισθή ως κηρός από προσώπου πυρός και ως ύδατα καταφερόμενα εις κατήφορον.","Kai ta órē thélousin analýsei ypokátō autoú kai ai koiládes thélousi diaschisthḗ ōs kērós apó prosṓpou pyrós kai ōs ýdata katapherómena eis katḗphoron."],[1,5,"Διά την ασέβειαν του Ιακώβ είναι άπαν τούτο και διά τας αμαρτίας του οίκου Ισραήλ. Τις είναι η ασέβεια του Ιακώβ; ουχί η Σαμάρεια; και τίνες οι υψηλοί τόποι του Ιούδα; ουχί η Ιερουσαλήμ;","Diá tēn asébeian tou Iakṓb eínai ápan toúto kai diá tas amartías tou oíkou Israḗl. Tis eínai ē asébeia tou Iakṓb? ouchí ē Samáreia? kai tínes oi ypsēloí tópoi tou Ioúda? ouchí ē Ierousalḗm?"],[1,6,"Διά τούτο θέλω καταστήσει την Σαμάρειαν εις σωρούς λίθων αγρού, όπου φυτεύεται αμπελών, και θέλω κατακυλίσει τους λίθους αυτής εις την κοιλάδα και ανακαλύψει τα θεμέλια αυτής.","Diá toúto thélō katastḗsei tēn Samáreian eis sōroús líthōn agroú, ópou phyteúetai ampelṓn, kai thélō katakylísei tous líthous autḗs eis tēn koiláda kai anakalýpsei ta themélia autḗs."],[1,7,"Και πάντα τα γλυπτά αυτής θέλουσι κατακοπή, και πάντα τα μισθώματα αυτής θέλουσι κατακαή εν πυρί, και πάντα τα είδωλα αυτής θέλω εξαφανίσει· διότι από μισθού πορνείας συνήγαγεν αυτά και εις μισθόν πορνείας θέλουσιν επιστρέψει.","Kai pánta ta glyptá autḗs thélousi katakopḗ, kai pánta ta misthṓmata autḗs thélousi katakaḗ en pyrí, kai pánta ta eídōla autḗs thélō exaphanísei: dióti apó misthoú porneías synḗgagen autá kai eis misthón porneías thélousin epistrépsei."],[1,8,"Διά τούτο θέλω θρηνήσει και ολολύξει, θέλω υπάγει εκδεδυμένος και γυμνός, θέλω κάμει θρήνον ως θώων και πένθος ως στρουθοκαμήλων.","Diá toúto thélō thrēnḗsei kai ololýxei, thélō ypágei ekdedyménos kai gymnós, thélō kámei thrḗnon ōs thṓōn kai pénthos ōs strouthokamḗlōn."],[1,9,"Διότι η πληγή αυτής είναι ανίατος, διότι ήλθεν έως του Ιούδα, έφθασεν έως της πύλης του λαού μου, έως της Ιερουσαλήμ.","Dióti ē plēgḗ autḗs eínai aníatos, dióti ḗlthen éōs tou Ioúda, éphthasen éōs tēs pýlēs tou laoú mou, éōs tēs Ierousalḗm."],[1,10,"Μη αναγγείλητε τούτο εις Γαθ, μη πενθήσητε πένθος· εν Βηθ-αφρά κυλίσθητι εις την κόνιν.","Mē anangeílēte toúto eis Gath, mē penthḗsēte pénthos: en Bēth-aphrá kylísthēti eis tēn kónin."],[1,11,"Διάβηθι, η κάτοικος της Σαφίρ, έχουσα γυμνήν την αισχύνην σου· η κάτοικος της Σαανάν ας μη εξέλθη· το πένθος της Βαιθ-εζήλ θέλει λάβει από σας την αρχήν αυτού.","Diábēthi, ē kátoikos tēs Saphír, échousa gymnḗn tēn aischýnēn sou: ē kátoikos tēs Saanán as mē exélthē: to pénthos tēs Baith-ezḗl thélei lábei apó sas tēn archḗn autoú."],[1,12,"Διότι η κάτοικος της Μαρώθ ελυπήθη διά τα αγαθά αυτής, επειδή κατέβη κακόν από του Κυρίου εις την πύλην της Ιερουσαλήμ.","Dióti ē kátoikos tēs Marṓth elypḗthē diá ta agathá autḗs, epeidḗ katébē kakón apó tou Kyríou eis tēn pýlēn tēs Ierousalḗm."],[1,13,"Κάτοικε της Λαχείς, ζεύξον την άμαξαν εις τον ταχύν ίππον· συ, η αρχή της αμαρτίας εις την θυγατέρα της Σιών· διότι αι ασέβειαι του Ισραήλ εν σοι ευρέθησαν.","Kátoike tēs Lacheís, zeúxon tēn ámaxan eis ton tachýn íppon: sy, ē archḗ tēs amartías eis tēn thygatéra tēs Siṓn: dióti ai asébeiai tou Israḗl en soi euréthēsan."],[1,14,"Διά τούτο θέλεις δώσει έγγραφον ελευθερώσεως εις την Μορέσεθ-γάθ· οι οίκοι του Αχζίβ θέλουσι ματαιώσει τας ελπίδας των βασιλέων του Ισραήλ.","Diá toúto théleis dṓsei éngraphon eleutherṓseōs eis tēn Moréseth-gáth: oi oíkoi tou Achzíb thélousi mataiṓsei tas elpídas tōn basiléōn tou Israḗl."],[1,15,"Θέλω έτι φέρει κληρονόμον εις σε, κάτοικε της Μαρησά· θέλει ελθεί έως Οδολλάμ, της δόξης του Ισραήλ.","Thélō éti phérei klēronómon eis se, kátoike tēs Marēsá: thélei eltheí éōs Odollám, tēs dóxēs tou Israḗl."],[1,16,"Φαλακρώθητι και κείρον την κεφαλήν σου διά τα τέκνα σου τα τρυφερά· πλάτυνον την φαλακρότητά σου ως αετός, διότι ηχμαλωτίσθησαν από σου.","Phalakrṓthēti kai keíron tēn kephalḗn sou diá ta tékna sou ta trypherá: plátynon tēn phalakrótētá sou ōs aetós, dióti ēchmalōtísthēsan apó sou."],[2,1,"Ουαί εις τους διαλογιζομένους ανομίαν και μηχανευομένους κακόν εν ταις κλίναις αυτών· μόλις φέγγει η αυγή και πράττουσιν αυτό, διότι είναι εν τη δυνάμει της χειρός αυτών.","Ouaí eis tous dialogizoménous anomían kai mēchaneuoménous kakón en tais klínais autṓn: mólis phéngei ē augḗ kai práttousin autó, dióti eínai en tē dynámei tēs cheirós autṓn."],[2,2,"Και επιθυμούσιν αγρούς και λαμβάνουσι διά της βίας, και οίκους και αρπάζουσιν αυτούς· ούτω διαρπάζουσιν άνθρωπον και τον οίκον αυτού, ναι, άνθρωπον και την κληρονομίαν αυτού.","Kai epithymoúsin agroús kai lambánousi diá tēs bías, kai oíkous kai arpázousin autoús: oútō diarpázousin ánthrōpon kai ton oíkon autoú, nai, ánthrōpon kai tēn klēronomían autoú."],[2,3,"διά τούτο ούτω λέγει Κύριος· Ιδού, εναντίον του γένους τούτου εγώ βουλεύομαι κακόν, εκ του οποίου δεν θέλετε ελευθερώσει τους τραχήλους σας ουδέ θέλετε περιπατεί υπερηφάνως, διότι ο καιρός ούτος είναι κακός.","diá toúto oútō légei Kýrios: Idoú, enantíon tou génous toútou egṓ bouleúomai kakón, ek tou opoíou den thélete eleutherṓsei tous trachḗlous sas oudé thélete peripateí yperēphánōs, dióti o kairós oútos eínai kakós."],[2,4,"Εν τη ημέρα εκείνη θέλει ληφθή παροιμία εναντίον σας, και θέλει θρηνήσει ο θρηνών με θρήνον και ειπεί, Διόλου ηφανίσθημεν· ηλλοίωσε την μερίδα του λαού μου· πως απεμάκρυνεν αυτήν απ' εμού· αντί να αποδώση, διεμέρισε τους αγρούς ημών.","En tē ēméra ekeínē thélei lēphthḗ paroimía enantíon sas, kai thélei thrēnḗsei o thrēnṓn me thrḗnon kai eipeí, Diólou ēphanísthēmen: ēlloíōse tēn merída tou laoú mou: pōs apemákrynen autḗn ap' emoú: antí na apodṓsē, diemérise tous agroús ēmṓn."],[2,5,"Διά τούτο συ δεν θέλεις έχει τινά βάλλοντα σχοινίον διά κλήρον, εν τη συνάξει του Κυρίου.","Diá toúto sy den théleis échei tiná bállonta schoiníon diá klḗron, en tē synáxei tou Kyríou."],[2,6,"Μη προφητεύετε, οι προφητεύοντες· δεν θέλουσι προφητεύσει εις αυτούς· η αισχύνη αυτών δεν θέλει απομακρυνθή.","Mē prophēteúete, oi prophēteúontes: den thélousi prophēteúsei eis autoús: ē aischýnē autṓn den thélei apomakrynthḗ."],[2,7,"Ω συ, ο καλούμενος οίκος Ιακώβ, εσμικρύνθη το πνεύμα του Κυρίου; είναι τοιαύτα τα επιτηδεύματα αυτού; οι λόγοι μου δεν κάμνουσι καλόν εις τον ορθώς περιπατούντα;","Ō sy, o kaloúmenos oíkos Iakṓb, esmikrýnthē to pneúma tou Kyríou? eínai toiaúta ta epitēdeúmata autoú? oi lógoi mou den kámnousi kalón eis ton orthṓs peripatoúnta?"],[2,8,"Και πρότερον ο λαός μου επανέστη ως εχθρός· το επένδυμα μετά του χιτώνος αρπάζετε από των διαβαινόντων αφόβως, των επιστρεφόντων από του πολέμου.","Kai próteron o laós mou epanéstē ōs echthrós: to epéndyma metá tou chitṓnos arpázete apó tōn diabainóntōn aphóbōs, tōn epistrephóntōn apó tou polémou."],[2,9,"Τας γυναίκας του λαού μου εξώσατε από των τερπνών αυτών οίκων· από των τέκνων αυτών αφηρέσατε την δόξαν μου διαπαντός.","Tas gynaíkas tou laoú mou exṓsate apó tōn terpnṓn autṓn oíkōn: apó tōn téknōn autṓn aphērésate tēn dóxan mou diapantós."],[2,10,"Σηκώθητε και αναχωρήσατε, διότι αύτη δεν είναι η ανάπαυσίς σας· επειδή εμιάνθη, θέλει σας αφανίσει, μάλιστα εν σκληρώ αφανισμώ.","Sēkṓthēte kai anachōrḗsate, dióti aútē den eínai ē anápausís sas: epeidḗ emiánthē, thélei sas aphanísei, málista en sklērṓ aphanismṓ."],[2,11,"Εάν τις περιπατή κατά το πνεύμα αυτού και λαλή ψεύδη, λέγων, Θέλω προφητεύσει εις σε περί οίνου και σίκερα, ούτος βεβαίως θέλει είσθαι ο προφήτης του λαού τούτου.","Eán tis peripatḗ katá to pneúma autoú kai lalḗ pseúdē, légōn, Thélō prophēteúsei eis se perí oínou kai síkera, oútos bebaíōs thélei eísthai o prophḗtēs tou laoú toútou."],[2,12,"Θέλω βεβαίως σε συνάξει όλον Ιακώβ· θέλω βεβαίως συλλέξει το υπόλοιπον του Ισραήλ· θέλω θέσει αυτούς ομού ως πρόβατα της Βοσόρρας, ως ποίμνιον εν μέσω της μάνδρας αυτών· μέγαν θόρυβον θέλουσι κάμει εκ του πλήθους των ανθρώπων.","Thélō bebaíōs se synáxei ólon Iakṓb: thélō bebaíōs sylléxei to ypóloipon tou Israḗl: thélō thései autoús omoú ōs próbata tēs Bosórras, ōs poímnion en mésō tēs mándras autṓn: mégan thórybon thélousi kámei ek tou plḗthous tōn anthrṓpōn."],[2,13,"Ο διαρρηγνύων ανέβη έμπροσθεν αυτών· διέρρηξαν και διέβησαν διά της πύλης και εξήλθον δι' αυτής· και ο βασιλεύς αυτών θέλει διαβή έμπροσθεν αυτών και ο Κύριος επί κεφαλής αυτών.","O diarrēgnýōn anébē émprosthen autṓn: diérrēxan kai diébēsan diá tēs pýlēs kai exḗlthon di' autḗs: kai o basileús autṓn thélei diabḗ émprosthen autṓn kai o Kýrios epí kephalḗs autṓn."],[3,1,"Και είπα, Ακούσατε τώρα, αρχηγοί του Ιακώβ και άρχοντες του οίκου Ισραήλ· δεν ανήκει εις εσάς να γνωρίζητε την κρίσιν;","Kai eípa, Akoúsate tṓra, archēgoí tou Iakṓb kai árchontes tou oíkou Israḗl: den anḗkei eis esás na gnōrízēte tēn krísin?"],[3,2,"Οι μισούντες το καλόν και αγαπώντες το κακόν, οι αποσπώντες το δέρμα αυτών επάνωθεν αυτών και την σάρκα αυτών από των οστών αυτών,","Oi misoúntes to kalón kai agapṓntes to kakón, oi apospṓntes to dérma autṓn epánōthen autṓn kai tēn sárka autṓn apó tōn ostṓn autṓn,"],[3,3,"οι κατατρώγοντες έτι την σάρκα του λαού μου και εκδείροντες το δέρμα αυτών επάνωθεν αυτών και συντρίβοντες τα οστά αυτών και κατακόπτοντες αυτά ως διά χύτραν και ως κρέας εν μέσω λέβητος.","oi katatrṓgontes éti tēn sárka tou laoú mou kai ekdeírontes to dérma autṓn epánōthen autṓn kai syntríbontes ta ostá autṓn kai katakóptontes autá ōs diá chýtran kai ōs kréas en mésō lébētos."],[3,4,"Τότε θέλουσι βοήσει προς τον Κύριον, πλην δεν θέλει εισακούσει αυτούς· θέλει μάλιστα κρύψει το πρόσωπον αυτού απ' αυτών εν τω καιρώ εκείνω, διότι εφέρθησαν κακώς εις τας πράξεις αυτών.","Tóte thélousi boḗsei pros ton Kýrion, plēn den thélei eisakoúsei autoús: thélei málista krýpsei to prósōpon autoú ap' autṓn en tō kairṓ ekeínō, dióti ephérthēsan kakṓs eis tas práxeis autṓn."],[3,5,"Ούτω λέγει Κύριος περί των προφητών, οίτινες πλανώσι τον λαόν μου, οίτινες δαγκάνοντες διά των οδόντων αυτών φωνάζουσιν, Ειρήνη· και εάν τις δεν βάλλη τι εις το στόμα αυτών, κηρύττουσιν εναντίον αυτού πόλεμον.","Oútō légei Kýrios perí tōn prophētṓn, oítines planṓsi ton laón mou, oítines dankánontes diá tōn odóntōn autṓn phōnázousin, Eirḗnē: kai eán tis den bállē ti eis to stóma autṓn, kērýttousin enantíon autoú pólemon."],[3,6,"Διά τούτο νυξ θέλει είσθαι εις εσάς αντί οράσεως και σκότος εις εσάς αντί μαντείας· και ο ήλιος θέλει δύσει επί τους προφήτας και η ημέρα θέλει συσκοτάσει επ' αυτούς.","Diá toúto nyx thélei eísthai eis esás antí oráseōs kai skótos eis esás antí manteías: kai o ḗlios thélei dýsei epí tous prophḗtas kai ē ēméra thélei syskotásei ep' autoús."],[3,7,"Τότε θέλουσι καταισχυνθή οι βλέποντες και θέλουσιν εντραπή οι μάντεις· και θέλουσι σκεπάσει τα χείλη αυτών πάντες ούτοι, διότι δεν είναι απόκρισις Θεού.","Tóte thélousi kataischynthḗ oi blépontes kai thélousin entrapḗ oi mánteis: kai thélousi skepásei ta cheílē autṓn pántes oútoi, dióti den eínai apókrisis Theoú."],[3,8,"Αλλ' εγώ βεβαίως είμαι πλήρης δυνάμεως διά του πνεύματος του Κυρίου και κρίσεως και ισχύος, διά να απαγγείλω εις τον Ιακώβ την παράβασιν αυτού και εις τον Ισραήλ την αμαρτίαν αυτού.","All' egṓ bebaíōs eímai plḗrēs dynámeōs diá tou pneúmatos tou Kyríou kai kríseōs kai ischýos, diá na apangeílō eis ton Iakṓb tēn parábasin autoú kai eis ton Israḗl tēn amartían autoú."],[3,9,"Ακούσατε λοιπόν τούτο, αρχηγοί του οίκου Ιακώβ και άρχοντες του οίκου Ισραήλ, οι βδελυττόμενοι την κρίσιν και διαστρέφοντες πάσαν ευθύτητα,","Akoúsate loipón toúto, archēgoí tou oíkou Iakṓb kai árchontes tou oíkou Israḗl, oi bdelyttómenoi tēn krísin kai diastréphontes pásan euthýtēta,"],[3,10,"οι οικοδομούντες την Σιών εν αίματι και την Ιερουσαλήμ εν ανομία.","oi oikodomoúntes tēn Siṓn en aímati kai tēn Ierousalḗm en anomía."],[3,11,"Οι άρχοντες αυτής κρίνουσι με δώρα και οι ιερείς αυτής διδάσκουσιν επί μισθώ και οι προφήται αυτής μαντεύουσιν επί αργυρίω και επαναπαύονται επί τον Κύριον, λέγοντες, Δεν είναι ο Κύριος εν μέσω ημών; κακόν δεν θέλει ελθεί εφ' ημάς.","Oi árchontes autḗs krínousi me dṓra kai oi iereís autḗs didáskousin epí misthṓ kai oi prophḗtai autḗs manteúousin epí argyríō kai epanapaúontai epí ton Kýrion, légontes, Den eínai o Kýrios en mésō ēmṓn? kakón den thélei eltheí eph' ēmás."],[3,12,"Διά τούτο η Σιών εξ αιτίας σας θέλει αροτριασθή ως αγρός, και η Ιερουσαλήμ θέλει γείνει σωροί λίθων, και το όρος του οίκου ως υψηλοί τόποι δρυμού.","Diá toúto ē Siṓn ex aitías sas thélei arotriasthḗ ōs agrós, kai ē Ierousalḗm thélei geínei sōroí líthōn, kai to óros tou oíkou ōs ypsēloí tópoi drymoú."],[4,1,"Και εν ταις εσχάταις ημέραις το όρος του οίκου του Κυρίου θέλει στηριχθή επί της κορυφής των ορέων και υψωθή υπεράνω των βουνών, και λαοί θέλουσι συρρέει εις αυτό.","Kai en tais eschátais ēmérais to óros tou oíkou tou Kyríou thélei stērichthḗ epí tēs koryphḗs tōn oréōn kai ypsōthḗ yperánō tōn bounṓn, kai laoí thélousi syrréei eis autó."],[4,2,"Και έθνη πολλά θέλουσιν υπάγει και ειπεί, Έλθετε και ας αναβώμεν εις το όρος του Κυρίου και εις τον οίκον του Θεού του Ιακώβ· και θέλει διδάξει ημάς τας οδούς αυτού, και θέλομεν περιπατήσει εν ταις τρίβοις αυτού· διότι εκ Σιών θέλει εξέλθει νόμος και λόγος Κυρίου εξ Ιερουσαλήμ.","Kai éthnē pollá thélousin ypágei kai eipeí, Élthete kai as anabṓmen eis to óros tou Kyríou kai eis ton oíkon tou Theoú tou Iakṓb: kai thélei didáxei ēmás tas odoús autoú, kai thélomen peripatḗsei en tais tríbois autoú: dióti ek Siṓn thélei exélthei nómos kai lógos Kyríou ex Ierousalḗm."],[4,3,"Και θέλει κρίνει αναμέσον λαών πολλών και θέλει ελέγξει έθνη ισχυρά, έως εις μακράν· και θέλουσι σφυρηλατήσει τας μαχαίρας αυτών διά υνία και τας λόγχας αυτών διά δρέπανα· δεν θέλει σηκώσει μάχαιραν έθνος εναντίον έθνους ουδέ θέλουσι μάθει πλέον τον πόλεμον.","Kai thélei krínei anaméson laṓn pollṓn kai thélei elénxei éthnē ischyrá, éōs eis makrán: kai thélousi sphyrēlatḗsei tas machaíras autṓn diá ynía kai tas lónchas autṓn diá drépana: den thélei sēkṓsei máchairan éthnos enantíon éthnous oudé thélousi máthei pléon ton pólemon."],[4,4,"Και θέλουσι κάθησθαι έκαστος υπό την άμπελον αυτού και υπό την συκήν αυτού, και δεν θέλει υπάρχει ο εκφοβών· διότι το στόμα του Κυρίου των δυνάμεων ελάλησε.","Kai thélousi káthēsthai ékastos ypó tēn ámpelon autoú kai ypó tēn sykḗn autoú, kai den thélei ypárchei o ekphobṓn: dióti to stóma tou Kyríou tōn dynámeōn elálēse."],[4,5,"Διότι πάντες οι λαοί θέλουσι περιπατεί έκαστος εν τω ονόματι του θεού αυτού· ημείς δε θέλομεν περιπατεί εν τω ονόματι Κυρίου του Θεού ημών εις τον αιώνα και εις τον αιώνα.","Dióti pántes oi laoí thélousi peripateí ékastos en tō onómati tou theoú autoú: ēmeís de thélomen peripateí en tō onómati Kyríou tou Theoú ēmṓn eis ton aiṓna kai eis ton aiṓna."],[4,6,"Εν τη ημέρα εκείνη, λέγει Κύριος, θέλω συνάξει την χωλαίνουσαν και θέλω εισδεχθή την εξωσμένην και εκείνην, την οποίαν έθλιψα.","En tē ēméra ekeínē, légei Kýrios, thélō synáxei tēn chōlaínousan kai thélō eisdechthḗ tēn exōsménēn kai ekeínēn, tēn opoían éthlipsa."],[4,7,"Και θέλω κάμει την χωλαίνουσαν υπόλοιπον και την αποβεβλημένην έθνος ισχυρόν, και ο Κύριος θέλει βασιλεύει επ' αυτούς εν τω όρει Σιών, από του νυν και έως του αιώνος.","Kai thélō kámei tēn chōlaínousan ypóloipon kai tēn apobeblēménēn éthnos ischyrón, kai o Kýrios thélei basileúei ep' autoús en tō órei Siṓn, apó tou nyn kai éōs tou aiṓnos."],[4,8,"Και συ, πύργε του ποιμνίου, οχύρωμα της θυγατρός Σιών, εις σε θέλει ελθεί η πρώτη εξουσία· ναι, θέλει ελθεί το βασίλειον εις την θυγατέρα της Ιερουσαλήμ.","Kai sy, pýrge tou poimníou, ochýrōma tēs thygatrós Siṓn, eis se thélei eltheí ē prṓtē exousía: nai, thélei eltheí to basíleion eis tēn thygatéra tēs Ierousalḗm."],[4,9,"Διά τι τώρα κραυγάζεις δυνατά; δεν είναι βασιλεύς εν σοι; ηφανίσθη ο σύμβουλός σου, ώστε σε κατέλαβον ωδίνες ως τικτούσης;","Diá ti tṓra kraugázeis dynatá? den eínai basileús en soi? ēphanísthē o sýmboulós sou, ṓste se katélabon ōdínes ōs tiktoúsēs?"],[4,10,"Κοιλοπόνει και αγωνίζου, θυγάτηρ Σιών, ως η τίκτουσα, διότι τώρα θέλεις εξέλθει εκ της πόλεως και θέλεις κατοικήσει εν αγρώ και θέλεις υπάγει έως της Βαβυλώνος· εκεί θέλεις ελευθερωθή, εκεί θέλει σε εξαγοράσει ο Κύριος εκ της χειρός των εχθρών σου.","Koilopónei kai agōnízou, thygátēr Siṓn, ōs ē tíktousa, dióti tṓra théleis exélthei ek tēs póleōs kai théleis katoikḗsei en agrṓ kai théleis ypágei éōs tēs Babylṓnos: ekeí théleis eleutherōthḗ, ekeí thélei se exagorásei o Kýrios ek tēs cheirós tōn echthrṓn sou."],[4,11,"Τώρα δε συνήχθησαν εναντίον σου έθνη πολλά λέγοντα, Ας μιανθή και ας επιβλέπη ο οφθαλμός ημών επί την Σιών.","Tṓra de synḗchthēsan enantíon sou éthnē pollá légonta, As mianthḗ kai as epiblépē o ophthalmós ēmṓn epí tēn Siṓn."],[4,12,"Αλλ' αυτοί δεν γνωρίζουσι τους λογισμούς του Κυρίου ουδέ εννοούσι την βουλήν αυτού, ότι συνήγαγεν αυτούς ως δράγματα αλωνίου.","All' autoí den gnōrízousi tous logismoús tou Kyríou oudé ennooúsi tēn boulḗn autoú, óti synḗgagen autoús ōs drágmata alōníou."],[4,13,"Σηκώθητι και αλώνιζε, θυγάτηρ Σιών, διότι θέλω κάμει το κέρας σου σιδηρούν και τας οπλάς σου θέλω κάμει χαλκάς, και θέλεις κατασυντρίψει λαούς πολλούς· και θέλω αφιερώσει τα διαρπάγματα αυτών εις τον Κύριον και την περιουσίαν αυτών εις τον Κύριον πάσης της γης.","Sēkṓthēti kai alṓnize, thygátēr Siṓn, dióti thélō kámei to kéras sou sidēroún kai tas oplás sou thélō kámei chalkás, kai théleis katasyntrípsei laoús polloús: kai thélō aphierṓsei ta diarpágmata autṓn eis ton Kýrion kai tēn periousían autṓn eis ton Kýrion pásēs tēs gēs."],[5,1,"Συναθροίσθητι τώρα εις τάγματα, θυγάτηρ ταγμάτων· έθεσε πολιορκίαν εναντίον ημών· θέλουσι πατάξει τον κριτήν του Ισραήλ εν ράβδω κατά της σιαγόνος.","Synathroísthēti tṓra eis tágmata, thygátēr tagmátōn: éthese poliorkían enantíon ēmṓn: thélousi patáxei ton kritḗn tou Israḗl en rábdō katá tēs siagónos."],[5,2,"Και συ, Βηθλεέμ Εφραθά, η μικρά ώστε να ήσαι μεταξύ των χιλιάδων του Ιούδα, εκ σου θέλει εξέλθει εις εμέ ανήρ διά να ήναι ηγούμενος εν τω Ισραήλ· του οποίου αι έξοδοι είναι απ' αρχής, από ημερών αιώνος.","Kai sy, Bēthleém Ephrathá, ē mikrá ṓste na ḗsai metaxý tōn chiliádōn tou Ioúda, ek sou thélei exélthei eis emé anḗr diá na ḗnai ēgoúmenos en tō Israḗl: tou opoíou ai éxodoi eínai ap' archḗs, apó ēmerṓn aiṓnos."],[5,3,"Διά τούτο θέλει αφήσει αυτούς, έως του καιρού καθ' ον η τίκτουσα θέλει γεννήσει· τότε το υπόλοιπον των αδελφών αυτού θέλει επιστρέψει εις τους υιούς Ισραήλ.","Diá toúto thélei aphḗsei autoús, éōs tou kairoú kath' on ē tíktousa thélei gennḗsei: tóte to ypóloipon tōn adelphṓn autoú thélei epistrépsei eis tous yioús Israḗl."],[5,4,"Και θέλει σταθή και ποιμάνει εν τη ισχύϊ του Κυρίου, εν τη μεγαλειότητι του ονόματος Κυρίου του Θεού αυτού· και θέλουσι κατοικήσει· διότι τώρα θέλει μεγαλυνθή έως των άκρων της γης.","Kai thélei stathḗ kai poimánei en tē ischýï tou Kyríou, en tē megaleiótēti tou onómatos Kyríou tou Theoú autoú: kai thélousi katoikḗsei: dióti tṓra thélei megalynthḗ éōs tōn ákrōn tēs gēs."],[5,5,"Και ούτος θέλει είσθαι ειρήνη. Όταν ο Ασσύριος έλθη εις την γην ημών και όταν πατήση εις τα παλάτια ημών, τότε θέλομεν επεγείρει κατ' αυτού επτά ποιμένας και οκτώ άρχοντας ανθρώπων·","Kai oútos thélei eísthai eirḗnē. Ótan o Assýrios élthē eis tēn gēn ēmṓn kai ótan patḗsē eis ta palátia ēmṓn, tóte thélomen epegeírei kat' autoú eptá poiménas kai oktṓ árchontas anthrṓpōn:"],[5,6,"και θέλουσι ποιμάνει την γην της Ασσυρίας εν ρομφαία και την γην του Νεβρώδ εν ταις εισόδοις αυτού· και θέλει ελευθερώσει ημάς εκ του Ασσυρίου, όταν έλθη εις την γην ημών και όταν πατήση εν τοις ορίοις ημών.","kai thélousi poimánei tēn gēn tēs Assyrías en romphaía kai tēn gēn tou Nebrṓd en tais eisódois autoú: kai thélei eleutherṓsei ēmás ek tou Assyríou, ótan élthē eis tēn gēn ēmṓn kai ótan patḗsē en tois oríois ēmṓn."],[5,7,"Και το υπόλοιπον του Ιακώβ θέλει είσθαι εν μέσω λαών πολλών ως δρόσος από Κυρίου, ως ρανίδες επί χόρτου, όστις δεν προσμένει παρά ανθρώπου ουδέ ελπίζει επί υιούς ανθρώπων.","Kai to ypóloipon tou Iakṓb thélei eísthai en mésō laṓn pollṓn ōs drósos apó Kyríou, ōs ranídes epí chórtou, óstis den prosménei pará anthrṓpou oudé elpízei epí yioús anthrṓpōn."],[5,8,"Και το υπόλοιπον του Ιακώβ θέλει είσθαι μεταξύ εθνών, εν μέσω λαών πολλών, ως λέων μεταξύ κτηνών του δρυμού, ως σκύμνος μεταξύ ποιμνίων προβάτων, όστις διαβαίνων καταπατεί και διασπαράττει και δεν υπάρχει ο ελευθερών.","Kai to ypóloipon tou Iakṓb thélei eísthai metaxý ethnṓn, en mésō laṓn pollṓn, ōs léōn metaxý ktēnṓn tou drymoú, ōs skýmnos metaxý poimníōn probátōn, óstis diabaínōn katapateí kai diasparáttei kai den ypárchei o eleutherṓn."],[5,9,"Η χειρ σου θέλει υψωθή επί τους εναντίους σου, και πάντες οι εχθροί σου θέλουσιν εκκοπή.","Ē cheir sou thélei ypsōthḗ epí tous enantíous sou, kai pántes oi echthroí sou thélousin ekkopḗ."],[5,10,"Και εν τη ημέρα εκείνη, λέγει Κύριος, θέλω εξολοθρεύσει τους ίππους σου εκ μέσου σου, και θέλω απολέσει τας αμάξας σου.","Kai en tē ēméra ekeínē, légei Kýrios, thélō exolothreúsei tous íppous sou ek mésou sou, kai thélō apolései tas amáxas sou."],[5,11,"Και θέλω εξολοθρεύσει τας πόλεις της γης σου, και κατεδαφίσει πάντα τα οχυρώματά σου.","Kai thélō exolothreúsei tas póleis tēs gēs sou, kai katedaphísei pánta ta ochyrṓmatá sou."],[5,12,"Και θέλω εξολοθρεύσει τας μαγείας από της χειρός σου, και δεν θέλεις έχει πλέον μάντεις.","Kai thélō exolothreúsei tas mageías apó tēs cheirós sou, kai den théleis échei pléon mánteis."],[5,13,"Και θέλω εξολοθρεύσει τα γλυπτά σου και τα είδωλά σου εκ μέσου σου, και δεν θέλεις λατρεύσει πλέον το έργον των χειρών σου.","Kai thélō exolothreúsei ta glyptá sou kai ta eídōlá sou ek mésou sou, kai den théleis latreúsei pléon to érgon tōn cheirṓn sou."],[5,14,"Και θέλω ανασπάσει τα άλση σου εκ μέσου σου, και θέλω αφανίσει τας πόλεις σου.","Kai thélō anaspásei ta álsē sou ek mésou sou, kai thélō aphanísei tas póleis sou."],[5,15,"Και θέλω κάμει εκδίκησιν μετά θυμού και μετ' οργής επί τα έθνη, τα οποία δεν μου εισήκουσαν.","Kai thélō kámei ekdíkēsin metá thymoú kai met' orgḗs epí ta éthnē, ta opoía den mou eisḗkousan."],[6,1,"Ακούσατε τώρα ό,τι λέγει ο Κύριος Σηκώθητι, διαδικάσθητι έμπροσθεν των ορέων, και ας ακούσωσιν οι βουνοί την φωνήν σου.","Akoúsate tṓra ó,ti légei o Kýrios Sēkṓthēti, diadikásthēti émprosthen tōn oréōn, kai as akoúsōsin oi bounoí tēn phōnḗn sou."],[6,2,"Ακούσατε, όρη, την κρίσιν του Κυρίου, και σεις, τα ισχυρά θεμέλια της γης διότι ο Κύριος έχει κρίσιν μετά του λαού αυτού και θέλει διαδικασθή μετά του Ισραήλ.","Akoúsate, órē, tēn krísin tou Kyríou, kai seis, ta ischyrá themélia tēs gēs dióti o Kýrios échei krísin metá tou laoú autoú kai thélei diadikasthḗ metá tou Israḗl."],[6,3,"Λαέ μου, τι σοι έκαμα; και εις τι σε παρηνώχλησα; μαρτύρησον κατ' εμού.","Laé mou, ti soi ékama? kai eis ti se parēnṓchlēsa? martýrēson kat' emoú."],[6,4,"Διότι σε ανεβίβασα εκ γης Αιγύπτου και σε ελύτρωσα εξ οίκου δουλείας και εξαπέστειλα έμπροσθέν σου τον Μωϋσήν, τον Ααρών και την Μαριάμ.","Dióti se anebíbasa ek gēs Aigýptou kai se elýtrōsa ex oíkou douleías kai exapésteila émprosthén sou ton Mōÿsḗn, ton Aarṓn kai tēn Mariám."],[6,5,"Λαέ μου, ενθυμήθητι τώρα τι εβουλεύθη Βαλάκ ο βασιλεύς του Μωάβ και τι απεκρίθη προς αυτόν Βαλαάμ ο του Βεώρ από Σιττείμ έως Γαλγάλων, διά να γνωρίσητε την δικαιοσύνην του Κυρίου.","Laé mou, enthymḗthēti tṓra ti ebouleúthē Balák o basileús tou Mōáb kai ti apekríthē pros autón Balaám o tou Beṓr apó Sitteím éōs Galgálōn, diá na gnōrísēte tēn dikaiosýnēn tou Kyríou."],[6,6,"Με τι θέλω ελθεί ενώπιον του Κυρίου, να προσκυνήσω ενώπιον του υψίστου Θεού; θέλω ελθεί ενώπιον αυτού με ολοκαυτώματα, με μόσχους ενιαυσίους;","Me ti thélō eltheí enṓpion tou Kyríou, na proskynḗsō enṓpion tou ypsístou Theoú? thélō eltheí enṓpion autoú me olokautṓmata, me móschous eniausíous?"],[6,7,"Θέλει ευαρεστηθή ο Κύριος εις χιλιάδας κριών ή εις μυριάδας ποταμών ελαίου; θέλω δώσει τον πρωτότοκόν μου διά την παράβασίν μου, τον καρπόν της κοιλίας μου διά την αμαρτίαν της ψυχής μου;","Thélei euarestēthḗ o Kýrios eis chiliádas kriṓn ḗ eis myriádas potamṓn elaíou? thélō dṓsei ton prōtótokón mou diá tēn parábasín mou, ton karpón tēs koilías mou diá tēn amartían tēs psychḗs mou?"],[6,8,"Αυτός σοι έδειξεν, άνθρωπε, τι το καλόν και τι ζητεί ο Κύριος παρά σου, ειμή να πράττης το δίκαιον και να αγαπάς έλεος και να περιπατής ταπεινώς μετά του Θεού σου;","Autós soi édeixen, ánthrōpe, ti to kalón kai ti zēteí o Kýrios pará sou, eimḗ na práttēs to díkaion kai na agapás éleos kai na peripatḗs tapeinṓs metá tou Theoú sou?"],[6,9,"Η φωνή του Κυρίου κράζει προς την πόλιν, και η σοφία θέλει φοβείσθαι το όνομά σου· ακούσατε την ράβδον και τις διώρισεν αυτήν.","Ē phōnḗ tou Kyríou krázei pros tēn pólin, kai ē sophía thélei phobeísthai to ónomá sou: akoúsate tēn rábdon kai tis diṓrisen autḗn."],[6,10,"Υπάρχουσιν έτι οι θησαυροί της ασεβείας εν τω οίκω του ασεβούς και το ελλιπές μέτρον το βδελυκτόν;","Ypárchousin éti oi thēsauroí tēs asebeías en tō oíkō tou aseboús kai to ellipés métron to bdelyktón?"],[6,11,"να δικαιώσω αυτούς με τας ασεβείς πλάστιγγας και με το σακκίον των δολίων ζυγίων;","na dikaiṓsō autoús me tas asebeís plástingas kai me to sakkíon tōn dolíōn zygíōn?"],[6,12,"Διότι οι πλούσιοι αυτής είναι πλήρεις αδικίας, και οι κάτοικοι αυτής ελάλησαν ψεύδη, και η γλώσσα αυτών είναι απατηλή εν τω στόματι αυτών.","Dióti oi ploúsioi autḗs eínai plḗreis adikías, kai oi kátoikoi autḗs elálēsan pseúdē, kai ē glṓssa autṓn eínai apatēlḗ en tō stómati autṓn."],[6,13,"Και εγώ λοιπόν πατάξας θέλω σε αδυνατίσει, θέλω σε ερημώσει εξ αιτίας των αμαρτιών σου.","Kai egṓ loipón patáxas thélō se adynatísei, thélō se erēmṓsei ex aitías tōn amartiṓn sou."],[6,14,"Συ θέλεις τρώγει και δεν θέλεις χορτάζεσθαι, και η πείνά σου θέλει είσθαι εν μέσω σου και θέλεις φύγει αλλά δεν θέλεις διασώσει, και ό,τι διέσωσας, θέλω παραδώσει εις την ρομφαίαν.","Sy théleis trṓgei kai den théleis chortázesthai, kai ē peíná sou thélei eísthai en mésō sou kai théleis phýgei allá den théleis diasṓsei, kai ó,ti diésōsas, thélō paradṓsei eis tēn romphaían."],[6,15,"Συ θέλεις σπείρει και δεν θέλεις θερίσει συ θέλεις πιέσει ελαίας και δεν θέλεις αλειφθή με έλαιον, και γλεύκος και δεν θέλεις πίει οίνον.","Sy théleis speírei kai den théleis therísei sy théleis piései elaías kai den théleis aleiphthḗ me élaion, kai gleúkos kai den théleis píei oínon."],[6,16,"Διότι εφυλάχθησαν τα διατάγματα του Αμρί και πάντα τα έργα του οίκου του Αχαάβ και επορεύθητε εν ταις βουλαίς αυτών διά να σε παραδώσω εις αφανισμόν και τους κατοίκους αυτής εις συριγμόν και θέλετε βαστάσει το όνειδος του λαού μου.","Dióti ephyláchthēsan ta diatágmata tou Amrí kai pánta ta érga tou oíkou tou Achaáb kai eporeúthēte en tais boulaís autṓn diá na se paradṓsō eis aphanismón kai tous katoíkous autḗs eis syrigmón kai thélete bastásei to óneidos tou laoú mou."],[7,1,"Ουαί εις εμέ, διότι είμαι ως επικαρπολογία θέρους, ως επιφυλλίς τρυγητού δεν υπάρχει βότρυς διά να φάγη τις η ψυχή μου επεθύμησε τας απαρχάς των καρπών.","Ouaí eis emé, dióti eímai ōs epikarpología thérous, ōs epiphyllís trygētoú den ypárchei bótrys diá na phágē tis ē psychḗ mou epethýmēse tas aparchás tōn karpṓn."],[7,2,"Ο όσιος απωλέσθη εκ της γης και ο ευθύς δεν υπάρχει μεταξύ των ανθρώπων πάντες ενεδρεύουσι διά αίμα κυνηγούσιν έκαστος τον αδελφόν αυτού.","O ósios apōlésthē ek tēs gēs kai o euthýs den ypárchei metaxý tōn anthrṓpōn pántes enedreúousi diá aíma kynēgoúsin ékastos ton adelphón autoú."],[7,3,"Εις το να κακοποιώσιν ετοιμάζουσι τας χείρας αυτών ο άρχων απαιτεί και ο κριτής κρίνει επί μισθώ· και ο μεγάλος προφέρει την πονηράν αυτού επιθυμίαν, την οποίαν συμπεριστρεφόμενοι εκπληρούσιν.","Eis to na kakopoiṓsin etoimázousi tas cheíras autṓn o árchōn apaiteí kai o kritḗs krínei epí misthṓ: kai o megálos prophérei tēn ponērán autoú epithymían, tēn opoían symperistrephómenoi ekplēroúsin."],[7,4,"Ο καλήτερος αυτών είναι ως άκανθα· ο ευθύς οξύτερος φραγμού ακανθώδους· η ημέρα των φυλάκων σου, η επίσκεψίς σου έφθασε· τώρα θέλει είσθαι η αμηχανία αυτών.","O kalḗteros autṓn eínai ōs ákantha: o euthýs oxýteros phragmoú akanthṓdous: ē ēméra tōn phylákōn sou, ē epískepsís sou éphthase: tṓra thélei eísthai ē amēchanía autṓn."],[7,5,"Μη εμπιστεύεσθε εις φίλον, μη θαρρείτε εις οικείον· φύλαττε τας θύρας του στόματός σου από της συγκαθευδούσης εν τω κόλπω σου·","Mē empisteúesthe eis phílon, mē tharreíte eis oikeíon: phýlatte tas thýras tou stómatós sou apó tēs synkatheudoúsēs en tō kólpō sou:"],[7,6,"διότι ο υιός περιφρονεί τον πατέρα, η θυγάτηρ επανίσταται κατά της μητρός αυτής, η νύμφη κατά της πενθεράς αυτής· οι εχθροί του ανθρώπου είναι οι άνθρωποι της εαυτού οικίας.","dióti o yiós periphroneí ton patéra, ē thygátēr epanístatai katá tēs mētrós autḗs, ē nýmphē katá tēs pentherás autḗs: oi echthroí tou anthrṓpou eínai oi ánthrōpoi tēs eautoú oikías."],[7,7,"Εγώ δε θέλω επιβλέψει επί Κύριον· θέλω προσμείνει τον Θεόν της σωτηρίας μου· ο Θεός μου θέλει μου εισακούσει.","Egṓ de thélō epiblépsei epí Kýrion: thélō prosmeínei ton Theón tēs sōtērías mou: o Theós mou thélei mou eisakoúsei."],[7,8,"Μη ευφραίνου εις εμέ, η εχθρά μου· αν και έπεσα, θέλω σηκωθή· αν και εκάθησα εν σκότει, ο Κύριος θέλει είσθαι φως εις εμέ.","Mē euphraínou eis emé, ē echthrá mou: an kai épesa, thélō sēkōthḗ: an kai ekáthēsa en skótei, o Kýrios thélei eísthai phōs eis emé."],[7,9,"Θέλω υποφέρει την οργήν του Κυρίου, διότι ημάρτησα εις αυτόν, εωσού διαδικάση την δίκην μου και κάμη την κρίσιν μου· θέλει με εξάξει εις το φως, θέλω ιδεί την δικαιοσύνην αυτού.","Thélō ypophérei tēn orgḗn tou Kyríou, dióti ēmártēsa eis autón, eōsoú diadikásē tēn díkēn mou kai kámē tēn krísin mou: thélei me exáxei eis to phōs, thélō ideí tēn dikaiosýnēn autoú."],[7,10,"Και θέλει ιδεί η εχθρά μου, και αισχύνη θέλει περικαλύψει αυτήν, ήτις λέγει προς εμέ, Που είναι Κύριος ο Θεός σου; οι οφθαλμοί μου θέλουσιν ιδεί αυτήν· τώρα θέλει είσθαι εις καταπάτημα ως ο πηλός των οδών.","Kai thélei ideí ē echthrá mou, kai aischýnē thélei perikalýpsei autḗn, ḗtis légei pros emé, Pou eínai Kýrios o Theós sou? oi ophthalmoí mou thélousin ideí autḗn: tṓra thélei eísthai eis katapátēma ōs o pēlós tōn odṓn."],[7,11,"Καθ' ην ημέραν τα τείχη σου μέλλουσι να κτισθώσι, την ημέραν εκείνην θέλει διαδοθή εις μακράν το πρόσταγμα.","Kath' ēn ēméran ta teíchē sou méllousi na ktisthṓsi, tēn ēméran ekeínēn thélei diadothḗ eis makrán to próstagma."],[7,12,"Την ημέραν εκείνην θέλουσιν ελθεί έως εις σε από της Ασσυρίας και των πόλεων της Αιγύπτου και από της Αιγύπτου έως του ποταμού και από θαλάσσης έως θαλάσσης και από όρους έως όρους.","Tēn ēméran ekeínēn thélousin eltheí éōs eis se apó tēs Assyrías kai tōn póleōn tēs Aigýptou kai apó tēs Aigýptou éōs tou potamoú kai apó thalássēs éōs thalássēs kai apó órous éōs órous."],[7,13,"Και η γη θέλει ερημωθή εξ αιτίας των κατοικούντων αυτήν, διά τον καρπόν των πράξεων αυτών.","Kai ē gē thélei erēmōthḗ ex aitías tōn katoikoúntōn autḗn, diá ton karpón tōn práxeōn autṓn."],[7,14,"Ποίμαινε τον λαόν σου εν τη ράβδω σου, το ποίμνιον της κληρονομίας σου, το οποίον κατοικεί μεμονωμένον εν τω δάσει, εν μέσω του Καρμήλου· ας νέμωνται την Βασάν και την Γαλαάδ καθώς εν ταις αρχαίαις ημέραις.","Poímaine ton laón sou en tē rábdō sou, to poímnion tēs klēronomías sou, to opoíon katoikeí memonōménon en tō dásei, en mésō tou Karmḗlou: as némōntai tēn Basán kai tēn Galaád kathṓs en tais archaíais ēmérais."],[7,15,"Καθώς εν ταις ημέραις της εξόδου σου εκ γης Αιγύπτου θέλω δείξει εις αυτόν θαυμάσια.","Kathṓs en tais ēmérais tēs exódou sou ek gēs Aigýptou thélō deíxei eis autón thaumásia."],[7,16,"Τα έθνη θέλουσιν ιδεί και θέλουσι καταισχυνθή διά πάσαν την ισχύν αυτών· θέλουσιν επιθέσει την χείρα επί το στόμα, τα ώτα αυτών θέλουσι κωφωθή.","Ta éthnē thélousin ideí kai thélousi kataischynthḗ diá pásan tēn ischýn autṓn: thélousin epithései tēn cheíra epí to stóma, ta ṓta autṓn thélousi kōphōthḗ."],[7,17,"Θέλουσι γλείφει το χώμα ως όφεις, ως τα ερπετά της γης θέλουσι σύρεσθαι από των τρυπών αυτών· θέλουσιν εκπλαγή εις Κύριον τον Θεόν ημών και θέλουσι φοβηθή από σου.","Thélousi gleíphei to chṓma ōs ópheis, ōs ta erpetá tēs gēs thélousi sýresthai apó tōn trypṓn autṓn: thélousin ekplagḗ eis Kýrion ton Theón ēmṓn kai thélousi phobēthḗ apó sou."],[7,18,"Τις Θεός όμοιός σου, συγχωρών ανομίαν και παραβλέπων την παράβασιν του υπολοίπου της κληρονομίας αυτού; δεν φυλάττει την οργήν αυτού διαπαντός, διότι αυτός αρέσκεται εις το έλεος.","Tis Theós ómoiós sou, synchōrṓn anomían kai parablépōn tēn parábasin tou ypoloípou tēs klēronomías autoú? den phyláttei tēn orgḗn autoú diapantós, dióti autós arésketai eis to éleos."],[7,19,"Θέλει επιστρέψει, θέλει ευσπλαγχνισθή ημάς, θέλει καταστρέψει τας ανομίας ημών· και θέλεις ρίψει πάσας τας αμαρτίας αυτών εις τα βάθη της θαλάσσης.","Thélei epistrépsei, thélei eusplanchnisthḗ ēmás, thélei katastrépsei tas anomías ēmṓn: kai théleis rípsei pásas tas amartías autṓn eis ta báthē tēs thalássēs."],[7,20,"Θέλεις εκτελέσει αλήθειαν εις τον Ιακώβ, έλεος εις τον Αβραάμ, καθώς ώμοσας εις τους πατέρας ημών από των αρχαίων ημερών.","Théleis ektelései alḗtheian eis ton Iakṓb, éleos eis ton Abraám, kathṓs ṓmosas eis tous patéras ēmṓn apó tōn archaíōn ēmerṓn."]],"grc-swete":[[1,1,"ΚAI ἐγένετο λόγος Κυρίου πρὸς Μειχαίαν τὸν τοῦ Μωρασθεὶ ἐν ἡμέραις Ἰωαθὰμ καὶ Ἀχὰζ καὶ Ἐζεκίου βασιλέων Ἰούδα, ὑπέρ ὧν εἶδεν περὶ Σαμαρείας καὶ περὶ Ἰερουσαλήμ.","KAI egéneto lógos Kyríou pròs Meichaían tòn toû Mōrastheì en hēmérais Iōathàm kaì Achàz kaì Ezekíou basiléōn Ioúda, hypér hō̂n eîden perì Samareías kaì perì Ierousalḗm."],[1,2,"Ἀκούσατε, λαοί, λόγους, καὶ προσεχέτω ἡ γῆ καὶ πάντες οἱ ἐν αὐτῇ, καὶ ἔσται κύριος Κύριος ἐν ὑμῖν εἰς μαρτύριον, Κύριος ἐξ οἴκου ἁγίου αὐτοῦ.","Akoúsate, laoí, lógous, kaì prosechétō hē gē̂ kaì pántes hoi en autē̂i, kaì éstai kýrios Kýrios en hymîn eis martýrion, Kýrios ex oíkou hagíou autoû."],[1,3,"διότι ἰδοὺ Κύριος ἐκπορεύεται ἐκ τοῦ τόπου αὐτοῦ, καὶ καταβήσεται ἐπὶ τὰ ὕψη τῆς γῆς,","dióti idoù Kýrios ekporeúetai ek toû tópou autoû, kaì katabḗsetai epì tà hýpsē tē̂s gē̂s,"],[1,4,"καὶ σαλευθήσεται τὰ ὄρη ὑποκάτωθεν αὐτοῦ, καὶ αἱ κοιλάδες τακήσονται ὡς κηρὸς ἀπὸ προσώπου πυρός, καὶ ὡς ὕδωρ καταφερόμενον ἐν καταβάσει.","kaì saleuthḗsetai tà órē hypokátōthen autoû, kaì hai koiládes takḗsontai hōs kēròs apò prosṓpou pyrós, kaì hōs hýdōr katapherómenon en katabásei."],[1,5,"διὰ ἀσέβειαν Ἰακὼβ πάντα ταῦτα, καὶ διὰ ἁμαρτίαν οἴκου Ἰσραήλ. τίς ἡ ἀσέβεια τοῦ Ἰακώβ, οὐ Σαμάρεια καὶ τίς ἡ ἁμαρτία οἵκου Ἰούδα, οὐχὶ Ἰερουσαλήμ;","dià asébeian Iakṑb pánta taûta, kaì dià hamartían oíkou Israḗl. tís hē asébeia toû Iakṓb, ou Samáreia kaì tís hē hamartía hoíkou Ioúda, ouchì Ierousalḗm?"],[1,6,"καὶ θήσομαι Σαμάρειαν εἰς ὀπωροφυλάκιον ἀγροῦ καὶ εἰς φυτίαν ἀμπελῶνος, καὶ κατασπάσω εἰς χάος τοὺς λίθους αὐτῆς, καὶ τὰ θεμέλια αὐτῆς ἀποκαλύψω·","kaì thḗsomai Samáreian eis opōrophylákion agroû kaì eis phytían ampelō̂nos, kaì kataspásō eis cháos toùs líthous autē̂s, kaì tà themélia autē̂s apokalýpsō:"],[1,7,"καὶ πάντα τὰ γλυπτὰ αὐτῆς κατακόψουσιν, καὶ πάντα τὰ μισθώματα αὐτῆς ἐμπρήσουσιν ἐν πυρί, καὶ πάντα τὰ εἴδωλα αὐτῆς θήσομαι εἰς ἀφανισμόν· διότι ἐκ μισθωμάτων πορνείας συνήγαγεν, καὶ ἐκ μισθωμάτων πορνείας συνέστρεψεν.","kaì pánta tà glyptà autē̂s katakópsousin, kaì pánta tà misthṓmata autē̂s emprḗsousin en pyrí, kaì pánta tà eídōla autē̂s thḗsomai eis aphanismón: dióti ek misthōmátōn porneías synḗgagen, kaì ek misthōmátōn porneías synéstrepsen."],[1,8,"ἔυεκεν τούτου κόψεται καὶ θρηνήσει, πορεύσεται ἀνυπόδετος καὶ γυμνή, ποιήσεται κοπετὸν ὡς δρακόντων καὶ πένθος ὡς θυγατέρων σειρήνων·","éyeken toútou kópsetai kaì thrēnḗsei, poreúsetai anypódetos kaì gymnḗ, poiḗsetai kopetòn hōs drakóntōn kaì pénthos hōs thygatérōn seirḗnōn:"],[1,9,"ὅτι κατεκράτησεν ἡ πληγὴ αὐτῆς, διότι ἥλθεν ἕως Ἰούδα καὶ ἥψατο ἕως πύλης λαοῦ μου, ἕως Ἰερουσαλήμ.","hóti katekrátēsen hē plēgḕ autē̂s, dióti hḗlthen héōs Ioúda kaì hḗpsato héōs pýlēs laoû mou, héōs Ierousalḗm."],[1,10,"Οἱ ἐν Γέθ, μὴ μεγαλύνεσθε, οἱ ἐν Ἀκείμ, μὴ ἀνοικοδομεῖτε ἐξ οἴκου καταγέλωτα· γῆν καταπάσασθε καταγέλωτα ὑμῶν·","Hoi en Géth, mḕ megalýnesthe, hoi en Akeím, mḕ anoikodomeîte ex oíkou katagélōta: gē̂n katapásasthe katagélōta hymō̂n:"],[1,11,"κατοικοῦσα καλῶς τὰς πόλεις αὐτῆς, οὐκ ἐξῆλθεν κατοικοῦσα Σεναάρ, κόψασθαι οἶκον ἐχόμενον αὐτῆς· λήμψεται ἐξ ὑμῶν πληγὴν ὀδύνης.","katoikoûsa kalō̂s tàs póleis autē̂s, ouk exē̂lthen katoikoûsa Senaár, kópsasthai oîkon echómenon autē̂s: lḗmpsetai ex hymō̂n plēgḕn odýnēs."],[1,12,"τίς ἡρξατο εἰς ἀγαθὰ κατοικούσῃ ὀδύνας ; ὅτι κατέβη κακὰ παρὰ Κυρίου ἐπὶ πύλας Ἰερουσαλήμ,","tís hērxato eis agathà katoikoúsēi odýnas ? hóti katébē kakà parà Kyríou epì pýlas Ierousalḗm,"],[1,13,"ψόφος ἁρμάτων καὶ ἱππευόντων. κατοικοῦσα λαχεἱς ἀρχηγὸς ἁμαρτίας αὕτη ἐστὶν τῇ θυγατρὶ Σειών, ὅτι ἐν σοὶ εὑρέθησαν ἀσέβειαι τοῦ Ἰσραήλ.","psóphos harmátōn kaì hippeuóntōn. katoikoûsa lachheis archēgòs hamartías haútē estìn tē̂i thygatrì Seiṓn, hóti en soì heuréthēsan asébeiai toû Israḗl."],[1,14,"διὰ τοῦτο δώσει ἐξαποστελλομένους ἕως κληρονομίας Γέθ, οἴκους ματαί ους, εἰς κενὸν ἐγένοντο τοῖς βασιλεῦσιν τοῦ Ἰσραήλ·","dià toûto dṓsei exapostelloménous héōs klēronomías Géth, oíkous mataí ous, eis kenòn egénonto toîs basileûsin toû Israḗl:"],[1,15,"ἕως τοῖς κληρονόμους ἀγάγωσιν, κατοικοῦσα Λάχεις· κληρονομία ἕως Ὀδολλὰμ ἤξει, ἡ δόξα τῆς θυγατρὸς Ἰσραήλ.","héōs toîs klēronómous agágōsin, katoikoûsa Lácheis: klēronomía héōs Odollàm ḗxei, hē dóxa tē̂s thygatròs Israḗl."],[1,16,"ξύρησαι καὶ κεῖραι ἐπὶ τὰ τέκνα τὰ τρυφερά σου, ἐνπλάτυνον τὴν χηρίαν σου ὡς ἀετός, ὅτι ήχμαλωτεύθησαν ἀπὸ σοῦ.","xýrēsai kaì keîrai epì tà tékna tà trypherá sou, enplátynon tḕn chērían sou hōs aetós, hóti ḗchmalōteúthēsan apò soû."],[2,1,"ʼΕγένοντο λογιζόμενοι κόπους καὶ ἐργαζόμενοι κακὰ ἐν ταῖς κοίταῖς αὐτῶν, καὶ ἄμα τῇ ἡμέρᾳ συνετέλουν αὐτά, διότι οὐκ ἥραν πρὸς τὸν θεὸν τὰς χεῖρας αὐτῶν·","ʼEgénonto logizómenoi kópous kaì ergazómenoi kakà en taîs koítaîs autō̂n, kaì áma tē̂i hēmérāi synetéloun autá, dióti ouk hḗran pròs tòn theòn tàs cheîras autō̂n:"],[2,2,"καὶ ἐπεθύμουν ἀγρούς, καὶ διήρπαζον ὀρφανούς, καὶ οἴκους κατεδυνάστευον, καὶ διήρπαζον ἄνδρα καὶ τὸν οἶκον αὐτοῦ, καὶ ἄνδρα καὶ τὴν κληρονομίαν αὐτοῦ.","kaì epethýmoun agroús, kaì diḗrpazon orphanoús, kaì oíkous katedynásteuon, kaì diḗrpazon ándra kaì tòn oîkon autoû, kaì ándra kaì tḕn klēronomían autoû."],[2,3,"διὰ τοῦτο λέγει Κύριος Ἰδοὺ ἐγὼ λογίζομαι ἐπὶ τὴν φυλὴν ταύτην κακά, ἐξ ὦν οὐ μὴ ἄρητε τοὺς τραχήλους ὑμῶν, καὶ οὐ μὴ πορευθῆτε ὄρθοὶ ἐξαίφνης, ὅτι καιρὸς πονηρός ἐστιν.","dià toûto légei Kýrios Idoù egṑ logízomai epì tḕn phylḕn taútēn kaká, ex ō̂n ou mḕ árēte toùs trachḗlous hymō̂n, kaì ou mḕ poreuthē̂te órthoì exaíphnēs, hóti kairòs ponērós estin."],[2,4,"Ἐν τῇ ἡμέρᾳ ἐκείνῃ λημφθήσεται ἐφʼ ὑμᾶς παραβολή, καὶ θρηνηθήσεται θρῆνος ἐν μέλει λέγων αλαιπωρίᾳ ἐταλαιπωρήσαμεν· μερὶς λαοῦ μου κατεμετρήθη ἐν σχοινίῳ, καὶ οὐκ ἦν ὁ κωλύσων αὐτὸν τοῦ ἀποστρέψαι· οἱ ἀγροὶ ἡμῶν διεμερίσθησαν.","En tē̂i hēmérāi ekeínēi lēmphthḗsetai ephʼ hymâs parabolḗ, kaì thrēnēthḗsetai thrē̂nos en mélei légōn alaipōríāi etalaipōrḗsamen: merìs laoû mou katemetrḗthē en schoiníōi, kaì ouk ē̂n ho kōlýsōn autòn toû apostrépsai: hoi agroì hēmō̂n diemerísthēsan."],[2,5,"διὰ τοῦτο οὐκ ἔσται σοι βάλλων σχοινίον ἐν κλήρῳ ἐν ἐκκλησίᾳ Κυρίου.","dià toûto ouk éstai soi bállōn schoiníon en klḗrōi en ekklēsíāi Kyríou."],[2,6,"μὴ κλαίετε δάκρυσιν, μηδέ δακρυέτωσαν ἐπὶ τούτοις· οὐ γὰρ ἀπώσεται ὀνείδη","mḕ klaíete dákrysin, mēdé dakryétōsan epì toútois: ou gàr apṓsetai oneídē"],[2,7,"ὁ λέγων Οἶκος Ἰακὼβ παρώργισεν πνεῦμα Κυρίου. εἰ ταῦτα τὰ ἐπιτηδεύματα αὐτοῦ ἐστίν; οὐχ οἱ λόγοι αὐτοῦ εἰσὶν καλοὶ μετʼ αὐτοῦ, καὶ ὀρθοὶ πεπόρευνται;","ho légōn Oîkos Iakṑb parṓrgisen pneûma Kyríou. ei taûta tà epitēdeúmata autoû estín? ouch hoi lógoi autoû eisìn kaloì metʼ autoû, kaì orthoì pepóreuntai?"],[2,8,"καὶ ἔμπροσθεν ὁ λαός μου εἰς ἔχθραν ἀντέστη· κατέναντι τῆς εἰρήνης αὐτοῦ τὴν δορὰν αὐτοῦ ἐξέδειραν, τοῦ ἀφελέσθαι ἐλπίδα συντριμμὸν πολέμου.","kaì émprosthen ho laós mou eis échthran antéstē: katénanti tē̂s eirḗnēs autoû tḕn doràn autoû exédeiran, toû aphelésthai elpída syntrimmòn polémou."],[2,9,"ἡγούμενοι λαοῦ μου ἀποριφήσονται ἐκ τῶν οἰκιῶν τρυφῆς αὐτῶν, διὰ τὰ πονηρὰ ἐπιτηδεύματα αὐτῶν ἐξώσθησαν. ἐγγίσατε ὄρεσιν αἰωνίοις·","hēgoúmenoi laoû mou aporiphḗsontai ek tō̂n oikiō̂n tryphē̂s autō̂n, dià tà ponērà epitēdeúmata autō̂n exṓsthēsan. engísate óresin aiōníois:"],[2,10,"ἀνάστηθι καὶ πορεύου, ὅτι οὐκ ἔστιν σοι αὕτη ἀνάπαυσις ἕνεκεν ἀκαθαρσίας. διεφθάρητε φθόρῳ,","anástēthi kaì poreúou, hóti ouk éstin soi haútē anápausis héneken akatharsías. diephthárēte phthórōi,"],[2,11,"κατεδιώχθητε οὐδενὸς διώκοντος· πνεῦμα ἔστησεν ψεῦδος, ἐστάλαξέν σοι εἰς οἶνον καὶ μέθυσμα. καὶ ἔσται ἐκ τῆς σταγόνος τοῦ λαοῦ τούτου","katediṓchthēte oudenòs diṓkontos: pneûma éstēsen pseûdos, estálaxén soi eis oînon kaì méthysma. kaì éstai ek tē̂s stagónos toû laoû toútou"],[2,12,"συναγόμενος συναχθήσεται Ἰακὼβ σὺν πᾶσιν· ἐκδεχόμενος ἐκδέξομαι τοὺς καταλοίπους τοῦ Ἰσραήλ, ἐπὶ τὸ αὐτὸ θήσομαι τὴν ἀποστροφὴν αὐτοῦ· ὡς πρόβατα ἐν θλίψει, ὡς ποίμνιον ἐν μέσῳ κοίτης αὐτῶν ἐξαλοῦνται ἐξ ἀνθρώπων·","synagómenos synachthḗsetai Iakṑb sỳn pâsin: ekdechómenos ekdéxomai toùs kataloípous toû Israḗl, epì tò autò thḗsomai tḕn apostrophḕn autoû: hōs próbata en thlípsei, hōs poímnion en mésōi koítēs autō̂n exaloûntai ex anthrṓpōn:"],[2,13,"διὰ τῆς διακοπῆς πρὸ προσώπου αὐτῶν διέκοψαν, καὶ διῆλθον πύλην καὶ ἐξῆλθον δι᾿ αὐτῆς, καὶ ἐξῆλθεν ὁ βασιλεὺς αὐτῶν πρὸ προσώπου αὐτῶν, ὁ δὲ κύριος ἡγήσεται αὐτῶν.","dià tē̂s diakopē̂s prò prosṓpou autō̂n diékopsan, kaì diē̂lthon pýlēn kaì exē̂lthon di᾿ autē̂s, kaì exē̂lthen ho basileùs autō̂n prò prosṓpou autō̂n, ho dè kýrios hēgḗsetai autō̂n."],[3,1,"Καὶ ἐρεῖ Ἀκούσατε δὴ ταῦτα, αἱ ἀρχαὶ οἴκου Ἰακὼβ καὶ οἱ κατάλοιποι οἴκου Ἰσραήλ. οὐχ ὑμῖν ἐστὶν τοῦ γνῶναι τὸ κρίμα;","Kaì ereî Akoúsate dḕ taûta, hai archaì oíkou Iakṑb kaì hoi katáloipoi oíkou Israḗl. ouch hymîn estìn toû gnō̂nai tò kríma?"],[3,2,"μισοῦντες τὰ καλὰ καὶ ζητοῦντες τὰ πονηρά, ἁρπάζοντες τὰ δέρματα αὐτῶν ἀπʼ αὐτῶν καὶ τὰς σάρκας αὐτῶν ἀπὸ τῶν ὀστέων αὐτῶν.","misoûntes tà kalà kaì zētoûntes tà ponērá, harpázontes tà dérmata autō̂n apʼ autō̂n kaì tàs sárkas autō̂n apò tō̂n ostéōn autō̂n."],[3,3,"ὸν τρόπον κατέφαγον τὰς σάρκας τοῦ λαοῦ μου, καὶ τὰ δέρματα αὐτῶν ἀπʼ αὐτῶν ἐξέδειραν, καὶ τὰ ὀστέα αὐτῶν συνέθλασαν καὶ ἐμέλισαν ὡς σάρκας εἰς λέβητα καὶ ὡς κρέα εἰς χύτραν,","òn trópon katéphagon tàs sárkas toû laoû mou, kaì tà dérmata autō̂n apʼ autō̂n exédeiran, kaì tà ostéa autō̂n synéthlasan kaì emélisan hōs sárkas eis lébēta kaì hōs kréa eis chýtran,"],[3,4,"οὕτως κεκράξονται πρὸς Κύριον καὶ οὐκ εἰσακούσεται αὐτῶν· καὶ ἀποστρέψει τὸ πρόσωπον αὐτοῦ ἀπʼ αὐτῶν ἐν τῷ καιρῷ ἐκείνῳ, ἀνθʼ ὦν ἐπονηρεύσαντο ἐν τοῖς ἐπιτηδεύμασιν αὐτῶν ἐπʼ αὐτούς.","hoútōs kekráxontai pròs Kýrion kaì ouk eisakoúsetai autō̂n: kaì apostrépsei tò prósōpon autoû apʼ autō̂n en tō̂i kairō̂i ekeínōi, anthʼ ō̂n eponēreúsanto en toîs epitēdeúmasin autō̂n epʼ autoús."],[3,5,"τάδᾳ λέγει Κύριος ἐπὶ τοὺς προφήτας τοὺς πλανῶντας τὸν λαόν μου, τοὺς δάκνοντας ἐν τοῖς ὀδοῦσιν αὐτῶν καὶ κηρύσσοντας ἐπʼ αὐμ τὸν εἰρήνην, καὶ οὐκ ἐδόθη εἰς τὸ στόμα αὐτῶν, ἤγειραν ἐπʼ αὐτὸν πόλεμον·","tádāi légei Kýrios epì toùs prophḗtas toùs planō̂ntas tòn laón mou, toùs dáknontas en toîs odoûsin autō̂n kaì kērýssontas epʼ aum tòn eirḗnēn, kaì ouk edóthē eis tò stóma autō̂n, ḗgeiran epʼ autòn pólemon:"],[3,6,"διὰ τοῦτο νὺξ ὑμῖν ἔσται ἐξ ὁράσεως, καὶ σκοτία ὑμῖν ἔσται ἐκ μαντείας, καὶ δύσεται ὁ ἥλιος ἐπὶ τοὺς προφήτας, καὶ συσκοτάσει ἐπʼ αὐτοὺς ἡ ἡμέρα·","dià toûto nỳx hymîn éstai ex horáseōs, kaì skotía hymîn éstai ek manteías, kaì dýsetai ho hḗlios epì toùs prophḗtas, kaì syskotásei epʼ autoùs hē hēméra:"],[3,7,"καὶ καταισχυνθήσονται οἱ ὁρῶντες τὰ ἐνύπνια, καὶ καταγελασθήσονται οἵ μάντεις, καὶ καταλαλήσουσιν κατʼ αὐτῶν πάντες αὐτοί, διότι οὐκ ἔσται ὁ εἰσακούων αὐτῶν.","kaì kataischynthḗsontai hoi horō̂ntes tà enýpnia, kaì katagelasthḗsontai hoí mánteis, kaì katalalḗsousin katʼ autō̂n pántes autoí, dióti ouk éstai ho eisakoúōn autō̂n."],[3,8,"ἐὰυ μὴ ἐγὼ ἐμπλήσω ἰσχὺν ἐν πνεύματι Κυρίου καὶ κρίματος καὶ δυναστείας τοῦ ἀπαγγεῖλαι τῷ Ἰακὼβ ἀσεβείας αὐτοῦ καὶ τῷ Ἰσραὴλ ἁμαρτίας αὐτοῦ.","eày mḕ egṑ emplḗsō ischỳn en pneúmati Kyríou kaì krímatos kaì dynasteías toû apangeîlai tō̂i Iakṑb asebeías autoû kaì tō̂i Israḕl hamartías autoû."],[3,9,"ἀκούσατε δὴ ταῦτα, οἱ ἡγούμενοι οἴκου Ἰακὼβ καὶ οἱ κατάλοιποι οἴκου Ἰσραήλ, οἱ βδελυσσόμενοι κρίμα καὶ πάντα τὰ ὀρθὰ διαστρέφοντες,","akoúsate dḕ taûta, hoi hēgoúmenoi oíkou Iakṑb kaì hoi katáloipoi oíkou Israḗl, hoi bdelyssómenoi kríma kaì pánta tà orthà diastréphontes,"],[3,10,"οἱ οἰκοδομοῦντες Σειὼν ἐν αἵμασιν καὶ Ἰερουσαλὴμ ἐν ἀδικίαις·","hoi oikodomoûntes Seiṑn en haímasin kaì Ierousalḕm en adikíais:"],[3,11,"οἱ ἡγούμενοι αὐτῆς μετὰ δώρων ἔκρινον, καὶ οἱ ἱερεῖς αὐτῆς μετὰ μισθοῦ ἀπεκρίνοντο, καὶ οἱ προφῆται αὐτῆς μετὰ ἀργυρίου ἐμαντεύοντο, καὶ ἐπὶ τὸν κύριον ἐπανεπαύοντο λέγοντες Οὐχὶ Κύριος ἐν ἡμῖν ἐστιν; οὐ μὴ ἐπέλθῃ ἐφʼ ἡμᾶς κακά.","hoi hēgoúmenoi autē̂s metà dṓrōn ékrinon, kaì hoi hiereîs autē̂s metà misthoû apekrínonto, kaì hoi prophē̂tai autē̂s metà argyríou emanteúonto, kaì epì tòn kýrion epanepaúonto légontes Ouchì Kýrios en hēmîn estin? ou mḕ epélthēi ephʼ hēmâs kaká."],[3,12,"διὰ τοῦτο δι᾿ ὑμᾶς Σειὼν ὡς ἀγρὸς ἀροτριαθήσεται, καὶ Ἰερουσαλὴμ ὡς ὀπωροφυλάκιον ἔσται, καὶ τὸ ὄρος τοῦ οἴκου εἰς ἄλσος δρυμοί.","dià toûto di᾿ hymâs Seiṑn hōs agròs arotriathḗsetai, kaì Ierousalḕm hōs opōrophylákion éstai, kaì tò óros toû oíkou eis álsos drymoí."],[4,1,"Καὶ ἔσται ἐπʼ ἐσχάτων τῶν ἡμερῶν ἐμφανές τὸ ὄρος τοῦ κυρίου, ἕτοιμον ἐπὶ τὰς κορυφὰς τῶν ὀρέων, καὶ μετεωρισθήσεται ὑπεράνω τῶν βουνῶν· καὶ σπεύσουσιν πρὸς αὐτὸ λαοί,","Kaì éstai epʼ eschátōn tō̂n hēmerō̂n emphanés tò óros toû kyríou, hétoimon epì tàs koryphàs tō̂n oréōn, kaì meteōristhḗsetai hyperánō tō̂n bounō̂n: kaì speúsousin pròs autò laoí,"],[4,2,"καὶ πορεύσονται ἔθνη πολλὰ καὶ ἐροῦσιν Δεῦτε ἀναβῶμεν εἰς τὸ ὄρος Κυρίου καὶ εἰς τὸν οἶκον τοῦ θεοῦ Ἰακώβ· καὶ δείξουσιν ἡμῖν τὴν ὁδὸν αὐτοῦ, καὶ πορευσόμεθα ἐυ ταῖς τρίβοις αὐτοῦ. ὅτι ἐκ Σειὼν ἐξελεύσεται νόμος, καὶ λόγος Κυρίου ἐξ Ἰερουσαλήμ,","kaì poreúsontai éthnē pollà kaì eroûsin Deûte anabō̂men eis tò óros Kyríou kaì eis tòn oîkon toû theoû Iakṓb: kaì deíxousin hēmîn tḕn hodòn autoû, kaì poreusómetha eu taîs tríbois autoû. hóti ek Seiṑn exeleúsetai nómos, kaì lógos Kyríou ex Ierousalḗm,"],[4,3,"καὶ κρινεῖ ἀνὰ μέσον λαῶν πολλῶν, καὶ ἐξελέγξει ἔθνη ἰσχυρὰ ἕως εἰς μακράν· καὶ κατακόψουσιν τὰς όομφαίας αὐτῶν εἰς ἄροτρα καὶ τὰ δόρατα αὐτῶν εἰς δρέπανα, καὶ οὐκέτι μὴ ἀντάρῃ ἔθνος ἐπ ἔθνος ῥομφαἰαν, καὶ οὐκέτι μὴ μάθωσιν πολεμεῖν·","kaì krineî anà méson laō̂n pollō̂n, kaì exelénxei éthnē ischyrà héōs eis makrán: kaì katakópsousin tàs óomphaías autō̂n eis árotra kaì tà dórata autō̂n eis drépana, kaì oukéti mḕ antárēi éthnos ep éthnos rhomphaian, kaì oukéti mḕ máthōsin polemeîn:"],[4,4,"καὶ ἀναπαύσεται ἕκαστος ὑποκάτω ἀμπέλου αὐτοῦ, καὶ ἕκαστος ὑποκάτω συκῆς αὐτοῦ, καὶ οὐκ ἔσται ὁ ἐκφοβῶν, διότι τὸ στόμα Κυρίου ΙΙαντοκράτορος ἐλάλησεν ταῦτα·","kaì anapaúsetai hékastos hypokátō ampélou autoû, kaì hékastos hypokátō sykē̂s autoû, kaì ouk éstai ho ekphobō̂n, dióti tò stóma Kyríou IIantokrátoros elálēsen taûta:"],[4,5,"ὅτι πάντες οἱ λαοὶ πορεύσουται ἕκαστος τὴν ὁδὸν αὐτοῦ, ἡμεῖς δὲ πορευσόμεθα ἐν ὀνόματι Κυρίου θεοῦ ἡμῶν εἰς τὸν αἰῶνα καὶ ἐπέκεινα.","hóti pántes hoi laoì poreúsoutai hékastos tḕn hodòn autoû, hēmeîs dè poreusómetha en onómati Kyríou theoû hēmō̂n eis tòn aiō̂na kaì epékeina."],[4,6,"ἐν τῇ ἡμέρᾳ ἐκείνῃ, λέγει Κύριος, συνάξω τὴν συντετριμμένην, καὶ τὴν ἐξωσμένην εἰσδέξομαι, καὶ οὓς ἀπωσάμην·","en tē̂i hēmérāi ekeínēi, légei Kýrios, synáxō tḕn syntetrimménēn, kaì tḕn exōsménēn eisdéxomai, kaì hoùs apōsámēn:"],[4,7,"καὶ θήσομαι τὴν συντετριμμένην εἰς ὑπόλιμμα, καὶ τὴν ἀπωσμένην εἰς ἔθνος δυνατόν, καὶ βασιλεύσει Κύριος ἐπʼ αὐτοὺς ἐν ὄρει Σειὼν ἀπὸ τοῦ υῦν ἕως εἰς τὸν αἰῶνα.","kaì thḗsomai tḕn syntetrimménēn eis hypólimma, kaì tḕn apōsménēn eis éthnos dynatón, kaì basileúsei Kýrios epʼ autoùs en órei Seiṑn apò toû yûn héōs eis tòn aiō̂na."],[4,8,"καὶ σύ, πύργος ποιμνίου αὐχμώδης, θυγάτηρ Σειών, ἐπὶ σὲ ἥξει, καὶ εἰσελεύσεται ἡ ἀρχὴ ἡ πρώτη, βασιλεία ἐκ Βαβυλῶνος τῇ θυγατὶ Ιερουσαλήμ.","kaì sý, pýrgos poimníou auchmṓdēs, thygátēr Seiṓn, epì sè hḗxei, kaì eiseleúsetai hē archḕ hē prṓtē, basileía ek Babylō̂nos tē̂i thygatì Ierousalḗm."],[4,9,"Καὶ νῦν ἴνα τί ἔγνως κακά ; μὴ βασιλεὺς οὐκ ἧν σοι; ἤ ἡ βουλή σου ἀπώλετο ὅτι κατεκράτησάν σου ὠδῖνες ὡς τικτούσης;","Kaì nŷn ína tí égnōs kaká ? mḕ basileùs ouk hē̂n soi? ḗ hē boulḗ sou apṓleto hóti katekrátēsán sou ōdînes hōs tiktoúsēs?"],[4,10,"ὥδινε καὶ ἀνδρίζου καὶ ἔγγιζε, θυγάτηρ Σειών, ὡς τίκτουσα· διότι νῦν ἐξελεύσῃ ἐκ πόλεως, καὶ κατασκηνώσεις ἐν πεδίῳ, καὶ ἥξεις ἕως Βαβυλῶνος· ἐκεῖθεν δύσεταί σε Κύριος ὁ θεός σου ἐκ χειρὸς ἐχθρῶν σου.","hṓdine kaì andrízou kaì éngize, thygátēr Seiṓn, hōs tíktousa: dióti nŷn exeleúsēi ek póleōs, kaì kataskēnṓseis en pedíōi, kaì hḗxeis héōs Babylō̂nos: ekeîthen dýsetaí se Kýrios ho theós sou ek cheiròs echthrō̂n sou."],[4,11,"καὶ νῦν ἐπισυνήχθη ἐπὶ σὲ ἔθνη πολλὰ λέγοντες Ἐπιχαρούμεθα, καὶ ἐπόψονται ἐπὶ Σειὼν οἱ ὀφθαλμοὶ ἡμῶν.","kaì nŷn episynḗchthē epì sè éthnē pollà légontes Epicharoúmetha, kaì epópsontai epì Seiṑn hoi ophthalmoì hēmō̂n."],[4,12,"αὐτοὶ δὲ οὐκ ἔγνωσαν τὸν λογισμὸν Κυρίου. καὶ οὐ συνῆκαν τὴν βουλὴν αὐτοῦ, ὅτι συνήγαγεν αὐτοὺς ὡς δράγματα ἄλωνος.","autoì dè ouk égnōsan tòn logismòn Kyríou. kaì ou synē̂kan tḕn boulḕn autoû, hóti synḗgagen autoùs hōs drágmata álōnos."],[4,13,"ἀνάστηθι καὶ ἀλόα αὐτούς, θυγάτηρ Σειών, ὅτι τὰ κέρατά σου θήσομαι σιδηρᾶ, καὶ τὰς ὁπλάς σου θήσομαι χαλκᾶς· καὶ κατατήξεις λαοὺς πολλούς, καὶ ἀναθήσεις τῷ κυρίῳ τὸ πλῆθος αὐτῶν, καὶ τὴν ἰσχὺν αὐτῶν τῷ κυρίῳ πάσης τῆς γῆς.","anástēthi kaì alóa autoús, thygátēr Seiṓn, hóti tà kératá sou thḗsomai sidērâ, kaì tàs hoplás sou thḗsomai chalkâs: kaì katatḗxeis laoùs polloús, kaì anathḗseis tō̂i kyríōi tò plē̂thos autō̂n, kaì tḕn ischỳn autō̂n tō̂i kyríōi pásēs tē̂s gē̂s."],[5,1,"νῦν ἐμφραχθήσεται θυγάτηρ ἐμφραγμῷ. συνοχὴν ἔταξεν ἐφʼ ὑμᾶς, ἐν ὸάβδῳ πατάξουσιν ἐπὶ σιαγόνα τὰς πύλας τοῦ Ἰσραήλ.","nŷn emphrachthḗsetai thygátēr emphragmō̂i. synochḕn étaxen ephʼ hymâs, en òábdōi patáxousin epì siagóna tàs pýlas toû Israḗl."],[5,2,"Καὶ σύ, Βηθλέεμ οἶκος Ἐφράθα, ὀλιγοστὸς εἶ τοῦ εἶναι ἐν χιλιάσιν Ἰούδα· ἐξ οὗ μοι ἐξελεύσεται τοῦ εἶναι εἰς ἄρχοντα τοῦ Ἰσραήλ. καὶ ἔξοδοι αὐτοῦ ἀπʼ ἀρχῆς ἐξ ἡμερῶν αἰῶνος.","Kaì sý, Bēthléem oîkos Ephrátha, oligostòs eî toû eînai en chiliásin Ioúda: ex hoû moi exeleúsetai toû eînai eis árchonta toû Israḗl. kaì éxodoi autoû apʼ archē̂s ex hēmerō̂n aiō̂nos."],[5,3,"διὰ τοῦτο δώσει αὐτοὺς ἕως καιροῦ τικτούσης τέξεται, καὶ οἱ ἐπίλοιποι τῶν ἀδελφῶν αὐτῶν ἐπιστρέψουσιν ἐπὶ τοὺς υἱοὺς Ἰσραήλ.","dià toûto dṓsei autoùs héōs kairoû tiktoúsēs téxetai, kaì hoi epíloipoi tō̂n adelphō̂n autō̂n epistrépsousin epì toùs hyioùs Israḗl."],[5,4,"καὶ στήσεται καὶ ὄψεται, καὶ ποιμανεῖ τὸ ποίμνιον αὐτοῦ ἐν ἰσχύι Κύριος. καὶ ἐν τῇ δόξῃ ὀνόματος Κυρίου θεοῦ αὐτῶν ὑπάρξουσιν· διότι νῦν μεγαλυνθήσεται ἕως ἄκρων τῆς γῆς.","kaì stḗsetai kaì ópsetai, kaì poimaneî tò poímnion autoû en ischýi Kýrios. kaì en tē̂i dóxēi onómatos Kyríou theoû autō̂n hypárxousin: dióti nŷn megalynthḗsetai héōs ákrōn tē̂s gē̂s."],[5,5,"καὶ ἔσται αὕτη εἰρήνη· Ἀσσοὺρ ὅταν ἐπέλθῃ ἐπὶ τὴν γῆν ὑμῶν καὶ ὅταν ἐπιβῇ ἐπὶ τὴν χώραν ὑμῶν, καὶ ἐπεγερθήσονται ἐπʼ αὐτὸν ἑπτὰ ποιμένες καὶ ὀκτὼ δήγματα ἀνθρόπων·","kaì éstai haútē eirḗnē: Assoùr hótan epélthēi epì tḕn gē̂n hymō̂n kaì hótan epibē̂i epì tḕn chṓran hymō̂n, kaì epegerthḗsontai epʼ autòn heptà poiménes kaì oktṑ dḗgmata anthrópōn:"],[5,6,"καὶ ποιμανοῦσιν τὸν Ἀσσοὺρ ἐν όομφαίᾳ καὶ τὴν γῆν τοῦ Νεβρὼδ ἐν τῇ τάφρῳ αὐτῆς· καὶ όύσεται ἐκ τοῦ Ἀσσούρ, ὅταν ἐπέλθῃ ἐπὶ τὴν γῆν ὑμῶν καὶ ὅταν ἐπιβῇ ἐπὶ τὰ δρία ὑμῶν.","kaì poimanoûsin tòn Assoùr en óomphaíāi kaì tḕn gē̂n toû Nebrṑd en tē̂i táphrōi autē̂s: kaì óýsetai ek toû Assoúr, hótan epélthēi epì tḕn gē̂n hymō̂n kaì hótan epibē̂i epì tà dría hymō̂n."],[5,7,"καὶ ἔσται τὸ ὑπόλιμμα τοῦ Ἰακὼβ ἐν τοῖς ἔθνεσιν ἐν μέσῳ λαῶν πολλῶν ὡς δρόσος παρὰ Κυρίου πίπτουσα καὶ ὡς ἄρνες ἐπὶ ἄγρωστιν, ὅπως μὴ συναχθῇ μηδεὶς μηδέ ὑποστῇ ἐν υἱοῖς ἀνθρώπων.","kaì éstai tò hypólimma toû Iakṑb en toîs éthnesin en mésōi laō̂n pollō̂n hōs drósos parà Kyríou píptousa kaì hōs árnes epì ágrōstin, hópōs mḕ synachthē̂i mēdeìs mēdé hypostē̂i en hyioîs anthrṓpōn."],[5,8,"καὶ ἔσται τὸ ὑπόλιμμα Ἰακὼβ ἐν τοῖς ξθνεσιν ἐν μέσῳ πολλῶν λαῶν ὡς λέων ἐν κτήνεσιν ἐν τῷ δρυμῷ καὶ ὡς σκύμνος ἐν ποιμνίοις προβάτων, ὃν τρόπον ὅταν διέλθῃ καὶ διαστείλας ἁρπάσῃ, καὶ μὴ ἦ ὁ ἐξαιρούμενος.","kaì éstai tò hypólimma Iakṑb en toîs xthnesin en mésōi pollō̂n laō̂n hōs léōn en ktḗnesin en tō̂i drymō̂i kaì hōs skýmnos en poimníois probátōn, hòn trópon hótan diélthēi kaì diasteílas harpásēi, kaì mḕ ē̂ ho exairoúmenos."],[5,9,"ὑψωθήσεται ἡ χείρ σου ἐπὶ τοὺς θλίβοντάς σε, καὶ πάντες οἱ ἐχθροί σου ἐξολεθρευθήσονται.","hypsōthḗsetai hē cheír sou epì toùs thlíbontás se, kaì pántes hoi echthroí sou exolethreuthḗsontai."],[5,10,"Καὶ ἔσται ἐν τῇ ἡμέρᾳ, λέγει Κύριος. ἐξολεθρεύσω τοὺς ἵππους ἐκ μέσου σου καὶ ἀπολῶ τὰ ἄρματά σου,","Kaì éstai en tē̂i hēmérāi, légei Kýrios. exolethreúsō toùs híppous ek mésou sou kaì apolō̂ tà ármatá sou,"],[5,11,"καὶ ἐξολεθρεύσω τὰς πόλεις τῆς γῆς σου καὶ ἐξαρῶ πάντα τὰ ὐχυρώματά σου,","kaì exolethreúsō tàs póleis tē̂s gē̂s sou kaì exarō̂ pánta tà ychyrṓmatá sou,"],[5,12,"καὶ ἐξολεθρεύσω τὰ φάρμακά σου ἐκ τῶν χειρῶν σου, καὶ ἀποφθεγγόμενοι οὐκ ἔσονται ἐν σοί","kaì exolethreúsō tà phármaká sou ek tō̂n cheirō̂n sou, kaì apophthengómenoi ouk ésontai en soí"],[5,13,"καὶ ἐξολεθρεύσω τὰ γλυπτά σου καὶ τὰς στήλας σου ἐκ μέσου σου, καὶ οὐκέτι μὴ προσκυνήσῃς τοῖς ἔργοις τῶν χειρῶν σου,","kaì exolethreúsō tà glyptá sou kaì tàs stḗlas sou ek mésou sou, kaì oukéti mḕ proskynḗsēis toîs érgois tō̂n cheirō̂n sou,"],[5,14,"καὶ ἐκκόψω τὰ ἄλση ἐκ μέσου σου, καὶ ἀφανιῶ τὰς πόλεις σου,","kaì ekkópsō tà álsē ek mésou sou, kaì aphaniō̂ tàs póleis sou,"],[5,15,"καὶ ποιήσω ἐν ὀργῇ καὶ ἐν θυμῷ ἐκδίκησιν ἐν τοῖς ἔθνεσιν, ἀνθʼ ὅν οὐκ εἰσήκουσαν.","kaì poiḗsō en orgē̂i kaì en thymō̂i ekdíkēsin en toîs éthnesin, anthʼ hón ouk eisḗkousan."],[6,1,"Ἀκούσατε δὴ λόγον. κύριος Κύριος εἶπεν Ἀνάστηθι κρίθητι πρὸς τὰ ὄρη, καὶ ἀκουσάτωσαν οἱ βουνοὶ φωνήν σου.","Akoúsate dḕ lógon. kýrios Kýrios eîpen Anástēthi kríthēti pròs tà órē, kaì akousátōsan hoi bounoì phōnḗn sou."],[6,2,"ἀκούσατε, λαοί, τὴν κρίσιν τοῦ κυρίου, καὶ αἱ φάραγγες θεμέλια τῆς γῆς, ὅτι κρίσις τῷ κυρίῳ πρὸς τὸν λαὸν αὐτοῦ, καὶ μετὰ τοῦ Ἰσραὴλ δίελεγχθήσεται.","akoúsate, laoí, tḕn krísin toû kyríou, kaì hai pháranges themélia tē̂s gē̂s, hóti krísis tō̂i kyríōi pròs tòn laòn autoû, kaì metà toû Israḕl díelenchthḗsetai."],[6,3,"λαός μου, τί ἐποίησά σοι, ἡ τί ἐλύπησά σε, ἡ τί παρηνώχλησά σοι; ἀποκρίθητί μοι.","laós mou, tí epoíēsá soi, hē tí elýpēsá se, hē tí parēnṓchlēsá soi? apokríthētí moi."],[6,4,"διότι ἀνήγαγόν σε ἐκ γῆς Αἰγύπτου, καὶ ἐξ οἴκου δουλίας ἐλυτρωσάμην σε, καὶ ἐξαπέστειλα πρὸ προσώπου σου τὸν Μωσῆν καὶ Ἀαρὼν καὶ Μαριάμ.","dióti anḗgagón se ek gē̂s Aigýptou, kaì ex oíkou doulías elytrōsámēn se, kaì exapésteila prò prosṓpou sou tòn Mōsē̂n kaì Aarṑn kaì Mariám."],[6,5,"λαός μου, μνήσθητι δὴ τί ἐβουλεύσατο κατὰ σοῦ Βαλὰκ βασιλεὺς Μωάβ, καὶ τί ἀπεκρίθη αὐτῷ Βαλαὰμ υἱὸς τοῦ Βεὼρ ἀπὸ τῶν σχοίνων ἕως τοῦ Γαλγάλ, ὅπως γνωσθῇ ἡ δικαιοσύνη τοῦ κυρίου.","laós mou, mnḗsthēti dḕ tí ebouleúsato katà soû Balàk basileùs Mōáb, kaì tí apekríthē autō̂i Balaàm hyiòs toû Beṑr apò tō̂n schoínōn héōs toû Galgál, hópōs gnōsthē̂i hē dikaiosýnē toû kyríou."],[6,6,"ἐν τίνι καταλάβω τὸν κύριον , ἀντιλήμψομαι θεοῦ μου Γψίστου; εἰ καταλήμψομαι αὐτὸν ἐν ὁλοκαυτώμασιν ἐν μόσχοις ἐνιαυσίοις;","en tíni katalábō tòn kýrion , antilḗmpsomai theoû mou Gpsístou? ei katalḗmpsomai autòn en holokautṓmasin en móschois eniausíois?"],[6,7,"εἰ προσδέξεται Κύριος ἐν χιλιάσιν κριῶν ἤ ἐν μυριάσιν χιμάραον πιόνων; εἰ δὰι πρωτότοκά μου ἀσεβείας, καρπὸν κοιλίας μου ὑπέρ ἁμαρτίας ψυχῆς μου;","ei prosdéxetai Kýrios en chiliásin kriō̂n ḗ en myriásin chimáraon piónōn? ei dài prōtótoká mou asebeías, karpòn koilías mou hypér hamartías psychē̂s mou?"],[6,8,"εἰ ἀνηγγέλη σοι, ἄνθρωπε, τί καλόν; ἡ τί Κύριος ἐκζητεῖ παρὰ σοῦ ἀλλʼ ἡ τοῦ ποιεῖν κρίμα καὶ ἀγαπᾶν ἔλεον καὶ ἕτοιμον εἶναι τοῦ πορεύεσθαι μετὰ Κυρίου θεοῦ σου;","ei anēngélē soi, ánthrōpe, tí kalón? hē tí Kýrios ekzēteî parà soû allʼ hē toû poieîn kríma kaì agapân éleon kaì hétoimon eînai toû poreúesthai metà Kyríou theoû sou?"],[6,9,"Φωνὴ Κυρίου τῇ πόλει ἐπικληθήσεται, καὶ σώσει φοβουμένους τὸ ὄνομα αὐτοῦ. ἄκουε, φυλή, καὶ τίς κοσμήσει πόλιν;","Phōnḕ Kyríou tē̂i pólei epiklēthḗsetai, kaì sṓsei phobouménous tò ónoma autoû. ákoue, phylḗ, kaì tís kosmḗsei pólin?"],[6,10,"μὴ πῦρ καὶ οἰκὸς ἀνόμου θησαυρίζων θησαυροὺς ἀνόμους, καὶ μετὰ ὕβρεως ἀδικία;","mḕ pŷr kaì oikòs anómou thēsaurízōn thēsauroùs anómous, kaì metà hýbreōs adikía?"],[6,11,"εζ ὄικαιωθήσεται ἐν ζυγῷ ἄνομος, καὶ ἐν μαρσίππῳ στάθμια δόλου;","ez óikaiōthḗsetai en zygō̂i ánomos, kaì en marsíppōi státhmia dólou?"],[6,12,"ἐξ ὧν τὸν πλοῦτον αὐτῶν ἀσεβείας ἔπλησαν, καὶ οἱ κατοικοῦντες αὐτὴν ἐλάλουν ψεύδη, καὶ ἡ γλῶσσα αὐτῶν, ὑψώθητι ἐν τῷ στόματι αὐτῶν.","ex hō̂n tòn ploûton autō̂n asebeías éplēsan, kaì hoi katoikoûntes autḕn eláloun pseúdē, kaì hē glō̂ssa autō̂n, hypsṓthēti en tō̂i stómati autō̂n."],[6,13,"καὶ ἐγὼ ἄρξομαι τοῦ πατάξαι σε, ἀφανιῶ σε ἐν ταῖς ἁμαρτίαις σου.","kaì egṑ árxomai toû patáxai se, aphaniō̂ se en taîs hamartíais sou."],[6,14,"σὺ φάγεσαι καὶ οὐ μὴ ἐμπλησθῇς, καὶ σκοτάσει ἐν σοὶ καὶ ἐκνεύσει, καὶ σὺ οὐ μὴ διασωθῇς, καὶ ὅσοι ἐὰν διασωθῶσιν εἰς όομφαίαν παραδοθήσονται·","sỳ phágesai kaì ou mḕ emplēsthē̂is, kaì skotásei en soì kaì ekneúsei, kaì sỳ ou mḕ diasōthē̂is, kaì hósoi eàn diasōthō̂sin eis óomphaían paradothḗsontai:"],[6,15,"σὺ σ περεῖς καὶ οὐ μὴ ἀμήσῃς. σὺ πιέσεις ἐλαίαν καὶ οὐ μὴ ἀλείψῃ ἕλαιον, καὶ οἰνον καὶ οὐ μὴ πίητε, καὶ ἀφανισθήσεται νόμιμα λαοῦ μου.","sỳ s pereîs kaì ou mḕ amḗsēis. sỳ piéseis elaían kaì ou mḕ aleípsēi hélaion, kaì oinon kaì ou mḕ píēte, kaì aphanisthḗsetai nómima laoû mou."],[6,16,"καὶ ἐφύλαξας τὰ δικαιώματα Ζαμβρεὶ καὶ πάντα τὰ ἔργα οἴκου Ἀχαάβ, καὶ ἐπορεύθητε ἐν ταῖς ὁδοῖς αὐτῶν, ὅπως παραδῶ σε εἰς ἀφανισμὸν καὶ τοὺς κατοικοῦντας αὐτὴν εἰς συρισμόν, καὶ ὀνείδη λαῶν λήψεσθε.","kaì ephýlaxas tà dikaiṓmata Zambreì kaì pánta tà érga oíkou Achaáb, kaì eporeúthēte en taîs hodoîs autō̂n, hópōs paradō̂ se eis aphanismòn kaì toùs katoikoûntas autḕn eis syrismón, kaì oneídē laō̂n lḗpsesthe."],[7,1,"Οἵμοι ὅτι ἐγενήθην ὡς συνάγων καλάμην ἐν ἀμήτῳ καὶ ὡς ἐπιφυλλίδα ἐν τρυγήτῳ, οὐχ ὑπάρχοντος βότρυος τοῦ φαγεῖν τὰ πρωτόγονα. οἵμοι ψυχή,","Hoímoi hóti egenḗthēn hōs synágōn kalámēn en amḗtōi kaì hōs epiphyllída en trygḗtōi, ouch hypárchontos bótryos toû phageîn tà prōtógona. hoímoi psychḗ,"],[7,2,"ὅτι ἀπόλωλεν εὐσεβὴς ἀπὸ τῆς γῆς. καὶ κατορθῶν ἐν ἀνθρώποις οὐχ ὑπάρχει· πάντες εἰς αἵματα δικάζονται, ἕκαστος τὸν πλησίον αὐτοῦ ἐκθλίβουσιν ἐκθλιβῇ,","hóti apólōlen eusebḕs apò tē̂s gē̂s. kaì katorthō̂n en anthrṓpois ouch hypárchei: pántes eis haímata dikázontai, hékastos tòn plēsíon autoû ekthlíbousin ekthlibē̂i,"],[7,3,"ἐπὶ τὸ κακὸν τὰς χεῖρας αὐτῶν ἑτοιμάζουσιν· ὁ ἄρχων αἰτεῖ, καὶ ὁ κριτῆς εἰρηνικοὺς λόγους ἐλάλησεν, καταθύμιον ψυχῆς αὐτοῦ ἐστιν. καὶ ἐξελοῦμαι τὰ ἀγαθὰ αὐτῶν","epì tò kakòn tàs cheîras autō̂n hetoimázousin: ho árchōn aiteî, kaì ho kritē̂s eirēnikoùs lógous elálēsen, katathýmion psychē̂s autoû estin. kaì exeloûmai tà agathà autō̂n"],[7,4,"ὁὡς σής ἐκτρώγων καὶ βαδίζων ἐπὶ κανόνος ἐν ἡμέρᾳ σκοπιᾶς. οὐαὶ οὐαί, αἱ ἐκδικήσεις σου ἤκασιν, νῦν ἔσονται κλαυθμοὶ αὐτῶν.","hhoōs sḗs ektrṓgōn kaì badízōn epì kanónos en hēmérāi skopiâs. ouaì ouaí, hai ekdikḗseis sou ḗkasin, nŷn ésontai klauthmoì autō̂n."],[7,5,"μὴ καταπιστεύετε ἐν φίλοις, καὶ μή ἐλπίζετε ἐπὶ ἡγουμένοις, ἀπὸ τῆς συνκοίτου σου φύλαξαι τοῦ ἀναθέσθαι τι αὐτῇ·","mḕ katapisteúete en phílois, kaì mḗ elpízete epì hēgouménois, apò tē̂s syn'koítou sou phýlaxai toû anathésthai ti autē̂i:"],[7,6,"διότι υἱὸς ἀτιμάζει πατέρα, θυγάτηρ ἐπαναστήσεται ἐπὶ τήν μητέρα αὐτῆς, νύμφη ἐπὶ τὴν πενθερὰν αὐτῆς, ἐχθροὶ πάντες ἀνδρὸς οἱ ἐν τῷ οἴκῳ αὐτοῦ.","dióti hyiòs atimázei patéra, thygátēr epanastḗsetai epì tḗn mētéra autē̂s, nýmphē epì tḕn pentheràn autē̂s, echthroì pántes andròs hoi en tō̂i oíkōi autoû."],[7,7,"Ἐγὼ δὲ ἐπὶ τὸν κύριον ἐπιβλέψομαι. ὑπομενῶ ἐπὶ τῷ θεῷ τῷ σωτῆρί μου, εἰσακούσεταί μου ὁ θεός μου.","Egṑ dè epì tòn kýrion epiblépsomai. hypomenō̂ epì tō̂i theō̂i tō̂i sōtē̂rí mou, eisakoúsetaí mou ho theós mou."],[7,8,"μὴ ἐπίχαιρέ μοι ἡ ἐχθρά μου ὅτι πέπτωκα, καὶ ἀναστήσομαι· διότι ἐὰν καθίσω ἐν τῷ σκότει, Κύριος φωτιεῖ μοι.","mḕ epíchairé moi hē echthrá mou hóti péptōka, kaì anastḗsomai: dióti eàn kathísō en tō̂i skótei, Kýrios phōtieî moi."],[7,9,"ὀργὴν Κυρίου ὑποίσω ὅτι ἥμαρτον αὐτῷ, ἕως τοῦ δικαιῶσαι αὐτὸν τὴν δίκην μου· καὶ ποιήσει τὸ κρίμα μου καὶ ἐξάξεις με εἰς τὸ φῶς, ὄψομαι τὴν δικαιοσύνην αὐτοῦ·","orgḕn Kyríou hypoísō hóti hḗmarton autō̂i, héōs toû dikaiō̂sai autòn tḕn díkēn mou: kaì poiḗsei tò kríma mou kaì exáxeis me eis tò phō̂s, ópsomai tḕn dikaiosýnēn autoû:"],[7,10,"καὶ ὄψεται ἡ ἐχθρά μου καὶ περιβαλεῖται αἰσχύνην, ἡ λέγουσα πρὸς μέ Ιοῦ Κύριος ὁ θεός σου; οἱ ὀφθαλμοί μου ἐπόψονται αὐτήν, νῦν ἔσται εἰς καταπάτημα ὡς πηλὸς ἐν ταῖς ὁδοῖς.","kaì ópsetai hē echthrá mou kaì peribaleîtai aischýnēn, hē légousa pròs mé Ioû Kýrios ho theós sou? hoi ophthalmoí mou epópsontai autḗn, nŷn éstai eis katapátēma hōs pēlòs en taîs hodoîs."],[7,11,"ἡμέρας ἀλοιφῆς πλίνθου, ἐξάλειψίς σου ἡ ἡμέρα ἐκείνη, καὶ ἀποτρίψεται νόμιμά σου ἡ ἡμέρα ἐκείνη·","hēméras aloiphē̂s plínthou, exáleipsís sou hē hēméra ekeínē, kaì apotrípsetai nómimá sou hē hēméra ekeínē:"],[7,12,"καὶ αἱ πόλεις σου είξουσιν εἰς ὁμαλισμὸν καὶ εἰς διαμερισμὸν Ἀσσυρίων, καὶ αἱ πόλεις σου αἱ ὀχυραὶ εἰς διαμερισμὸν ἀπὸ Τύρου ἕως τοῦ ποταμοῦ, καὶ ἀπὸ θαλάσσης ἕως θαλάσσης, καὶ ἀπὸ ὄρους ἕως τοῦ ὄρους·","kaì hai póleis sou eíxousin eis homalismòn kaì eis diamerismòn Assyríōn, kaì hai póleis sou hai ochyraì eis diamerismòn apò Týrou héōs toû potamoû, kaì apò thalássēs héōs thalássēs, kaì apò órous héōs toû órous:"],[7,13,"καὶ ἔσται ἡ γἡ εἰς ἀφανισμὸν σὺν τοῖς κατοικοῦσιν αὐτήν, ἀπὸ καρπῶν ἐπιτηδευμάτων αὐτῶν.","kaì éstai hē ghē eis aphanismòn sỳn toîs katoikoûsin autḗn, apò karpō̂n epitēdeumátōn autō̂n."],[7,14,"ΓΓΙοίμαινε λαόν σου ἐν ὸάβδῳ σου, πρόβατα κληρονομίας σου, κατασκηνοῦντας καθʼ θαυτοὺς δρυμὸν ἐν μέσῳ τοῦ Καρμήλου· νεμήσονται τὴν Bασανεῖτιν καὶ τὴν Γαλααδεῖτιν καθὼς αἱἡμέραι τοῦ αἰῶνος.","NGIoímaine laón sou en òábdōi sou, próbata klēronomías sou, kataskēnoûntas kathʼ thautoùs drymòn en mésōi toû Karmḗlou: nemḗsontai tḕn Basaneîtin kaì tḕn Galaadeîtin kathṑs hhaiēmérai toû aiō̂nos."],[7,15,"καὶ κατὰ τὰς ἡμέρας ἐξοδίας σου ἐξ Αἰγύπτου ὄψεσθε θαυμαστά·","kaì katà tàs hēméras exodías sou ex Aigýptou ópsesthe thaumastá:"],[7,16,"ὄψονται ἔθνη καὶ καταισχυνθήσονται καὶ ἐκ πάσης τῆς ἰσχύος αὐτῶν, ἐπιθήσουσιν χεῖρας ἐπὶ τὸ στόμα αὐτῶν, τὰ ὦτα αὐτῶν ἀποκωφωθήσονται,","ópsontai éthnē kaì kataischynthḗsontai kaì ek pásēs tē̂s ischýos autō̂n, epithḗsousin cheîras epì tò stóma autō̂n, tà ō̂ta autō̂n apokōphōthḗsontai,"],[7,17,"λίξουσιν χοῦν ὡς ὄφις σύροντες γῆν, συγχυθήσονται ἐν συνκλεισμῷ αὐτῶν· ἐπὶ τῷ κυρίῳ θεῷ ἡμῶν ἐκστήσονται, καὶ φοβηθήσονται ἀπὸ σοῦ.","líxousin choûn hōs óphis sýrontes gē̂n, synchythḗsontai en syn'kleismō̂i autō̂n: epì tō̂i kyríōi theō̂i hēmō̂n ekstḗsontai, kaì phobēthḗsontai apò soû."],[7,18,"Τός θεὸς ὥσπερ σύ; ἐξαίρων ἀνομίας καὶ ὑπερβαίνων ἀσεβείας τοῖς καταλοίποις τῆς κληρονομίας αὐτοῦ· καὶ οὐ συνέσχεν εἰς μαρτύριον ὀργὴν αὐτοῦ, ὅτι θελητὴς ἐλέους ἐστίν.","Tós theòs hṓsper sý? exaírōn anomías kaì hyperbaínōn asebeías toîs kataloípois tē̂s klēronomías autoû: kaì ou synéschen eis martýrion orgḕn autoû, hóti thelētḕs eléous estín."],[7,19,"ἐπιστρέψει καὶ οἰκτειρήσει ἡμᾶς, καταδύσει τὰς ἀδικίας ἡμῶν καὶ ἀποριφήσονται εἰς τὰ βάθη τῆς θαλάσσης, πάσας τὰς ἁμαρτίας ἡμῶν.","epistrépsei kaì oikteirḗsei hēmâs, katadýsei tàs adikías hēmō̂n kaì aporiphḗsontai eis tà báthē tē̂s thalássēs, pásas tàs hamartías hēmō̂n."],[7,20,"δώσει εἰς ἀλήθειαν τῷ Ἰακώβ, ἔλεον τῷ Ἀβραάμ, καθότι ὥμοσας τοῖς πατράσιν ἡμῶν κατὰ τὰς ἡμέρας τὰς ἔμπροσθεν.","dṓsei eis alḗtheian tō̂i Iakṓb, éleon tō̂i Abraám, kathóti hṓmosas toîs patrásin hēmō̂n katà tàs hēméras tàs émprosthen."]],"chu-elizabeth":[[1,1,"Слово Господне, еже бысть ко Михею Морасфитину, во дни Иоафама и Ахаза и Езекии царей Иудиных, о нихже виде о Самарии и о Иерусалиме.","Slovo Gospodne, eže bystʹ ko Miheû Morasfitinu, vo dni Ioafama i Ahaza i Ezekii carej Iudinyh, o nihže vide o Samarii i o Ierusalime."],[1,2,"Слышите, людие вси, словеса, и внемли, земле и вси иже на ней, и будет Господь Бог в вас в послушествование, Господь от дому святаго Своего.","Slyšite, lûdie vsi, slovesa, i vnemli, zemle i vsi iže na nej, i budet Gospodʹ Bog v vas v poslušestvovanie, Gospodʹ ot domu svâtago Svoego."],[1,3,"Понеже, се, Господь исходит от места Своего, и снидет и наступит на высоты земныя,","Poneže, se, Gospodʹ ishodit ot mesta Svoego, i snidet i nastupit na vysoty zemnyâ,"],[1,4,"и поколеблются горы под Ним, и юдоли растают яко воск от лица огня и яко вода сходящи со устремлением.","i pokoleblûtsâ gory pod Nim, i ûdoli rastaût âko vosk ot lica ognâ i âko voda shodâŝi so ustremleniem."],[1,5,"Нечестия ради Иаковля вся сия и греха ради дому Израилева. Кое нечестие дому Иаковлю? Не Самариа ли? И кий грех дому Иудина? Не Иерусалим ли?","Nečestiâ radi Iakovlâ vsâ siâ i greha radi domu Izraileva. Koe nečestie domu Iakovlû? Ne Samaria li? I kij greh domu Iudina? Ne Ierusalim li?"],[1,6,"И положу Самарию во овощное хранилище селное и в сад винограда, и развергу в пропасть камение ея, и основания ея открыю:","I položu Samariû vo ovoŝnoe hraniliŝe selnoe i v sad vinograda, i razvergu v propastʹ kamenie eâ, i osnovaniâ eâ otkryû:"],[1,7,"и вся изваянная ея сокрушат, и вся мзды ея запалят огнем, и вся кумиры ея положу в пагубу: понеже от найма блуда собра и от найма блужения соврати.","i vsâ izvaânnaâ eâ sokrušat, i vsâ mzdy eâ zapalât ognem, i vsâ kumiry eâ položu v pagubu: poneže ot najma bluda sobra i ot najma bluženiâ sovrati."],[1,8,"Сего ради возрыдает и восплачется, пойдет боса и нага, сотворит плачь аки змиев и рыдание аки дщерей сиринских:","Sego radi vozrydaet i vosplačetsâ, pojdet bosa i naga, sotvorit plačʹ aki zmiev i rydanie aki dŝerej sirinskih:"],[1,9,"яко одержа язва ея, понеже прииде даже до Иуды и коснуся до врат людий моих даже до Иерусалима.","âko oderža âzva eâ, poneže priide daže do Iudy i kosnusâ do vrat lûdij moih daže do Ierusalima."],[1,10,"Уже в Гефе, не величайтеся, и Иенакимляне, не сограждайте из дому на посмеяние, перстию посыплите посмеяние ваше.","Uže v Gefe, ne veličajtesâ, i Ienakimlâne, ne sograždajte iz domu na posmeânie, perstiû posyplite posmeânie vaše."],[1,11,"Обитающая добре во градех своих, не изыде живущая в Сеннааре, плачитеся дому (сущаго) близ ея, приимет от вас язву болезней.","Obitaûŝaâ dobre vo gradeh svoih, ne izyde živuŝaâ v Sennaare, plačitesâ domu (suŝago) bliz eâ, priimet ot vas âzvu boleznej."],[1,12,"Кто нача во благая вселившейся в болезнех, яко снидоша злая от Господа на врата Иерусалимля,","Kto nača vo blagaâ vselivšejsâ v bolezneh, âko snidoša zlaâ ot Gospoda na vrata Ierusalimlâ,"],[1,13,"шум колесниц и конников: живущая в Лахисе началница греха та есть дщери Сиони, яко в тебе обретошася нечестия Израилева.","šum kolesnic i konnikov: živuŝaâ v Lahise načalnica greha ta estʹ dŝeri Sioni, âko v tebe obretošasâ nečestiâ Izraileva."],[1,14,"Сего ради даст посылаемыя даже до наследия Гефова, домы суетны, вотще быша царем Израилевым,","Sego radi dast posylaemyâ daže do naslediâ Gefova, domy suetny, votŝe byša carem Izrailevym,"],[1,15,"дондеже наследники приведу тебе, живущая в Лахисе, наследие даже до Одоллама приидет, слава дщере Сиони.","dondeže nasledniki privedu tebe, živuŝaâ v Lahise, nasledie daže do Odollama priidet, slava dŝere Sioni."],[1,16,"Оброснися и остризися по чадех своих младых: разшири оброснение твое яко орел, понеже пленени быша от тебе.","Obrosnisâ i ostrizisâ po čadeh svoih mladyh: razširi obrosnenie tvoe âko orel, poneže pleneni byša ot tebe."],[2,1,"Быша помышляюще труды и делающе злая на ложах своих, и купно со днем совершаху тая, понеже не воздвигоша к Богу рук своих:","Byša pomyšlâûŝe trudy i delaûŝe zlaâ na ložah svoih, i kupno so dnem soveršahu taâ, poneže ne vozdvigoša k Bogu ruk svoih:"],[2,2,"и желаху сел, и грабляху сирот, и домы отимаху, и расхищаху мужа и дом его, и мужа и наследие его.","i želahu sel, i grablâhu sirot, i domy otimahu, i rashiŝahu muža i dom ego, i muža i nasledie ego."],[2,3,"Сего ради сия глаголет Господь: се, Аз помышляю на племя сие злая, от нихже не подвигнете вый ваших и не пойдете прости внезапу, яко время зло есть.","Sego radi siâ glagolet Gospodʹ: se, Az pomyšlâû na plemâ sie zlaâ, ot nihže ne podvignete vyj vaših i ne pojdete prosti vnezapu, âko vremâ zlo estʹ."],[2,4,"В той день приимется на вы притча, и восплачется плачь с песнию, глаголющь: бедство пострадахом: часть людий моих измерися ужем, и не бе возбраняяй его, еже отвратитися: села ваша разделена быша.","V toj denʹ priimetsâ na vy pritča, i vosplačetsâ plačʹ s pesniû, glagolûŝʹ: bedstvo postradahom: častʹ lûdij moih izmerisâ užem, i ne be vozbranââj ego, eže otvratitisâ: sela vaša razdelena byša."],[2,5,"Сего ради не будет тебе вмещущь ужа в жребии в сонме Господни.","Sego radi ne budet tebe vmeŝuŝʹ uža v žrebii v sonme Gospodni."],[2,6,"Не плачитеся слезами, ниже да слезят о сих: не отвержет бо укоризны","Ne plačitesâ slezami, niže da slezât o sih: ne otveržet bo ukorizny"],[2,7,"глаголяй: дом Иаковль разгнева Дух Господень: не сия ли суть начинания Его? Не словеса ли Его суть добра с ним, и правии ходиша?","glagolâj: dom Iakovlʹ razgneva Duh Gospodenʹ: ne siâ li sutʹ načinaniâ Ego? Ne slovesa li Ego sutʹ dobra s nim, i pravii hodiša?"],[2,8,"И прежде людие Мои во вражду сопротивишася, противу миру своему: кожу его одраша, еже отяти упование, сокрушение ратное:","I prežde lûdie Moi vo vraždu soprotivišasâ, protivu miru svoemu: kožu ego odraša, eže otâti upovanie, sokrušenie ratnoe:"],[2,9,"сего ради старейшины людий Моих извергутся из домов сладости своея, злых ради начинаний своих отриновени быша. Приближитеся горам вечным:","sego radi starejšiny lûdij Moih izvergutsâ iz domov sladosti svoeâ, zlyh radi načinanij svoih otrinoveni byša. Približitesâ goram večnym:"],[2,10,"востани и пойди, яко несть тебе сей покой: нечистоты ради, истлесте тлением,","vostani i pojdi, âko nestʹ tebe sej pokoj: nečistoty radi, istleste tleniem,"],[2,11,"прогнастеся ни кимже гоними: дух постави лжу, искапа тебе в вино и пиянство: и будет, от капли людий сих,","prognastesâ ni kimže gonimi: duh postavi lžu, iskapa tebe v vino i piânstvo: i budet, ot kapli lûdij sih,"],[2,12,"собираемь соберется Иаков со всеми: приемяй прииму оставших Израилевых, вкупе положу возвращение его, аки овцы в скорби, яко паству посреде ложа их: изскочат от человек.","sobiraemʹ soberetsâ Iakov so vsemi: priemâj priimu ostavših Izrailevyh, vkupe položu vozvraŝenie ego, aki ovcy v skorbi, âko pastvu posrede loža ih: izskočat ot čelovek."],[2,13,"Взыди просечением пред лицем их: просекоша, и проидоша врата, и изыдоша ими. И изыде царь их пред лицем их, Господь же Вождь их будет.","Vzydi prosečeniem pred licem ih: prosekoša, i proidoša vrata, i izydoša imi. I izyde carʹ ih pred licem ih, Gospodʹ že Voždʹ ih budet."],[3,1,"И речет: слышите убо сия, власти дому Иаковля и оставшии дому Израилева: не вам ли есть еже разумети суд?","I rečet: slyšite ubo siâ, vlasti domu Iakovlâ i ostavšii domu Izraileva: ne vam li estʹ eže razumeti sud?"],[3,2,"Ненавидящии добра, а ищущии зла, похищающии кожы их с них и плоти их от костей их:","Nenavidâŝii dobra, a iŝuŝii zla, pohiŝaûŝii kožy ih s nih i ploti ih ot kostej ih:"],[3,3,"якоже объядоша плоти людий Моих, и кожы их от костей их одраша, и кости их столкоша и содробиша яко плоти в коноб и яко мяса в горнец:","âkože obʺâdoša ploti lûdij Moih, i kožy ih ot kostej ih odraša, i kosti ih stolkoša i sodrobiša âko ploti v konob i âko mâsa v gornec:"],[3,4,"тако возопиют ко Господу, и не послушает их и отвратит лице Свое от них в то время, понеже слукавноваша в начинаниих своих на Ня.","tako vozopiût ko Gospodu, i ne poslušaet ih i otvratit lice Svoe ot nih v to vremâ, poneže slukavnovaša v načinaniih svoih na Nâ."],[3,5,"Сия глаголет Господь на пророки льстящыя людий Моих, угрызающыя зубы своими и проповедающыя мир на них, и не вдася во уста их, возставиша на них рать:","Siâ glagolet Gospodʹ na proroki lʹstâŝyâ lûdij Moih, ugryzaûŝyâ zuby svoimi i propovedaûŝyâ mir na nih, i ne vdasâ vo usta ih, vozstaviša na nih ratʹ:"],[3,6,"сего ради нощь будет вам от видения, и тма будет вам от волхвования, и зайдет солнце на пророки, и померкнет на ня день:","sego radi noŝʹ budet vam ot videniâ, i tma budet vam ot volhvovaniâ, i zajdet solnce na proroki, i pomerknet na nâ denʹ:"],[3,7,"и усрамятся видящии сония, и посмеяни будут волсви, и возглаголют на них вси сии, зане не будет послушаяй их.","i usramâtsâ vidâŝii soniâ, i posmeâni budut volsvi, i vozglagolût na nih vsi sii, zane ne budet poslušaâj ih."],[3,8,"Аще аз не наполню силы Духом Господним и судом и силою, еже возвестити Иакову нечестия его и Израилеви грехи его.","Aŝe az ne napolnû sily Duhom Gospodnim i sudom i siloû, eže vozvestiti Iakovu nečestiâ ego i Izrailevi grehi ego."],[3,9,"Слышите сия, старейшины дому Иаковля и оставшии дому Израилева, гнушающиися судом и вся правая развращающии,","Slyšite siâ, starejšiny domu Iakovlâ i ostavšii domu Izraileva, gnušaûŝiisâ sudom i vsâ pravaâ razvraŝaûŝii,"],[3,10,"созидающии Сиона кровьми и Иерусалима неправдами:","sozidaûŝii Siona krovʹmi i Ierusalima nepravdami:"],[3,11,"старейшины его на дарех суждаху, и жерцы его на мзде отвещаваху, и пророцы его на сребре волхвоваху, и на Господе почиваху, глаголюще: не Господь ли в нас есть? Не приидут на ны злая.","starejšiny ego na dareh suždahu, i žercy ego na mzde otveŝavahu, i prorocy ego na srebre volhvovahu, i na Gospode počivahu, glagolûŝe: ne Gospodʹ li v nas estʹ? Ne priidut na ny zlaâ."],[3,12,"Сего ради вас дела Сион якоже нива изорется, и Иерусалим яко овощное хранилище будет, и гора дому якоже луг дубравный.","Sego radi vas dela Sion âkože niva izoretsâ, i Ierusalim âko ovoŝnoe hraniliŝe budet, i gora domu âkože lug dubravnyj."],[4,1,"И будет в последния дни явлена гора Господня, уготована над верхи гор, и вознесется выше холмов, и потщатся к ней людие,","I budet v posledniâ dni âvlena gora Gospodnâ, ugotovana nad verhi gor, i voznesetsâ vyše holmov, i potŝatsâ k nej lûdie,"],[4,2,"и приидут языцы мнози и рекут: приидите, взыдем на гору Господню и в дом Бога Иаковля: и покажут нам путь Его, и пойдем по стезям Его: яко от Сиона изыдет закон, и слово Господне из Иерусалима,","i priidut âzycy mnozi i rekut: priidite, vzydem na goru Gospodnû i v dom Boga Iakovlâ: i pokažut nam putʹ Ego, i pojdem po stezâm Ego: âko ot Siona izydet zakon, i slovo Gospodne iz Ierusalima,"],[4,3,"и разсудит среде людий многих и изобличит языки крепки даже до земли дальния: и раскуют мечы своя на рала и сулицы своя на серпы, и не ктому возмет язык на язык меча, и не научатся ксему воевати.","i razsudit srede lûdij mnogih i izobličit âzyki krepki daže do zemli dalʹniâ: i raskuût mečy svoâ na rala i sulicy svoâ na serpy, i ne ktomu vozmet âzyk na âzyk meča, i ne naučatsâ ksemu voevati."],[4,4,"И почиет кийждо под лозою своею и кийждо под смоковницею своею, и не будет устрашающаго, зане уста Господа Вседержителя глаголаша сия.","I počiet kijždo pod lozoû svoeû i kijždo pod smokovniceû svoeû, i ne budet ustrašaûŝago, zane usta Gospoda Vsederžitelâ glagolaša siâ."],[4,5,"Яко вси людие пойдут кийждо в путь свой, а мы пойдем во имя Господа Бога нашего в век и далечае.","Âko vsi lûdie pojdut kijždo v putʹ svoj, a my pojdem vo imâ Gospoda Boga našego v vek i dalečae."],[4,6,"В той день, глаголет Господь, соберу сокрушенную, и отриновенную прииму, и ихже отринух:","V toj denʹ, glagolet Gospodʹ, soberu sokrušennuû, i otrinovennuû priimu, i ihže otrinuh:"],[4,7,"и положу сокрушенную во останок и отриновенную в язык крепок, и воцарится Господь над ними в горе Сионе отныне и до века.","i položu sokrušennuû vo ostanok i otrinovennuû v âzyk krepok, i vocaritsâ Gospodʹ nad nimi v gore Sione otnyne i do veka."],[4,8,"И ты, столпе паствы мгляный, дщи Сионя, к тебе приидет и внидет власть первая, царство из Вавилона дщери Иерусалимли.","I ty, stolpe pastvy mglânyj, dŝi Sionâ, k tebe priidet i vnidet vlastʹ pervaâ, carstvo iz Vavilona dŝeri Ierusalimli."],[4,9,"И ныне вскую познала еси зло? Не бе ли тебе царя? Или совет твой погибе, яко обыдоша тя болезни, аки раждающия?","I nyne vskuû poznala esi zlo? Ne be li tebe carâ? Ili sovet tvoj pogibe, âko obydoša tâ bolezni, aki raždaûŝiâ?"],[4,10,"Болезнуй и мужайся и приближайся, дщи Сионя, яко раждающая: зане ныне изыдеши из града и вселишися на поли и дойдеши Вавилона: оттуду изимет тя и оттуду избавит тя Господь Бог твой от руки враг твоих.","Boleznuj i mužajsâ i približajsâ, dŝi Sionâ, âko raždaûŝaâ: zane nyne izydeši iz grada i vselišisâ na poli i dojdeši Vavilona: ottudu izimet tâ i ottudu izbavit tâ Gospodʹ Bog tvoj ot ruki vrag tvoih."],[4,11,"И ныне собрашася на тя языцы мнози глаголющии: порадуемся: и воззрят на Сион очи наши.","I nyne sobrašasâ na tâ âzycy mnozi glagolûŝii: poraduemsâ: i vozzrât na Sion oči naši."],[4,12,"Сии же не разумеша помышления Господня и не домыслишася совета Его, яко собра их аки снопы гуменныя.","Sii že ne razumeša pomyšleniâ Gospodnâ i ne domyslišasâ soveta Ego, âko sobra ih aki snopy gumennyâ."],[4,13,"Востани и измлати их, дщи Сионя, яко роги твоя положу железны и пазнокти твоя положу медяны, и истончиши люди многи, и возложиши Господеви множество их и крепость их Господеви всея земли.","Vostani i izmlati ih, dŝi Sionâ, âko rogi tvoâ položu železny i paznokti tvoâ položu medâny, i istončiši lûdi mnogi, i vozložiši Gospodevi množestvo ih i krepostʹ ih Gospodevi vseâ zemli."],[5,1,"Ныне оградится дщи Ефремова ограждением, рать учини на вы, жезлом поразят о челюсть племен Израилевых.","Nyne ograditsâ dŝi Efremova ograždeniem, ratʹ učini na vy, žezlom porazât o čelûstʹ plemen Izrailevyh."],[5,2,"И ты, Вифлееме, доме Ефрафов, еда мал еси, еже быти в тысящах Иудиных? Из тебе бо Мне изыдет Старейшина, Еже быти в Князя во Израили, исходи же Его из начала от дний века.","I ty, Vifleeme, dome Efrafov, eda mal esi, eže byti v tysâŝah Iudinyh? Iz tebe bo Mne izydet Starejšina, Eže byti v Knâzâ vo Izraili, ishodi že Ego iz načala ot dnij veka."],[5,3,"Сего ради даст я, до времене раждающия породит, и прочии от братии их обратятся к сыном Израилевым.","Sego radi dast â, do vremene raždaûŝiâ porodit, i pročii ot bratii ih obratâtsâ k synom Izrailevym."],[5,4,"И станет, и узрит, и упасет паству Свою крепостию Господь, и в славе имене Господа Бога Своего пребудут: зане ныне возвеличится даже до конец земли.","I stanet, i uzrit, i upaset pastvu Svoû krepostiû Gospodʹ, i v slave imene Gospoda Boga Svoego prebudut: zane nyne vozveličitsâ daže do konec zemli."],[5,5,"И будет Сей мир, егда Ассур приидет на землю вашу, и егда взыдет на страну вашу, и востанут нань седмь пастырей и осмь язв человеческих,","I budet Sej mir, egda Assur priidet na zemlû vašu, i egda vzydet na stranu vašu, i vostanut nanʹ sedmʹ pastyrej i osmʹ âzv čelovečeskih,"],[5,6,"и упасут Ассура оружием и землю Невродову копиями ея, и избавит от Ассура, егда приидет на землю вашу и егда вступит на пределы вашя.","i upasut Assura oružiem i zemlû Nevrodovu kopiâmi eâ, i izbavit ot Assura, egda priidet na zemlû vašu i egda vstupit na predely vašâ."],[5,7,"И будет останок Иаковль в языцех среде людий многих, аки роса от Господа падающи и яко агнцы на злаце, яко да не соберется ни един, ниже постоит в сынех человеческих.","I budet ostanok Iakovlʹ v âzyceh srede lûdij mnogih, aki rosa ot Gospoda padaûŝi i âko agncy na zlace, âko da ne soberetsâ ni edin, niže postoit v syneh čelovečeskih."],[5,8,"И будет останок Иаковль в языцех среде людий многих, аки лев в скотех в дубраве и яко львичищь в стадех овчих, якоже егда пройдет, и отлучив восхитит, и не будет изимающаго.","I budet ostanok Iakovlʹ v âzyceh srede lûdij mnogih, aki lev v skoteh v dubrave i âko lʹvičiŝʹ v stadeh ovčih, âkože egda projdet, i otlučiv voshitit, i ne budet izimaûŝago."],[5,9,"Вознесется рука твоя на оскорбляющыя тя, и вси врази твои потребятся.","Voznesetsâ ruka tvoâ na oskorblâûŝyâ tâ, i vsi vrazi tvoi potrebâtsâ."],[5,10,"И будет в той день, глаголет Господь, потреблю кони твоя из среды твоея и погублю колесницы твоя,","I budet v toj denʹ, glagolet Gospodʹ, potreblû koni tvoâ iz sredy tvoeâ i pogublû kolesnicy tvoâ,"],[5,11,"и потреблю грады земли твоея и развергу вся твердыни твоя,","i potreblû grady zemli tvoeâ i razvergu vsâ tverdyni tvoâ,"],[5,12,"и отвергу волхвования твоя от руку твоею, и волхвующии не будут в тебе:","i otvergu volhvovaniâ tvoâ ot ruku tvoeû, i volhvuûŝii ne budut v tebe:"],[5,13,"и потреблю изваянная твоя и кумиры твоя из среды тебе, и посем да не поклонишися делом рук твоих:","i potreblû izvaânnaâ tvoâ i kumiry tvoâ iz sredy tebe, i posem da ne poklonišisâ delom ruk tvoih:"],[5,14,"и посеку дубравы от среды тебе и погублю грады твоя:","i poseku dubravy ot sredy tebe i pogublû grady tvoâ:"],[5,15,"и сотворю со гневом и с яростию месть языком, понеже не послушаша Мене.","i sotvorû so gnevom i s ârostiû mestʹ âzykom, poneže ne poslušaša Mene."],[6,1,"Слышите, яже глагола Господь: востани, судися с горами, и да слышат холми глас твой.","Slyšite, âže glagola Gospodʹ: vostani, sudisâ s gorami, i da slyšat holmi glas tvoj."],[6,2,"Слышите, горы, суд Господень, и дебри основания земли, яко суд Господень к людем Его, и со Израилем претися имать.","Slyšite, gory, sud Gospodenʹ, i debri osnovaniâ zemli, âko sud Gospodenʹ k lûdem Ego, i so Izrailem pretisâ imatʹ."],[6,3,"Людие Мои, что сотворих вам, или чим оскорбих вас, или чим стужих вам? Отвещайте Ми.","Lûdie Moi, čto sotvorih vam, ili čim oskorbih vas, ili čim stužih vam? Otveŝajte Mi."],[6,4,"Зане изведох вас из земли Египетския и из дому работы избавих вас, и послах пред вами Моисеа и Аарона и Мариам.","Zane izvedoh vas iz zemli Egipetskiâ i iz domu raboty izbavih vas, i poslah pred vami Moisea i Aarona i Mariam."],[6,5,"Людие Мои, помяните убо, что совеща на вы Валак царь Моавитский, и что ему отвеща Валаам сын Веоров, от Сития до Галгал? Яко да познается правда Господня.","Lûdie Moi, pomânite ubo, čto soveŝa na vy Valak carʹ Moavitskij, i čto emu otveŝa Valaam syn Veorov, ot Sitiâ do Galgal? Âko da poznaetsâ pravda Gospodnâ."],[6,6,"В чем постигну Господа, срящу Бога моего Вышняго? Срящу ли Его со всесожжением, телцы единолетными?","V čem postignu Gospoda, srâŝu Boga moego Vyšnâgo? Srâŝu li Ego so vsesožženiem, telcy edinoletnymi?"],[6,7,"Еда приимет Господь в тысящах овнов, или во тмах козлищ тучных? Дам ли первенцы моя о нечестии моем, плод утробы моея, за грехи души моея?","Eda priimet Gospodʹ v tysâŝah ovnov, ili vo tmah kozliŝ tučnyh? Dam li pervency moâ o nečestii moem, plod utroby moeâ, za grehi duši moeâ?"],[6,8,"Возвестися бо тебе, человече, что добро, или чесого Господь ищет от тебе, разве еже творити суд и любити милость и готову быти еже ходити с Господем Богом твоим?","Vozvestisâ bo tebe, čeloveče, čto dobro, ili česogo Gospodʹ iŝet ot tebe, razve eže tvoriti sud i lûbiti milostʹ i gotovu byti eže hoditi s Gospodem Bogom tvoim?"],[6,9,"Глас Господень граду призовется, и спасет боящыяся имене Его: послушай, племя, и кто украсит град?","Glas Gospodenʹ gradu prizovetsâ, i spaset boâŝyâsâ imene Ego: poslušaj, plemâ, i kto ukrasit grad?"],[6,10,"Еда огнь и дом беззаконнаго собирая имения беззаконная и со укоризною неправды?","Eda ognʹ i dom bezzakonnago sobiraâ imeniâ bezzakonnaâ i so ukoriznoû nepravdy?"],[6,11,"Еда оправдится в мериле беззаконник и во вретищи меры неправыя,","Eda opravditsâ v merile bezzakonnik i vo vretiŝi mery nepravyâ,"],[6,12,"от нихже богатство свое нечестия наполниша? И живущии в ней глаголаху лжу, и язык их вознесеся во устех их.","ot nihže bogatstvo svoe nečestiâ napolniša? I živuŝii v nej glagolahu lžu, i âzyk ih voznesesâ vo usteh ih."],[6,13,"И Аз начну поражати тя и погублю тя во гресех твоих.","I Az načnu poražati tâ i pogublû tâ vo greseh tvoih."],[6,14,"Ты ясти будеши и не насытишися, и померкнет в тебе, и совратишися, и не спасешися: и елицы аще избудут, оружию предадятся.","Ty âsti budeši i ne nasytišisâ, i pomerknet v tebe, i sovratišisâ, i ne spasešisâ: i elicy aŝe izbudut, oružiû predadâtsâ."],[6,15,"Ты посееши, но не пожнеши: ты изгнетеши масличие, но не помажешися маслом: и насадите вино, и не испиете: и погибнут законы людий Моих.","Ty poseeši, no ne požneši: ty izgneteši masličie, no ne pomažešisâ maslom: i nasadite vino, i ne ispiete: i pogibnut zakony lûdij Moih."],[6,16,"И хранил еси оправдания Замвриина и вся дела дому Ахаавля, и ходисте в советех их, яко да предам тя в пагубу, и живущыя в ней во звиздание, и укоризны людий приимете.","I hranil esi opravdaniâ Zamvriina i vsâ dela domu Ahaavlâ, i hodiste v soveteh ih, âko da predam tâ v pagubu, i živuŝyâ v nej vo zvizdanie, i ukorizny lûdij priimete."],[7,1,"У, люте мне! Понеже бых аки собираяй сламу на жатве, и яко пародок во оымании винограда не сущу гроздию, еже ясти первоплодная, яже вожделе душа моя.","U, lûte mne! Poneže byh aki sobiraâj slamu na žatve, i âko parodok vo oymanii vinograda ne suŝu grozdiû, eže âsti pervoplodnaâ, âže voždele duša moâ."],[7,2,"У, люте мне, душе! Яко погибе благочестивый от земли, и исправляющаго в человецех несть: вси во кровех прятся, кийждо ближняго своего озлобляет озлоблением,","U, lûte mne, duše! Âko pogibe blagočestivyj ot zemli, i ispravlâûŝago v čeloveceh nestʹ: vsi vo kroveh prâtsâ, kijždo bližnâgo svoego ozloblâet ozlobleniem,"],[7,3,"на зло руки своя уготовляют: князь просит, и судия мирная словеса глаголет, желание души его есть: и отиму благая их,","na zlo ruki svoâ ugotovlâût: knâzʹ prosit, i sudiâ mirnaâ slovesa glagolet, želanie duši ego estʹ: i otimu blagaâ ih,"],[7,4,"яко моль поядаяй, и ходяй по правилам в день стражбы. У, люте! У, люте! Отмщения Твоя приспеша, ныне будут плачы их.","âko molʹ poâdaâj, i hodâj po pravilam v denʹ stražby. U, lûte! U, lûte! Otmŝeniâ Tvoâ prispeša, nyne budut plačy ih."],[7,5,"Не верите другом, ни надейтеся на старейшины, и от сожителницы твоея хранися, еже сказати ей что:","Ne verite drugom, ni nadejtesâ na starejšiny, i ot sožitelnicy tvoeâ hranisâ, eže skazati ej čto:"],[7,6,"понеже сын безчестит отца, дщерь востанет на матерь свою и невеста на свекровь свою, врази вси мужу домашнии его.","poneže syn bezčestit otca, dŝerʹ vostanet na materʹ svoû i nevesta na svekrovʹ svoû, vrazi vsi mužu domašnii ego."],[7,7,"Аз же ко Господеви воззрю, потерплю Бога спаса моего, услышит мя Бог мой.","Az že ko Gospodevi vozzrû, poterplû Boga spasa moego, uslyšit mâ Bog moj."],[7,8,"Не радуйся о мне, враждебница моя, яко падох, и востану: зане аще сяду во тме, Господь осветит мя.","Ne radujsâ o mne, vraždebnica moâ, âko padoh, i vostanu: zane aŝe sâdu vo tme, Gospodʹ osvetit mâ."],[7,9,"Гнев Господень стерплю, яко согреших Ему, дондеже оправдит прю мою и сотворит суд мой: и изведет мя на свет, и узрю правду Его.","Gnev Gospodenʹ sterplû, âko sogreših Emu, dondeže opravdit prû moû i sotvorit sud moj: i izvedet mâ na svet, i uzrû pravdu Ego."],[7,10,"И узрит враждебница моя, и облечется в студ глаголющая ко мне: где есть Господь Бог твой? Очи мои воззрят на ню, ныне будет в попрание аки кал на путех.","I uzrit vraždebnica moâ, i oblečetsâ v stud glagolûŝaâ ko mne: gde estʹ Gospodʹ Bog tvoj? Oči moi vozzrât na nû, nyne budet v popranie aki kal na puteh."],[7,11,"День глаждения плинфа: изглаждение твое день оный, и сотрет законы твоя день оный.","Denʹ glaždeniâ plinfa: izglaždenie tvoe denʹ onyj, i sotret zakony tvoâ denʹ onyj."],[7,12,"И гради твои приидут на поравнение и в разделение Ассирийско, и гради твои твердии в разделение от Тира даже до реки Сирския, и от моря даже до моря, и от горы даже до горы, дние воды и молвы.","I gradi tvoi priidut na poravnenie i v razdelenie Assirijsko, i gradi tvoi tverdii v razdelenie ot Tira daže do reki Sirskiâ, i ot morâ daže do morâ, i ot gory daže do gory, dnie vody i molvy."],[7,13,"И будет земля в пагубу со живущими на ней, от плодов начинаний их.","I budet zemlâ v pagubu so živuŝimi na nej, ot plodov načinanij ih."],[7,14,"Паси люди Твоя жезлом Твоим, овцы наследия Твоего, вселяющыяся едины в дубраве среде Кармила, попасут Васанитиду и Галаадитиду, якоже дние века.","Pasi lûdi Tvoâ žezlom Tvoim, ovcy naslediâ Tvoego, vselâûŝyâsâ ediny v dubrave srede Karmila, popasut Vasanitidu i Galaaditidu, âkože dnie veka."],[7,15,"И по днем исхода твоего из Египта узрите чудесная.","I po dnem ishoda tvoego iz Egipta uzrite čudesnaâ."],[7,16,"Узрят языцы и усрамятся от всея крепости своея, руце возложат на уста своя, и уши их оглохнут,","Uzrât âzycy i usramâtsâ ot vseâ kreposti svoeâ, ruce vozložat na usta svoâ, i uši ih oglohnut,"],[7,17,"полижут персть яко змиеве плежуще по земли, смятутся во облежении своем: о Господе Бозе нашем ужаснутся и убоятся от Тебе.","poližut perstʹ âko zmieve pležuŝe po zemli, smâtutsâ vo obleženii svoem: o Gospode Boze našem užasnutsâ i uboâtsâ ot Tebe."],[7,18,"Кто Бог якоже Ты, отемляй беззакония и оставляяй нечестия останком наследия Своего? И не удержа гнева Своего во свидение, яко Волитель милости есть.","Kto Bog âkože Ty, otemlâj bezzakoniâ i ostavlââj nečestiâ ostankom naslediâ Svoego? I ne uderža gneva Svoego vo svidenie, âko Volitelʹ milosti estʹ."],[7,19,"Той обратит и ущедрит ны, и погрузит неправды нашя и ввержет в глубины морския вся грехи нашя,","Toj obratit i uŝedrit ny, i pogruzit nepravdy našâ i vveržet v glubiny morskiâ vsâ grehi našâ,"],[7,20,"даст истину Иакову, (и) милость Аврааму, якоже клялся еси отцем нашым во дни первыя.","dast istinu Iakovu, (i) milostʹ Avraamu, âkože klâlsâ esi otcem našym vo dni pervyâ."]]}};